import { graphHeight, graphWidth } from "../../../../functions/xp-curve/graph";

export {
  graphHeight,
  graphWidth,
  plotHeight,
  plotLeft,
  plotTop,
  plotWidth,
} from "../../../../functions/xp-curve/graph";

export function getGraphPointerPosition(
  svg: SVGSVGElement,
  event: PointerEvent,
): { x: number; y: number } {
  const bounds = svg.getBoundingClientRect();

  return {
    x: ((event.clientX - bounds.left) / bounds.width) * graphWidth,
    y: ((event.clientY - bounds.top) / bounds.height) * graphHeight,
  };
}
