import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";
import { getXpAwardSettings } from "../xp-award/settings/load";
import { getXpActorChoices } from "../xp-curve/actors";

export async function resetFortune(selectedActorIds?: string[]): Promise<string> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.sessionManagementConsole);
  const settings = getXpAwardSettings();
  const actorIds =
    selectedActorIds ??
    getXpActorChoices(settings.defaultSelection)
      .actors.filter(({ selected }) => selected)
      .map(({ id }) => id);
  let changed = 0;

  for (const actorId of actorIds) {
    const actor = game.actors.get(actorId) as SessionActorRuntime | undefined;
    if (!actor) continue;
    const target = getFortuneMaximum(actor);
    const current = readNumberPath(actor.system, ["status", "fortune", "value"]);
    if (current !== target) {
      await actor.update({ "system.status.fortune.value": target });
      changed += 1;
    }
  }

  return `Fortune restored for ${changed} of ${actorIds.length} characters.`;
}

function getFortuneMaximum(actor: SessionActorRuntime): number {
  const fate = readNumberPath(actor.system, ["status", "fate", "value"]);
  const luckName = game.i18n.localize("NAME.Luck");
  const luckAdvances = Array.from(actor.items ?? [])
    .filter((item) => item.type === "talent" && item.name === luckName)
    .reduce((total, item) => total + readNumberPath(item.system, ["advances", "value"]), 0);
  return Math.max(0, fate + luckAdvances);
}

function readNumberPath(value: unknown, path: string[]): number {
  let current = value;
  for (const key of path) {
    if (!current || typeof current !== "object") return 0;
    current = (current as Record<string, unknown>)[key];
  }
  const numeric = Number(current);
  return Number.isFinite(numeric) ? Math.round(numeric) : 0;
}

interface SessionActorRuntime extends FoundryActorDocument {
  items?: Iterable<{ name: string; system: unknown; type: string }>;
  update: (data: Record<string, unknown>) => Promise<unknown>;
}
