import { defineStore } from "pinia";
import { ref } from "vue";
import type {
  LightPresetId,
  TokenToolsActions,
  TokenToolsInitialization,
  VisionMode,
  VisionSettings,
} from "../../../types/token-tools/TokenTools";
export const useTokenToolsConsoleStore = defineStore("token-tools-console", () => {
  const controlledCount = ref(0);
  const settings = ref<VisionSettings>();
  const vision = ref<VisionMode>("normal");
  const light = ref<LightPresetId>("none");
  const busy = ref(false);
  const errorMessage = ref("");
  let actions: TokenToolsActions | undefined;
  function initialize(
    initialization: TokenToolsInitialization,
    nextActions: TokenToolsActions,
  ): void {
    controlledCount.value = initialization.controlledCount;
    settings.value = structuredClone(initialization.settings);
    actions = nextActions;
  }
  async function apply(): Promise<void> {
    await run(() => getActions().apply({ light: light.value, vision: vision.value }));
  }
  async function save(): Promise<void> {
    await run(() => getActions().saveSettings(getSettings()));
  }
  async function run(operation: () => Promise<void>): Promise<void> {
    busy.value = true;
    errorMessage.value = "";
    try {
      await operation();
    } catch (error) {
      errorMessage.value = error instanceof Error ? error.message : "The token update failed.";
    } finally {
      busy.value = false;
    }
  }
  function getActions(): TokenToolsActions {
    if (!actions) throw new Error("Token Tools has not been initialized.");
    return actions;
  }
  function getSettings(): VisionSettings {
    if (!settings.value) throw new Error("Token Tools has not been initialized.");
    return settings.value;
  }
  return { apply, busy, controlledCount, errorMessage, initialize, light, save, settings, vision };
});
