import type {
  AdministrationInitialization,
  AdministrationPackChoice,
} from "../../types/administration/Administration";
import { MODULE_ID } from "../constants";
import { ADMINISTRATION_SETTINGS } from "./settings/keys";

export function getAdministrationInitialization(): AdministrationInitialization {
  const runtime = game as unknown as AdministrationGameRuntime;
  const scene = runtime.scenes.viewed;

  return {
    packs: Array.from(runtime.packs)
      .filter(({ metadata }) => metadata.system === "wfrp4e")
      .map<AdministrationPackChoice>((pack) => ({
        id: pack.collection,
        label: pack.metadata.label || pack.collection,
        packageName: pack.metadata.packageName,
        selected: false,
        type: pack.metadata.type,
        visibility: pack.ownership.PLAYER === "OBSERVER" ? "observer" : "limited",
      }))
      .sort((left, right) => left.label.localeCompare(right.label)),
    ...(scene
      ? {
          scene: {
            globalLight: scene.environment.globalLight.enabled,
            id: scene.id,
            name: scene.name,
            tokenVision: scene.tokenVision,
          },
        }
      : {}),
    spectators: Array.from(runtime.users)
      .filter(
        (user) =>
          !user.isGM &&
          (user as FoundryUser & { active?: boolean }).active !== false &&
          !user.character,
      )
      .map(({ name }) => name)
      .sort(),
    showUnassignedPlayerWarning:
      game.settings.get(MODULE_ID, ADMINISTRATION_SETTINGS.showUnassignedPlayerWarning) === true,
  };
}

interface AdministrationGameRuntime {
  packs: Iterable<AdministrationPackRuntime>;
  scenes: { viewed?: AdministrationSceneRuntime | null };
  users: Iterable<FoundryUser>;
}

interface AdministrationPackRuntime {
  collection: string;
  metadata: { label?: string; packageName: string; system?: string; type: string };
  ownership: { PLAYER?: string };
}

interface AdministrationSceneRuntime {
  environment: { globalLight: { enabled: boolean } };
  id: string;
  name: string;
  tokenVision: boolean;
}
