import { LOCALIZATION_NAMESPACE, MODULE_ID } from "../constants";

export function registerBooleanLauncherSetting(key: string, localizationKey: string): void {
  game.settings.register(MODULE_ID, key, {
    config: false,
    default: true,
    hint: `${LOCALIZATION_NAMESPACE}.Settings.${localizationKey}.Hint`,
    name: `${LOCALIZATION_NAMESPACE}.Settings.${localizationKey}.Name`,
    requiresReload: true,
    scope: "client",
    type: Boolean,
  });
}

export function registerHiddenWorldSetting(
  key: string,
  defaultValue: boolean | number | string,
  type: BooleanConstructor | NumberConstructor | StringConstructor,
  localizationRoot: string,
  options: Pick<FoundrySettingConfig, "choices" | "range"> = {},
): void {
  game.settings.register(MODULE_ID, key, {
    ...options,
    config: false,
    default: defaultValue,
    hint: `${localizationRoot}.Hint`,
    name: `${localizationRoot}.Name`,
    scope: "world",
    type,
  });
}
