import type { PsychologyPayload, PsychologyType } from "../../types/fear-terror/Psychology";

export function normalizePsychologyPayload(payload: PsychologyPayload): PsychologyPayload {
  const fallbackRating = payload.type === "fear" ? 0 : 1;
  const numericRating = Number(payload.rating);
  const rating = Number.isFinite(numericRating)
    ? Math.max(0, Math.trunc(numericRating))
    : fallbackRating;
  const source = payload.source?.trim();

  if (source) {
    return {
      rating,
      source,
      type: payload.type,
    };
  }

  return {
    rating,
    type: payload.type,
  };
}

export function getPsychologyTypeLabel(type: PsychologyType): "Fear" | "Terror" {
  return type === "fear" ? "Fear" : "Terror";
}

export function buildPromptTitle(label: string, payload: PsychologyPayload): string {
  const sourceSuffix = payload.source ? ` - ${payload.source}` : "";

  return `${label} ${payload.rating}${sourceSuffix}`;
}

export function buildSummaryPromptContent(heading: string, payload: PsychologyPayload): string {
  return `<h2>${heading}</h2>${buildPsychologyLink(payload)}`;
}

export function buildPsychologyLink(payload: PsychologyPayload): string {
  const linkName = getPsychologyTypeLabel(payload.type);
  const sourcePart = payload.source ? `, ${payload.source}` : "";

  return `@${linkName}[${payload.rating}${sourcePart}]`;
}
