import { computed, ref } from "vue";
import { defineStore } from "pinia";

import type {
  AdministrationActions,
  AdministrationInitialization,
  CompendiumVisibility,
  SceneLightingMode,
} from "../../../types/administration/Administration";

export const useAdministrationConsoleStore = defineStore("administration-console", () => {
  const packs = ref<AdministrationInitialization["packs"]>([]);
  const scene = ref<AdministrationInitialization["scene"]>();
  const spectators = ref<string[]>([]);
  const showUnassignedPlayerWarning = ref(true);
  const visibility = ref<CompendiumVisibility>("observer");
  const errorMessage = ref<string>();
  const statusMessage = ref<string>();
  const isWorking = ref(false);
  let actions: AdministrationActions | undefined;
  const selectedPackIds = computed(() =>
    packs.value.filter(({ selected }) => selected).map(({ id }) => id),
  );

  function initialize(
    initialization: AdministrationInitialization,
    nextActions: AdministrationActions,
  ): void {
    actions = nextActions;
    packs.value = initialization.packs.map((pack) => ({ ...pack }));
    scene.value = initialization.scene ? { ...initialization.scene } : undefined;
    spectators.value = [...initialization.spectators];
    showUnassignedPlayerWarning.value = initialization.showUnassignedPlayerWarning;
  }

  function setAllPacks(selected: boolean): void {
    packs.value.forEach((pack) => (pack.selected = selected));
  }

  async function applyVisibility(): Promise<void> {
    await run(async () => {
      await getActions().setCompendiumVisibility(selectedPackIds.value, visibility.value);
      packs.value.forEach((pack) => {
        if (pack.selected) pack.visibility = visibility.value;
      });
      statusMessage.value = "Compendium visibility updated.";
    });
  }

  async function applySceneMode(mode: SceneLightingMode): Promise<void> {
    await run(async () => {
      await getActions().setSceneLighting(mode);
      if (scene.value) {
        scene.value.globalLight = mode === "global-light";
        scene.value.tokenVision = mode === "token-vision";
      }
      statusMessage.value = "Scene lighting mode updated.";
    });
  }

  async function rollD100(): Promise<void> {
    await run(async () => {
      await getActions().rollD100();
      statusMessage.value = "d100 rolled to chat.";
    });
  }

  async function savePlayerWarning(): Promise<void> {
    await run(async () => {
      await getActions().setUnassignedPlayerWarning(showUnassignedPlayerWarning.value);
      statusMessage.value = "Player warning preference saved.";
    });
  }

  async function run(operation: () => Promise<void>): Promise<void> {
    if (isWorking.value) return;
    isWorking.value = true;
    errorMessage.value = undefined;
    statusMessage.value = undefined;
    try {
      await operation();
    } catch (error) {
      errorMessage.value =
        error instanceof Error ? error.message : "The administration action failed.";
    } finally {
      isWorking.value = false;
    }
  }

  function getActions(): AdministrationActions {
    if (!actions) throw new Error("The Administration Console has not been initialized.");
    return actions;
  }

  return {
    applySceneMode,
    applyVisibility,
    errorMessage,
    initialize,
    isWorking,
    packs,
    rollD100,
    savePlayerWarning,
    scene,
    selectedPackIds,
    setAllPacks,
    showUnassignedPlayerWarning,
    spectators,
    statusMessage,
    visibility,
  };
});
