import {
  buildXpActorChoices,
  getXpActorCategory,
  type XpActorSelectionCandidate,
} from "../../functions/xp-curve/selection";
import type {
  XpActorCategory,
  XpActorChoice,
  XpDefaultSelection,
} from "../../types/xp-curve/XpCurve";

export interface XpActorRuntime {
  awardExperience: (amount: number, reason: string) => Promise<void>;
  choice: XpActorChoice;
}

interface WfrpActorXp {
  awardExperience: (amount: number, reason: string) => Promise<void>;
  totalXp: number;
}

type WfrpAwardExp = (
  this: Record<string, unknown>,
  amount: number,
  reason: string,
  message?: null,
  suppressChat?: boolean,
) => Promise<unknown> | unknown;

export function getXpActorChoices(defaultSelection: XpDefaultSelection): {
  actors: XpActorChoice[];
  selectionSource: "default" | "targets";
} {
  const assignedActorIds = getAssignedActorIds();
  const targetedActorIds = getTargetedActorIds();
  const selectionSource = targetedActorIds === undefined ? "default" : "targets";
  const candidates = Array.from(game.actors)
    .filter((actor) => actor.type === "character")
    .map(extractXpActorSelectionCandidate);
  const actors = buildXpActorChoices({
    assignedActorIds,
    candidates,
    defaultSelection,
    targetedActorIds,
  });

  return { actors, selectionSource };
}

export function getXpActorRuntimes(actorIds: string[]): XpActorRuntime[] {
  const assignedActorIds = getAssignedActorIds();

  return actorIds.map((actorId) => {
    const actor = game.actors.get(actorId);

    if (!actor || actor.type !== "character") {
      throw new Error(`XP recipient ${actorId} is no longer an available character actor.`);
    }

    return createXpActorRuntime(actor, getXpActorCategory(actor, assignedActorIds), true);
  });
}

function extractXpActorSelectionCandidate(actor: FoundryActorDocument): XpActorSelectionCandidate {
  const actorXp = extractWfrpActorXp(actor);

  return {
    hasPlayerOwner: actor.hasPlayerOwner,
    id: actor.id,
    name: actor.name,
    totalXp: actorXp.totalXp,
  };
}

function createXpActorRuntime(
  actor: FoundryActorDocument,
  category: XpActorCategory,
  selected: boolean,
): XpActorRuntime {
  const actorXp = extractWfrpActorXp(actor);

  return {
    awardExperience: actorXp.awardExperience,
    choice: {
      category,
      id: actor.id,
      name: actor.name,
      selected,
      totalXp: actorXp.totalXp,
    },
  };
}

function extractWfrpActorXp(actor: FoundryActorDocument): WfrpActorXp {
  const system = actor.system;

  if (!isRecord(system)) {
    throw new Error(`WFRP4e actor "${actor.name}" does not expose readable system data.`);
  }

  const details = system["details"];
  const awardExp = system["awardExp"];

  if (!isRecord(details) || typeof awardExp !== "function") {
    throw new Error(`WFRP4e actor "${actor.name}" does not expose XP award operations.`);
  }

  const experience = details["experience"];

  if (!isRecord(experience) || !Number.isFinite(Number(experience["total"]))) {
    throw new Error(`WFRP4e actor "${actor.name}" does not expose a numeric total XP value.`);
  }

  return {
    awardExperience: async (amount, reason) => {
      await (awardExp as WfrpAwardExp).call(system, amount, reason, null, true);
    },
    totalXp: Math.max(0, Math.round(Number(experience["total"]))),
  };
}

function getAssignedActorIds(): Set<string> {
  return new Set(
    Array.from(game.users)
      .map((user) => user.character?.id)
      .filter((actorId): actorId is string => typeof actorId === "string"),
  );
}

function getTargetedActorIds(): Set<string> | undefined {
  const targets = game.user?.targets;

  if (!targets || targets.size === 0) {
    return undefined;
  }

  return new Set(
    Array.from(targets)
      .map((token) => token.actor)
      .filter((actor): actor is FoundryActorDocument => actor?.type === "character")
      .map((actor) => actor.id),
  );
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}
