import type { ToolkitApplicationHandle } from "../../../types/module/api/ModuleApi";
import { MODULE_ID } from "../../constants";
import { SessionManagementApplication } from "./SessionManagementApplication";

export async function openSessionManagementConsole(): Promise<ToolkitApplicationHandle> {
  const application = new SessionManagementApplication();
  await application.render(true);
  return application;
}

export function openSessionManagementConsoleFromUi(): void {
  void openSessionManagementConsole().catch((error: unknown) => {
    console.error(`${MODULE_ID} | Failed to open the Session Turnover Console.`, error);
    ui.notifications.error(
      "Drowsy’s WFRP4e Toolkit could not open the Session Turnover Console. See the browser console for details.",
    );
  });
}
