import type {
  CompendiumVisibility,
  SceneLightingMode,
} from "../../types/administration/Administration";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";
import { MODULE_ID } from "../constants";
import { ADMINISTRATION_SETTINGS } from "./settings/keys";

export async function setSceneLighting(mode: SceneLightingMode): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.administrationConsole);
  const scene = (game as unknown as AdministrationGameRuntime).scenes.viewed;
  if (!scene) throw new Error("View a Scene before changing its lighting mode.");

  await scene.update({
    "environment.globalLight.enabled": mode === "global-light",
    "tokenVision": mode === "token-vision",
  });
  ui.notifications.info(
    `${scene.name} now uses ${mode === "global-light" ? "global illumination" : "Token Vision"}.`,
  );
}

export async function setCompendiumVisibility(
  packIds: string[],
  visibility: CompendiumVisibility,
): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.administrationConsole);
  const runtime = game as unknown as AdministrationGameRuntime;
  const uniqueIds = new Set(packIds);
  if (uniqueIds.size === 0) throw new Error("Select at least one compendium pack.");
  const ownership = {
    ASSISTANT: "OWNER",
    GAMEMASTER: "OWNER",
    PLAYER: visibility === "observer" ? "OBSERVER" : "LIMITED",
    TRUSTED: visibility === "observer" ? "OBSERVER" : "LIMITED",
  };
  let updated = 0;

  for (const pack of runtime.packs) {
    if (!uniqueIds.has(pack.collection)) continue;
    await pack.configure({ ownership });
    updated += 1;
  }

  if (updated !== uniqueIds.size)
    throw new Error("One or more selected compendium packs are unavailable.");
  ui.notifications.info(`${updated} compendium pack${updated === 1 ? "" : "s"} updated.`);
}

export async function rollD100(): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.administrationConsole);
  const roll = new Roll("1d100");
  await roll.evaluate();
  await roll.toMessage({ flavor: "d100" });
}

export async function setUnassignedPlayerWarning(enabled: boolean): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.administrationConsole);
  await game.settings.set(MODULE_ID, ADMINISTRATION_SETTINGS.showUnassignedPlayerWarning, enabled);
  ui.notifications.info(`Unassigned-player warning ${enabled ? "enabled" : "disabled"}.`);
}

interface AdministrationGameRuntime {
  packs: Iterable<AdministrationPackRuntime>;
  scenes: { viewed?: AdministrationSceneRuntime | null };
}

interface AdministrationPackRuntime {
  collection: string;
  configure: (data: { ownership: Record<string, string> }) => Promise<unknown>;
}

interface AdministrationSceneRuntime {
  name: string;
  update: (data: Record<string, unknown>) => Promise<unknown>;
}
