<script setup lang="ts">
import { storeToRefs } from "pinia";
import { useXpAwardConsoleStore } from "../../../state/apps/xp-award-console/store";
import type { XpAwardConsoleActions } from "../../../types/xp-award/Console";
import type { XpAwardConsoleInitialization } from "../../../types/xp-award/XpAward";

const props = defineProps<{
  actions: XpAwardConsoleActions;
  initialization: XpAwardConsoleInitialization;
}>();
const store = useXpAwardConsoleStore();
store.initialize(props.initialization, props.actions);
const {
  actors,
  amount,
  canApply,
  defaultReason,
  defaultSelection,
  errorMessage,
  includeTimestampInReason,
  isSettingsOpen,
  isWorking,
  plan,
  resolvedReason,
  selectedActors,
  selectionSource,
} = storeToRefs(store);
function signed(value: number): string {
  return value > 0 ? `+${value}` : String(value);
}
</script>

<template>
  <main
    class="tw:@container tw:flex tw:h-full tw:min-h-0 tw:flex-col tw:overflow-hidden tw:bg-base-200! tw:text-base-content!"
  >
    <header
      class="tw:flex tw:shrink-0 tw:items-center tw:justify-between tw:gap-3 tw:border-b tw:border-base-content/20 tw:px-4 tw:py-2"
    >
      <h1 class="tw:m-0 tw:font-serif tw:text-xl">Award XP</h1>
      <button
        class="dui-btn dui-btn-ghost dui-btn-square dui-btn-sm"
        type="button"
        aria-label="Open XP Award Settings"
        title="XP Award Settings"
        :disabled="isWorking || isSettingsOpen"
        @click="store.openSettings"
      >
        <i class="fa-solid fa-gear" aria-hidden="true" />
      </button>
    </header>
    <p
      v-if="errorMessage"
      class="dui-alert dui-alert-error tw:m-3 tw:mb-0 tw:shrink-0"
      role="alert"
    >
      {{ errorMessage }}
    </p>
    <form
      class="tw:flex tw:min-h-0 tw:flex-1 tw:flex-col tw:gap-3 tw:p-4"
      @submit.prevent="store.applyAwards"
    >
      <div
        class="tw:grid tw:min-h-0 tw:flex-1 tw:grid-cols-2 tw:gap-4 tw:@max-[32rem]:grid-cols-1 tw:@max-[32rem]:grid-rows-[minmax(0,1fr)_minmax(0,1fr)]"
      >
        <div class="tw:flex tw:min-h-0 tw:min-w-0 tw:flex-col tw:gap-3">
          <fieldset
            class="tw:m-0 tw:grid tw:shrink-0 tw:gap-3 tw:border-0 tw:p-0"
            :disabled="isWorking || isSettingsOpen"
          >
            <label class="tw:grid tw:gap-1 tw:text-sm" for="fixed-xp-amount"
              ><span>XP</span>
              <input
                id="fixed-xp-amount"
                v-model.number="amount"
                class="dui-input dui-input-sm tw:w-full tw:bg-base-100!"
                type="number"
                step="1"
                required
              />
            </label>
            <label class="tw:grid tw:gap-1 tw:text-sm" for="fixed-xp-reason"
              ><span>Reason</span>
              <input
                id="fixed-xp-reason"
                v-model="defaultReason"
                class="dui-input dui-input-sm tw:w-full tw:bg-base-100!"
                type="text"
              />
            </label>
          </fieldset>
          <section
            class="tw:flex tw:min-h-0 tw:flex-1 tw:flex-col tw:gap-2"
            aria-labelledby="xp-preview-title"
          >
            <h2 id="xp-preview-title" class="tw:m-0 tw:font-serif tw:text-lg">Preview</h2>
            <div
              class="tw:min-h-0 tw:overflow-y-auto tw:rounded-box tw:border tw:border-base-content/20 tw:bg-base-100! tw:p-3 tw:text-sm tw:break-words"
              aria-live="polite"
            >
              <p class="tw:m-0 tw:font-semibold">XP entries</p>
              <p class="tw:mt-1 tw:mb-2">{{ resolvedReason || "No reason" }}</p>
              <p class="tw:m-0 tw:text-xs tw:text-base-content/65!">
                Amounts appear beside selected recipients. Companions receive half XP.
              </p>
              <p
                v-if="includeTimestampInReason"
                class="tw:mt-2 tw:mb-0 tw:text-xs tw:text-base-content/65!"
              >
                The timestamp is set when you confirm.
              </p>
            </div>
          </section>
        </div>
        <section
          class="tw:flex tw:min-h-0 tw:min-w-0 tw:flex-col tw:overflow-hidden tw:rounded-box tw:border tw:border-base-content/20 tw:bg-base-100!"
          aria-labelledby="xp-recipients-title"
        >
          <div class="tw:shrink-0 tw:border-b tw:border-base-content/15 tw:p-3">
            <h2 id="xp-recipients-title" class="tw:m-0 tw:font-serif tw:text-lg">
              Recipients
              <span class="tw:text-sm tw:font-normal">({{ selectedActors.length }})</span>
            </h2>
            <p class="tw:mt-1 tw:mb-0 tw:text-xs tw:text-base-content/65!">
              {{
                selectionSource === "targets"
                  ? "From your targets"
                  : `From your ${defaultSelection} default`
              }}
            </p>
          </div>
          <div class="tw:min-h-0 tw:flex-1 tw:overflow-y-auto tw:overscroll-contain tw:p-2">
            <label
              v-for="actor in actors"
              :key="actor.id"
              class="tw:flex tw:cursor-pointer tw:items-center tw:gap-3 tw:rounded-box tw:p-3 tw:hover:bg-base-200"
            >
              <i
                class="fa-solid fa-user tw:shrink-0 tw:text-xl tw:text-base-content/60!"
                aria-hidden="true"
              />
              <span class="tw:min-w-0 tw:flex-1 tw:break-words tw:text-sm">
                <span class="tw:block tw:font-semibold">{{ actor.name }}</span>
                <span class="tw:block tw:text-xs tw:text-base-content/65!"
                  >{{ actor.category === "companion" ? "Companion" : "Character"
                  }}<template v-if="actor.selected">
                    ·
                    {{
                      signed(plan.awards.find((award) => award.actorId === actor.id)?.amount ?? 0)
                    }}
                    XP</template
                  ></span
                >
              </span>
              <input
                v-model="actor.selected"
                class="dui-checkbox dui-checkbox-sm dui-checkbox-primary tw:shrink-0"
                :aria-label="`Include ${actor.name}`"
                :disabled="isWorking || isSettingsOpen"
                type="checkbox"
              />
            </label>
            <p v-if="!actors.length" class="tw:p-3 tw:text-sm">
              No character actors are available.
            </p>
          </div>
        </section>
      </div>
      <footer
        class="tw:flex tw:shrink-0 tw:items-center tw:justify-between tw:gap-3 tw:border-t tw:border-base-content/15 tw:pt-3"
      >
        <p class="tw:m-0 tw:text-sm">
          {{
            selectedActors.length
              ? `${signed(plan.totalChange)} XP in total`
              : "Select at least one recipient."
          }}
        </p>
        <button class="dui-btn dui-btn-primary tw:shrink-0" :disabled="!canApply" type="submit">
          <span
            v-if="isWorking"
            class="dui-loading dui-loading-spinner dui-loading-sm"
            aria-hidden="true"
          />Confirm
        </button>
      </footer>
    </form>
  </main>
</template>
