import type { ToolkitApplicationHandle } from "../../../types/module/api/ModuleApi";
import { MODULE_ID } from "../../constants";
import {
  XpCurveConfiguratorApplication,
  type XpCurveConfiguratorOptions,
} from "./XpCurveConfiguratorApplication";

export async function openXpCurveConfigurator(
  options: XpCurveConfiguratorOptions = {},
): Promise<ToolkitApplicationHandle> {
  const application = new XpCurveConfiguratorApplication(options);
  await application.render(true);

  return application;
}

export function openXpCurveConfiguratorFromUi(options: XpCurveConfiguratorOptions = {}): void {
  void openXpCurveConfigurator(options).catch((error: unknown) => {
    console.error(`${MODULE_ID} | Failed to open the XP Curve Configurator.`, error);
    ui.notifications.error(
      "Drowsy’s WFRP4e Toolkit could not open the XP Curve Configurator. See the browser console for details.",
    );
  });
}
