import { GmToolkitMigrationApplication } from "../../apps/gm-toolkit-migration/GmToolkitMigrationApplication";
import { LOCALIZATION_NAMESPACE, MODULE_ID } from "../../constants";
import { registerHiddenWorldSetting } from "../../settings/register";
import { GM_TOOLKIT_MIGRATION_SETTINGS } from "./keys";

export function registerGmToolkitMigrationSettings(): void {
  registerHiddenWorldSetting(
    GM_TOOLKIT_MIGRATION_SETTINGS.state,
    JSON.stringify({ version: 1 }),
    String,
    `${LOCALIZATION_NAMESPACE}.Settings.GmToolkitMigration.State`,
  );

  game.settings.registerMenu(MODULE_ID, "gmToolkitMigration", {
    hint: `${LOCALIZATION_NAMESPACE}.Menu.GmToolkitMigration.Hint`,
    icon: "fa-solid fa-box-archive",
    label: `${LOCALIZATION_NAMESPACE}.Menu.GmToolkitMigration.Label`,
    name: `${LOCALIZATION_NAMESPACE}.Menu.GmToolkitMigration.Name`,
    restricted: GmToolkitMigrationApplication.ACCESS_POLICY.gmOnly,
    type: GmToolkitMigrationApplication,
  });
}
