import type { XpCurveSettings, XpDefaultSelection } from "../../../types/xp-curve/XpCurve";
import { MODULE_ID } from "../../constants";
import { XP_CURVE_SETTINGS } from "./keys";

export function getXpCurveSettings(): XpCurveSettings {
  return {
    defaultReason: readString(XP_CURVE_SETTINGS.defaultReason),
    defaultSelection: readDefaultSelection(XP_CURVE_SETTINGS.defaultSelection),
    parameters: {
      companionMultiplier: readNumber(XP_CURVE_SETTINGS.companionMultiplier),
      curveExponent: readNumber(XP_CURVE_SETTINGS.curveExponent),
      gapForMaximumAward: readNumber(XP_CURVE_SETTINGS.gapForMaximumAward),
      maximumAward: readNumber(XP_CURVE_SETTINGS.maximumAward),
      scaleExponent: readNumber(XP_CURVE_SETTINGS.scaleExponent),
      scalePivot: readNumber(XP_CURVE_SETTINGS.scalePivot),
    },
  };
}

export async function saveXpCurveSettings(settings: XpCurveSettings): Promise<void> {
  const values = [
    [XP_CURVE_SETTINGS.companionMultiplier, settings.parameters.companionMultiplier],
    [XP_CURVE_SETTINGS.curveExponent, settings.parameters.curveExponent],
    [XP_CURVE_SETTINGS.defaultReason, settings.defaultReason],
    [XP_CURVE_SETTINGS.defaultSelection, settings.defaultSelection],
    [XP_CURVE_SETTINGS.gapForMaximumAward, settings.parameters.gapForMaximumAward],
    [XP_CURVE_SETTINGS.maximumAward, settings.parameters.maximumAward],
    [XP_CURVE_SETTINGS.scaleExponent, settings.parameters.scaleExponent],
    [XP_CURVE_SETTINGS.scalePivot, settings.parameters.scalePivot],
  ] as const;

  for (const [key, value] of values) {
    await game.settings.set(MODULE_ID, key, value);
  }
}

export function isXpCurveLauncherEnabled(
  setting: typeof XP_CURVE_SETTINGS.showTokenControlsLauncher,
): boolean {
  return readBoolean(setting);
}

function readBoolean(key: string): boolean {
  return game.settings.get(MODULE_ID, key) === true;
}

function readNumber(key: string): number {
  return Number(game.settings.get(MODULE_ID, key));
}

function readString(key: string): string {
  const value = game.settings.get(MODULE_ID, key);

  return typeof value === "string" ? value : "";
}

function readDefaultSelection(key: string): XpDefaultSelection {
  return normalizeDefaultSelection(readString(key));
}

function normalizeDefaultSelection(value: string): XpDefaultSelection {
  if (value === "company" || value === "world") {
    return value;
  }

  return "party";
}
