import { registerModuleApi } from "../api/register-module-api";
import { registerAdministrationHooks, warnAboutUnassignedPlayers } from "../administration/hooks";
import { registerAdministrationSettings } from "../administration/settings/register";
import { registerCombatHooks } from "../combat/hooks";
import { registerCombatSettings } from "../combat/settings/register";
import { MODULE_ID, WFRP4E_SYSTEM_ID } from "../constants";
import { registerActorSheetEntry } from "../fear-terror/actor-sheet/register";
import { registerDarkWhispersSettings } from "../dark-whispers/settings/register";
import { registerDarkWhispersChatHooks } from "../dark-whispers/service";
import { registerGmToolkitMigrationSettings } from "../gm-toolkit/settings/register";
import { registerGroupTestHooks } from "../group-test/service";
import { registerGroupTestSettings } from "../group-test/settings/register";
import { registerSceneControl } from "../fear-terror/scene-controls/register";
import { registerFearTerrorSettings } from "../fear-terror/settings/register";
import { registerSessionManagementSettings } from "../session-management/settings/register";
import { registerSessionManagementHooks } from "../session-management/hooks";
import { registerToolkitHomeSettings } from "../toolkit-home/settings/register";
import { registerTokenToolsSettings } from "../token-tools/settings/register";
import { registerXpCurveSceneControl } from "../xp-curve/scene-controls/register";
import { registerXpCurveSettings } from "../xp-curve/settings/register";
import { registerXpAwardSettings } from "../xp-award/settings/register";

export function registerModuleHooks(): void {
  registerAdministrationHooks();
  registerCombatHooks();
  registerDarkWhispersChatHooks();
  registerGroupTestHooks();
  registerSessionManagementHooks();
  Hooks.once("init", () => {
    console.info(`${MODULE_ID} | Initializing`);
    registerAdministrationSettings();
    registerCombatSettings();
    registerFearTerrorSettings();
    registerDarkWhispersSettings();
    registerGmToolkitMigrationSettings();
    registerGroupTestSettings();
    registerSessionManagementSettings();
    registerToolkitHomeSettings();
    registerTokenToolsSettings();
    registerXpAwardSettings();
    registerXpCurveSettings();
    registerActorSheetEntry();
    registerSceneControl();
    registerXpCurveSceneControl();
  });

  Hooks.once("ready", () => {
    if (game.system.id !== WFRP4E_SYSTEM_ID) {
      console.warn(
        `${MODULE_ID} | Loaded outside ${WFRP4E_SYSTEM_ID}; skipping module API registration.`,
      );
      return;
    }

    registerModuleApi();
    warnAboutUnassignedPlayers();
    console.info(`${MODULE_ID} | Ready`);
  });
}
