import { computed, ref } from "vue";

import type { XpActorChoice } from "../../../types/xp-curve/XpCurve";

export function createXpActorSelection(consoleName: string) {
  const actors = ref<XpActorChoice[]>([]);
  const selectedActors = computed(() => actors.value.filter((actor) => actor.selected));
  let initialSelectedActorIds = new Set<string>();

  function initializeActors(nextActors: XpActorChoice[]): void {
    actors.value = nextActors.map((actor) => ({ ...actor }));
    initialSelectedActorIds = new Set(
      nextActors.filter((actor) => actor.selected).map((actor) => actor.id),
    );
  }

  function setActorSelected(actorId: string, selected: boolean): void {
    const actor = actors.value.find((candidate) => candidate.id === actorId);

    if (!actor) {
      throw new Error(`${consoleName} cannot select unknown actor ${actorId}.`);
    }

    actor.selected = selected;
  }

  function setAllActorsSelected(selected: boolean): void {
    for (const actor of actors.value) {
      actor.selected = selected;
    }
  }

  function resetSelection(): void {
    for (const actor of actors.value) {
      actor.selected = initialSelectedActorIds.has(actor.id);
    }
  }

  return {
    actors,
    initializeActors,
    resetSelection,
    selectedActors,
    setActorSelected,
    setAllActorsSelected,
  };
}
