import type { ActorChoice } from "../../types/shared/ActorChoice";

export type ActorSelectionMode = "company" | "controlled" | "party" | "targeted";

export interface ActorSelectionCandidate {
  actorType: string;
  hasPlayerOwner: boolean;
  id: string;
  label: string;
  uuid: string;
}

export interface TokenActorSelectionCandidate {
  actor: ActorSelectionCandidate;
  tokenUuid: string;
}

export function buildActorChoices(options: {
  actors: readonly ActorSelectionCandidate[];
  assignedActorIds: ReadonlySet<string>;
  controlled: readonly TokenActorSelectionCandidate[];
  includeVehicles: boolean;
  initial: ActorSelectionMode;
  targeted: readonly TokenActorSelectionCandidate[];
}): ActorChoice[] {
  const targetedActorIds = new Set(options.targeted.map(({ actor }) => actor.id));
  const controlledActorIds = new Set(options.controlled.map(({ actor }) => actor.id));
  const choices = options.actors
    .filter((actor) => isEligible(actor, options.includeVehicles))
    .map(
      (actor): ActorChoice => ({
        actorType: actor.actorType,
        label: actor.label,
        selected: isInitiallySelected(
          actor.id,
          actor.hasPlayerOwner,
          options.initial,
          options.assignedActorIds,
          controlledActorIds,
          targetedActorIds,
        ),
        source: options.assignedActorIds.has(actor.id)
          ? "assigned"
          : actor.hasPlayerOwner
            ? "owned"
            : "world",
        uuid: actor.uuid,
      }),
    );

  addTokenChoices(choices, options.targeted, "targeted", options);
  addTokenChoices(choices, options.controlled, "controlled", options);

  return choices.sort((left, right) => left.label.localeCompare(right.label));
}

function addTokenChoices(
  choices: ActorChoice[],
  tokens: readonly TokenActorSelectionCandidate[],
  source: "controlled" | "targeted",
  options: { includeVehicles: boolean; initial: ActorSelectionMode },
): void {
  for (const token of tokens) {
    if (!isEligible(token.actor, options.includeVehicles)) continue;

    const existing = choices.find(
      (choice) => choice.uuid === token.actor.uuid || choice.uuid === token.tokenUuid,
    );
    if (existing) {
      if (source === options.initial) existing.selected = true;
      continue;
    }

    choices.push({
      actorType: token.actor.actorType,
      label: token.actor.label,
      selected: source === options.initial,
      source,
      uuid: token.tokenUuid,
    });
  }
}

function isEligible(actor: ActorSelectionCandidate, includeVehicles: boolean): boolean {
  return (
    actor.actorType === "character" ||
    actor.actorType === "creature" ||
    (includeVehicles && actor.actorType === "vehicle")
  );
}

function isInitiallySelected(
  actorId: string,
  hasPlayerOwner: boolean,
  initial: ActorSelectionMode,
  assigned: ReadonlySet<string>,
  controlled: ReadonlySet<string>,
  targeted: ReadonlySet<string>,
): boolean {
  if (initial === "party") return assigned.has(actorId);
  if (initial === "company") return assigned.has(actorId) || hasPlayerOwner;
  return initial === "controlled" ? controlled.has(actorId) : targeted.has(actorId);
}
