<script setup lang="ts">
import { ref } from "vue";

import type { ToolkitHomeAction, ToolkitHomeSection } from "../../../types/toolkit-home/Console";
import ConsoleFrame from "./ConsoleFrame.vue";

defineProps<{
  description: string;
  icon: string;
  sections: ToolkitHomeSection[];
  title: string;
}>();

const errorMessage = ref<string>();
const workingActionId = ref<string>();

async function activate(action: ToolkitHomeAction): Promise<void> {
  errorMessage.value = undefined;
  workingActionId.value = action.id;

  try {
    await action.open();
  } catch (error) {
    console.error(`Launcher action "${action.label}" failed.`, error);
    errorMessage.value =
      error instanceof Error ? error.message : `${action.label} could not be completed.`;
  } finally {
    workingActionId.value = undefined;
  }
}
</script>

<template>
  <ConsoleFrame
    :description="description"
    :error-message="errorMessage"
    :icon="icon"
    :title="title"
  >
    <div class="tw:grid tw:min-w-0 tw:gap-4">
      <section v-for="section in sections" :key="section.id" class="tw:grid tw:gap-2">
        <h2 class="tw:m-0 tw:font-serif tw:text-lg tw:text-base-content!">
          {{ section.label }}
        </h2>
        <div class="tw:grid tw:min-w-0 tw:gap-2 tw:min-[38rem]:grid-cols-2">
          <button
            v-for="action in section.actions"
            :key="action.id"
            class="dui-card dui-card-border tw:m-0! tw:h-auto! tw:min-h-0! tw:w-full! tw:min-w-0 tw:cursor-pointer tw:items-stretch! tw:justify-start! tw:gap-0! tw:border-2 tw:border-base-content/20! tw:bg-base-100! tw:p-0! tw:text-left tw:text-base-content! tw:shadow-sm tw:transition tw:leading-normal! hover:tw:border-primary/60!"
            :disabled="workingActionId !== undefined"
            type="button"
            @click="activate(action)"
          >
            <span
              class="dui-card-body tw:w-full tw:min-w-0 tw:flex-row tw:items-start tw:gap-3 tw:p-4"
            >
              <i
                :class="action.icon"
                class="tw:mt-1 tw:w-6 tw:shrink-0 tw:text-center tw:text-lg tw:text-primary!"
                aria-hidden="true"
              />
              <span class="tw:min-w-0 tw:flex-1">
                <span class="tw:block tw:font-semibold tw:text-base-content!">
                  {{ action.label }}
                </span>
                <span class="tw:block tw:text-xs tw:text-base-content/75!">{{
                  action.description
                }}</span>
              </span>
              <span
                v-if="workingActionId === action.id"
                class="dui-loading dui-loading-sm dui-loading-spinner tw:shrink-0"
                aria-label="Working"
              />
            </span>
          </button>
        </div>
      </section>
    </div>
  </ConsoleFrame>
</template>
