import type { DamageProtection, DamageRequest } from "../../types/damage/Damage";

export interface DamageBatchPlan {
  formula: string;
  location: string;
  rollDamagePerActor: boolean;
  rollLocationPerActor: boolean;
  uuids: string[];
}

export function buildDamageBatchPlan(request: DamageRequest): DamageBatchPlan {
  const formula = request.formula.trim();
  if (request.uuids.length === 0) throw new Error("Select at least one actor.");
  if (!formula) throw new Error("Enter a damage amount or roll formula.");

  return {
    formula,
    location: request.hitLocation || "body",
    rollDamagePerActor: request.randomizeDamage,
    rollLocationPerActor: request.hitLocation === "roll" && request.randomizeHitLocation,
    uuids: [...new Set(request.uuids)],
  };
}

export function normalizeDamageRollTotal(total: unknown, formula: string): number {
  const numericTotal = Number(total);
  if (!Number.isFinite(numericTotal))
    throw new Error(`Could not evaluate damage formula “${formula}”.`);
  const damage = Math.round(numericTotal);
  if (damage < 0) throw new Error("Damage cannot be negative.");
  return damage;
}

export function resolveDamageLocation(location: string, rolledLocation?: string): string {
  return location === "roll" ? rolledLocation || "body" : location || "body";
}

export function getDamageTypeKey(
  protection: DamageProtection,
): "IGNORE_ALL" | "IGNORE_AP" | "IGNORE_TB" | "NORMAL" {
  return {
    "ignore-all": "IGNORE_ALL" as const,
    "ignore-armour": "IGNORE_AP" as const,
    "ignore-toughness": "IGNORE_TB" as const,
    "normal": "NORMAL" as const,
  }[protection];
}

export function formatDamageResult(input: {
  actorName: string;
  damage?: number;
  error?: string;
  message?: string;
}): string {
  if (input.message) return input.message;
  const actorName = escapeHtml(input.actorName);
  if (input.error)
    return `<p><strong>${actorName}</strong>: failed — ${escapeHtml(input.error)}</p>`;
  return `<p><strong>${actorName}</strong>: ${input.damage ?? 0} damage applied.</p>`;
}

export function formatDamageBatchFailure(successCount: number, failureCount: number): string {
  return `Damage was applied to ${successCount} actor${successCount === 1 ? "" : "s"}; ${failureCount} failed. See the private chat summary.`;
}

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
