import { buildGmToolkitDarkWhispersMigrationPreview } from "../../functions/gm-toolkit/content";
import { buildGmToolkitCutoverReport } from "../../functions/gm-toolkit/cutover";
import { buildGmToolkitMigrationPreview } from "../../functions/gm-toolkit/migration";
import type { GmToolkitCutoverReport } from "../../types/gm-toolkit/Cutover";
import type { GmToolkitMigrationPreview } from "../../types/gm-toolkit/Migration";
import type { GmToolkitMigrationState } from "../../types/gm-toolkit/State";
import { getDarkWhispersPromptLibraryState } from "../dark-whispers/settings/load";
import { getSessionManagementState } from "../session-management/settings/load";
import { getXpAwardSettings } from "../xp-award/settings/load";
import { getGmToolkitDarkWhispersCandidates } from "./content-source";
import { getGmToolkitLauncherMigrationPreview } from "./launcher-source";
import { getGmToolkitMigrationState } from "./settings/load";
import { getGmToolkitSourceSnapshot } from "./source";
import { getGmToolkitFeatureTargetValues } from "./setting-targets";

export function getGmToolkitImportPreview(): GmToolkitMigrationPreview | undefined {
  const source = getGmToolkitSourceSnapshot();
  const libraryState = getDarkWhispersPromptLibraryState();
  const darkWhispers = buildGmToolkitDarkWhispersMigrationPreview(
    getGmToolkitDarkWhispersCandidates(),
    libraryState.library,
    libraryState.warnings,
  );
  const launchers = getGmToolkitLauncherMigrationPreview();

  if (!source && darkWhispers.candidates.length === 0 && launchers.candidates.length === 0) {
    return undefined;
  }

  if (source) {
    return buildGmToolkitMigrationPreview(
      source,
      {
        featureSettings: getGmToolkitFeatureTargetValues(),
        sessionReference: getSessionManagementState().currentSessionReference,
        xpAwardSettings: getXpAwardSettings(),
      },
      darkWhispers,
      launchers,
    );
  }

  return {
    darkWhispers,
    dispositionCounts: { import: 0, pending: 0, retire: 0, skip: 0, supersede: 0 },
    imports: [],
    launchers,
    sourceCounts: { baseline: 0, persisted: 0, registered: 0 },
    version: 1,
  };
}

export function getGmToolkitCutoverReport(
  preview: GmToolkitMigrationPreview | undefined = getGmToolkitImportPreview(),
  state: GmToolkitMigrationState = getGmToolkitMigrationState(),
): GmToolkitCutoverReport | undefined {
  const currentSource = preview?.source;
  const savedSource = state.migration?.source;
  const source = currentSource ?? savedSource;

  if (!preview && !source) {
    return undefined;
  }

  const sessionState = getSessionManagementState();
  const reportPreview = source
    ? buildGmToolkitMigrationPreview(
        source,
        {
          featureSettings: getGmToolkitFeatureTargetValues(),
          sessionReference: sessionState.currentSessionReference,
          xpAwardSettings: getXpAwardSettings(),
        },
        preview?.darkWhispers,
        preview?.launchers,
      )
    : preview!;
  const activeCombat = game.combats.active;

  return buildGmToolkitCutoverReport({
    combat: activeCombat
      ? {
          active: true,
          id: activeCombat.id,
          name: activeCombat.name,
          ...(Number.isFinite(activeCombat.round) ? { round: Number(activeCombat.round) } : {}),
        }
      : { active: false },
    generatedAt: new Date().toISOString(),
    ...(state.migration ? { migration: state.migration } : {}),
    preview: reportPreview,
    sourceEvidence: currentSource ? "current" : savedSource ? "saved-snapshot" : "world-documents",
  });
}
