<script setup lang="ts">
import { sessionLogText } from "../../../../functions/session-management/submission";
import { storeToRefs } from "pinia";
import { useSessionManagementStore } from "../../../../state/apps/session-management/store";
const store = useSessionManagementStore();
const {
  actors,
  amount,
  canConfirm,
  currentSessionReference,
  isSettingsOpen,
  isWorking,
  nextSessionReference,
  occurredAtLocal,
  pending,
  plan,
  reason,
  settings,
} = storeToRefs(store);
</script>

<template>
  <form
    id="session-end"
    role="tabpanel"
    aria-labelledby="session-tab-end"
    class="tw:flex tw:min-h-0 tw:flex-1 tw:flex-col tw:gap-3 tw:p-4"
    @submit.prevent="store.confirm"
  >
    <div
      class="tw:grid tw:min-h-0 tw:flex-1 tw:grid-cols-[minmax(0,1fr)_minmax(0,1fr)] tw:gap-4 tw:@max-[32rem]:grid-cols-1 tw:@max-[32rem]:grid-rows-[minmax(0,1.3fr)_minmax(0,1fr)]"
    >
      <div class="tw:flex tw:min-h-0 tw:min-w-0 tw:flex-col tw:gap-3">
        <fieldset
          class="tw:m-0 tw:grid tw:gap-3 tw:border-0 tw:p-0 tw:@max-[32rem]:grid-cols-2"
          :disabled="isWorking || pending || isSettingsOpen"
        >
          <label
            class="tw:grid tw:gap-1 tw:text-sm tw:@max-[32rem]:col-span-2"
            for="session-occurred-at"
            ><span>Date &amp; time</span
            ><input
              id="session-occurred-at"
              v-model="occurredAtLocal"
              class="dui-input dui-input-sm tw:min-w-0 tw:w-full tw:bg-base-100!"
              type="datetime-local"
              required
          /></label>
          <label class="tw:grid tw:gap-1 tw:text-sm" for="session-xp"
            ><span>Session XP</span
            ><input
              id="session-xp"
              v-model.number="amount"
              class="dui-input dui-input-sm tw:w-full tw:bg-base-100!"
              type="number"
              min="0"
              step="1"
              required
          /></label>
          <label class="tw:grid tw:gap-1 tw:text-sm" for="session-number"
            ><span>Session number</span
            ><input
              id="session-number"
              :value="currentSessionReference"
              class="dui-input dui-input-sm tw:w-full tw:bg-base-100!"
              type="number"
              min="0"
              step="1"
              required
              @input="currentSessionReference = ($event.target as HTMLInputElement).value"
          /></label>
        </fieldset>
        <section
          aria-labelledby="session-preview-title"
          class="tw:flex tw:min-h-0 tw:flex-1 tw:flex-col tw:gap-2"
        >
          <h2 id="session-preview-title" class="tw:m-0 tw:font-serif tw:text-lg">Preview</h2>
          <div
            class="tw:min-h-0 tw:overflow-y-auto tw:rounded-box tw:border tw:border-base-content/20 tw:bg-base-100! tw:p-3 tw:text-sm tw:break-words"
            aria-live="polite"
          >
            <p class="tw:m-0 tw:font-semibold">Session log</p>
            <p class="tw:mt-1 tw:mb-3">
              {{ sessionLogText(currentSessionReference, occurredAtLocal) }}
            </p>
            <p class="tw:m-0 tw:font-semibold">XP entries</p>
            <p class="tw:mt-1 tw:mb-0">
              {{ amount > 0 ? reason || "Choose a date and time" : "No XP will be awarded." }}
            </p>
            <p v-if="amount > 0" class="tw:mt-2 tw:mb-0 tw:text-xs tw:text-base-content/70!">
              Amounts appear beside each selected recipient. Companions receive half XP.
            </p>
          </div>
        </section>
      </div>
      <section
        class="tw:flex tw:min-h-0 tw:min-w-0 tw:flex-col tw:overflow-hidden tw:rounded-box tw:border tw:border-base-content/20 tw:bg-base-100!"
        aria-labelledby="session-recipients-title"
      >
        <div class="tw:shrink-0 tw:border-b tw:border-base-content/15 tw:p-3">
          <h2 id="session-recipients-title" class="tw:m-0 tw:font-serif tw:text-lg">
            Recipients <span class="tw:text-sm tw:font-normal">({{ plan.awards.length }})</span>
          </h2>
        </div>
        <div class="tw:min-h-0 tw:flex-1 tw:overflow-y-auto tw:overscroll-contain tw:p-2">
          <label
            v-for="actor in actors"
            :key="actor.id"
            class="tw:flex tw:cursor-pointer tw:items-center tw:gap-3 tw:rounded-box tw:p-3 tw:hover:bg-base-200"
          >
            <i
              class="fa-solid fa-user tw:shrink-0 tw:text-xl tw:text-base-content/60!"
              aria-hidden="true"
            />
            <span class="tw:min-w-0 tw:flex-1 tw:break-words tw:text-sm"
              ><span class="tw:block tw:font-semibold">{{ actor.name }}</span
              ><span class="tw:block tw:text-xs tw:text-base-content/65!"
                >{{ actor.category === "companion" ? "Companion" : "Character"
                }}<template v-if="actor.selected">
                  · +{{
                    plan.awards.find((award) => award.actorId === actor.id)?.amount ?? 0
                  }}
                  XP</template
                ></span
              ></span
            >
            <input
              v-model="actor.selected"
              class="dui-checkbox dui-checkbox-sm dui-checkbox-primary tw:shrink-0"
              :aria-label="`Include ${actor.name}`"
              :disabled="isWorking || pending || isSettingsOpen"
              type="checkbox"
            />
          </label>
          <p v-if="!actors.length" class="tw:p-3 tw:text-sm">No character actors are available.</p>
        </div>
      </section>
    </div>
    <footer
      class="tw:flex tw:shrink-0 tw:items-center tw:justify-between tw:gap-3 tw:border-t tw:border-base-content/15 tw:pt-3"
    >
      <div class="tw:min-w-0 tw:text-sm">
        <p class="tw:m-0">
          Next session: <strong>{{ nextSessionReference || "—" }}</strong>
        </p>
        <p class="tw:mt-1 tw:mb-0 tw:text-xs tw:text-base-content/65!">
          {{
            [
              settings.pause && "Pause play",
              settings.fortuneReset && "Restore Fortune",
              settings.holdingScene && "Holding scene",
              settings.exportChat && "Export chat",
            ]
              .filter(Boolean)
              .join(" · ")
          }}
        </p>
      </div>
      <button class="dui-btn dui-btn-primary tw:shrink-0" :disabled="!canConfirm" type="submit">
        <span
          v-if="isWorking"
          class="dui-loading dui-loading-spinner dui-loading-sm"
          aria-hidden="true"
        />{{ pending ? "Retry" : "Confirm" }}
      </button>
    </footer>
  </form>
</template>
