import type { Component } from "vue";
import type {
  SessionConfigurationActions,
  SessionConfigurationInitialization,
} from "../../../types/session-management/Configuration";
import SessionSettingsApp from "../../../view/apps/session-management/settings/SessionSettingsApp.vue";
import { MODULE_ID, MODULE_TITLE } from "../../constants";
import { getSessionManagementConsoleInitialization } from "../../session-management/initialization";
import {
  saveCurrentSessionReference,
  saveSessionConfiguration,
} from "../../session-management/service";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../access";

export class SessionSettingsApplication extends FoundryVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.sessionManagementConsole;
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-session-settings`,
    position: { width: 480, height: 720 },
    window: {
      title: `${MODULE_TITLE} — Session Management Settings`,
      icon: "fa-solid fa-gear",
      resizable: true,
    },
  };
  onSaved?: (data: SessionConfigurationInitialization) => void;
  onClosed?: () => void;
  protected override getVueComponent(): Component {
    return SessionSettingsApp;
  }
  protected override getVueProps(): Record<string, unknown> {
    const initialization = getSessionManagementConsoleInitialization();
    const actions: SessionConfigurationActions = {
      save: async (settings, reference) => {
        await saveSessionConfiguration(settings);
        if (reference !== initialization.state.currentSessionReference)
          await saveCurrentSessionReference(reference);
        this.onSaved?.({
          currentSessionReference: reference,
          scenes: initialization.scenes,
          settings,
        });
        await this.close();
      },
    };
    return {
      actions,
      initialization: {
        ...initialization,
        currentSessionReference: initialization.state.currentSessionReference,
      },
    };
  }
  protected override async _preClose(
    options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<void> {
    await super._preClose(options);
    this.onClosed?.();
  }
}

export async function openSessionSettings(
  onSaved: (data: SessionConfigurationInitialization) => void,
): Promise<void> {
  const application = new SessionSettingsApplication();
  application.onSaved = onSaved;
  const closed = new Promise<void>((resolve) => {
    application.onClosed = resolve;
  });
  await application.render(true);
  await closed;
}
