import {
  initializeSessionForm,
  buildSessionTurnoverRequest,
  applySessionTurnoverResult,
  applySessionSettingsUpdate,
} from "../../../functions/session-management/form";
import { computed, ref } from "vue";
import { defineStore } from "pinia";
import { calculateFixedXpAwardPlan } from "../../../functions/xp-award/calculate";
import {
  nextSessionNumber,
  sessionXpReason,
} from "../../../functions/session-management/submission";
import type {
  SessionForm,
  SessionManagementConsoleActions,
  SessionManagementConsoleInitialization,
} from "../../../types/session-management/Console";
import type { SessionConfigurationInitialization } from "../../../types/session-management/Configuration";

export const useSessionManagementStore = defineStore("session-management", () => {
  const initialization = ref<SessionManagementConsoleInitialization>();
  const currentSessionReference = ref("");
  const occurredAtLocal = ref("");
  const amount = ref(0);
  const actors = ref<SessionManagementConsoleInitialization["actors"]>([]);
  const activeTab = ref<"end" | "log">("end");
  const errorMessage = ref<string>();
  const statusMessage = ref<string>();
  const isWorking = ref(false);
  const isSettingsOpen = ref(false);
  let actions: SessionManagementConsoleActions;
  const state = computed(() => initialization.value!.state);
  const settings = computed(() => initialization.value!.settings);
  const pending = computed(
    () =>
      state.value.turnover?.steps.some(
        (step) => step.status === "failed" || step.status === "pending",
      ) ?? false,
  );
  const nextSessionReference = computed(() => {
    try {
      return nextSessionNumber(currentSessionReference.value);
    } catch {
      return "";
    }
  });
  const validDate = computed(
    () =>
      Boolean(occurredAtLocal.value) && !Number.isNaN(new Date(occurredAtLocal.value).getTime()),
  );
  const plan = computed(() => calculateFixedXpAwardPlan(actors.value, amount.value));
  const reason = computed(() =>
    validDate.value
      ? sessionXpReason(settings.value.xp, currentSessionReference.value, occurredAtLocal.value)
      : "",
  );
  const canConfirm = computed(
    () =>
      !isWorking.value &&
      !isSettingsOpen.value &&
      Boolean(nextSessionReference.value) &&
      validDate.value &&
      Number.isSafeInteger(amount.value) &&
      amount.value >= 0 &&
      (amount.value === 0 || plan.value.awards.length > 0),
  );

  function initialize(
    data: SessionManagementConsoleInitialization,
    nextActions: SessionManagementConsoleActions,
  ): void {
    actions = nextActions;
    const initialized = initializeSessionForm(data);
    initialization.value = initialized.initialization;
    assignForm(initialized.form);
  }

  function formSnapshot(): SessionForm {
    return {
      actors: actors.value,
      amount: amount.value,
      currentSessionReference: currentSessionReference.value,
      occurredAtLocal: occurredAtLocal.value,
    };
  }

  function assignForm(form: SessionForm): void {
    actors.value = form.actors;
    amount.value = form.amount;
    currentSessionReference.value = form.currentSessionReference;
    occurredAtLocal.value = form.occurredAtLocal;
  }

  async function confirm(): Promise<void> {
    if (!canConfirm.value) return;
    isWorking.value = true;
    errorMessage.value = undefined;
    statusMessage.value = undefined;
    try {
      const request = buildSessionTurnoverRequest(formSnapshot(), settings.value);
      const result = await actions.runSessionTurnover(request);
      initialization.value!.state = applySessionTurnoverResult(
        state.value,
        result,
        request.nextSessionReference,
      );
      if (result.record) {
        currentSessionReference.value = state.value.currentSessionReference;
        statusMessage.value = `Session ${result.record.reference} completed. Ready for session ${currentSessionReference.value}.`;
      }
    } catch (error) {
      console.error("Drowsy’s WFRP4e Toolkit | Session turnover failed.", error);
      errorMessage.value =
        error instanceof Error ? error.message : "The session could not be completed.";
      initialize(actions.reload(), actions);
    } finally {
      isWorking.value = false;
    }
  }

  async function openSettings(): Promise<void> {
    if (isWorking.value || pending.value || isSettingsOpen.value) return;
    isSettingsOpen.value = true;
    try {
      await actions.openSettings((saved: SessionConfigurationInitialization) => {
        const updated = applySessionSettingsUpdate(
          formSnapshot(),
          state.value.currentSessionReference,
          settings.value,
          saved,
        );
        assignForm(updated.form);
        initialization.value!.settings = saved.settings;
        state.value.currentSessionReference = saved.currentSessionReference;
        if (updated.reloadActors) actors.value = actions.reload().actors;
      });
    } catch (error) {
      console.error("Drowsy’s WFRP4e Toolkit | Session settings failed.", error);
      errorMessage.value =
        error instanceof Error ? error.message : "Could not open session settings.";
    } finally {
      isSettingsOpen.value = false;
    }
  }

  return {
    activeTab,
    actors,
    amount,
    canConfirm,
    confirm,
    currentSessionReference,
    errorMessage,
    initialize,
    isSettingsOpen,
    isWorking,
    nextSessionReference,
    occurredAtLocal,
    openSettings,
    pending,
    plan,
    reason,
    settings,
    state,
    statusMessage,
  };
});
