import { buildDarkWhispersRecipients } from "../../functions/dark-whispers/recipients";
import type { DarkWhispersConsoleInitialization } from "../../types/dark-whispers/Console";
import type { FoundryActorDocument } from "../../types/foundry";
import { getDarkWhispersPromptLibrary, getDarkWhispersSettings } from "./settings/load";

interface WhisperActorRuntime extends FoundryActorDocument {
  ownership?: Record<string, number>;
  system: { status?: { corruption?: { max?: number; value?: number } } };
  uuid: string;
}

export function getDarkWhispersConsoleInitialization(): DarkWhispersConsoleInitialization {
  const settings = getDarkWhispersSettings();
  const recipients = buildDarkWhispersRecipients({
    actors: (Array.from(game.actors) as WhisperActorRuntime[]).map((actor) => ({
      corruption: Number(actor.system.status?.corruption?.value ?? 0),
      corruptionMax: Number(actor.system.status?.corruption?.max ?? 0),
      hasPlayerOwner: actor.hasPlayerOwner,
      id: actor.id,
      label: actor.name,
      ownership: actor.ownership ?? {},
      type: actor.type,
      uuid: actor.uuid,
    })),
    defaultGroup: settings.defaultGroup,
    targetedActorIds: new Set(
      Array.from(game.user?.targets ?? []).flatMap((token) =>
        token.actor ? [token.actor.id] : [],
      ),
    ),
    users: Array.from(game.users).map((user) => ({
      ...(user.character ? { characterId: user.character.id } : {}),
      id: user.id,
      isGm: user.isGM,
      name: user.name,
    })),
  });
  return { prompts: structuredClone(getDarkWhispersPromptLibrary().prompts), recipients, settings };
}
