import { computed, ref } from "vue";
import { defineStore } from "pinia";

import { calculateXpAwardPlan } from "../../../functions/xp-curve/calculate";
import { resolveXpAwardReason } from "../../../functions/xp-curve/reason";
import type {
  XpCurveConsoleActions,
  XpCurveConsoleInitialization,
  XpReasonContext,
} from "../../../types/xp-curve/Console";
import type {
  XpAwardRequest,
  XpCurveParameters,
  XpDefaultSelection,
} from "../../../types/xp-curve/XpCurve";
import { DEFAULT_XP_CURVE_PARAMETERS } from "../../../types/xp-curve/XpCurve";
import { createXpActorSelection } from "../shared/xp-actor-selection";

export const useXpCurveConsoleStore = defineStore("xp-curve-console", () => {
  const {
    actors,
    initializeActors,
    resetSelection,
    selectedActors,
    setActorSelected,
    setAllActorsSelected,
  } = createXpActorSelection("The XP Curve Console");
  const parameters = ref<XpCurveParameters>({ ...DEFAULT_XP_CURVE_PARAMETERS });
  const defaultReason = ref("");
  const defaultSelection = ref<XpDefaultSelection>("party");
  const selectionSource = ref<"default" | "targets">("default");
  const errorMessage = ref<undefined | string>();
  const isWorking = ref(false);
  let consoleActions: XpCurveConsoleActions | undefined;
  let reasonContext: XpReasonContext | undefined;
  const plan = computed(() => calculateXpAwardPlan(actors.value, parameters.value));
  const positiveAwardCount = computed(
    () => plan.value.awards.filter((award) => award.award > 0).length,
  );
  const canApply = computed(
    () => selectedActors.value.length >= 2 && plan.value.totalAward > 0 && !isWorking.value,
  );
  const resolvedReason = computed(() =>
    resolveXpAwardReason(defaultReason.value, getReasonContext()),
  );

  function initialize(
    nextInitialization: XpCurveConsoleInitialization,
    actions: XpCurveConsoleActions,
  ): void {
    consoleActions = actions;
    reasonContext = nextInitialization.reasonContext;
    initializeActors(nextInitialization.actors);
    parameters.value = { ...nextInitialization.parameters };
    defaultReason.value = nextInitialization.defaultReason;
    defaultSelection.value = nextInitialization.defaultSelection;
    selectionSource.value = nextInitialization.selectionSource;
    errorMessage.value = undefined;
  }

  async function applyAwards(): Promise<void> {
    if (!canApply.value || isWorking.value) {
      return;
    }

    isWorking.value = true;
    errorMessage.value = undefined;

    try {
      const request: XpAwardRequest = {
        actorIds: selectedActors.value.map((actor) => actor.id),
        defaultReason: defaultReason.value,
        defaultSelection: defaultSelection.value,
        parameters: parameters.value,
      };
      const result = await getConsoleActions().applyAwards(request);
      getConsoleActions().onActionComplete(result);
    } catch (error) {
      console.error("Drowsy’s WFRP4e Toolkit | XP curve award failed.", error);
      errorMessage.value =
        error instanceof Error ? error.message : "The XP awards could not be completed.";
    } finally {
      isWorking.value = false;
    }
  }

  function getConsoleActions(): XpCurveConsoleActions {
    if (!consoleActions) {
      throw new Error("The XP Curve Console has not been initialized.");
    }

    return consoleActions;
  }

  function getReasonContext(): XpReasonContext {
    if (!reasonContext) {
      throw new Error("The XP Curve Console has not been initialized.");
    }

    return reasonContext;
  }

  return {
    actors,
    applyAwards,
    canApply,
    defaultReason,
    errorMessage,
    initialize,
    isWorking,
    plan,
    positiveAwardCount,
    resetSelection,
    resolvedReason,
    selectedActors,
    selectionSource,
    setActorSelected,
    setAllActorsSelected,
  };
});
