import { buildSceneControlToolclip } from "../../../functions/scene-controls/toolclip";
import { FearConsoleApplication } from "../../apps/fear-console/FearConsoleApplication";
import { openFearConsoleFromUi } from "../../apps/fear-console/open";
import { LOCALIZATION_NAMESPACE } from "../../constants";
import { FEAR_TERROR_LAUNCHER_SETTINGS, isFearTerrorLauncherEnabled } from "../settings/launchers";

const TOOL_NAME = "openFearConsole";

export function registerSceneControl(): void {
  Hooks.on("getSceneControlButtons", (controls) => {
    if (
      !FearConsoleApplication.canCurrentUserAccess() ||
      !isFearTerrorLauncherEnabled(FEAR_TERROR_LAUNCHER_SETTINGS.tokenControls)
    ) {
      return;
    }

    addTokenControlButton(controls as FoundrySceneControls);
  });
}

function addTokenControlButton(controls: FoundrySceneControls): void {
  const tokenControls = controls.tokens;

  if (!tokenControls) {
    return;
  }

  tokenControls.tools[TOOL_NAME] = {
    button: true,
    icon: "fa-solid fa-skull",
    name: TOOL_NAME,
    onChange: () => {
      openFearConsoleFromUi();
    },
    order: 99,
    title: "Fear Console",
    toolclip: buildSceneControlToolclip(
      "Fear Console",
      `${LOCALIZATION_NAMESPACE}.SceneControls.OpenFearConsole`,
    ),
  };
}
