import type { ImperialPeriod } from "../../types/imperial-calendar/Calendar";

export const IMPERIAL_DAYS_PER_YEAR = 400;
export const IMPERIAL_SECONDS_PER_DAY = 86_400;
export const IMPERIAL_MAX_YEAR = 99_999;

// Calendar facts verified against Simple Calendar Reborn 2.6.1's Warhammer preset.
// Festivals occupy a full day even though they sit outside numbered months/weeks.
export const IMPERIAL_PERIODS: readonly ImperialPeriod[] = [
  { name: "Hexenstag", days: 1, intercalary: true },
  { name: "Nachexen", days: 32, intercalary: false },
  { name: "Jahrdrung", days: 33, intercalary: false },
  { name: "Mitterfruhl", days: 1, intercalary: true },
  { name: "Pflugzeit", days: 33, intercalary: false },
  { name: "Sigmarzeit", days: 33, intercalary: false },
  { name: "Sommerzeit", days: 33, intercalary: false },
  { name: "Sonnstill", days: 1, intercalary: true },
  { name: "Vorgeheim", days: 33, intercalary: false },
  { name: "Geheimnistag", days: 1, intercalary: true },
  { name: "Nachgeheim", days: 32, intercalary: false },
  { name: "Erntezeit", days: 33, intercalary: false },
  { name: "Mittherbst", days: 1, intercalary: true },
  { name: "Brauzeit", days: 33, intercalary: false },
  { name: "Kaldezeit", days: 33, intercalary: false },
  { name: "Ulriczeit", days: 33, intercalary: false },
  { name: "Mondstille", days: 1, intercalary: true },
  { name: "Vorhexen", days: 33, intercalary: false },
];

export function getImperialPeriod(name: string): ImperialPeriod {
  const period = IMPERIAL_PERIODS.find((candidate) => candidate.name === name);
  if (!period) throw new RangeError("Choose an Imperial month or festival.");
  return period;
}
