import { buildSceneControlToolclip } from "../../../functions/scene-controls/toolclip";
import { XpCurveConsoleApplication } from "../../apps/xp-curve-console/XpCurveConsoleApplication";
import { openXpCurveConsoleFromUi } from "../../apps/xp-curve-console/open";
import { LOCALIZATION_NAMESPACE } from "../../constants";
import { XP_CURVE_SETTINGS } from "../settings/keys";
import { isXpCurveLauncherEnabled } from "../settings/load";

const TOOL_NAME = "openXpCurveConsole";

export function registerXpCurveSceneControl(): void {
  Hooks.on("getSceneControlButtons", (controls) => {
    if (
      !XpCurveConsoleApplication.canCurrentUserAccess() ||
      !isXpCurveLauncherEnabled(XP_CURVE_SETTINGS.showTokenControlsLauncher)
    ) {
      return;
    }

    const tokenControls = (controls as FoundrySceneControls).tokens;

    if (!tokenControls) {
      return;
    }

    tokenControls.tools[TOOL_NAME] = {
      button: true,
      icon: "fa-solid fa-chart-line",
      name: TOOL_NAME,
      onChange: openXpCurveConsoleFromUi,
      order: 98,
      title: "XP Curve Console",
      toolclip: buildSceneControlToolclip(
        "XP Curve Console",
        `${LOCALIZATION_NAMESPACE}.SceneControls.OpenXpCurveConsole`,
      ),
    };
  });
}
