import type { Component } from "vue";

import type { XpCurveConfiguratorActions } from "../../../types/xp-curve/Configuration";
import XpCurveConfiguratorApp from "../../../view/apps/xp-curve-configurator/XpCurveConfiguratorApp.vue";
import {
  getXpCurveConfiguratorInitialization,
  saveXpCurveConfiguratorSettings,
} from "../../xp-curve/configuration";
import { MODULE_ID, MODULE_TITLE } from "../../constants";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../access";

export interface XpCurveConfiguratorOptions {
  onSaved?: () => Promise<unknown> | unknown;
}

export class XpCurveConfiguratorApplication extends FoundryVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.xpCurveConsole;

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    classes: [MODULE_ID, `${MODULE_ID}-xp-curve-configurator`],
    id: `${MODULE_ID}-xp-curve-configurator`,
    position: {
      height: 760,
      width: 920,
    },
    window: {
      icon: "fa-solid fa-chart-line",
      resizable: true,
      title: `${MODULE_TITLE} — XP Curve Configurator`,
    },
  };

  readonly #options: XpCurveConfiguratorOptions;

  constructor(options: XpCurveConfiguratorOptions = {}) {
    super();
    this.#options = options;
  }

  protected override getVueComponent(): Component {
    return XpCurveConfiguratorApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    const actions: XpCurveConfiguratorActions = {
      saveConfiguration: async (configuration) => {
        await saveXpCurveConfiguratorSettings(configuration);
        await this.#options.onSaved?.();
      },
    };

    return {
      actions,
      initialization: getXpCurveConfiguratorInitialization(),
    };
  }
}
