import { XpAwardConsoleApplication } from "../../apps/xp-award-console/XpAwardConsoleApplication";
import { LOCALIZATION_NAMESPACE, MODULE_ID } from "../../constants";
import { registerHiddenWorldSetting } from "../../settings/register";
import { XP_AWARD_SETTINGS } from "./keys";

export function registerXpAwardSettings(): void {
  registerWorldSetting(
    XP_AWARD_SETTINGS.auditLog,
    JSON.stringify({ batches: [], version: 1 }),
    String,
    "AuditLog",
  );
  registerWorldSetting(XP_AWARD_SETTINGS.defaultAmount, 20, Number, "DefaultAmount", {
    range: { max: 100_000, min: -100_000, step: 1 },
  });
  registerWorldSetting(
    XP_AWARD_SETTINGS.defaultReason,
    "Session %session% (%date%)",
    String,
    "DefaultReason",
  );
  registerWorldSetting(XP_AWARD_SETTINGS.defaultSelection, "party", String, "DefaultSelection", {
    choices: {
      company: `${LOCALIZATION_NAMESPACE}.Settings.XpAward.DefaultSelection.Company`,
      party: `${LOCALIZATION_NAMESPACE}.Settings.XpAward.DefaultSelection.Party`,
      world: `${LOCALIZATION_NAMESPACE}.Settings.XpAward.DefaultSelection.World`,
    },
  });
  registerWorldSetting(
    XP_AWARD_SETTINGS.includeTimestampInReason,
    true,
    Boolean,
    "IncludeTimestampInReason",
  );

  game.settings.registerMenu(MODULE_ID, "xpAwardConsole", {
    hint: `${LOCALIZATION_NAMESPACE}.Menu.XpAwardConsole.Hint`,
    icon: "fa-solid fa-award",
    label: `${LOCALIZATION_NAMESPACE}.Menu.XpAwardConsole.Label`,
    name: `${LOCALIZATION_NAMESPACE}.Menu.XpAwardConsole.Name`,
    restricted: XpAwardConsoleApplication.ACCESS_POLICY.gmOnly,
    type: XpAwardConsoleApplication,
  });
}

function registerWorldSetting(
  key: string,
  defaultValue: boolean | number | string,
  type: BooleanConstructor | NumberConstructor | StringConstructor,
  localizationKey: string,
  options: Pick<FoundrySettingConfig, "choices" | "range"> = {},
): void {
  registerHiddenWorldSetting(
    key,
    defaultValue,
    type,
    `${LOCALIZATION_NAMESPACE}.Settings.XpAward.${localizationKey}`,
    options,
  );
}
