import type { GmToolkitSettingValue } from "../../types/gm-toolkit/Migration";
import { ADMINISTRATION_SETTINGS } from "../administration/settings/keys";
import { ADVANTAGE_SETTINGS } from "../combat/settings/keys";
import { DARK_WHISPERS_SETTINGS } from "../dark-whispers/settings/keys";
import { GROUP_TEST_SETTINGS } from "../group-test/settings/keys";
import { SESSION_MANAGEMENT_SETTINGS } from "../session-management/settings/keys";
import { VISION_SETTINGS } from "../token-tools/settings/keys";
import { MODULE_ID } from "../constants";

const targets: Record<string, string> = {
  automateConditionAdvantage: ADVANTAGE_SETTINGS.automateCondition,
  automateDamageAdvantage: ADVANTAGE_SETTINGS.automateDamage,
  automateOpposedTestAdvantage: ADVANTAGE_SETTINGS.automateOpposed,
  bypassTestDialogGroupTest: GROUP_TEST_SETTINGS.bypassDialog,
  clearAdvantageCombatJoin: ADVANTAGE_SETTINGS.clearOnJoin,
  clearAdvantageCombatLeave: ADVANTAGE_SETTINGS.clearOnLeave,
  defaultDifficultyGroupTest: GROUP_TEST_SETTINGS.defaultDifficulty,
  defaultGroupDarkWhispers: DARK_WHISPERS_SETTINGS.defaultGroup,
  defaultPartyGroupTest: GROUP_TEST_SETTINGS.defaultGroup,
  defaultRollModeGroupTest: GROUP_TEST_SETTINGS.defaultRollMode,
  defaultSkillGroupTest: GROUP_TEST_SETTINGS.defaultSkill,
  defaultTestModifierGroupTest: GROUP_TEST_SETTINGS.defaultModifier,
  exportChat: SESSION_MANAGEMENT_SETTINGS.exportChat,
  fallbackAdjustDifficulty: GROUP_TEST_SETTINGS.fallbackDifficultySteps,
  fallbackAdvancedSkills: GROUP_TEST_SETTINGS.fallbackAdvanced,
  holdingScene: SESSION_MANAGEMENT_SETTINGS.holdingSceneUuid,
  messageDarkWhispers: DARK_WHISPERS_SETTINGS.messageStyle,
  overrideDarkVision: VISION_SETTINGS.overrideDarkVision,
  overrideNightVision: VISION_SETTINGS.overrideNightVision,
  persistAdvantageNotifications: ADVANTAGE_SETTINGS.persistentNotifications,
  promptMomentumLoss: ADVANTAGE_SETTINGS.promptMomentumLoss,
  quicktest1GroupTest: GROUP_TEST_SETTINGS.quickTest1,
  quicktest2GroupTest: GROUP_TEST_SETTINGS.quickTest2,
  quicktest3GroupTest: GROUP_TEST_SETTINGS.quickTest3,
  quicktest4GroupTest: GROUP_TEST_SETTINGS.quickTest4,
  rangeDarkVision: VISION_SETTINGS.darkRange,
  rangeNormalSight: VISION_SETTINGS.normalRange,
  scenePullActivate: SESSION_MANAGEMENT_SETTINGS.pullPolicy,
  summariseResultsThresholdGroupTest: GROUP_TEST_SETTINGS.summaryThreshold,
  suppressSpectatorNotice: ADMINISTRATION_SETTINGS.showUnassignedPlayerWarning,
};

export function getGmToolkitFeatureTargetValues(): Record<string, boolean | number | string> {
  return Object.fromEntries(
    Object.entries(targets).map(([sourceKey, targetKey]) => {
      const value = game.settings.get(MODULE_ID, targetKey);
      return [sourceKey, inverseTransform(sourceKey, value)];
    }),
  );
}

export async function applyGmToolkitFeatureSetting(
  sourceKey: string,
  value: GmToolkitSettingValue,
): Promise<void> {
  const targetKey = targets[sourceKey];
  if (!targetKey) throw new Error(`No Drowsy setting target exists for ${sourceKey}.`);
  await game.settings.set(MODULE_ID, targetKey, await transform(sourceKey, value));
}

export async function validateGmToolkitFeatureSetting(
  sourceKey: string,
  value: GmToolkitSettingValue,
): Promise<void> {
  if (!targets[sourceKey]) throw new Error(`No Drowsy setting target exists for ${sourceKey}.`);
  await transform(sourceKey, value);
}

async function transform(
  sourceKey: string,
  value: GmToolkitSettingValue,
): Promise<boolean | number | string> {
  if (sourceKey === "holdingScene") return resolveSceneUuid(String(value));
  if (sourceKey === "scenePullActivate")
    return value === "always" ? "activate" : value === "prompt" ? "prompt" : "pull";
  if (sourceKey === "suppressSpectatorNotice") return value !== true;
  if (sourceKey === "messageDarkWhispers")
    return value === "tempt" || value === "offer" ? "offer" : value === "plain" ? "plain" : "taunt";
  return primitive(value);
}

function resolveSceneUuid(name: string): string {
  const normalized = name.trim();
  if (!normalized) return "";
  const scenes = Array.from(
    (game as unknown as { scenes: Iterable<{ name: string; uuid: string }> }).scenes,
  );
  const matches = scenes.filter(
    (scene) => scene.name.localeCompare(normalized, undefined, { sensitivity: "accent" }) === 0,
  );
  if (matches.length === 0)
    throw new Error(
      `Holding Scene “${normalized}” was not found. Choose it manually in Session Management.`,
    );
  if (matches.length > 1)
    throw new Error(
      `More than one Scene is named “${normalized}”. Choose it manually in Session Management.`,
    );
  return matches[0]!.uuid;
}

function inverseTransform(sourceKey: string, value: unknown): boolean | number | string {
  if (sourceKey === "holdingScene") {
    const uuid = String(value ?? "");
    const scene = Array.from(
      (game as unknown as { scenes?: Iterable<{ name: string; uuid: string }> }).scenes ?? [],
    ).find((candidate) => candidate.uuid === uuid);
    return scene?.name ?? "";
  }
  if (sourceKey === "scenePullActivate")
    return value === "activate" ? "always" : value === "prompt" ? "prompt" : "never";
  if (sourceKey === "suppressSpectatorNotice") return value !== true;
  if (sourceKey === "messageDarkWhispers") return value === "offer" ? "tempt" : primitive(value);
  return primitive(value);
}

function primitive(value: unknown): boolean | number | string {
  return typeof value === "boolean" || typeof value === "number" || typeof value === "string"
    ? value
    : "";
}
