<script setup lang="ts">
import { sessionLogText } from "../../../../functions/session-management/submission";
import { storeToRefs } from "pinia";
import { useSessionManagementStore } from "../../../../state/apps/session-management/store";
const { state } = storeToRefs(useSessionManagementStore());
function formatDateTime(value: string): string {
  return new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(
    new Date(value),
  );
}
</script>
<template>
  <section
    id="session-log"
    role="tabpanel"
    aria-labelledby="session-tab-log"
    class="tw:min-h-0 tw:flex-1 tw:overflow-y-auto tw:p-4"
  >
    <p v-if="!state.sessions.length" class="tw:text-sm">No sessions recorded yet.</p>
    <ol v-else class="tw:m-0 tw:grid tw:[list-style:none] tw:gap-2 tw:p-0">
      <li
        v-for="record in state.sessions"
        :key="record.id"
        class="tw:rounded-box tw:border tw:border-base-content/15 tw:bg-base-100! tw:p-3"
      >
        <p class="tw:m-0 tw:text-sm">
          {{ sessionLogText(record.reference, record.occurredAt) }}
        </p>
        <p class="tw:mt-1 tw:mb-0 tw:text-xs tw:text-base-content/65!">
          Recorded {{ formatDateTime(record.recordedAt) }}
        </p>
      </li>
    </ol>
  </section>
</template>
