import { computed } from "vue";

import {
  buildCatchUpGraphProjection,
  calculateCatchUpGraphBounds,
  calculateCatchUpPointerUpdate,
  calculateCatchUpReferenceKeyboardUpdate,
  calculateCurveExponentKeyboardUpdate,
  projectCatchUpGraphY,
  projectGraphX,
} from "../../../../functions/xp-curve/graph";
import type { CatchUpGraphBounds } from "../../../../types/xp-curve/Graph";
import type { XpAward, XpCurveSample } from "../../../../types/xp-curve/XpCurve";
import { type ActiveGraphDrag, useGraphDrag } from "./graph/drag";
import { getGraphPointerPosition } from "./graphMath";

type DragKind = "reference" | "shape";

export interface CatchUpGraphProps {
  awards: XpAward[];
  curveExponent: number;
  gapForMaximumAward: number;
  maximumAward: number;
  samples: XpCurveSample[];
}

export type CatchUpGraphEmit = {
  (event: "update:curveExponent", value: number): void;
  (event: "update:gapForMaximumAward", value: number): void;
  (event: "update:maximumAward", value: number): void;
};

export function useCatchUpGraph(props: CatchUpGraphProps, emit: CatchUpGraphEmit) {
  const calculatedBounds = computed(() =>
    calculateCatchUpGraphBounds(
      props.gapForMaximumAward,
      props.maximumAward,
      props.samples,
      props.awards,
    ),
  );
  const { activeDrag, beginDrag, endDrag, updateDrag } = useGraphDrag<DragKind, CatchUpGraphBounds>(
    () => ({ ...calculatedBounds.value }),
    updateFromPointer,
  );
  const bounds = computed(() => activeDrag.value?.snapshot ?? calculatedBounds.value);
  const projection = computed(() =>
    buildCatchUpGraphProjection({
      awards: props.awards,
      bounds: bounds.value,
      curveExponent: props.curveExponent,
      gapForMaximumAward: props.gapForMaximumAward,
      maximumAward: props.maximumAward,
      samples: props.samples,
    }),
  );
  const maximumGap = computed(() => bounds.value.maximumGap);
  const points = computed(() => projection.value.points);
  const recipientLegend = computed(() => projection.value.recipientLegend);
  const recipientPoints = computed(() => projection.value.recipientPoints);
  const referencePoint = computed(() => projection.value.referencePoint);
  const shapePoint = computed(() => projection.value.shapePoint);

  function toGraphX(gap: number): number {
    return projectGraphX(gap, bounds.value.maximumGap);
  }

  function toGraphY(value: number): number {
    return projectCatchUpGraphY(value, bounds.value.maximumValue);
  }

  function updateFromPointer(
    drag: ActiveGraphDrag<DragKind, CatchUpGraphBounds>,
    event: PointerEvent,
  ): void {
    const update = calculateCatchUpPointerUpdate(
      drag.kind,
      getGraphPointerPosition(drag.svg, event),
      drag.snapshot,
      props.maximumAward,
    );

    if (update.kind === "reference") {
      emit("update:gapForMaximumAward", update.gapForMaximumAward);
      emit("update:maximumAward", update.maximumAward);
      return;
    }

    emit("update:curveExponent", update.curveExponent);
  }

  function updateReferenceWithKeyboard(event: KeyboardEvent): void {
    const update = calculateCatchUpReferenceKeyboardUpdate(
      event.key,
      props.gapForMaximumAward,
      props.maximumAward,
    );

    if (!update) {
      return;
    }

    event.preventDefault();

    if (update.gapForMaximumAward !== undefined) {
      emit("update:gapForMaximumAward", update.gapForMaximumAward);
    }

    if (update.maximumAward !== undefined) {
      emit("update:maximumAward", update.maximumAward);
    }
  }

  function updateShapeWithKeyboard(event: KeyboardEvent): void {
    const curveExponent = calculateCurveExponentKeyboardUpdate(
      event.key,
      props.curveExponent,
      0.1,
      5,
    );

    if (curveExponent === undefined) {
      return;
    }

    event.preventDefault();
    emit("update:curveExponent", curveExponent);
  }

  return {
    beginDrag,
    endDrag,
    maximumGap,
    points,
    recipientLegend,
    recipientPoints,
    referencePoint,
    shapePoint,
    toGraphX,
    toGraphY,
    updateDrag,
    updateReferenceWithKeyboard,
    updateShapeWithKeyboard,
  };
}
