import type { ToolkitApplicationHandle } from "../../../types/module/api/ModuleApi";
import { MODULE_ID } from "../../constants";
import { XpCurveConsoleApplication } from "./XpCurveConsoleApplication";

export async function openXpCurveConsole(): Promise<ToolkitApplicationHandle> {
  const application = new XpCurveConsoleApplication();
  await application.render(true);

  return application;
}

export function openXpCurveConsoleFromUi(): void {
  void openXpCurveConsole().catch((error: unknown) => {
    console.error(`${MODULE_ID} | Failed to open the XP Curve Console.`, error);
    ui.notifications.error(
      "Drowsy’s WFRP4e Toolkit could not open the XP Curve Console. See the browser console for details.",
    );
  });
}
