import { ref } from "vue";
import { defineStore } from "pinia";

import type {
  FearConsoleConfiguration,
  FearConsoleConfiguratorActions,
} from "../../../types/fear-terror/Configuration";

export const useFearConsoleConfiguratorStore = defineStore("fear-console-configurator", () => {
  const configuration = ref<FearConsoleConfiguration>({
    launchers: {
      actorSheet: true,
      tokenControls: true,
    },
  });
  const errorMessage = ref<undefined | string>();
  const statusMessage = ref<undefined | string>();
  const isSaving = ref(false);
  let configuratorActions: FearConsoleConfiguratorActions | undefined;

  function initialize(
    nextConfiguration: FearConsoleConfiguration,
    actions: FearConsoleConfiguratorActions,
  ): void {
    configuratorActions = actions;
    configuration.value = {
      launchers: { ...nextConfiguration.launchers },
    };
    errorMessage.value = undefined;
    statusMessage.value = undefined;
  }

  async function saveConfiguration(): Promise<void> {
    if (isSaving.value) {
      return;
    }

    isSaving.value = true;
    errorMessage.value = undefined;
    statusMessage.value = undefined;

    try {
      await getConfiguratorActions().saveConfiguration({
        launchers: { ...configuration.value.launchers },
      });
      statusMessage.value = "Launcher preferences saved. Reload Foundry to apply them.";
    } catch (error) {
      console.error("Drowsy’s WFRP4e Toolkit | Fear configuration save failed.", error);
      errorMessage.value =
        error instanceof Error
          ? error.message
          : "The Fear Console configuration could not be saved.";
    } finally {
      isSaving.value = false;
    }
  }

  function getConfiguratorActions(): FearConsoleConfiguratorActions {
    if (!configuratorActions) {
      throw new Error("The Fear Console Configurator has not been initialized.");
    }

    return configuratorActions;
  }

  return {
    configuration,
    errorMessage,
    initialize,
    isSaving,
    saveConfiguration,
    statusMessage,
  };
});
