export async function importGmToolkitSettings(
  request: GmToolkitImportRequest,
): Promise<GmToolkitMigrationSnapshot> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.gmToolkitMigration);
  const preview = getGmToolkitImportPreview();

  if (!preview?.source) {
    throw new Error("No installed module or persisted GM Toolkit world settings were found.");
  }

  const appliedFields = Array.from(new Set(request.fields)).filter(isGmToolkitImportField);

  if (!appliedFields.length) {
    throw new Error("Select at least one value to import.");
  }

  const featureFields = appliedFields.filter(
    (field) =>
      !["defaultXpAmount", "defaultXpReason", "defaultXpSelection", "sessionReference"].includes(
        field,
      ),
  );
  featureFields.sort((left, right) =>
    left === "holdingScene" ? -1 : right === "holdingScene" ? 1 : 0,
  );
  for (const field of featureFields) {
    const sourceSetting = preview.source.settings.find((setting) => setting.key === field);
    if (sourceSetting) await validateGmToolkitFeatureSetting(field, sourceSetting.value);
  }

  const sessionState = getSessionManagementState();
  const result = applyGmToolkitImportSelections(
    preview,
    {
      sessionReference: sessionState.currentSessionReference,
      xpAwardSettings: getXpAwardSettings(),
    },
    appliedFields,
  );
  const snapshot: GmToolkitMigrationSnapshot = {
    appliedFields,
    importedAt: new Date().toISOString(),
    sessionReference: result.sessionReference,
    source: preview.source,
    version: 2,
    xpAwardSettings: result.xpAwardSettings,
  };

  if (
    appliedFields.some((field) =>
      ["defaultXpAmount", "defaultXpReason", "defaultXpSelection"].includes(field),
    )
  ) {
    await saveXpAwardSettings(snapshot.xpAwardSettings);
  }
  if (appliedFields.includes("sessionReference")) {
    await saveSessionManagementState({
      ...sessionState,
      currentSessionReference: snapshot.sessionReference,
    });
  }
  for (const field of featureFields) {
    const sourceSetting = preview.source.settings.find((setting) => setting.key === field);
    if (sourceSetting) await applyGmToolkitFeatureSetting(field, sourceSetting.value);
  }
  await saveGmToolkitMigrationState({
    ...getGmToolkitMigrationState(),
    migration: snapshot,
    version: 1,
  });
  ui.notifications.info(
    `${appliedFields.length} value${appliedFields.length === 1 ? "" : "s"} imported into Drowsy’s Toolkit.`,
  );

  return snapshot;
}

/** @deprecated Use importGmToolkitSettings. */
export const importGmToolkitSessionData = importGmToolkitSettings;

export async function importGmToolkitDarkWhispers(
  request: GmToolkitDarkWhispersImportRequest,
): Promise<GmToolkitDarkWhispersImportResult> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.gmToolkitMigration);
  const preview = getGmToolkitImportPreview();

  if (!preview) {
    throw new Error("No GM Toolkit Dark Whispers table was found.");
  }

  const result = applyGmToolkitDarkWhispersImport(
    preview.darkWhispers,
    getDarkWhispersPromptLibrary(),
    request,
    new Date().toISOString(),
  );
  await saveDarkWhispersPromptLibrary(result.library);
  const refreshedPreview = getGmToolkitImportPreview();

  if (!refreshedPreview) {
    throw new Error("The Dark Whispers prompts were saved but could not be reloaded.");
  }

  ui.notifications.info(
    `${result.added} Dark Whispers prompt${result.added === 1 ? "" : "s"} added, ${result.replaced} replaced, and ${result.skipped} unchanged.`,
  );

  return { ...result, preview: refreshedPreview };
}

export async function remapGmToolkitLaunchers(
  request: GmToolkitLauncherRemapRequest,
): Promise<GmToolkitLauncherRemapResult> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.gmToolkitMigration);
  const currentUser = game.user;

  if (!currentUser) {
    throw new Error("The current Foundry user is unavailable.");
  }

  const preview = getGmToolkitLauncherMigrationPreview();
  const assignments = buildGmToolkitLauncherAssignments(preview, request.slots);

  if (!assignments.length) {
    throw new Error("Select at least one standard hotbar launcher with an available replacement.");
  }

  const resolvedLaunchers = new Map<string, Awaited<ReturnType<typeof resolveDrowsyLauncher>>>();

  for (const assignment of assignments) {
    let resolved = resolvedLaunchers.get(assignment.macroId);

    if (!resolved) {
      resolved = await resolveDrowsyLauncher(assignment.macroId);
      resolvedLaunchers.set(assignment.macroId, resolved);
    }

    await currentUser.assignHotbarMacro(resolved.macro, assignment.slot);
  }

  const importedLaunchers = Array.from(resolvedLaunchers.values()).filter(
    ({ imported }) => imported,
  ).length;
  ui.notifications.info(
    `${assignments.length} hotbar slot${assignments.length === 1 ? "" : "s"} remapped to Drowsy launchers.`,
  );

  return {
    importedLaunchers,
    preview: getGmToolkitLauncherMigrationPreview(),
    remappedSlots: assignments.length,
  };
}

export async function reviewGmToolkitCutover(): Promise<GmToolkitCutoverReviewResult> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.gmToolkitMigration);
  const currentUser = game.user;

  if (!currentUser) {
    throw new Error("The current Foundry user is unavailable.");
  }

  const state = getGmToolkitMigrationState();
  const report = getGmToolkitCutoverReport(undefined, state);

  if (!report) {
    throw new Error("No GM Toolkit data is available to review.");
  }

  const review = createGmToolkitCutoverReview(
    report,
    { id: currentUser.id, name: currentUser.name },
    new Date().toISOString(),
  );
  await saveGmToolkitMigrationState({ ...state, cutoverReview: review, version: 1 });
  ui.notifications.info("Migration review saved.");

  return { report, review };
}
