import type { Component } from "vue";

import type { XpAwardConsoleActions } from "../../../types/xp-award/Console";
import XpAwardConsoleApp from "../../../view/apps/xp-award-console/XpAwardConsoleApp.vue";
import { MODULE_ID, MODULE_TITLE } from "../../constants";
import { getXpAwardConsoleInitialization } from "../../xp-award/initialization";
import { applyFixedXpAwards } from "../../xp-award/service";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../access";
import { openXpAwardSettings } from "./XpAwardSettingsApplication";

export class XpAwardConsoleApplication extends FoundryVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.xpAwardConsole;

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    classes: [MODULE_ID, `${MODULE_ID}-xp-award-console`],
    id: `${MODULE_ID}-xp-award-console`,
    position: {
      height: 500,
      width: 700,
    },
    window: {
      icon: "fa-solid fa-award",
      resizable: true,
      title: `${MODULE_TITLE} — XP Award Console`,
    },
  };

  protected override getVueComponent(): Component {
    return XpAwardConsoleApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    const actions: XpAwardConsoleActions = {
      applyAwards: applyFixedXpAwards,
      openSettings: openXpAwardSettings,
      onActionComplete: () => {
        void this.close().catch((error: unknown) => {
          console.error(`${MODULE_ID} | Failed to close the XP Award Console.`, error);
          ui.notifications.error(
            "XP changes completed, but Drowsy’s WFRP4e Toolkit could not close the console.",
          );
        });
      },
    };

    return {
      actions,
      initialization: getXpAwardConsoleInitialization(),
    };
  }
}
