import { LOCALIZATION_NAMESPACE, MODULE_ID } from "../../constants";
import { VISION_SETTINGS } from "./keys";
export function registerTokenToolsSettings(): void {
  const defaults = {
    darkRange: 120,
    normalRange: 2,
    overrideDarkVision: false,
    overrideNightVision: false,
  };
  for (const [name, key] of Object.entries(VISION_SETTINGS)) {
    const value = defaults[name as keyof typeof defaults];
    game.settings.register(MODULE_ID, key, {
      config: false,
      default: value,
      hint: `${LOCALIZATION_NAMESPACE}.Settings.Vision.${name}.Hint`,
      name: `${LOCALIZATION_NAMESPACE}.Settings.Vision.${name}.Name`,
      scope: "world",
      type: typeof value === "boolean" ? Boolean : Number,
    });
  }
}
