import type { Component } from "vue";
import type { XpAwardSettingsActions } from "../../../types/xp-award/Console";
import type { XpAwardConsoleInitialization } from "../../../types/xp-award/XpAward";
import XpAwardSettingsApp from "../../../view/apps/xp-award-console/XpAwardSettingsApp.vue";
import { MODULE_ID, MODULE_TITLE } from "../../constants";
import { getXpAwardConsoleInitialization } from "../../xp-award/initialization";
import { getXpAwardSettings, saveXpAwardSettings } from "../../xp-award/settings/load";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../access";

export class XpAwardSettingsApplication extends FoundryVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.xpAwardConsole;
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-xp-award-settings`,
    position: { width: 460, height: 530 },
    window: {
      title: `${MODULE_TITLE} — XP Award Settings`,
      icon: "fa-solid fa-gear",
      resizable: true,
    },
  };
  onSaved?: (data: XpAwardConsoleInitialization) => void;
  onClosed?: () => void;

  protected override getVueComponent(): Component {
    return XpAwardSettingsApp;
  }
  protected override getVueProps(): Record<string, unknown> {
    const actions: XpAwardSettingsActions = {
      save: async (settings) => {
        assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.xpAwardConsole);
        if (!Number.isSafeInteger(settings.defaultAmount) || settings.defaultAmount === 0)
          throw new Error("Enter a non-zero whole-number XP amount.");
        await saveXpAwardSettings(settings);
        this.onSaved?.(getXpAwardConsoleInitialization());
        await this.close();
      },
    };
    return { actions, initialization: getXpAwardSettings() };
  }
  protected override async _preClose(
    options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<void> {
    await super._preClose(options);
    this.onClosed?.();
  }
}

export async function openXpAwardSettings(
  onSaved: (data: XpAwardConsoleInitialization) => void,
): Promise<void> {
  const application = new XpAwardSettingsApplication();
  application.onSaved = onSaved;
  const closed = new Promise<void>((resolve) => {
    application.onClosed = resolve;
  });
  await application.render(true);
  await closed;
}
