import { isRecord, readString } from "../records/parse";
import type {
  GmToolkitImportComparison,
  GmToolkitImportField,
  GmToolkitImportItem,
  GmToolkitMigrationPreview,
  GmToolkitDarkWhispersMigrationPreview,
  GmToolkitSettingDefinition,
  GmToolkitSettingDisposition,
  GmToolkitSettingSnapshot,
  GmToolkitSettingValue,
  GmToolkitSettingValueSource,
  GmToolkitSourceSnapshot,
} from "../../types/gm-toolkit/Migration";
import type { XpAwardSettings } from "../../types/xp-award/XpAward";
import type { GmToolkitLauncherMigrationPreview } from "../../types/gm-toolkit/LauncherMigration";
import { GM_TOOLKIT_IMPORT_FIELDS, GM_TOOLKIT_IMPORT_LABELS } from "./import-fields";

export function normalizeGmToolkitSetting(
  definition: GmToolkitSettingDefinition,
  value: unknown,
  source: GmToolkitSettingValueSource,
): GmToolkitSettingSnapshot {
  const normalized = normalizeValue(definition, value);

  return {
    disposition: definition.disposition,
    family: definition.family,
    key: definition.key,
    source,
    valid: normalized.valid,
    value: normalized.value,
  };
}

export function buildGmToolkitMigrationPreview(
  source: GmToolkitSourceSnapshot,
  target: {
    featureSettings?: Record<string, boolean | number | string>;
    sessionReference: string;
    xpAwardSettings: XpAwardSettings;
  },
  darkWhispers: GmToolkitDarkWhispersMigrationPreview = {
    candidates: [],
    currentPromptCount: 0,
    warnings: [],
  },
  launchers: GmToolkitLauncherMigrationPreview = {
    candidates: [],
    counts: { ambiguous: 0, customized: 0, standard: 0 },
    remappableSlots: [],
    version: 1,
    warnings: [],
  },
): GmToolkitMigrationPreview {
  const imports = [
    createImport(source, target, "sessionReference", "sessionID", "Session reference"),
    createImport(source, target, "defaultXpAmount", "addXPDefaultAmount", "XP amount"),
    createImport(source, target, "defaultXpSelection", "defaultPartySessionTurnover", "Recipients"),
    createImport(source, target, "defaultXpReason", "addXPDefaultReason", "XP reason"),
    ...GM_TOOLKIT_IMPORT_FIELDS.slice(4).map((field) =>
      createFeatureImport(source, target.featureSettings ?? {}, field),
    ),
  ];

  return {
    darkWhispers,
    dispositionCounts: countBy(source.settings, "disposition", [
      "import",
      "pending",
      "retire",
      "skip",
      "supersede",
    ]),
    imports,
    launchers,
    source,
    sourceCounts: countBy(source.settings, "source", ["baseline", "persisted", "registered"]),
    version: 1,
  };
}

function createFeatureImport(
  source: GmToolkitSourceSnapshot,
  target: Record<string, boolean | number | string>,
  sourceKey: GmToolkitImportField,
): GmToolkitImportItem {
  const setting = source.settings.find((candidate) => candidate.key === sourceKey);
  const sourceValue = toPrimitive(setting?.value);
  const currentValue = target[sourceKey] ?? "";
  return {
    comparison: compareValues(currentValue, sourceValue),
    currentValue,
    field: sourceKey,
    label: GM_TOOLKIT_IMPORT_LABELS[sourceKey] ?? sourceKey,
    sourceKey,
    sourceValue,
  };
}

export function parseGmToolkitSourceSnapshot(value: unknown): GmToolkitSourceSnapshot | undefined {
  if (!isRecord(value) || value["schemaVersion"] !== "9.2.0") {
    return undefined;
  }

  const settings = Array.isArray(value["settings"])
    ? value["settings"].flatMap(parseSettingSnapshot)
    : [];

  if (!settings.length) {
    return undefined;
  }

  const moduleVersion = readString(value["moduleVersion"]);

  return {
    active: value["active"] === true,
    installed: value["installed"] === true,
    ...(moduleVersion ? { moduleVersion } : {}),
    schemaVersion: "9.2.0",
    settings,
    warnings: Array.isArray(value["warnings"])
      ? value["warnings"].filter((warning): warning is string => typeof warning === "string")
      : [],
  };
}

export function isGmToolkitImportField(value: unknown): value is GmToolkitImportField {
  return (
    typeof value === "string" && GM_TOOLKIT_IMPORT_FIELDS.includes(value as GmToolkitImportField)
  );
}

function createImport(
  source: GmToolkitSourceSnapshot,
  target: { sessionReference: string; xpAwardSettings: XpAwardSettings },
  field: GmToolkitImportField,
  sourceKey: string,
  label: string,
): GmToolkitImportItem {
  const setting = source.settings.find((candidate) => candidate.key === sourceKey);
  const sourceValue = normalizeImportValue(field, setting?.value);
  const currentValue = readTargetValue(field, target);

  return {
    comparison: compareValues(currentValue, sourceValue),
    currentValue,
    field,
    label,
    sourceKey,
    sourceValue,
  };
}

function normalizeImportValue(
  field: GmToolkitImportField,
  value: GmToolkitSettingValue | undefined,
): number | string {
  if (field === "defaultXpAmount") {
    const amount = Number(value);
    return Number.isFinite(amount) ? Math.round(amount) : 0;
  }

  if (field === "defaultXpSelection") {
    return value === "company" ? "company" : "party";
  }

  return typeof value === "string" && value !== "null" ? value : "";
}

function readTargetValue(
  field: GmToolkitImportField,
  target: { sessionReference: string; xpAwardSettings: XpAwardSettings },
): number | string {
  switch (field) {
    case "sessionReference":
      return target.sessionReference;
    case "defaultXpAmount":
      return target.xpAwardSettings.defaultAmount;
    case "defaultXpReason":
      return target.xpAwardSettings.defaultReason;
    case "defaultXpSelection":
      return target.xpAwardSettings.defaultSelection;
  }
}

function compareValues(
  currentValue: boolean | number | string,
  sourceValue: boolean | number | string,
): GmToolkitImportComparison {
  if (currentValue === sourceValue) {
    return "same";
  }

  return currentValue === "" ? "target-empty" : "different";
}

function toPrimitive(value: GmToolkitSettingValue | undefined): boolean | number | string {
  return typeof value === "boolean" || typeof value === "number" || typeof value === "string"
    ? value
    : "";
}

function normalizeValue(
  definition: GmToolkitSettingDefinition,
  value: unknown,
): { valid: boolean; value: GmToolkitSettingValue } {
  if (definition.kind === "array") {
    return Array.isArray(value)
      ? { valid: true, value }
      : { valid: false, value: definition.defaultValue };
  }

  if (definition.kind === "boolean") {
    return typeof value === "boolean"
      ? { valid: true, value }
      : { valid: false, value: definition.defaultValue };
  }

  if (definition.kind === "number") {
    const numericValue = Number(value);
    return Number.isFinite(numericValue)
      ? { valid: true, value: numericValue }
      : { valid: false, value: definition.defaultValue };
  }

  return typeof value === "string"
    ? { valid: true, value }
    : { valid: false, value: definition.defaultValue };
}

function parseSettingSnapshot(value: unknown): GmToolkitSettingSnapshot[] {
  if (!isRecord(value)) {
    return [];
  }

  const disposition = value["disposition"];
  const family = value["family"];
  const source = value["source"];
  const settingValue = value["value"];

  if (
    !isDisposition(disposition) ||
    !isFamily(family) ||
    !isValueSource(source) ||
    !isSettingValue(settingValue)
  ) {
    return [];
  }

  return [
    {
      disposition,
      family,
      key: readString(value["key"]),
      source,
      valid: value["valid"] === true,
      value: settingValue,
    },
  ];
}

function countBy<
  T extends GmToolkitSettingSnapshot,
  K extends "disposition" | "source",
  V extends T[K] & string,
>(items: readonly T[], key: K, values: readonly V[]): Record<V, number> {
  return Object.fromEntries(
    values.map((value) => [value, items.filter((item) => item[key] === value).length]),
  ) as Record<V, number>;
}

function isDisposition(value: unknown): value is GmToolkitSettingDisposition {
  return ["import", "pending", "retire", "skip", "supersede"].includes(String(value));
}

function isFamily(value: unknown): value is GmToolkitSettingSnapshot["family"] {
  return [
    "advantage",
    "dark-whispers",
    "group-tests",
    "session",
    "spectators",
    "token-hud",
    "vision",
  ].includes(String(value));
}

function isValueSource(value: unknown): value is GmToolkitSettingValueSource {
  return ["baseline", "persisted", "registered"].includes(String(value));
}

function isSettingValue(value: unknown): value is GmToolkitSettingValue {
  return ["boolean", "number", "string"].includes(typeof value) || Array.isArray(value);
}
