import { defineStore } from "pinia";
import { computed, ref } from "vue";
import type {
  DamageConsoleActions,
  DamageConsoleInitialization,
  DamageProtection,
} from "../../../types/damage/Damage";

export const useDamageConsoleStore = defineStore("damage-console", () => {
  const actors = ref<DamageConsoleInitialization["actors"]>([]);
  const hitLocations = ref<DamageConsoleInitialization["hitLocations"]>([]);
  const formula = ref("1d10");
  const hitLocation = ref("body");
  const minimumOne = ref(true);
  const protection = ref<DamageProtection>("normal");
  const randomizeDamage = ref(true);
  const randomizeHitLocation = ref(false);
  const busy = ref(false);
  const errorMessage = ref("");
  let actions: DamageConsoleActions | undefined;
  const selectedUuids = computed(() =>
    actors.value.filter((actor) => actor.selected).map((actor) => actor.uuid),
  );

  function initialize(
    initialization: DamageConsoleInitialization,
    nextActions: DamageConsoleActions,
  ): void {
    actors.value = structuredClone(initialization.actors);
    hitLocations.value = initialization.hitLocations;
    actions = nextActions;
  }

  async function apply(): Promise<void> {
    busy.value = true;
    errorMessage.value = "";
    try {
      await getActions().applyDamage({
        formula: formula.value,
        hitLocation: hitLocation.value,
        minimumOne: minimumOne.value,
        protection: protection.value,
        randomizeDamage: randomizeDamage.value,
        randomizeHitLocation: randomizeHitLocation.value,
        uuids: selectedUuids.value,
      });
    } catch (error) {
      errorMessage.value = error instanceof Error ? error.message : "Damage could not be applied.";
    } finally {
      busy.value = false;
    }
  }

  function getActions(): DamageConsoleActions {
    if (!actions) throw new Error("The Damage Console has not been initialized.");
    return actions;
  }
  return {
    actors,
    apply,
    busy,
    errorMessage,
    formula,
    hitLocation,
    hitLocations,
    initialize,
    minimumOne,
    protection,
    randomizeDamage,
    randomizeHitLocation,
  };
});
