import type { GroupTestConsoleInitialization } from "../../types/group-test/GroupTest";
import { getActorChoices } from "../actors/selection";
import { getGroupTestSettings } from "./settings/load";
import { getGroupTestSkillNames } from "./skill-catalog";

export function getGroupTestConsoleInitialization(): GroupTestConsoleInitialization {
  const settings = getGroupTestSettings();
  return {
    actors: getActorChoices({ initial: settings.defaultGroup }),
    settings,
    skills: getGroupTestSkillNames(),
  };
}
