import { MODULE_ID } from "../constants";
import { ADMINISTRATION_SETTINGS } from "./settings/keys";

export function registerAdministrationHooks(): void {
  Hooks.on("getChatMessageContextOptions", (_html, optionsValue) => {
    const options = optionsValue as Array<Record<string, unknown>>;
    options.push({
      callback: updateChatFlavor,
      condition: () => game.user?.isGM === true,
      icon: '<i class="fa-solid fa-pen-fancy"></i>',
      name: "Edit message flavor",
    });
  });
}

export function warnAboutUnassignedPlayers(): void {
  if (game.settings.get(MODULE_ID, ADMINISTRATION_SETTINGS.showUnassignedPlayerWarning) !== true) {
    return;
  }
  const names = Array.from(game.users)
    .filter(
      (user) =>
        !user.isGM &&
        (user as FoundryUser & { active?: boolean }).active !== false &&
        !user.character,
    )
    .map(({ name }) => name);
  if (names.length > 0) {
    ui.notifications.warn(
      `${names.join(", ")} ${names.length === 1 ? "has" : "have"} no assigned character.`,
    );
  }
}

async function updateChatFlavor(elementValue: unknown): Promise<void> {
  try {
    const candidate =
      elementValue instanceof HTMLElement
        ? elementValue
        : (elementValue as { 0?: unknown } | undefined)?.[0];
    if (!(candidate instanceof HTMLElement)) {
      throw new Error("The selected chat message element is unavailable.");
    }
    const messageId =
      candidate.dataset["messageId"] ??
      candidate.closest<HTMLElement>("[data-message-id]")?.dataset["messageId"];
    const messages = (game as unknown as ChatFlavorGameRuntime).messages;
    const message = messageId ? messages.get(messageId) : undefined;
    if (!message) throw new Error("The selected chat message is no longer available.");
    const result = await foundry.applications.api.DialogV2.input({
      content: `<label class="form-group"><span>Flavor</span><input name="flavor" type="text" value="${foundry.utils.escapeHTML(message.flavor ?? "")}"></label>`,
      modal: true,
      ok: { icon: "fa-solid fa-check", label: "Apply" },
      position: { width: 420 },
      rejectClose: false,
      window: { title: "Edit message flavor" },
    });
    if (!result) return;
    const flavor = typeof result["flavor"] === "string" ? result["flavor"] : "";
    await message.update({ flavor });
  } catch (error) {
    ui.notifications.error(
      error instanceof Error ? error.message : "Chat flavor could not be updated.",
    );
  }
}

interface ChatFlavorGameRuntime {
  messages: {
    get: (
      id: string,
    ) => { flavor?: string; update: (data: { flavor: string }) => Promise<unknown> } | undefined;
  };
}
