import { resolveXpAwardReason } from "../xp-curve/reason";
import type { XpReasonContext } from "../../types/xp-curve/Console";

export function resolveFixedXpAwardReason(
  template: string,
  context: XpReasonContext & { datetime: string },
  includeTimestamp: boolean,
): string {
  let effectiveTemplate = template;

  if (includeTimestamp && !effectiveTemplate.includes("%datetime%")) {
    effectiveTemplate = effectiveTemplate.trim()
      ? `${effectiveTemplate} — awarded %datetime%`
      : "Awarded %datetime%";
  }

  return resolveXpAwardReason(effectiveTemplate, context);
}

export function formatXpAwardDateTime(isoDateTime: string): string {
  return `${isoDateTime.slice(0, 10)} ${isoDateTime.slice(11, 19)} UTC`;
}
