import type { FearConsoleOptions } from "../../../types/fear-terror/Console";
import type { ToolkitApplicationHandle } from "../../../types/module/api/ModuleApi";
import { MODULE_ID } from "../../constants";
import { FearConsoleApplication } from "./FearConsoleApplication";

export async function openFearConsole(
  options: FearConsoleOptions = {},
): Promise<ToolkitApplicationHandle> {
  const application = new FearConsoleApplication(options);
  await application.render(true);

  return application;
}

export function openFearConsoleFromUi(options: FearConsoleOptions = {}): void {
  void openFearConsole(options).catch((error: unknown) => {
    console.error(`${MODULE_ID} | Failed to open the Fear Console.`, error);
    ui.notifications.error(
      "Drowsy’s WFRP4e Toolkit could not open the Fear Console. See the browser console for details.",
    );
  });
}
