import type { ActorChoice } from "../../types/shared/ActorChoice";
import {
  buildActorChoices,
  type ActorSelectionCandidate,
  type ActorSelectionMode,
  type TokenActorSelectionCandidate,
} from "../../functions/actors/selection";

interface ActorDocumentRuntime extends FoundryActorDocument {
  uuid: string;
}

interface TokenRuntime {
  actor?: ActorDocumentRuntime | null;
  document: { uuid: string };
}

export function getActorChoices(
  options: {
    includeVehicles?: boolean;
    initial?: ActorSelectionMode;
  } = {},
): ActorChoice[] {
  const initial = options.initial ?? "targeted";
  const actors = Array.from(game.actors) as ActorDocumentRuntime[];
  const assigned = new Set(
    Array.from(game.users)
      .map((user) => user.character?.id)
      .filter((id): id is string => Boolean(id)),
  );
  const targeted = getCanvasTokens("targeted");
  const controlled = getCanvasTokens("controlled");
  return buildActorChoices({
    actors: actors.map(toActorSelectionCandidate),
    assignedActorIds: assigned,
    controlled: controlled.flatMap(toTokenActorSelectionCandidate),
    includeVehicles: options.includeVehicles === true,
    initial,
    targeted: targeted.flatMap(toTokenActorSelectionCandidate),
  });
}

export async function resolveActors(uuids: readonly string[]): Promise<ActorDocumentRuntime[]> {
  const actors: ActorDocumentRuntime[] = [];
  for (const uuid of [...new Set(uuids)]) {
    const document = (await fromUuid(uuid)) as
      | ActorDocumentRuntime
      | { actor?: ActorDocumentRuntime | null }
      | null;
    const actor = document && "actor" in document ? document.actor : document;
    if (actor && "documentName" in actor && actor.documentName === "Actor") actors.push(actor);
  }
  return actors;
}

function getCanvasTokens(mode: "controlled" | "targeted"): TokenRuntime[] {
  const runtime = canvas as
    | {
        tokens?: {
          controlled?: TokenRuntime[];
        };
      }
    | undefined;
  if (mode === "controlled") return runtime?.tokens?.controlled ?? [];
  return Array.from((game.user?.targets ?? new Set()) as Set<TokenRuntime>);
}

function toActorSelectionCandidate(actor: ActorDocumentRuntime): ActorSelectionCandidate {
  return {
    actorType: actor.type,
    hasPlayerOwner: actor.hasPlayerOwner,
    id: actor.id,
    label: actor.name,
    uuid: actor.uuid,
  };
}

function toTokenActorSelectionCandidate(token: TokenRuntime): TokenActorSelectionCandidate[] {
  return token.actor
    ? [{ actor: toActorSelectionCandidate(token.actor), tokenUuid: token.document.uuid }]
    : [];
}
