<script setup lang="ts">
import { computed } from "vue";

import { getSelectedGmToolkitDarkWhispersCandidate } from "../../../functions/gm-toolkit/content-selection";
import type { GmToolkitDarkWhispersMigrationPreview } from "../../../types/gm-toolkit/Migration";

const props = defineProps<{
  conflictPolicy: "preserve" | "replace";
  isWorking: boolean;
  preview: GmToolkitDarkWhispersMigrationPreview;
  selectedTableId: string;
  selections: Record<string, boolean>;
}>();

const emit = defineEmits<{
  "import": [];
  "selectionChange": [resultId: string, selected: boolean];
  "tableChange": [tableId: string];
  "update:conflictPolicy": [policy: "preserve" | "replace"];
}>();

const selectedCandidate = computed(() =>
  getSelectedGmToolkitDarkWhispersCandidate(props.preview, props.selectedTableId),
);
const selectedCount = computed(
  () => Object.values(props.selections).filter((selected) => selected).length,
);
const hasConflicts = computed(() =>
  selectedCandidate.value?.prompts.some((prompt) => prompt.comparison === "conflict"),
);

function comparisonLabel(comparison: string): string {
  if (comparison === "same") return "Already imported";
  if (comparison === "duplicate") return "Same text exists";
  if (comparison === "conflict") return "Source changed";
  return "New prompt";
}

function updateSelection(resultId: string, event: Event): void {
  const input = event.currentTarget;
  emit("selectionChange", resultId, input instanceof HTMLInputElement && input.checked);
}

function updateTable(event: Event): void {
  const input = event.currentTarget;
  emit("tableChange", input instanceof HTMLSelectElement ? input.value : "");
}

function updateConflictPolicy(event: Event): void {
  const input = event.currentTarget;
  emit(
    "update:conflictPolicy",
    input instanceof HTMLSelectElement && input.value === "replace" ? "replace" : "preserve",
  );
}
</script>

<template>
  <section
    class="dui-card dui-card-border tw:min-w-0 tw:border-2 tw:border-secondary/40! tw:bg-base-100! tw:shadow-md"
    aria-labelledby="gm-toolkit-content-title"
  >
    <div class="dui-card-body tw:min-w-0 tw:gap-3 tw:p-4">
      <div class="tw:flex tw:flex-wrap tw:items-start tw:justify-between tw:gap-3">
        <div class="tw:min-w-0 tw:flex-1">
          <div class="tw:flex tw:flex-wrap tw:items-center tw:gap-2">
            <h2 id="gm-toolkit-content-title" class="dui-card-title tw:font-serif tw:text-lg">
              Dark Whispers prompts
            </h2>
            <span class="dui-badge dui-badge-sm">
              {{ preview.currentPromptCount }} in Drowsy library
            </span>
          </div>
          <p class="tw:m-0 tw:text-sm tw:text-base-content/70!">
            Copy selected prompt text into Drowsy-owned world data. The original RollTable remains
            unchanged.
          </p>
        </div>
        <button
          class="dui-btn dui-btn-sm tw:border-secondary! tw:text-base-content!"
          :disabled="isWorking || selectedCount === 0 || !selectedCandidate"
          type="button"
          @click="emit('import')"
        >
          <span
            v-if="isWorking"
            class="dui-loading dui-loading-spinner dui-loading-sm"
            aria-hidden="true"
          />
          <i v-else class="fa-solid fa-file-import" aria-hidden="true" />
          Import {{ selectedCount || "selected" }} prompts
        </button>
      </div>

      <div v-if="preview.candidates.length" class="tw:grid tw:gap-3 tw:min-[42rem]:grid-cols-2">
        <label class="tw:grid tw:min-w-0 tw:gap-1">
          <span class="tw:text-sm tw:font-semibold">Source RollTable</span>
          <select
            class="dui-select dui-select-sm tw:w-full tw:border-base-content/25! tw:bg-base-100!"
            :value="selectedTableId"
            @change="updateTable"
          >
            <option
              v-for="candidate in preview.candidates"
              :key="candidate.tableId"
              :value="candidate.tableId"
            >
              {{ candidate.tableName }} — {{ candidate.prompts.length }} prompts
            </option>
          </select>
        </label>

        <label v-if="hasConflicts" class="tw:grid tw:min-w-0 tw:gap-1">
          <span class="tw:text-sm tw:font-semibold">Changed imported prompts</span>
          <select
            class="dui-select dui-select-sm tw:w-full tw:border-base-content/25! tw:bg-base-100!"
            :value="conflictPolicy"
            @change="updateConflictPolicy"
          >
            <option value="preserve">Keep Drowsy version</option>
            <option value="replace">Replace with source version</option>
          </select>
        </label>
      </div>

      <div
        v-if="selectedCandidate"
        class="tw:max-w-full tw:overflow-x-auto tw:rounded-box tw:border tw:border-base-content/20!"
      >
        <table class="dui-table dui-table-sm tw:min-w-[42rem]">
          <thead class="tw:bg-base-300/60!">
            <tr>
              <th scope="col">Import</th>
              <th scope="col">Roll</th>
              <th scope="col">Prompt text</th>
              <th scope="col">Comparison</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="prompt in selectedCandidate.prompts" :key="prompt.resultId">
              <td>
                <label class="tw:flex tw:cursor-pointer tw:items-center tw:gap-2">
                  <input
                    class="dui-checkbox dui-checkbox-sm"
                    :checked="selections[prompt.resultId]"
                    type="checkbox"
                    @change="updateSelection(prompt.resultId, $event)"
                  />
                  <span class="tw:sr-only">Import Dark Whispers prompt {{ prompt.range }}</span>
                </label>
              </td>
              <td class="tw:tabular-nums">{{ prompt.range }}</td>
              <th class="tw:max-w-md tw:whitespace-normal" scope="row">{{ prompt.text }}</th>
              <td>
                <span class="dui-badge dui-badge-sm">
                  {{ comparisonLabel(prompt.comparison) }}
                </span>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      <div v-else class="dui-alert" role="status">
        <i class="fa-solid fa-table-list" aria-hidden="true" />
        <span>No imported GM Toolkit Dark Whispers RollTable is available to copy.</span>
      </div>

      <div
        v-for="warning in [...preview.warnings, ...(selectedCandidate?.warnings ?? [])]"
        :key="warning"
        class="dui-alert dui-alert-warning tw:py-2 tw:text-xs"
        role="alert"
      >
        <i class="fa-solid fa-triangle-exclamation" aria-hidden="true" />
        <span>{{ warning }}</span>
      </div>
    </div>
  </section>
</template>
