import { defineStore } from "pinia";
import { computed, ref } from "vue";
import type {
  DarkWhispersConsoleActions,
  DarkWhispersConsoleInitialization,
  DarkWhispersSettings,
} from "../../../types/dark-whispers/Console";
import type { DarkWhispersPrompt } from "../../../types/dark-whispers/PromptLibrary";

export const useDarkWhispersConsoleStore = defineStore("dark-whispers-console", () => {
  const prompts = ref<DarkWhispersPrompt[]>([]);
  const recipients = ref<DarkWhispersConsoleInitialization["recipients"]>([]);
  const settings = ref<DarkWhispersSettings>();
  const message = ref("");
  const sendToOwners = ref(false);
  const busy = ref(false);
  const errorMessage = ref("");
  let actions: DarkWhispersConsoleActions | undefined;
  const eligibleRecipients = computed(() =>
    recipients.value.filter((recipient) => recipient.corruption > 0),
  );

  function initialize(
    initialization: DarkWhispersConsoleInitialization,
    nextActions: DarkWhispersConsoleActions,
  ): void {
    prompts.value = structuredClone(initialization.prompts);
    recipients.value = structuredClone(initialization.recipients);
    settings.value = structuredClone(initialization.settings);
    actions = nextActions;
    chooseRandom();
  }
  function chooseRandom(): void {
    if (prompts.value.length)
      message.value = prompts.value[Math.floor(Math.random() * prompts.value.length)]?.text ?? "";
  }
  function addPrompt(): void {
    prompts.value.push({ id: crypto.randomUUID(), text: "" });
  }
  function removePrompt(id: string): void {
    prompts.value = prompts.value.filter((prompt) => prompt.id !== id);
  }
  async function send(): Promise<void> {
    await run(() =>
      getActions().send({
        message: message.value,
        recipientUuids: recipients.value
          .filter((recipient) => recipient.selected)
          .map((recipient) => recipient.uuid),
        sendToOwners: sendToOwners.value,
      }),
    );
  }
  async function save(): Promise<void> {
    await run(() => getActions().save(prompts.value, getSettings()));
  }
  async function run(operation: () => Promise<void>): Promise<void> {
    busy.value = true;
    errorMessage.value = "";
    try {
      await operation();
    } catch (error) {
      errorMessage.value =
        error instanceof Error ? error.message : "The action could not be completed.";
    } finally {
      busy.value = false;
    }
  }
  function getActions(): DarkWhispersConsoleActions {
    if (!actions) throw new Error("The Dark Whispers Console has not been initialized.");
    return actions;
  }
  function getSettings(): DarkWhispersSettings {
    if (!settings.value) throw new Error("The Dark Whispers Console has not been initialized.");
    return settings.value;
  }
  return {
    addPrompt,
    busy,
    chooseRandom,
    eligibleRecipients,
    errorMessage,
    initialize,
    message,
    prompts,
    recipients,
    removePrompt,
    save,
    send,
    sendToOwners,
    settings,
  };
});
