import type { XpReasonContext } from "../../types/xp-curve/Console";

export function resolveXpAwardReason(template: string, context: XpReasonContext): string {
  return template
    .replaceAll("%session%", context.session)
    .replaceAll("%date%", context.date)
    .replaceAll("%datetime%", context.datetime ?? "")
    .replace(/\s+\(\s*\)\s*/g, " ")
    .replace(/\s{2,}/g, " ")
    .trim();
}

export function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
