import type {
  XpActorChoice,
  XpAwardPlan,
  XpCurveParameters,
  XpCurveSample,
  XpDecaySample,
} from "../../types/xp-curve/XpCurve";

const MINIMUM_POSITIVE_VALUE = 0.01;
const MAXIMUM_CALCULATED_XP = Number.MAX_SAFE_INTEGER;

export function normalizeXpCurveParameters(parameters: XpCurveParameters): XpCurveParameters {
  return {
    companionMultiplier: clamp(parameters.companionMultiplier, 0, 1),
    curveExponent: clamp(parameters.curveExponent, 0.1, 5),
    gapForMaximumAward: Math.max(1, normalizeWholeNumber(parameters.gapForMaximumAward)),
    maximumAward: Math.max(0, normalizeWholeNumber(parameters.maximumAward)),
    scaleExponent: clamp(parameters.scaleExponent, 0, 2),
    scalePivot: Math.max(1, normalizeWholeNumber(parameters.scalePivot)),
  };
}

export function calculateXpAwardPlan(
  actors: XpActorChoice[],
  parameters: XpCurveParameters,
): XpAwardPlan {
  const selectedActors = actors.filter((actor) => actor.selected);
  const normalizedParameters = normalizeXpCurveParameters(parameters);
  const highestXp = Math.max(0, ...selectedActors.map((actor) => actor.totalXp));
  const awards = selectedActors.map((actor) => {
    const beforeXp = normalizeWholeNumber(actor.totalXp);
    const gap = Math.max(0, highestXp - beforeXp);
    const recipientMultiplier =
      actor.category === "companion" ? normalizedParameters.companionMultiplier : 1;
    const catchUpValue = calculateCatchUpValue(gap, normalizedParameters);
    const decayMultiplier = calculateRecipientDecay(beforeXp, normalizedParameters);
    const modifiedAward = Math.max(
      0,
      Math.round(catchUpValue * decayMultiplier * recipientMultiplier),
    );
    const award = Math.min(normalizedParameters.maximumAward, modifiedAward);

    return {
      actorId: actor.id,
      actorName: actor.name,
      afterXp: beforeXp + award,
      award,
      beforeXp,
      catchUpValue,
      category: actor.category,
      decayMultiplier,
      gap,
      modifiedAward,
      recipientMultiplier,
    };
  });

  return {
    awards,
    highestXp,
    totalAward: awards.reduce((total, award) => total + award.award, 0),
  };
}

export function calculateAwardForGap(
  gap: number,
  recipientXp: number,
  parameters: XpCurveParameters,
  recipientMultiplier = 1,
): number {
  const normalizedParameters = normalizeXpCurveParameters(parameters);
  const catchUpValue = calculateCatchUpValue(gap, normalizedParameters);
  const decayMultiplier = calculateRecipientDecay(recipientXp, normalizedParameters);
  const normalizedRecipientMultiplier = clamp(recipientMultiplier, 0, 1);
  const modifiedAward = Math.round(catchUpValue * decayMultiplier * normalizedRecipientMultiplier);

  return Math.min(normalizedParameters.maximumAward, Math.max(0, modifiedAward));
}

export function calculateCatchUpValue(gap: number, parameters: XpCurveParameters): number {
  const normalizedParameters = normalizeXpCurveParameters(parameters);
  const normalizedGap = Math.max(0, Number.isFinite(gap) ? gap : 0);
  const progress = normalizedGap / normalizedParameters.gapForMaximumAward;
  const value = normalizedParameters.maximumAward * progress ** normalizedParameters.curveExponent;

  return Number.isFinite(value) ? Math.min(value, MAXIMUM_CALCULATED_XP) : MAXIMUM_CALCULATED_XP;
}

export function calculateRecipientDecay(
  recipientXp: number,
  parameters: XpCurveParameters,
): number {
  const normalizedParameters = normalizeXpCurveParameters(parameters);
  const normalizedRecipientXp = Math.max(0, Number.isFinite(recipientXp) ? recipientXp : 0);
  const scaleRatio = Math.min(
    1,
    normalizedParameters.scalePivot /
      Math.max(normalizedRecipientXp, normalizedParameters.scalePivot),
  );

  return scaleRatio ** normalizedParameters.scaleExponent;
}

export function sampleXpCurve(
  parameters: XpCurveParameters,
  requestedMaximumGap = parameters.gapForMaximumAward * 1.4,
  sampleCount = 24,
): XpCurveSample[] {
  const normalizedParameters = normalizeXpCurveParameters(parameters);
  const normalizedSampleCount = Math.max(2, normalizeWholeNumber(sampleCount));
  const maximumGap = Math.max(
    normalizedParameters.gapForMaximumAward * 1.4,
    Number.isFinite(requestedMaximumGap) ? requestedMaximumGap : 0,
  );

  return Array.from({ length: normalizedSampleCount + 1 }, (_, index) => {
    const gap = (maximumGap * index) / normalizedSampleCount;

    return {
      award: calculateCatchUpValue(gap, normalizedParameters),
      gap,
    };
  });
}

export function sampleXpDecayCurve(
  parameters: XpCurveParameters,
  requestedMaximumRecipientXp = parameters.scalePivot * 4,
  sampleCount = 32,
): XpDecaySample[] {
  const normalizedParameters = normalizeXpCurveParameters(parameters);
  const normalizedSampleCount = Math.max(2, normalizeWholeNumber(sampleCount));
  const maximumRecipientXp = Math.max(
    1000,
    normalizedParameters.scalePivot * 4,
    Number.isFinite(requestedMaximumRecipientXp) ? requestedMaximumRecipientXp : 0,
  );

  return Array.from({ length: normalizedSampleCount + 1 }, (_, index) => {
    const recipientXp = (maximumRecipientXp * index) / normalizedSampleCount;

    return {
      multiplier: calculateRecipientDecay(recipientXp, normalizedParameters),
      recipientXp,
    };
  });
}

function clamp(value: number, minimum: number, maximum: number): number {
  const numericValue = Number(value);
  const finiteValue = Number.isFinite(numericValue) ? numericValue : MINIMUM_POSITIVE_VALUE;

  return Math.min(maximum, Math.max(minimum, finiteValue));
}

function normalizeWholeNumber(value: number): number {
  const numericValue = Number(value);

  return Number.isFinite(numericValue) ? Math.round(numericValue) : 0;
}
