import { MODULE_ID } from "../constants";
import {
  buildOpposedAdvantagePlan,
  selectMomentumLossActorIds,
} from "../../functions/combat/advantage";
import { addAdvantage, asAdvantageActor, setAdvantage } from "./advantage";
import { getAdvantageSettings } from "./settings/load";

const processedTests = new Set<string>();

export function registerCombatHooks(): void {
  Hooks.on("wfrp4e:opposedTestResult", handleOpposedTest);
  Hooks.on("wfrp4e:applyDamage", handleDamage);
  Hooks.on("createActiveEffect", handleCondition);
  Hooks.on("createCombatant", (combatant) => void handleCombatant(combatant, "join"));
  Hooks.on("deleteCombatant", (combatant) => void handleCombatant(combatant, "leave"));
  Hooks.on("preUpdateCombat", (combat, change) => void handleRoundEnd(combat, change));
  Hooks.on("updateCombat", (combat, change) => void rememberRoundStart(combat, change));
}

async function handleOpposedTest(...args: unknown[]): Promise<void> {
  if (!isResponsibleGm() || !getAdvantageSettings().automateOpposed) return;
  const [opposed, attackerTest, defenderTest] = args as Record<string, unknown>[];
  if (!opposed || !attackerTest || !defenderTest) return;
  const context = defenderTest["context"] as Record<string, unknown> | undefined;
  if (context?.["unopposed"] === true) return;
  const attackerData = attackerTest["data"] as Record<string, unknown> | undefined;
  const testResult = attackerData?.["result"] as Record<string, unknown> | undefined;
  const resultOptions = testResult?.["options"] as Record<string, unknown> | undefined;
  if (resultOptions?.["preventAdvantage"] === true || testResult?.["canDualWield"] === true) return;
  const result = opposed["result"] as Record<string, unknown> | undefined;
  const attacker = asAdvantageActor(attackerTest["actor"]);
  const defender = asAdvantageActor(defenderTest["actor"]);
  if (!attacker || !defender || !result) return;
  const id = readTestId(attackerTest);
  if (id && processedTests.has(id)) return;
  if (id) rememberTest(id);
  const winner = result["winner"] === "attacker" ? attacker : defender;
  const loser = winner === attacker ? defender : attacker;
  const participants = { attacker, defender };
  const plan = buildOpposedAdvantagePlan(
    winner === attacker ? "attacker" : "defender",
    usesGroupAdvantage(),
  );
  for (const change of plan) {
    const actor = participants[change.participant];
    if (change.mode === "set") await setAdvantage(actor, change.amount);
    else await addAdvantage(actor, change.amount);
  }
  notifyAdvantage(`${winner.name} gained Advantage; ${loser.name} lost Advantage.`);
}

async function handleDamage(value: unknown): Promise<void> {
  if (!isResponsibleGm() || !getAdvantageSettings().automateDamage || !isRecord(value)) return;
  const opposed = value["opposedTest"] as Record<string, unknown> | undefined;
  const defenderTest = opposed?.["defenderTest"] as Record<string, unknown> | undefined;
  const context = defenderTest?.["context"] as Record<string, unknown> | undefined;
  if (context?.["unopposed"] !== true) return;
  const attacker = asAdvantageActor(value["attacker"]);
  const damaged = asAdvantageActor(value["actor"]);
  if (!attacker || !damaged) return;
  const attackerTest = opposed?.["attackerTest"] as Record<string, unknown> | undefined;
  const id = attackerTest ? readTestId(attackerTest) : "";
  if (id && processedTests.has(id)) return;
  if (id) rememberTest(id);
  if (!usesGroupAdvantage()) await setAdvantage(damaged, 0);
  await addAdvantage(attacker, 1);
  notifyAdvantage(`${attacker.name} gained Advantage for outmanoeuvring ${damaged.name}.`);
}

async function handleCondition(value: unknown): Promise<void> {
  if (!isResponsibleGm() || !getAdvantageSettings().automateCondition || !isRecord(value)) return;
  if (value["isCondition"] !== true || usesGroupAdvantage()) return;
  const conditionId = String(value["conditionId"] ?? "");
  if (["dead", "engaged", "fear", "grappling"].includes(conditionId)) return;
  const actor = asAdvantageActor(value["parent"]);
  if (actor && (actor as typeof actor & { inCombat?: boolean }).inCombat === true) {
    await setAdvantage(actor, 0);
    notifyAdvantage(`${actor.name} lost Advantage after receiving a condition.`);
  }
}

async function handleCombatant(value: unknown, event: "join" | "leave"): Promise<void> {
  if (!isResponsibleGm() || !isRecord(value)) return;
  const settings = getAdvantageSettings();
  if ((event === "join" && !settings.clearOnJoin) || (event === "leave" && !settings.clearOnLeave))
    return;
  if (event === "join" && usesGroupAdvantage()) return;
  const actor = asAdvantageActor(value["actor"]);
  if (actor) await setAdvantage(actor, 0);
}

async function handleRoundEnd(combatValue: unknown, changeValue: unknown): Promise<void> {
  if (!isResponsibleGm() || usesGroupAdvantage() || !getAdvantageSettings().promptMomentumLoss)
    return;
  if (!isRecord(combatValue) || !isRecord(changeValue)) return;
  const nextRound = Number(changeValue["round"]);
  const currentRound = Number(combatValue["round"]);
  if (!Number.isFinite(nextRound) || nextRound <= currentRound || currentRound <= 0) return;
  const combatants = readCombatants(combatValue);
  const candidateActorIds = new Set(
    selectMomentumLossActorIds(
      combatants.flatMap((combatant) => {
        const actor = asAdvantageActor(combatant["actor"]);
        return actor
          ? [
              {
                actorId: actor.id,
                currentAdvantage: Number(actor.system.status?.advantage?.value ?? 0),
                roundStartAdvantage: Number(readFlag(combatant, "roundStartAdvantage") ?? 0),
              },
            ]
          : [];
      }),
    ),
  );
  const candidates = combatants.filter((combatant) => {
    const actor = asAdvantageActor(combatant["actor"]);
    return actor ? candidateActorIds.has(actor.id) : false;
  });
  if (candidates.length === 0) return;
  const names = candidates
    .map((combatant) => asAdvantageActor(combatant["actor"])?.name)
    .join(", ");
  const confirmed = await foundry.applications.api.DialogV2.confirm({
    content: `<p>Reduce Advantage by 1 for combatants who gained no momentum this round?</p><p><strong>${foundry.utils.escapeHTML(names)}</strong></p>`,
    modal: true,
    rejectClose: false,
    window: { title: "Lose Momentum" },
  });
  if (!confirmed) return;
  for (const combatant of candidates) {
    const actor = asAdvantageActor(combatant["actor"]);
    if (actor) await addAdvantage(actor, -1);
  }
  await postMomentumSummary(
    candidates.flatMap((combatant) => {
      const name = asAdvantageActor(combatant["actor"])?.name;
      return name ? [name] : [];
    }),
  );
  notifyAdvantage(
    `Reduced Advantage for ${candidates.length} combatant${candidates.length === 1 ? "" : "s"}.`,
  );
}

async function postMomentumSummary(names: string[]): Promise<void> {
  const whisper = Array.from(game.users)
    .filter((user) => user.isGM)
    .map((user) => user.id);
  const items = names.map((name) => `<li>${foundry.utils.escapeHTML(name)}</li>`).join("");
  await ChatMessage.create({
    content: `<h3>Momentum Loss</h3><p>Advantage reduced by 1:</p><ul>${items}</ul>`,
    whisper,
  });
}

async function rememberRoundStart(combatValue: unknown, changeValue: unknown): Promise<void> {
  if (
    !isResponsibleGm() ||
    !isRecord(combatValue) ||
    !isRecord(changeValue) ||
    !("round" in changeValue)
  )
    return;
  for (const combatant of readCombatants(combatValue)) {
    const actor = asAdvantageActor(combatant["actor"]);
    const setFlag = combatant["setFlag"];
    if (actor && typeof setFlag === "function") {
      await setFlag.call(
        combatant,
        MODULE_ID,
        "roundStartAdvantage",
        Number(actor.system.status?.advantage?.value ?? 0),
      );
    }
  }
}

function readCombatants(combat: Record<string, unknown>): Record<string, unknown>[] {
  const value = combat["combatants"];
  return value && typeof value === "object"
    ? Array.from(value as Iterable<Record<string, unknown>>)
    : [];
}

function readFlag(combatant: Record<string, unknown>, key: string): unknown {
  const getFlag = combatant["getFlag"];
  return typeof getFlag === "function" ? getFlag.call(combatant, MODULE_ID, key) : undefined;
}

function readTestId(test: Record<string, unknown>): string {
  const message = test["message"] as Record<string, unknown> | undefined;
  return String(message?.["id"] ?? "");
}

function rememberTest(id: string): void {
  processedTests.add(id);
  if (processedTests.size > 100) processedTests.delete(processedTests.values().next().value ?? "");
}

function usesGroupAdvantage(): boolean {
  return game.settings.get("wfrp4e", "useGroupAdvantage") === true;
}

function isResponsibleGm(): boolean {
  return (
    game.user?.isGM === true &&
    (game.user as FoundryUser & { isUniqueGM?: boolean }).isUniqueGM !== false
  );
}

function notifyAdvantage(message: string): void {
  ui.notifications.info(message, { permanent: getAdvantageSettings().persistentNotifications });
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}
