import type { ConditionCheckRequest } from "../../types/combat/Combat";
import { resolveActors } from "../actors/selection";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";

interface ConditionRuntime {
  conditionValue?: number;
}

interface ConditionTestRuntime {
  result?: { SL?: number };
  roll: () => Promise<ConditionTestRuntime>;
  succeeded?: boolean;
}

interface ConditionActorRuntime extends FoundryActorDocument {
  applyBasicDamage: (damage: number, options?: Record<string, unknown>) => Promise<unknown>;
  hasCondition: (id: string) => ConditionRuntime | undefined;
  removeCondition: (id: string, count?: number) => Promise<unknown>;
  setupCharacteristic: (
    key: string,
    options?: Record<string, unknown>,
  ) => Promise<ConditionTestRuntime>;
  setupSkill: (skill: unknown, options?: Record<string, unknown>) => Promise<ConditionTestRuntime>;
  statuses: Iterable<string>;
}

export async function checkConditions(request: ConditionCheckRequest): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.combatConsole);
  if (request.endOfRoundOnly && !isEndOfRound()) {
    throw new Error("Condition checks can only run at the end of the active combat round.");
  }
  const actors = (await resolveActors(request.uuids)) as ConditionActorRuntime[];
  const assigned = new Set(Array.from(game.users).map((user) => user.character?.id));
  let processed = 0;

  for (const actor of actors) {
    if (request.skipPlayerCharacters && assigned.has(actor.id)) continue;
    for (const condition of Array.from(actor.statuses ?? [])) {
      if (await processCondition(actor, condition)) processed += 1;
    }
  }
  ui.notifications.info(
    `Processed ${processed} supported condition check${processed === 1 ? "" : "s"}.`,
  );
}

async function processCondition(actor: ConditionActorRuntime, condition: string): Promise<boolean> {
  const count = Math.max(1, Number(actor.hasCondition(condition)?.conditionValue ?? 1));
  if (condition === "surprised") {
    await actor.removeCondition(condition);
    return true;
  }
  if (condition === "ablaze") {
    const roll = (await new Roll(`1d10 + ${count} - 1`).evaluate()) as { total?: number };
    await actor.applyBasicDamage(Number(roll.total ?? count), {});
    return true;
  }
  if (actor.type === "vehicle" || !["broken", "poisoned"].includes(condition)) return false;
  const skill =
    condition === "broken" ? game.i18n.localize("NAME.Cool") : game.i18n.localize("NAME.Endurance");
  const characteristic = condition === "broken" ? "wp" : "t";
  const test = await setupConditionTest(actor, skill, characteristic);
  const result = await test.roll();
  if (result.succeeded) {
    const removal = Math.min(count, Math.max(1, Number(result.result?.SL ?? 0) + 1));
    await actor.removeCondition(condition, removal);
  }
  return true;
}

async function setupConditionTest(
  actor: ConditionActorRuntime,
  skill: string,
  characteristic: string,
): Promise<ConditionTestRuntime> {
  const options = {
    appendTitle: ` — ${actor.name}`,
    fields: { difficulty: "challenging", rollMode: "gmroll" },
    skipDialog: true,
    skipTargets: true,
  };
  const ownedSkill = actor.has(skill, "skill");
  return ownedSkill
    ? actor.setupSkill(ownedSkill, options)
    : actor.setupCharacteristic(characteristic, options);
}

function isEndOfRound(): boolean {
  const combat = (
    game as unknown as {
      combat?: {
        active?: boolean;
        current?: { turn?: number };
        round?: number;
        turns?: unknown[];
      } | null;
    }
  ).combat;
  return Boolean(
    combat?.active &&
    Number(combat.round) > 0 &&
    Number(combat.current?.turn) === (combat.turns?.length ?? 0) - 1,
  );
}
