<script setup lang="ts">
import { storeToRefs } from "pinia";
import { useImperialCalendarStore } from "../../../state/apps/imperial-calendar/store";
import { formatImperialDuration } from "../../../functions/imperial-calendar/fields";
import ConsoleFrame from "../shared/ConsoleFrame.vue";
import ImperialDateInput from "./ImperialDateInput.vue";

const store = useImperialCalendarStore();
const { start, end, calculation } = storeToRefs(store);
</script>

<template>
  <ConsoleFrame
    title="Imperial Calendar Calculator"
    icon="fa-solid fa-calendar-days"
    description="Find the time between two Imperial dates, including festival days."
  >
    <div class="tw:grid tw:min-w-0 tw:gap-3">
      <div
        class="tw:grid tw:min-w-0 tw:gap-3 tw:grid-cols-[repeat(auto-fit,minmax(min(100%,16rem),1fr))]"
      >
        <ImperialDateInput
          v-model="start"
          label="Start date"
          @change-period="store.changePeriod('start', $event)"
        />
        <ImperialDateInput
          v-model="end"
          label="End date"
          @change-period="store.changePeriod('end', $event)"
        />
      </div>
      <button class="dui-btn dui-btn-sm tw:justify-self-end" type="button" @click="store.swapDates">
        <i class="fa-solid fa-right-left" aria-hidden="true" /> Swap dates
      </button>
      <section
        class="tw:min-w-0 tw:rounded-box tw:border-2 tw:border-primary/30! tw:bg-base-100! tw:p-4"
        aria-label="Calculation result"
        aria-live="polite"
        aria-atomic="true"
      >
        <p v-if="calculation.error" class="tw:m-0 tw:text-error!">{{ calculation.error }}</p>
        <template v-else-if="calculation.result">
          <h2 class="tw:m-0 tw:font-serif tw:text-lg">
            {{ calculation.result.totalSeconds < 0 ? "End is before start" : "Elapsed time" }}
          </h2>
          <p class="tw:my-2 tw:text-2xl tw:font-semibold tw:tabular-nums tw:break-words">
            {{ formatImperialDuration(calculation.result) }}
          </p>
          <p v-if="calculation.result.years" class="tw:my-2 tw:text-sm">
            {{ formatImperialDuration(calculation.result, true) }} (400-day years)
          </p>
          <p class="tw:my-2 tw:text-sm tw:tabular-nums">
            End − start: {{ calculation.result.totalSeconds.toLocaleString() }} seconds
          </p>
          <p class="tw:m-0 tw:text-xs tw:text-base-content/70!">
            {{
              calculation.result.totalSeconds < 0
                ? "The duration above runs backward. Swap dates to measure forward."
                : "Same date and time = zero elapsed. Midnight to the next midnight = one day."
            }}
          </p>
        </template>
      </section>
      <p class="tw:m-0 tw:text-xs tw:leading-relaxed tw:text-base-content/70!">
        Standard Imperial calendar: 400 days per year, including six festival days. No leap years;
        24 hours per day. Enter dates manually; calculating does not advance the world clock.
      </p>
    </div>
  </ConsoleFrame>
</template>
