export type XpActorCategory = "companion" | "standard";

export type XpDefaultSelection = "company" | "party" | "world";

export interface XpActorChoice {
  category: XpActorCategory;
  id: string;
  name: string;
  selected: boolean;
  totalXp: number;
}

export interface XpCurveParameters {
  companionMultiplier: number;
  curveExponent: number;
  gapForMaximumAward: number;
  maximumAward: number;
  scaleExponent: number;
  scalePivot: number;
}

export interface XpCurveSettings {
  defaultReason: string;
  defaultSelection: XpDefaultSelection;
  parameters: XpCurveParameters;
}

export interface XpCurveSample {
  award: number;
  gap: number;
}

export interface XpDecaySample {
  multiplier: number;
  recipientXp: number;
}

export interface XpAward {
  actorId: string;
  actorName: string;
  afterXp: number;
  award: number;
  beforeXp: number;
  catchUpValue: number;
  category: XpActorCategory;
  decayMultiplier: number;
  gap: number;
  modifiedAward: number;
  recipientMultiplier: number;
}

export interface XpAwardPlan {
  awards: XpAward[];
  highestXp: number;
  totalAward: number;
}

export interface XpAwardRequest {
  actorIds: string[];
  defaultReason: string;
  defaultSelection: XpDefaultSelection;
  parameters: XpCurveParameters;
}

export interface XpAwardResult extends XpAwardPlan {
  reason: string;
}

export const DEFAULT_XP_CURVE_PARAMETERS: XpCurveParameters = {
  companionMultiplier: 0.5,
  curveExponent: 1.75,
  gapForMaximumAward: 5000,
  maximumAward: 1000,
  scaleExponent: 1,
  scalePivot: 7500,
};

export const DEFAULT_XP_CURVE_SETTINGS: XpCurveSettings = {
  defaultReason: "XP Curve %session% (%date%)",
  defaultSelection: "company",
  parameters: { ...DEFAULT_XP_CURVE_PARAMETERS },
};
