import type { GroupTestSettings } from "../../../types/group-test/GroupTest";
import { MODULE_ID } from "../../constants";
import { GROUP_TEST_SETTINGS } from "./keys";

export function getGroupTestSettings(): GroupTestSettings {
  return {
    bypassDialog: bool("bypassDialog"),
    defaultDifficulty: text("defaultDifficulty"),
    defaultGroup: text("defaultGroup") === "company" ? "company" : "party",
    defaultModifier: number("defaultModifier"),
    defaultRollMode: text("defaultRollMode"),
    defaultSkill: text("defaultSkill"),
    fallbackAdvanced: bool("fallbackAdvanced"),
    fallbackDifficultySteps: number("fallbackDifficultySteps"),
    quickTests: [text("quickTest1"), text("quickTest2"), text("quickTest3"), text("quickTest4")],
    summaryThreshold: number("summaryThreshold"),
  };
}

export async function saveGroupTestSettings(settings: GroupTestSettings): Promise<void> {
  const values: Record<keyof typeof GROUP_TEST_SETTINGS, boolean | number | string> = {
    bypassDialog: settings.bypassDialog,
    defaultDifficulty: settings.defaultDifficulty,
    defaultGroup: settings.defaultGroup,
    defaultModifier: settings.defaultModifier,
    defaultRollMode: settings.defaultRollMode,
    defaultSkill: settings.defaultSkill,
    fallbackAdvanced: settings.fallbackAdvanced,
    fallbackDifficultySteps: settings.fallbackDifficultySteps,
    quickTest1: settings.quickTests[0],
    quickTest2: settings.quickTests[1],
    quickTest3: settings.quickTests[2],
    quickTest4: settings.quickTests[3],
    summaryThreshold: settings.summaryThreshold,
  };
  for (const [name, key] of Object.entries(GROUP_TEST_SETTINGS)) {
    await game.settings.set(MODULE_ID, key, values[name as keyof typeof values]);
  }
}

function bool(key: keyof typeof GROUP_TEST_SETTINGS): boolean {
  return game.settings.get(MODULE_ID, GROUP_TEST_SETTINGS[key]) === true;
}
function number(key: keyof typeof GROUP_TEST_SETTINGS): number {
  return Number(game.settings.get(MODULE_ID, GROUP_TEST_SETTINGS[key])) || 0;
}
function text(key: keyof typeof GROUP_TEST_SETTINGS): string {
  return String(game.settings.get(MODULE_ID, GROUP_TEST_SETTINGS[key]) ?? "");
}
