import type { Component } from "vue";

import type { FearConsoleActions, FearConsoleOptions } from "../../../types/fear-terror/Console";
import FearConsoleApp from "../../../view/apps/fear-console/FearConsoleApp.vue";
import { openFearConsoleConfiguratorFromUi } from "../fear-console-configurator/open";
import { inferControlledTokenPsychologyPayload } from "../../fear-terror/infer";
import { getTargetedActorChoices } from "../../fear-terror/selection";
import {
  applyPsychologyToTargetedActors,
  copyPsychologyLink,
  postPsychologyPrompt,
} from "../../fear-terror/service";
import { MODULE_ID, MODULE_TITLE } from "../../constants";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../access";

export class FearConsoleApplication extends FoundryVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.fearConsole;

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    classes: [MODULE_ID, `${MODULE_ID}-fear-console`],
    id: `${MODULE_ID}-fear-console`,
    position: {
      height: 560,
      width: 620,
    },
    window: {
      icon: "fa-solid fa-skull",
      resizable: true,
      title: `${MODULE_TITLE} — Fear Console`,
    },
  };

  readonly #options: FearConsoleOptions;

  constructor(options: FearConsoleOptions = {}) {
    super();
    this.#options = options;
  }

  protected override getVueComponent(): Component {
    return FearConsoleApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    const actions: FearConsoleActions = {
      applyToSelectedActors: applyPsychologyToTargetedActors,
      copyLink: copyPsychologyLink,
      getActorChoices: getTargetedActorChoices,
      onActionComplete: () => {
        void this.close().catch((error: unknown) => {
          console.error(`${MODULE_ID} | Failed to close the Fear Console.`, error);
          ui.notifications.error(
            "The Fear Console completed the action but could not close its window.",
          );
        });
      },
      openConfigurator: openFearConsoleConfiguratorFromUi,
      postPrompt: postPsychologyPrompt,
    };

    return {
      actions,
      initialPayload: this.#options.initialPayload ?? inferControlledTokenPsychologyPayload(),
    };
  }
}
