import { parseGmToolkitMigrationState } from "../../../functions/gm-toolkit/state";
import type { GmToolkitMigrationState } from "../../../types/gm-toolkit/State";
import { MODULE_ID } from "../../constants";
import { getSessionManagementState } from "../../session-management/settings/load";
import { GM_TOOLKIT_MIGRATION_SETTINGS } from "./keys";

export function getGmToolkitMigrationState(): GmToolkitMigrationState {
  const state = parseGmToolkitMigrationState(
    game.settings.get(MODULE_ID, GM_TOOLKIT_MIGRATION_SETTINGS.state),
  );

  if (state.migration || state.cutoverReview) {
    return state;
  }

  const legacyState = getSessionManagementState();

  return {
    ...(legacyState.gmToolkitCutoverReview
      ? { cutoverReview: legacyState.gmToolkitCutoverReview }
      : {}),
    ...(legacyState.gmToolkitMigration ? { migration: legacyState.gmToolkitMigration } : {}),
    version: 1,
  };
}

export async function saveGmToolkitMigrationState(state: GmToolkitMigrationState): Promise<void> {
  await game.settings.set(MODULE_ID, GM_TOOLKIT_MIGRATION_SETTINGS.state, JSON.stringify(state));
}
