import { LOCALIZATION_NAMESPACE, MODULE_ID } from "../../constants";
import { GROUP_TEST_SETTINGS } from "./keys";

const defaults: Record<keyof typeof GROUP_TEST_SETTINGS, boolean | number | string> = {
  bypassDialog: true,
  defaultDifficulty: "average",
  defaultGroup: "party",
  defaultModifier: 0,
  defaultRollMode: "blindroll",
  defaultSkill: "Lore (Reikland)",
  fallbackAdvanced: false,
  fallbackDifficultySteps: 0,
  quickTest1: "Perception",
  quickTest2: "Cool",
  quickTest3: "Intuition",
  quickTest4: "Gossip",
  summaryThreshold: 2,
};

export function registerGroupTestSettings(): void {
  for (const [name, key] of Object.entries(GROUP_TEST_SETTINGS)) {
    const value = defaults[name as keyof typeof defaults];
    game.settings.register(MODULE_ID, key, {
      config: false,
      default: value,
      hint: `${LOCALIZATION_NAMESPACE}.Settings.GroupTest.${name}.Hint`,
      name: `${LOCALIZATION_NAMESPACE}.Settings.GroupTest.${name}.Name`,
      scope: "world",
      type: typeof value === "boolean" ? Boolean : typeof value === "number" ? Number : String,
    });
  }
}
