import type {
  CatchUpGraphBounds,
  CatchUpGraphProjection,
  DecayGraphBounds,
  DecayGraphProjection,
} from "../../types/xp-curve/Graph";
import type { XpAward, XpCurveSample, XpDecaySample } from "../../types/xp-curve/XpCurve";

export const graphWidth = 560;
export const graphHeight = 270;
export const plotLeft = 68;
export const plotRight = 20;
export const plotTop = 24;
export const plotBottom = 54;
export const plotWidth = graphWidth - plotLeft - plotRight;
export const plotHeight = graphHeight - plotTop - plotBottom;

export function calculateCatchUpGraphBounds(
  gapForMaximumAward: number,
  maximumAward: number,
  samples: XpCurveSample[],
  awards: XpAward[],
): CatchUpGraphBounds {
  return {
    maximumGap: Math.max(
      1,
      gapForMaximumAward * 1.4,
      ...samples.map((sample) => sample.gap),
      ...awards.map((award) => award.gap * 1.05),
    ),
    maximumValue: Math.max(
      1,
      maximumAward * 1.25,
      ...samples.map((sample) => sample.award * 1.05),
      ...awards.map((award) => award.catchUpValue * 1.05),
    ),
  };
}

export function calculateDecayGraphBounds(
  scalePivot: number,
  samples: XpDecaySample[],
  awards: XpAward[],
): DecayGraphBounds {
  return {
    maximumRecipientXp: Math.max(
      1000,
      scalePivot * 4,
      ...samples.map((sample) => sample.recipientXp),
      ...awards.map((award) => award.beforeXp * 1.05),
    ),
  };
}

export function buildCatchUpGraphProjection(input: {
  awards: XpAward[];
  bounds: CatchUpGraphBounds;
  curveExponent: number;
  gapForMaximumAward: number;
  maximumAward: number;
  samples: XpCurveSample[];
}): CatchUpGraphProjection {
  const toX = (gap: number) => projectGraphX(gap, input.bounds.maximumGap);
  const toY = (value: number) => projectCatchUpGraphY(value, input.bounds.maximumValue);

  return {
    points: input.samples
      .map((sample) => `${toX(sample.gap).toFixed(1)},${toY(sample.award).toFixed(1)}`)
      .join(" "),
    recipientLegend: input.awards.map((award, index) => ({
      actorId: award.actorId,
      index: index + 1,
      text: `${award.actorName} — ${award.gap} XP gap — initial ${Math.round(award.catchUpValue)} XP`,
    })),
    recipientPoints: input.awards.map((award, index) => ({
      actorId: award.actorId,
      index: index + 1,
      label: `${award.actorName}: ${Math.round(award.gap)} XP gap, ${Math.round(award.catchUpValue)} initial XP`,
      x: toX(award.gap),
      y: toY(award.catchUpValue),
    })),
    referencePoint: {
      x: toX(input.gapForMaximumAward),
      y: toY(input.maximumAward),
    },
    shapePoint: {
      x: toX(input.gapForMaximumAward / 2),
      y: toY(input.maximumAward * 0.5 ** input.curveExponent),
    },
  };
}

export function buildDecayGraphProjection(input: {
  awards: XpAward[];
  bounds: DecayGraphBounds;
  samples: XpDecaySample[];
  scaleExponent: number;
  scalePivot: number;
}): DecayGraphProjection {
  const toX = (recipientXp: number) => projectGraphX(recipientXp, input.bounds.maximumRecipientXp);
  const toY = projectDecayGraphY;

  return {
    pivotPoint: {
      x: toX(input.scalePivot),
      y: toY(1),
    },
    points: input.samples
      .map((sample) => `${toX(sample.recipientXp).toFixed(1)},${toY(sample.multiplier).toFixed(1)}`)
      .join(" "),
    recipientLegend: input.awards.map((award, index) => ({
      actorId: award.actorId,
      index: index + 1,
      text: `${award.actorName} — ${award.beforeXp} XP — ${Math.round(award.decayMultiplier * 100)}% multiplier`,
    })),
    recipientPoints: input.awards.map((award, index) => ({
      actorId: award.actorId,
      index: index + 1,
      label: `${award.actorName}: ${award.beforeXp} total XP, ${Math.round(award.decayMultiplier * 100)}% catch-up strength`,
      x: toX(award.beforeXp),
      y: toY(award.decayMultiplier),
    })),
    strengthPoint: {
      x: toX(input.scalePivot * 2),
      y: toY(0.5 ** input.scaleExponent),
    },
  };
}

export function calculateCatchUpPointerUpdate(
  kind: "reference" | "shape",
  point: { x: number; y: number },
  bounds: CatchUpGraphBounds,
  maximumAward: number,
):
  | { curveExponent: number; kind: "shape" }
  | { gapForMaximumAward: number; kind: "reference"; maximumAward: number } {
  if (kind === "reference") {
    const gapRatio = clamp((point.x - plotLeft) / plotWidth, 0.001, 1);
    const valueRatio = 1 - clamp((point.y - plotTop) / plotHeight, 0, 1);

    return {
      gapForMaximumAward: Math.max(1, Math.round(gapRatio * bounds.maximumGap)),
      kind,
      maximumAward: Math.max(0, Math.round(valueRatio * bounds.maximumValue)),
    };
  }

  const normalizedValue = clamp(
    ((plotTop + plotHeight - point.y) / plotHeight) *
      (bounds.maximumValue / Math.max(1, maximumAward)),
    0.03,
    0.99,
  );
  const exponent = Math.log(normalizedValue) / Math.log(0.5);

  return {
    curveExponent: roundToStep(clamp(exponent, 0.1, 5), 0.05),
    kind,
  };
}

export function calculateDecayPointerUpdate(
  kind: "pivot" | "strength",
  point: { x: number; y: number },
  bounds: DecayGraphBounds,
): { kind: "pivot"; scalePivot: number } | { kind: "strength"; scaleExponent: number } {
  if (kind === "pivot") {
    const ratio = clamp((point.x - plotLeft) / plotWidth, 0.001, 1);

    return {
      kind,
      scalePivot: Math.max(1, Math.round(ratio * bounds.maximumRecipientXp)),
    };
  }

  const multiplier = clamp(1 - (point.y - plotTop) / plotHeight, 0.25, 0.99);
  const exponent = Math.log(multiplier) / Math.log(0.5);

  return {
    kind,
    scaleExponent: roundToStep(clamp(exponent, 0, 2), 0.05),
  };
}

export function calculateCatchUpReferenceKeyboardUpdate(
  key: string,
  gapForMaximumAward: number,
  maximumAward: number,
): { gapForMaximumAward?: number; maximumAward?: number } | undefined {
  const gapStep = Math.max(10, Math.round(gapForMaximumAward / 20));
  const awardStep = Math.max(1, Math.round(Math.max(1, maximumAward) / 20));

  if (key === "ArrowLeft" || key === "ArrowRight") {
    return {
      gapForMaximumAward: Math.max(
        1,
        gapForMaximumAward + (key === "ArrowLeft" ? -gapStep : gapStep),
      ),
    };
  }

  if (key === "ArrowUp" || key === "ArrowDown") {
    return {
      maximumAward: Math.max(0, maximumAward + (key === "ArrowUp" ? awardStep : -awardStep)),
    };
  }

  return undefined;
}

export function calculateCurveExponentKeyboardUpdate(
  key: string,
  currentValue: number,
  minimum: number,
  maximum: number,
): number | undefined {
  if (!["ArrowDown", "ArrowLeft", "ArrowRight", "ArrowUp"].includes(key)) {
    return undefined;
  }

  const direction = key === "ArrowUp" || key === "ArrowRight" ? -1 : 1;

  return roundToStep(clamp(currentValue + direction * 0.05, minimum, maximum), 0.05);
}

export function calculateDecayPivotKeyboardUpdate(
  key: string,
  scalePivot: number,
): number | undefined {
  if (key !== "ArrowLeft" && key !== "ArrowRight") {
    return undefined;
  }

  const step = Math.max(100, Math.round(scalePivot / 20));

  return Math.max(1, scalePivot + (key === "ArrowLeft" ? -step : step));
}

export function projectGraphX(value: number, maximum: number): number {
  return plotLeft + (Math.max(0, value) / Math.max(1, maximum)) * plotWidth;
}

export function projectCatchUpGraphY(value: number, maximum: number): number {
  return plotTop + (1 - Math.max(0, value) / Math.max(1, maximum)) * plotHeight;
}

export function projectDecayGraphY(multiplier: number): number {
  return plotTop + (1 - clamp(multiplier, 0, 1)) * plotHeight;
}

function clamp(value: number, minimum: number, maximum: number): number {
  return Math.min(maximum, Math.max(minimum, value));
}

function roundToStep(value: number, step: number): number {
  const decimalPlaces = step.toString().split(".")[1]?.length ?? 0;

  return Number((Math.round(value / step) * step).toFixed(decimalPlaces));
}
