<script setup lang="ts">
defineProps<{
  ariaLabel: string;
  x: number;
  y: number;
  ariaValueMax?: number;
  ariaValueMin?: number;
  ariaValueNow?: number;
  ariaValueText?: string;
  role?: "button" | "slider";
}>();

const emit = defineEmits<{
  keydown: [event: KeyboardEvent];
  pointerdown: [event: PointerEvent];
}>();
</script>

<template>
  <g
    class="tw:cursor-grab tw:text-secondary!"
    :role="role ?? 'slider'"
    tabindex="0"
    :aria-label="ariaLabel"
    :aria-valuemax="ariaValueMax"
    :aria-valuemin="ariaValueMin"
    :aria-valuenow="ariaValueNow"
    :aria-valuetext="ariaValueText"
    @keydown="emit('keydown', $event)"
    @pointerdown.stop="emit('pointerdown', $event)"
  >
    <rect
      :x="x - 8"
      :y="y - 8"
      fill="currentColor"
      height="16"
      rx="2"
      stroke="currentColor"
      stroke-width="8"
      stroke-opacity="0.18"
      width="16"
    />
    <rect
      class="tw:text-base-100!"
      :x="x - 3"
      :y="y - 3"
      fill="currentColor"
      height="6"
      rx="1"
      width="6"
    />
  </g>
</template>
