import type {
  GmToolkitCutoverCombatSummary,
  GmToolkitCutoverContentSummary,
  GmToolkitCutoverLauncherIssue,
  GmToolkitCutoverNotice,
  GmToolkitCutoverReport,
  GmToolkitCutoverReview,
  GmToolkitCutoverSettingItem,
  GmToolkitCutoverSourceEvidence,
} from "../../types/gm-toolkit/Cutover";
import type { GmToolkitMigrationPreview } from "../../types/gm-toolkit/Migration";
import type { GmToolkitMigrationSnapshot } from "../../types/gm-toolkit/State";
import { isRecord, normalizeIsoDateTime, readString } from "../records/parse";
import { GM_TOOLKIT_9_2_LAUNCHERS } from "./launcher-catalog";
import { isGmToolkitLauncherRemappable } from "./launchers";

export function buildGmToolkitCutoverReport(options: {
  combat: GmToolkitCutoverCombatSummary;
  generatedAt: string;
  migration?: GmToolkitMigrationSnapshot;
  preview: GmToolkitMigrationPreview;
  sourceEvidence: GmToolkitCutoverSourceEvidence;
}): GmToolkitCutoverReport {
  const settings = buildSettingItems(options.preview, options.migration);
  const content = buildContentSummary(options.preview);
  const launchers = buildLauncherSummary(options.preview);
  const replacement = buildReplacementSummary();
  const source = buildSourceSummary(options.preview, options.sourceEvidence);
  const reportEvidence = {
    content,
    launchers,
    replacement,
    settings: {
      dispositionCounts: options.preview.dispositionCounts,
      items: settings,
      total: options.preview.source?.settings.length ?? 0,
    },
    source: {
      moduleVersion: source.moduleVersion ?? "",
      schemaVersion: source.schemaVersion,
    },
  };

  return {
    combat: { ...options.combat },
    content,
    evidenceId: fingerprint(JSON.stringify(reportEvidence)),
    generatedAt: new Date(options.generatedAt).toISOString(),
    launchers,
    notices: buildNotices(options.preview, settings, content, launchers, options.combat),
    replacement,
    settings: {
      dispositionCounts: { ...options.preview.dispositionCounts },
      items: settings,
      total: options.preview.source?.settings.length ?? 0,
    },
    source,
    version: 1,
  };
}

function buildReplacementSummary(): GmToolkitCutoverReport["replacement"] {
  const unavailableCapabilities = GM_TOOLKIT_9_2_LAUNCHERS.filter(({ replacement }) =>
    ["partial", "pending"].includes(replacement.disposition),
  ).map(({ name }) => name);

  return {
    ready: unavailableCapabilities.length === 0,
    unavailableCapabilities,
  };
}

export function createGmToolkitCutoverReview(
  report: GmToolkitCutoverReport,
  reviewer: { id: string; name: string },
  reviewedAt: string,
): GmToolkitCutoverReview {
  const normalizedReviewedAt = normalizeIsoDateTime(reviewedAt);

  if (!normalizedReviewedAt || !reviewer.id || !reviewer.name.trim()) {
    throw new Error("A valid GM and review time are required to save the review.");
  }

  return {
    evidenceId: report.evidenceId,
    reviewedAt: normalizedReviewedAt,
    reviewedByUserId: reviewer.id,
    reviewedByUserName: reviewer.name.trim(),
    version: 1,
  };
}

export function parseGmToolkitCutoverReview(value: unknown): GmToolkitCutoverReview | undefined {
  if (!isRecord(value) || value["version"] !== 1) {
    return undefined;
  }

  const evidenceId = readString(value["evidenceId"]);
  const reviewedAt = normalizeIsoDateTime(value["reviewedAt"]);
  const reviewedByUserId = readString(value["reviewedByUserId"]);
  const reviewedByUserName = readString(value["reviewedByUserName"]);

  return evidenceId && reviewedAt && reviewedByUserId && reviewedByUserName
    ? { evidenceId, reviewedAt, reviewedByUserId, reviewedByUserName, version: 1 }
    : undefined;
}

function buildSettingItems(
  preview: GmToolkitMigrationPreview,
  migration: GmToolkitMigrationSnapshot | undefined,
): GmToolkitCutoverSettingItem[] {
  const appliedFields = new Set(migration?.appliedFields ?? []);

  return preview.imports.map((item) => {
    const applied = appliedFields.has(item.field);
    const status = applied
      ? item.comparison === "same"
        ? "imported"
        : "changed-after-import"
      : item.comparison === "same"
        ? "already-matched"
        : "not-imported";

    return {
      currentValue: item.currentValue,
      field: item.field,
      label: item.label,
      sourceKey: item.sourceKey,
      sourceValue: item.sourceValue,
      status,
    };
  });
}

function buildContentSummary(preview: GmToolkitMigrationPreview): GmToolkitCutoverContentSummary {
  const candidate =
    preview.darkWhispers.candidates.find(
      ({ tableId }) => tableId === preview.darkWhispers.recommendedTableId,
    ) ?? preview.darkWhispers.candidates[0];
  const prompts = candidate?.prompts ?? [];

  return {
    comparisonCounts: {
      conflict: prompts.filter(({ comparison }) => comparison === "conflict").length,
      duplicate: prompts.filter(({ comparison }) => comparison === "duplicate").length,
      new: prompts.filter(({ comparison }) => comparison === "new").length,
      same: prompts.filter(({ comparison }) => comparison === "same").length,
    },
    currentPromptCount: preview.darkWhispers.currentPromptCount,
    sourcePromptCount: prompts.length,
    ...(candidate
      ? { sourceTableId: candidate.tableId, sourceTableName: candidate.tableName }
      : {}),
  };
}

function buildLauncherSummary(preview: GmToolkitMigrationPreview) {
  const candidates = preview.launchers.candidates;
  const unresolved = candidates
    .filter(
      ({ match, replacement }) =>
        match !== "standard" ||
        replacement.disposition === "partial" ||
        replacement.disposition === "pending",
    )
    .map<GmToolkitCutoverLauncherIssue>((candidate) => ({
      disposition: candidate.replacement.disposition,
      hotbarSlots: [...candidate.hotbarSlots],
      macroId: candidate.macroId,
      macroName: candidate.macroName,
      match: candidate.match,
      outcome: candidate.replacement.label,
    }));

  for (const candidate of candidates) {
    if (isGmToolkitLauncherRemappable(candidate)) {
      unresolved.push({
        disposition: candidate.replacement.disposition,
        hotbarSlots: [...candidate.hotbarSlots],
        macroId: candidate.macroId,
        macroName: candidate.macroName,
        match: candidate.match,
        outcome:
          "A complete replacement exists, but one or more hotbar slots still use the source macro.",
      });
    }
  }

  return {
    detectedMacros: candidates.length,
    hotbarSlots: candidates.reduce((total, candidate) => total + candidate.hotbarSlots.length, 0),
    remappableSlots: preview.launchers.remappableSlots.length,
    unresolved: unresolved.sort((left, right) => left.macroName.localeCompare(right.macroName)),
  };
}

function buildSourceSummary(
  preview: GmToolkitMigrationPreview,
  evidence: GmToolkitCutoverSourceEvidence,
) {
  const source = preview.source;
  const current = evidence === "current";

  return {
    active: current && source?.active === true,
    evidence,
    installed: current && source?.installed === true,
    ...(source?.moduleVersion ? { moduleVersion: source.moduleVersion } : {}),
    schemaVersion: "9.2.0" as const,
  };
}

function buildNotices(
  preview: GmToolkitMigrationPreview,
  settings: readonly GmToolkitCutoverSettingItem[],
  content: GmToolkitCutoverContentSummary,
  launchers: ReturnType<typeof buildLauncherSummary>,
  combat: GmToolkitCutoverCombatSummary,
): GmToolkitCutoverNotice[] {
  const notices: GmToolkitCutoverNotice[] = [];
  const replacement = buildReplacementSummary();
  const settingsToReview = settings.filter(
    ({ status }) => status === "changed-after-import" || status === "not-imported",
  ).length;
  const contentToReview = content.comparisonCounts.conflict + content.comparisonCounts.new;

  if (combat.active) {
    notices.push({
      code: "active-combat",
      message:
        "Finish the active combat before disabling GM Toolkit. Combat-specific data is not copied.",
    });
  }

  if (!replacement.ready) {
    notices.push({
      code: "replacement-incomplete",
      message: `${replacement.unavailableCapabilities.length} GM Toolkit action${replacement.unavailableCapabilities.length === 1 ? " does" : "s do"} not yet have a complete Drowsy equivalent. Keep GM Toolkit enabled if you use them.`,
    });
  }

  if (settingsToReview > 0) {
    notices.push({
      code: "settings-review",
      message: `${settingsToReview} compatible setting value${settingsToReview === 1 ? " needs" : "s need"} an explicit keep-or-import decision.`,
    });
  }

  if (contentToReview > 0) {
    notices.push({
      code: "content-review",
      message: `${contentToReview} Dark Whispers prompt${contentToReview === 1 ? " needs" : "s need"} an explicit import-or-preserve decision.`,
    });
  }

  if (launchers.unresolved.length > 0) {
    notices.push({
      code: "launcher-review",
      message: `${launchers.unresolved.length} detected launcher${launchers.unresolved.length === 1 ? " needs" : "s need"} review before you disable GM Toolkit.`,
    });
  }

  const sourceWarnings = [
    ...(preview.source?.warnings ?? []),
    ...preview.darkWhispers.warnings,
    ...preview.launchers.warnings,
  ];
  notices.push(...sourceWarnings.map((message) => ({ code: "source-warning" as const, message })));

  return notices;
}

function fingerprint(value: string): string {
  let hash = 0x811c9dc5;

  for (let index = 0; index < value.length; index += 1) {
    hash = Math.imul(hash ^ value.charCodeAt(index), 0x01000193) >>> 0;
  }

  return hash.toString(16).padStart(8, "0");
}
