import { ref } from "vue";
import { defineStore } from "pinia";

import {
  createGmToolkitDarkWhispersSelections,
  getSelectedGmToolkitDarkWhispersResultIds,
} from "../../../functions/gm-toolkit/content-selection";
import {
  createGmToolkitLauncherSelections,
  getSelectedGmToolkitLauncherSlots,
  type GmToolkitLauncherSelections,
} from "../../../functions/gm-toolkit/launcher-selection";
import {
  cloneGmToolkitMigrationPreview,
  createGmToolkitImportSelections,
  getSelectedGmToolkitImportFields,
  reconcileGmToolkitMigrationPreview,
  type GmToolkitImportSelections,
} from "../../../functions/gm-toolkit/selection";
import type {
  GmToolkitMigrationConsoleActions,
  GmToolkitMigrationConsoleInitialization,
} from "../../../types/gm-toolkit/Console";
import type { GmToolkitCutoverReport } from "../../../types/gm-toolkit/Cutover";
import type {
  GmToolkitImportField,
  GmToolkitMigrationPreview,
} from "../../../types/gm-toolkit/Migration";
import type { GmToolkitMigrationState } from "../../../types/gm-toolkit/State";

export const useGmToolkitMigrationStore = defineStore("gm-toolkit-migration", () => {
  const state = ref<GmToolkitMigrationState>({ version: 1 });
  const preview = ref<GmToolkitMigrationPreview>();
  const cutoverReport = ref<GmToolkitCutoverReport>();
  const settingSelections = ref<GmToolkitImportSelections>(
    createGmToolkitImportSelections(undefined, false),
  );
  const darkWhispersTableId = ref("");
  const darkWhispersSelections = ref<Record<string, boolean>>({});
  const darkWhispersConflictPolicy = ref<"preserve" | "replace">("preserve");
  const launcherSelections = ref<GmToolkitLauncherSelections>({});
  const errorMessage = ref<undefined | string>();
  const statusMessage = ref<undefined | string>();
  const isWorking = ref(false);
  let actions: GmToolkitMigrationConsoleActions | undefined;

  function initialize(
    initialization: GmToolkitMigrationConsoleInitialization,
    nextActions: GmToolkitMigrationConsoleActions,
  ): void {
    actions = nextActions;
    state.value = { ...initialization.state };
    preview.value = cloneGmToolkitMigrationPreview(initialization.preview);
    cutoverReport.value = initialization.cutoverReport;
    settingSelections.value = createGmToolkitImportSelections(
      preview.value,
      initialization.state.migration === undefined,
    );
    initializeDarkWhispersSelections();
    initializeLauncherSelections();
    errorMessage.value = undefined;
    statusMessage.value = undefined;
  }

  async function importSettings(): Promise<void> {
    await runAction(async () => {
      const fields = getSelectedGmToolkitImportFields(settingSelections.value);
      const migration = await getActions().importSettings({ fields });
      state.value.migration = migration;
      preview.value = reconcileGmToolkitMigrationPreview(
        preview.value,
        migration.appliedFields ?? [],
      );
      settingSelections.value = createGmToolkitImportSelections(preview.value, false);
      refreshCutoverReport();
      statusMessage.value = `${fields.length} setting${fields.length === 1 ? "" : "s"} imported.`;
    });
  }

  async function importDarkWhispers(): Promise<void> {
    await runAction(async () => {
      const result = await getActions().importDarkWhispers({
        conflictPolicy: darkWhispersConflictPolicy.value,
        resultIds: getSelectedGmToolkitDarkWhispersResultIds(darkWhispersSelections.value),
        tableId: darkWhispersTableId.value,
      });
      preview.value = cloneGmToolkitMigrationPreview(result.preview);
      initializeDarkWhispersSelections();
      initializeLauncherSelections();
      refreshCutoverReport();
      statusMessage.value = `${result.added} prompt${result.added === 1 ? "" : "s"} added, ${result.replaced} replaced, and ${result.skipped} unchanged.`;
    });
  }

  async function remapLaunchers(): Promise<void> {
    await runAction(async () => {
      const result = await getActions().remapLaunchers({
        slots: getSelectedGmToolkitLauncherSlots(launcherSelections.value),
      });

      if (preview.value) {
        preview.value = { ...preview.value, launchers: result.preview };
      }
      initializeLauncherSelections();
      refreshCutoverReport();
      statusMessage.value = `${result.remappedSlots} hotbar slot${result.remappedSlots === 1 ? "" : "s"} updated.`;
    });
  }

  async function reviewCutover(): Promise<void> {
    await runAction(async () => {
      const result = await getActions().reviewCutover();
      state.value.cutoverReview = result.review;
      cutoverReport.value = result.report;
      statusMessage.value = "Review saved.";
    });
  }

  function setSettingSelection(field: GmToolkitImportField, selected: boolean): void {
    settingSelections.value[field] = selected;
  }

  function setDarkWhispersTable(tableId: string): void {
    darkWhispersTableId.value = tableId;
    darkWhispersSelections.value = createGmToolkitDarkWhispersSelections(
      getDarkWhispersPreview(),
      tableId,
    );
  }

  function setDarkWhispersSelection(resultId: string, selected: boolean): void {
    darkWhispersSelections.value[resultId] = selected;
  }

  function setLauncherSelection(slot: number, selected: boolean): void {
    launcherSelections.value[slot] = selected;
  }

  function initializeDarkWhispersSelections(): void {
    const darkWhispers = getDarkWhispersPreview();
    const tableId = darkWhispers.recommendedTableId ?? darkWhispers.candidates[0]?.tableId ?? "";
    darkWhispersTableId.value = tableId;
    darkWhispersSelections.value = createGmToolkitDarkWhispersSelections(darkWhispers, tableId);
    darkWhispersConflictPolicy.value = "preserve";
  }

  function initializeLauncherSelections(): void {
    launcherSelections.value = createGmToolkitLauncherSelections(preview.value?.launchers);
  }

  function refreshCutoverReport(): void {
    cutoverReport.value = getActions().getCutoverReport();
  }

  function getDarkWhispersPreview() {
    return (
      preview.value?.darkWhispers ?? {
        candidates: [],
        currentPromptCount: 0,
        warnings: [],
      }
    );
  }

  async function runAction(operation: () => Promise<void>): Promise<void> {
    if (isWorking.value) return;

    isWorking.value = true;
    errorMessage.value = undefined;
    statusMessage.value = undefined;

    try {
      await operation();
    } catch (error) {
      console.error("Drowsy’s WFRP4e Toolkit | GM Toolkit import action failed.", error);
      errorMessage.value =
        error instanceof Error ? error.message : "The action could not be completed.";
    } finally {
      isWorking.value = false;
    }
  }

  function getActions(): GmToolkitMigrationConsoleActions {
    if (!actions) throw new Error("The GM Toolkit importer has not been initialized.");
    return actions;
  }

  return {
    cutoverReport,
    darkWhispersConflictPolicy,
    darkWhispersSelections,
    darkWhispersTableId,
    errorMessage,
    importDarkWhispers,
    importSettings,
    initialize,
    isWorking,
    launcherSelections,
    preview,
    remapLaunchers,
    reviewCutover,
    setDarkWhispersSelection,
    setDarkWhispersTable,
    setLauncherSelection,
    setSettingSelection,
    settingSelections,
    state,
    statusMessage,
  };
});
