import { createPinia } from "pinia";
import { type App as VueApp, type Component, createApp } from "vue";

import {
  assertCurrentUserCanAccessApplication,
  canCurrentUserAccessApplication,
  type ToolkitApplicationAccessPolicy,
} from "./access";

export abstract class FoundryVueApplication extends foundry.applications.api.ApplicationV2 {
  static ACCESS_POLICY: ToolkitApplicationAccessPolicy = {
    gmOnly: true,
    name: "Drowsy’s WFRP4e Toolkit application",
  };

  #vueApp: undefined | VueApp<Element>;

  static canCurrentUserAccess(): boolean {
    return canCurrentUserAccessApplication(this.ACCESS_POLICY);
  }

  override async render(force?: boolean): Promise<this> {
    const applicationClass = this.constructor as typeof FoundryVueApplication;
    assertCurrentUserCanAccessApplication(applicationClass.ACCESS_POLICY);

    return super.render(force);
  }

  protected getVueProps(): Record<string, unknown> | undefined {
    return undefined;
  }

  protected abstract getVueComponent(): Component;

  protected override async _renderHTML(
    _context: foundry.applications.types.ApplicationRenderContext,
    _options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<HTMLElement> {
    const mountRoot = document.createElement("div");
    mountRoot.classList.add(
      "wfrp4e-enhanced-fear-terror-root",
      "tw:[&_*]:box-border",
      "tw:box-border",
      "tw:block",
      "tw:h-full",
      "tw:max-h-full",
      "tw:max-w-full",
      "tw:min-h-0",
      "tw:overflow-auto",
      "tw:text-base-content",
      "tw:w-full",
    );
    mountRoot.dataset["theme"] = "wfrp4e-enhanced-fear-terror";

    return mountRoot;
  }

  protected override _replaceHTML(
    result: HTMLElement,
    content: HTMLElement,
    _options: foundry.applications.types.ApplicationRenderOptions,
  ): void {
    this.unmountVue();
    content.classList.add(
      "wfrp4e-enhanced-fear-terror-app",
      "tw:box-border",
      "tw:min-h-0",
      "tw:overflow-hidden",
      "tw:p-0",
      "tw:relative",
    );
    content.replaceChildren(result);

    this.#vueApp = createApp(this.getVueComponent(), this.getVueProps() ?? {});
    this.#vueApp.use(createPinia());
    this.#vueApp.mount(result);
  }

  protected override async _preClose(
    options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<void> {
    this.unmountVue();
    await super._preClose(options);
  }

  private unmountVue(): void {
    this.#vueApp?.unmount();
    this.#vueApp = undefined;
  }
}
