import type { ToolkitApplicationHandle } from "../../../types/module/api/ModuleApi";
import { MODULE_ID } from "../../constants";
import { FearConsoleConfiguratorApplication } from "./FearConsoleConfiguratorApplication";

export async function openFearConsoleConfigurator(): Promise<ToolkitApplicationHandle> {
  const application = new FearConsoleConfiguratorApplication();
  await application.render(true);

  return application;
}

export function openFearConsoleConfiguratorFromUi(): void {
  void openFearConsoleConfigurator().catch((error: unknown) => {
    console.error(`${MODULE_ID} | Failed to open the Fear Console Configurator.`, error);
    ui.notifications.error(
      "Drowsy’s WFRP4e Toolkit could not open the Fear Console Configurator. See the browser console for details.",
    );
  });
}
