import {
  EMPTY_GM_TOOLKIT_MIGRATION_STATE,
  type GmToolkitMigrationSnapshot,
  type GmToolkitMigrationState,
} from "../../types/gm-toolkit/State";
import { isRecord, normalizeIsoDateTime, readString } from "../records/parse";
import { parseGmToolkitCutoverReview } from "./cutover";
import { isGmToolkitImportField, parseGmToolkitSourceSnapshot } from "./migration";

export function parseGmToolkitMigrationState(value: unknown): GmToolkitMigrationState {
  const parsed = parseJsonRecord(value);

  if (!parsed || parsed["version"] !== 1) {
    return { ...EMPTY_GM_TOOLKIT_MIGRATION_STATE };
  }

  const migration = parseGmToolkitMigrationSnapshot(parsed["migration"]);
  const cutoverReview = parseGmToolkitCutoverReview(parsed["cutoverReview"]);

  return {
    ...(cutoverReview ? { cutoverReview } : {}),
    ...(migration ? { migration } : {}),
    version: 1,
  };
}

export function parseGmToolkitMigrationSnapshot(
  value: unknown,
): GmToolkitMigrationSnapshot | undefined {
  if (!isRecord(value) || !isRecord(value["xpAwardSettings"])) {
    return undefined;
  }

  const importedAt = normalizeIsoDateTime(value["importedAt"]);
  const sessionReference = readString(value["sessionReference"]);
  const settings = value["xpAwardSettings"];
  const defaultSelection = settings["defaultSelection"];

  if (
    !importedAt ||
    (defaultSelection !== "party" &&
      defaultSelection !== "company" &&
      defaultSelection !== "world") ||
    !Number.isFinite(Number(settings["defaultAmount"]))
  ) {
    return undefined;
  }

  const source = parseGmToolkitSourceSnapshot(value["source"]);
  const appliedFields = Array.isArray(value["appliedFields"])
    ? value["appliedFields"].filter(isGmToolkitImportField)
    : undefined;

  return {
    ...(appliedFields ? { appliedFields } : {}),
    importedAt,
    sessionReference,
    ...(source ? { source } : {}),
    ...(value["version"] === 2 ? { version: 2 as const } : {}),
    xpAwardSettings: {
      defaultAmount: Math.round(Number(settings["defaultAmount"])),
      defaultReason: readString(settings["defaultReason"]),
      defaultSelection,
      includeTimestampInReason: settings["includeTimestampInReason"] === true,
    },
  };
}

function parseJsonRecord(value: unknown): Record<string, unknown> | undefined {
  if (typeof value !== "string") {
    return undefined;
  }

  try {
    const parsed: unknown = JSON.parse(value);
    return isRecord(parsed) ? parsed : undefined;
  } catch {
    return undefined;
  }
}
