import type { SessionTurnoverRequest } from "../../types/session-management/SessionManagement";
import type { XpAwardSettings } from "../../types/xp-award/XpAward";
import { formatXpAwardDateTime, resolveFixedXpAwardReason } from "../xp-award/reason";

export function nextSessionNumber(reference: string): string {
  const value = Number(reference);
  if (
    !reference.trim() ||
    !Number.isSafeInteger(value) ||
    value < 0 ||
    !Number.isSafeInteger(value + 1)
  ) {
    throw new Error("Enter a whole session number of zero or more.");
  }
  return String(value + 1);
}

export function sessionXpReason(
  settings: XpAwardSettings,
  reference: string,
  occurredAt: string,
): string {
  const date = new Date(occurredAt);
  if (Number.isNaN(date.getTime())) throw new Error("Enter a valid session date and time.");
  const iso = date.toISOString();
  return resolveFixedXpAwardReason(
    settings.defaultReason,
    {
      date: occurredAt.slice(0, 10),
      datetime: formatXpAwardDateTime(iso),
      session: reference.trim(),
    },
    settings.includeTimestampInReason,
  );
}

export function validateSessionSubmission(request: SessionTurnoverRequest): void {
  if (Number.isNaN(new Date(request.occurredAt).getTime()))
    throw new Error("Enter a valid session date and time.");
  if (!request.xp) return;
  if (request.nextSessionReference !== nextSessionNumber(request.sessionReference)) {
    throw new Error("The next session must be one higher than the submitted session number.");
  }
  if (!Number.isSafeInteger(request.xp.defaultAmount) || request.xp.defaultAmount < 0) {
    throw new Error("Enter a whole Session XP amount of zero or more.");
  }
  if (request.xpAward && !request.xp.actorIds.length)
    throw new Error("Select at least one XP recipient, or enter 0 XP.");
}

export function parseSessionSubmission(value: unknown): SessionTurnoverRequest | undefined {
  if (!value || typeof value !== "object") return undefined;
  const row = value as Record<string, unknown>;
  if (
    !["sessionReference", "nextSessionReference", "occurredAt"].every(
      (key) => typeof row[key] === "string",
    ) ||
    !["chatExport", "fortuneReset", "holdingScene", "pause", "xpAward"].every(
      (key) => typeof row[key] === "boolean",
    )
  )
    return undefined;
  const xp = row["xp"] as Record<string, unknown> | undefined;
  if (
    xp &&
    (!Array.isArray(xp["actorIds"]) ||
      !xp["actorIds"].every((id) => typeof id === "string") ||
      typeof xp["defaultAmount"] !== "number" ||
      typeof xp["defaultReason"] !== "string" ||
      typeof xp["includeTimestampInReason"] !== "boolean" ||
      !["party", "company", "world"].includes(String(xp["defaultSelection"])))
  )
    return undefined;
  const request = value as SessionTurnoverRequest;
  try {
    validateSessionSubmission(request);
    return request;
  } catch {
    return undefined;
  }
}

export function sessionLogText(reference: string, occurredAt: string): string {
  const date = new Date(occurredAt);
  const label = Number.isNaN(date.getTime())
    ? "Choose a date and time"
    : new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(date);
  return `Session ${reference || "—"} · ${label}`;
}
