const defaultReason = defineModel<string>("defaultReason", { required: true });
const emit = defineEmits<{
  "reset": [];
  "select-all": [selected: boolean];
  "update:selected": [actorId: string, selected: boolean];
}>();

function updateSelection(actorId: string, selected: boolean): void {
  emit("update:selected", actorId, selected);
}
</script>

