      :actors="actors"
      :disabled="disabled"
      :plan="plan"
      @reset="emit('reset')"
      @select-all="emit('select-all', $event)"
      @update:selected="updateSelection"
    />

    <section
      class="dui-card dui-card-border tw:min-w-0 tw:border-2 tw:border-base-content/20! tw:bg-base-100! tw:text-base-content! tw:shadow-md"
