import type {
  DarkWhispersRecipient,
  DarkWhispersSettings,
} from "../../types/dark-whispers/Console";

export interface DarkWhispersActorCandidate {
  corruption: number;
  corruptionMax: number;
  hasPlayerOwner: boolean;
  id: string;
  label: string;
  ownership: Record<string, number>;
  type: string;
  uuid: string;
}

export interface DarkWhispersUserCandidate {
  characterId?: string;
  id: string;
  isGm: boolean;
  name: string;
}

export function buildDarkWhispersRecipients(input: {
  actors: readonly DarkWhispersActorCandidate[];
  defaultGroup: DarkWhispersSettings["defaultGroup"];
  targetedActorIds: ReadonlySet<string>;
  users: readonly DarkWhispersUserCandidate[];
}): DarkWhispersRecipient[] {
  const assignedActorIds = new Set(input.users.map((user) => user.characterId));

  return input.actors
    .filter(
      (actor) =>
        actor.type === "character" &&
        (input.defaultGroup === "company" ? actor.hasPlayerOwner : assignedActorIds.has(actor.id)),
    )
    .map((actor) => {
      const assignedUser = input.users.find((user) => !user.isGm && user.characterId === actor.id);
      const ownerCount = input.users.filter(
        (user) => !user.isGm && Number(actor.ownership[user.id] ?? 0) >= 3,
      ).length;

      return {
        assignedUser: assignedUser?.name,
        corruption: actor.corruption,
        corruptionMax: actor.corruptionMax,
        label: actor.label,
        ownerCount,
        selected: actor.corruption > 0 && input.targetedActorIds.has(actor.id),
        uuid: actor.uuid,
      };
    });
}
