import type { FearConsoleConfiguration } from "../../types/fear-terror/Configuration";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";
import { MODULE_ID } from "../constants";
import { FEAR_TERROR_LAUNCHER_SETTINGS, isFearTerrorLauncherEnabled } from "./settings/launchers";

export function getFearConsoleConfiguration(): FearConsoleConfiguration {
  return {
    launchers: {
      actorSheet: isFearTerrorLauncherEnabled(FEAR_TERROR_LAUNCHER_SETTINGS.actorSheet),
      tokenControls: isFearTerrorLauncherEnabled(FEAR_TERROR_LAUNCHER_SETTINGS.tokenControls),
    },
  };
}

export async function saveFearConsoleConfiguration(
  configuration: FearConsoleConfiguration,
): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.fearConsole);
  const values = [
    [FEAR_TERROR_LAUNCHER_SETTINGS.actorSheet, configuration.launchers.actorSheet],
    [FEAR_TERROR_LAUNCHER_SETTINGS.tokenControls, configuration.launchers.tokenControls],
  ] as const;

  for (const [key, value] of values) {
    await game.settings.set(MODULE_ID, key, value);
  }

  ui.notifications.info("Fear Console configuration saved. Reload to update its launchers.");
}
