import { suggestPsychologyPayload } from "../../functions/fear-terror/suggestion";
import type { PsychologyPayload } from "../../types/fear-terror/Psychology";

export function inferControlledTokenPsychologyPayload(): PsychologyPayload | undefined {
  if (typeof canvas === "undefined" || !canvas) {
    return undefined;
  }

  for (const token of canvas.tokens?.controlled ?? []) {
    if (token.actor) {
      return inferActorPsychologyPayload(token.actor);
    }
  }

  return undefined;
}

export function inferActorPsychologyPayload(actor: FoundryActorDocument): PsychologyPayload {
  const terrorRating = getTraitRating(actor, "CHAT.Terror");

  return suggestPsychologyPayload({
    fearRating: terrorRating === undefined ? getTraitRating(actor, "CHAT.Fear") : undefined,
    source: actor.name,
    terrorRating,
  });
}

function getTraitRating(actor: FoundryActorDocument, localizationKey: string): number | undefined {
  if (typeof actor.has !== "function") {
    throw new Error(
      `WFRP4e actor "${actor.name}" does not expose the required trait lookup method.`,
    );
  }

  const trait = actor.has(game.i18n.localize(localizationKey));
  const value = trait?.specification?.value;

  if (typeof value === "number") {
    return value;
  }

  if (typeof value === "string") {
    const rating = Number(value);

    if (Number.isFinite(rating)) {
      return rating;
    }
  }

  return undefined;
}
