import { MODULE_ID } from "../constants";

let skillNames: string[] = [];

export function getGroupTestSkillNames(): string[] {
  return [...skillNames];
}

export async function compileGroupTestSkillNames(): Promise<void> {
  const names = new Set<string>();
  const runtime = game as unknown as {
    actors: Iterable<{ items?: Iterable<SkillIndexEntry> }>;
    items?: Iterable<SkillIndexEntry>;
    packs: Iterable<{
      getIndex?: (options?: Record<string, unknown>) => Promise<Iterable<SkillIndexEntry>>;
      metadata?: { system?: string; type?: string };
    }>;
  };
  for (const actor of runtime.actors) collectSkills(actor.items, names);
  collectSkills(runtime.items, names);
  for (const pack of runtime.packs) {
    if (!pack.getIndex || pack.metadata?.system !== "wfrp4e" || pack.metadata?.type !== "Item")
      continue;
    try {
      collectSkills(await pack.getIndex({ fields: ["type"] }), names);
    } catch (error) {
      console.warn(`${MODULE_ID} | Could not index WFRP4e skills from a compendium.`, error);
    }
  }
  skillNames = [...names].sort((left, right) => left.localeCompare(right));
}

interface SkillIndexEntry {
  name?: string;
  type?: string;
}

function collectSkills(items: Iterable<SkillIndexEntry> | undefined, names: Set<string>): void {
  for (const item of items ?? []) if (item.type === "skill" && item.name) names.add(item.name);
}
