import { SessionManagementApplication } from "../../apps/session-management/SessionManagementApplication";
import { LOCALIZATION_NAMESPACE, MODULE_ID } from "../../constants";
import { registerHiddenWorldSetting } from "../../settings/register";
import { SESSION_MANAGEMENT_SETTINGS } from "./keys";

export function registerSessionManagementSettings(): void {
  registerHiddenWorldSetting(
    SESSION_MANAGEMENT_SETTINGS.options,
    "{}",
    String,
    `${LOCALIZATION_NAMESPACE}.Settings.SessionManagement.State`,
  );
  registerHiddenWorldSetting(
    SESSION_MANAGEMENT_SETTINGS.state,
    JSON.stringify({ currentSessionReference: "", sessions: [], version: 1 }),
    String,
    `${LOCALIZATION_NAMESPACE}.Settings.SessionManagement.State`,
  );
  registerHiddenWorldSetting(
    SESSION_MANAGEMENT_SETTINGS.holdingSceneUuid,
    "",
    String,
    `${LOCALIZATION_NAMESPACE}.Settings.SessionManagement.HoldingSceneUuid`,
  );
  registerHiddenWorldSetting(
    SESSION_MANAGEMENT_SETTINGS.exportChat,
    false,
    Boolean,
    `${LOCALIZATION_NAMESPACE}.Settings.SessionManagement.ExportChat`,
  );
  registerHiddenWorldSetting(
    SESSION_MANAGEMENT_SETTINGS.pullPolicy,
    "pull",
    String,
    `${LOCALIZATION_NAMESPACE}.Settings.SessionManagement.PullPolicy`,
    {
      choices: {
        activate: `${LOCALIZATION_NAMESPACE}.Settings.SessionManagement.PullPolicy.Activate`,
        pull: `${LOCALIZATION_NAMESPACE}.Settings.SessionManagement.PullPolicy.Pull`,
      },
    },
  );

  game.settings.registerMenu(MODULE_ID, "sessionManagementConsole", {
    hint: `${LOCALIZATION_NAMESPACE}.Menu.SessionManagementConsole.Hint`,
    icon: "fa-solid fa-calendar-check",
    label: `${LOCALIZATION_NAMESPACE}.Menu.SessionManagementConsole.Label`,
    name: `${LOCALIZATION_NAMESPACE}.Menu.SessionManagementConsole.Name`,
    restricted: SessionManagementApplication.ACCESS_POLICY.gmOnly,
    type: SessionManagementApplication,
  });
}
