import type { XpCurveConsoleInitialization, XpReasonContext } from "../../types/xp-curve/Console";
import { getCurrentSessionReference } from "../session-management/settings/load";
import { getXpActorChoices } from "./actors";
import { getXpCurveSettings } from "./settings/load";

export function getXpCurveConsoleInitialization(): XpCurveConsoleInitialization {
  const settings = getXpCurveSettings();
  const selection = getXpActorChoices(settings.defaultSelection);

  return {
    ...settings,
    ...selection,
    reasonContext: getXpReasonContext(),
  };
}

export function getXpReasonContext(): XpReasonContext {
  const configuredDate = game.world.nextSession?.slice(0, 10);

  return {
    date: configuredDate || new Date().toISOString().slice(0, 10),
    session: getCurrentSessionReference(),
  };
}
