import type {
  GmToolkitImportField,
  GmToolkitImportResult,
  GmToolkitMigrationPreview,
} from "../../types/gm-toolkit/Migration";
import type { XpAwardSettings } from "../../types/xp-award/XpAward";

export function applyGmToolkitImportSelections(
  preview: GmToolkitMigrationPreview,
  target: { sessionReference: string; xpAwardSettings: XpAwardSettings },
  fields: readonly GmToolkitImportField[],
): GmToolkitImportResult {
  const selectedFields = new Set(fields);
  const result: GmToolkitImportResult = {
    sessionReference: target.sessionReference,
    xpAwardSettings: { ...target.xpAwardSettings },
  };

  for (const item of preview.imports) {
    if (!selectedFields.has(item.field)) {
      continue;
    }

    switch (item.field) {
      case "sessionReference":
        result.sessionReference = String(item.sourceValue);
        break;
      case "defaultXpAmount":
        result.xpAwardSettings.defaultAmount = Number(item.sourceValue);
        break;
      case "defaultXpReason":
        result.xpAwardSettings.defaultReason = String(item.sourceValue);
        break;
      case "defaultXpSelection":
        result.xpAwardSettings.defaultSelection =
          item.sourceValue === "company" ? "company" : "party";
        break;
    }
  }

  return result;
}
