import { isRecord, normalizeIsoDateTime, readString } from "../records/parse";
import type {
  DarkWhispersImportRecord,
  DarkWhispersPrompt,
  DarkWhispersPromptLibraryParseResult,
  DarkWhispersPromptSource,
} from "../../types/dark-whispers/PromptLibrary";
import { EMPTY_DARK_WHISPERS_PROMPT_LIBRARY } from "../../types/dark-whispers/PromptLibrary";

export function normalizeDarkWhispersPromptText(value: unknown): string {
  return typeof value === "string"
    ? value
        .replace(/\r\n?/g, "\n")
        .replace(/[\t ]+\n/g, "\n")
        .replace(/\n{3,}/g, "\n\n")
        .trim()
    : "";
}

export function parseDarkWhispersPromptLibrary(
  value: unknown,
): DarkWhispersPromptLibraryParseResult {
  if (typeof value !== "string") {
    return emptyParseResult("The Dark Whispers prompt library setting was not serialized text.");
  }

  let parsed: unknown;

  try {
    parsed = JSON.parse(value) as unknown;
  } catch {
    return emptyParseResult("The Dark Whispers prompt library contains invalid JSON.");
  }

  if (!isRecord(parsed) || parsed["version"] !== 1 || !Array.isArray(parsed["prompts"])) {
    return emptyParseResult("The Dark Whispers prompt library has an unsupported schema.");
  }

  const warnings: string[] = [];
  const prompts = parsed["prompts"].flatMap((prompt, index) => {
    const normalized = parsePrompt(prompt);

    if (!normalized) {
      warnings.push(`Dark Whispers prompt ${index + 1} was invalid and was skipped.`);
      return [];
    }

    return [normalized];
  });
  const lastImport = parseImportRecord(parsed["lastImport"]);

  if (parsed["lastImport"] !== undefined && !lastImport) {
    warnings.push("The Dark Whispers import record was invalid and was skipped.");
  }

  return {
    library: {
      ...(lastImport ? { lastImport } : {}),
      prompts,
      version: 1,
    },
    warnings,
  };
}

function emptyParseResult(warning: string): DarkWhispersPromptLibraryParseResult {
  return {
    library: { ...EMPTY_DARK_WHISPERS_PROMPT_LIBRARY, prompts: [] },
    warnings: [warning],
  };
}

function parsePrompt(value: unknown): DarkWhispersPrompt | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const id = readString(value["id"]);
  const text = normalizeDarkWhispersPromptText(value["text"]);
  const source = parseSource(value["source"]);

  if (!id || !text) {
    return undefined;
  }

  return {
    id,
    ...(source ? { source } : {}),
    text,
  };
}

function parseSource(value: unknown): DarkWhispersPromptSource | undefined {
  if (!isRecord(value) || value["type"] !== "gm-toolkit") {
    return undefined;
  }

  const moduleVersion = readString(value["moduleVersion"]);
  const resultId = readString(value["resultId"]);
  const tableId = readString(value["tableId"]);

  return resultId && tableId
    ? {
        ...(moduleVersion ? { moduleVersion } : {}),
        resultId,
        tableId,
        type: "gm-toolkit",
      }
    : undefined;
}

function parseImportRecord(value: unknown): DarkWhispersImportRecord | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const conflictPolicy = value["conflictPolicy"];
  const importedAt = normalizeIsoDateTime(value["importedAt"]);
  const resultIds = Array.isArray(value["resultIds"])
    ? value["resultIds"].filter((resultId): resultId is string => typeof resultId === "string")
    : [];
  const sourceModuleVersion = readString(value["sourceModuleVersion"]);
  const sourceTableId = readString(value["sourceTableId"]);
  const sourceTableName = readString(value["sourceTableName"]);

  if (
    (conflictPolicy !== "preserve" && conflictPolicy !== "replace") ||
    !importedAt ||
    !sourceTableId ||
    !sourceTableName
  ) {
    return undefined;
  }

  return {
    conflictPolicy,
    importedAt,
    resultIds,
    ...(sourceModuleVersion ? { sourceModuleVersion } : {}),
    sourceTableId,
    sourceTableName,
  };
}
