import type { ImperialDateTime, ImperialElapsedTime } from "../../types/imperial-calendar/Calendar";
import {
  getImperialPeriod,
  IMPERIAL_DAYS_PER_YEAR,
  IMPERIAL_MAX_YEAR,
  IMPERIAL_PERIODS,
  IMPERIAL_SECONDS_PER_DAY,
} from "./calendar";

/** Exact elapsed time, not an inclusive count of dates touched. Pure arithmetic only. */
export function calculateImperialElapsedTime(
  start: ImperialDateTime,
  end: ImperialDateTime,
): ImperialElapsedTime {
  const totalSeconds = toSeconds(end) - toSeconds(start);
  const magnitude = Math.abs(totalSeconds);
  const wholeDays = Math.floor(magnitude / IMPERIAL_SECONDS_PER_DAY);
  return {
    totalSeconds,
    wholeDays,
    years: Math.floor(wholeDays / IMPERIAL_DAYS_PER_YEAR),
    days: wholeDays % IMPERIAL_DAYS_PER_YEAR,
    hours: Math.floor((magnitude % IMPERIAL_SECONDS_PER_DAY) / 3600),
    minutes: Math.floor((magnitude % 3600) / 60),
    seconds: magnitude % 60,
  };
}

export function validateImperialDateTime(date: ImperialDateTime): void {
  const period = getImperialPeriod(date.period);
  requireInteger(date.year, 1, IMPERIAL_MAX_YEAR, "Year (I.C.)");
  requireInteger(date.day, 1, period.days, `Day in ${period.name}`);
  requireInteger(date.hour ?? 0, 0, 23, "Hour");
  requireInteger(date.minute ?? 0, 0, 59, "Minute");
  requireInteger(date.second ?? 0, 0, 59, "Second");
}

function toSeconds(date: ImperialDateTime): number {
  validateImperialDateTime(date);
  let days = (date.year - 1) * IMPERIAL_DAYS_PER_YEAR + date.day - 1;
  for (const period of IMPERIAL_PERIODS) {
    if (period.name === date.period) break;
    days += period.days;
  }
  return (
    days * IMPERIAL_SECONDS_PER_DAY +
    (date.hour ?? 0) * 3600 +
    (date.minute ?? 0) * 60 +
    (date.second ?? 0)
  );
}

function requireInteger(value: number, minimum: number, maximum: number, label: string): void {
  if (!Number.isInteger(value) || value < minimum || value > maximum) {
    throw new RangeError(`${label} must be a whole number from ${minimum} to ${maximum}.`);
  }
}
