import type { GmToolkitMigrationConsoleInitialization } from "../../types/gm-toolkit/Console";
import { getGmToolkitCutoverReport, getGmToolkitImportPreview } from "./migration";
import { getGmToolkitMigrationState } from "./settings/load";

export function getGmToolkitMigrationConsoleInitialization(): GmToolkitMigrationConsoleInitialization {
  const state = getGmToolkitMigrationState();
  const preview = getGmToolkitImportPreview();
  const cutoverReport = getGmToolkitCutoverReport(preview, state);

  return {
    ...(cutoverReport ? { cutoverReport } : {}),
    ...(preview ? { preview } : {}),
    state,
  };
}
