import type { PsychologyPayload } from "../../types/fear-terror/Psychology";

export interface PsychologySuggestionInput {
  fearRating: number | undefined;
  source: string;
  terrorRating: number | undefined;
}

export function suggestPsychologyPayload({
  fearRating,
  source,
  terrorRating,
}: PsychologySuggestionInput): PsychologyPayload {
  if (terrorRating !== undefined) {
    return {
      rating: terrorRating,
      source,
      type: "terror",
    };
  }

  if (fearRating !== undefined) {
    return {
      rating: fearRating,
      source,
      type: "fear",
    };
  }

  return {
    rating: 1,
    source,
    type: "fear",
  };
}
