function replacement(label: string, macroId: string, macroName: string) {
  return { label, macroId, macroName };
}
function launcher(
  id: string,
  name: string,
  commandLength: number,
  commandFingerprint: string,
): GmToolkitLauncherDefinition {
  return {
    commandFingerprint,
    commandLength,
    id,
    name,
    replacement: { disposition: "ready", ...replacements[id]! },
  };
}
