import { parseDarkWhispersPromptLibrary } from "../../../functions/dark-whispers/library";
import type {
  DarkWhispersPromptLibrary,
  DarkWhispersPromptLibraryParseResult,
} from "../../../types/dark-whispers/PromptLibrary";
import { MODULE_ID } from "../../constants";
import { DARK_WHISPERS_SETTINGS } from "./keys";
import type { DarkWhispersSettings } from "../../../types/dark-whispers/Console";

export function getDarkWhispersPromptLibraryState(): DarkWhispersPromptLibraryParseResult {
  return parseDarkWhispersPromptLibrary(
    game.settings.get(MODULE_ID, DARK_WHISPERS_SETTINGS.promptLibrary),
  );
}

export function getDarkWhispersPromptLibrary(): DarkWhispersPromptLibrary {
  const state = getDarkWhispersPromptLibraryState();

  for (const warning of state.warnings) {
    console.warn(`${MODULE_ID} | ${warning}`);
  }

  return state.library;
}

export async function saveDarkWhispersPromptLibrary(
  library: DarkWhispersPromptLibrary,
): Promise<void> {
  await game.settings.set(MODULE_ID, DARK_WHISPERS_SETTINGS.promptLibrary, JSON.stringify(library));
}

export function getDarkWhispersSettings(): DarkWhispersSettings {
  const group = game.settings.get(MODULE_ID, DARK_WHISPERS_SETTINGS.defaultGroup);
  const style = game.settings.get(MODULE_ID, DARK_WHISPERS_SETTINGS.messageStyle);
  return {
    defaultGroup: group === "company" ? "company" : "party",
    messageStyle: style === "offer" || style === "plain" ? style : "taunt",
  };
}

export async function saveDarkWhispersSettings(settings: DarkWhispersSettings): Promise<void> {
  await game.settings.set(MODULE_ID, DARK_WHISPERS_SETTINGS.defaultGroup, settings.defaultGroup);
  await game.settings.set(MODULE_ID, DARK_WHISPERS_SETTINGS.messageStyle, settings.messageStyle);
}
