import type {
  GmToolkitImportField,
  GmToolkitMigrationPreview,
} from "../../types/gm-toolkit/Migration";

export type GmToolkitImportSelections = Record<GmToolkitImportField, boolean>;

export function cloneGmToolkitMigrationPreview(
  preview: GmToolkitMigrationPreview | undefined,
): GmToolkitMigrationPreview | undefined {
  if (!preview) {
    return undefined;
  }

  return {
    ...preview,
    darkWhispers: {
      ...preview.darkWhispers,
      candidates: preview.darkWhispers.candidates.map((candidate) => ({
        ...candidate,
        prompts: candidate.prompts.map((prompt) => ({ ...prompt })),
        warnings: [...candidate.warnings],
      })),
      warnings: [...preview.darkWhispers.warnings],
    },
    dispositionCounts: { ...preview.dispositionCounts },
    imports: preview.imports.map((item) => ({ ...item })),
    launchers: {
      ...preview.launchers,
      candidates: preview.launchers.candidates.map((candidate) => ({
        ...candidate,
        hotbarSlots: [...candidate.hotbarSlots],
        replacement: { ...candidate.replacement },
      })),
      counts: { ...preview.launchers.counts },
      remappableSlots: [...preview.launchers.remappableSlots],
      warnings: [...preview.launchers.warnings],
    },
    ...(preview.source
      ? {
          source: {
            ...preview.source,
            settings: preview.source.settings.map((setting) => ({
              ...setting,
              value: Array.isArray(setting.value) ? [...setting.value] : setting.value,
            })),
            warnings: [...preview.source.warnings],
          },
        }
      : {}),
    sourceCounts: { ...preview.sourceCounts },
  };
}

export function createGmToolkitImportSelections(
  preview: GmToolkitMigrationPreview | undefined,
  selectDifferences: boolean,
): GmToolkitImportSelections {
  const selections = Object.fromEntries(
    (preview?.imports ?? []).map(({ field }) => [field, false]),
  ) as GmToolkitImportSelections;

  if (selectDifferences) {
    for (const item of preview?.imports ?? []) {
      selections[item.field] = item.comparison !== "same";
    }
  }

  return selections;
}

export function getSelectedGmToolkitImportFields(
  selections: GmToolkitImportSelections,
): GmToolkitImportField[] {
  return Object.entries(selections)
    .filter(([, selected]) => selected)
    .map(([field]) => field);
}

export function reconcileGmToolkitMigrationPreview(
  preview: GmToolkitMigrationPreview | undefined,
  appliedFields: readonly GmToolkitImportField[],
): GmToolkitMigrationPreview | undefined {
  const nextPreview = cloneGmToolkitMigrationPreview(preview);

  if (!nextPreview) {
    return undefined;
  }

  const applied = new Set(appliedFields);

  for (const item of nextPreview.imports) {
    if (applied.has(item.field)) {
      item.currentValue = item.sourceValue;
      item.comparison = "same";
    }
  }

  return nextPreview;
}
