import type {
  XpActorCategory,
  XpActorChoice,
  XpDefaultSelection,
} from "../../types/xp-curve/XpCurve";

export interface XpActorSelectionCandidate {
  hasPlayerOwner: boolean;
  id: string;
  name: string;
  totalXp: number;
}

export interface BuildXpActorChoicesOptions {
  assignedActorIds: ReadonlySet<string>;
  candidates: XpActorSelectionCandidate[];
  defaultSelection: XpDefaultSelection;
  targetedActorIds?: ReadonlySet<string>;
}

export function buildXpActorChoices(options: BuildXpActorChoicesOptions): XpActorChoice[] {
  const { assignedActorIds, candidates, defaultSelection, targetedActorIds } = options;

  return candidates
    .map((actor) => {
      const category = getXpActorCategory(actor, assignedActorIds);

      return {
        category,
        id: actor.id,
        name: actor.name,
        selected:
          targetedActorIds?.has(actor.id) ??
          isXpActorSelectedByDefault(actor.id, category, defaultSelection, assignedActorIds),
        totalXp: actor.totalXp,
      };
    })
    .sort(compareXpActorChoices);
}

export function getXpActorCategory(
  actor: Pick<XpActorSelectionCandidate, "hasPlayerOwner" | "id">,
  assignedActorIds: ReadonlySet<string>,
): XpActorCategory {
  return actor.hasPlayerOwner && !assignedActorIds.has(actor.id) ? "companion" : "standard";
}

export function isXpActorSelectedByDefault(
  actorId: string,
  category: XpActorCategory,
  defaultSelection: XpDefaultSelection,
  assignedActorIds: ReadonlySet<string>,
): boolean {
  if (defaultSelection === "world") {
    return true;
  }

  if (defaultSelection === "company") {
    return assignedActorIds.has(actorId) || category === "companion";
  }

  return assignedActorIds.has(actorId);
}

function compareXpActorChoices(left: XpActorChoice, right: XpActorChoice): number {
  if (left.selected !== right.selected) {
    return left.selected ? -1 : 1;
  }

  return left.name.localeCompare(right.name);
}
