import {
  buildPsychologyLink,
  buildPromptTitle,
  buildSummaryPromptContent,
  normalizePsychologyPayload,
} from "../../functions/fear-terror/payload";
import type { PsychologyPayload } from "../../types/fear-terror/Psychology";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";
import { getTargetedActorDocuments } from "./selection";

export async function applyPsychologyToTargetedActors(payload: PsychologyPayload): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.fearConsole);
  const actors = getTargetedActorDocuments();

  if (actors.length === 0) {
    ui.notifications.warn("Target one or more tokens before applying Fear or Terror.");
    return;
  }

  const normalizedPayload = normalizePsychologyPayload(payload);

  await Promise.all(actors.map((actor) => applyPsychology(actor, normalizedPayload)));
}

export async function postPsychologyPrompt(payload: PsychologyPayload): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.fearConsole);
  const normalizedPayload = normalizePsychologyPayload(payload);
  const affectedActors = getTargetedActorDocuments();
  const label = getLocalizedPsychologyLabel(normalizedPayload);
  const title = buildPromptTitle(label, normalizedPayload);
  const promptHtml = await foundry.applications.handlebars.renderTemplate(
    "systems/wfrp4e/templates/chat/fear.hbs",
    { title },
  );
  const html = addAffectedActorsToPrompt(promptHtml, affectedActors);

  await ChatMessage.create({
    content: html,
    speaker: { alias: label },
    system: {
      rating: normalizedPayload.rating,
      source: normalizedPayload.source,
      type: normalizedPayload.type,
    },
    type: "psych",
  });
}

export async function copyPsychologyLink(payload: PsychologyPayload): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.fearConsole);
  const normalizedPayload = normalizePsychologyPayload(payload);
  const link = buildPsychologyLink(normalizedPayload);

  await game.clipboard.copyPlainText(link);
  ui.notifications.info(`${getLocalizedPsychologyLabel(normalizedPayload)} link copied.`);
}

export async function postPsychologySummaryPrompt(payload: PsychologyPayload): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.fearConsole);
  const normalizedPayload = normalizePsychologyPayload(payload);
  const heading = getLocalizedPsychologyLabel(normalizedPayload);
  const content = buildSummaryPromptContent(heading, normalizedPayload);
  const messageData = game.wfrp4e.utility.chatDataSetup(content, "gmroll", false, {
    alias: "Drowsy’s WFRP4e Toolkit",
  });

  await ChatMessage.create(messageData);
}

async function applyPsychology(
  actor: FoundryActorDocument,
  payload: PsychologyPayload,
): Promise<void> {
  if (payload.type === "fear") {
    await actor.applyFear(payload.rating, payload.source);
    return;
  }

  await actor.applyTerror(payload.rating, payload.source);
}

function getLocalizedPsychologyLabel(payload: PsychologyPayload): string {
  const localizationKey = payload.type === "fear" ? "CHAT.Fear" : "CHAT.Terror";

  return game.i18n.localize(localizationKey);
}

function addAffectedActorsToPrompt(promptHtml: string, actors: FoundryActorDocument[]): string {
  if (actors.length === 0) {
    return promptHtml;
  }

  const template = document.createElement("template");
  template.innerHTML = promptHtml.trim();

  const affectedActors = document.createElement("div");
  const heading = document.createElement("strong");
  const list = document.createElement("ul");

  heading.textContent = actors.length === 1 ? "Affected actor" : "Affected actors";

  for (const actor of actors) {
    const item = document.createElement("li");
    item.textContent = actor.name;
    list.append(item);
  }

  affectedActors.append(heading, list);

  const applyButton = template.content.querySelector('[data-action="apply"]');

  if (applyButton) {
    applyButton.before(affectedActors);
  } else {
    template.content.append(affectedActors);
  }

  return template.innerHTML;
}
