<script setup lang="ts">
import { graphHeight, graphWidth, plotHeight, plotLeft, plotTop, plotWidth } from "../graphMath";
import type { XpGraphMarker } from "../../../../../types/xp-curve/Graph";

defineProps<{
  description: string;
  descriptionId: string;
  markers: XpGraphMarker[];
  maximumXLabel: string;
  minimumYLabel: string;
  points: string;
  title: string;
  titleId: string;
  verticalGuideX: number;
  xAxisLabel: string;
  yAxisLabel: string;
  maximumYLabel?: string;
}>();

const emit = defineEmits<{
  pointercancel: [event: PointerEvent];
  pointermove: [event: PointerEvent];
  pointerup: [event: PointerEvent];
}>();
</script>

<template>
  <svg
    class="tw:block tw:h-auto tw:w-full tw:max-w-full tw:touch-none tw:[user-select:none]"
    :viewBox="`0 0 ${graphWidth} ${graphHeight}`"
    role="img"
    :aria-labelledby="`${titleId} ${descriptionId}`"
    @pointercancel="emit('pointercancel', $event)"
    @pointermove="emit('pointermove', $event)"
    @pointerup="emit('pointerup', $event)"
  >
    <title :id="titleId">{{ title }}</title>
    <desc :id="descriptionId">{{ description }}</desc>

    <line
      class="tw:text-base-content/25!"
      :x1="plotLeft"
      :x2="plotLeft"
      :y1="plotTop"
      :y2="plotTop + plotHeight"
      stroke="currentColor"
    />
    <line
      class="tw:text-base-content/25!"
      :x1="plotLeft"
      :x2="plotLeft + plotWidth"
      :y1="plotTop + plotHeight"
      :y2="plotTop + plotHeight"
      stroke="currentColor"
    />
    <line
      class="tw:text-base-content/25!"
      :x1="verticalGuideX"
      :x2="verticalGuideX"
      :y1="plotTop"
      :y2="plotTop + plotHeight"
      stroke="currentColor"
      stroke-dasharray="4 5"
    />

    <slot name="guides" />

    <polyline
      class="tw:text-secondary!"
      fill="none"
      :points="points"
      stroke="currentColor"
      stroke-linecap="round"
      stroke-linejoin="round"
      stroke-width="3"
    />

    <g
      v-for="marker in markers"
      :key="marker.actorId"
      class="tw:text-base-content!"
      aria-hidden="true"
    >
      <circle :cx="marker.x" :cy="marker.y" fill="currentColor" r="9">
        <title>{{ marker.label }}</title>
      </circle>
      <text
        class="tw:text-base-100!"
        :x="marker.x"
        :y="marker.y + 3"
        fill="currentColor"
        font-size="9"
        font-weight="700"
        text-anchor="middle"
      >
        {{ marker.index }}
      </text>
    </g>

    <slot name="handles" />

    <text
      class="tw:text-base-content/65!"
      :x="plotLeft"
      :y="plotTop + plotHeight + 18"
      fill="currentColor"
      font-size="11"
      text-anchor="middle"
    >
      0
    </text>
    <text
      class="tw:text-base-content/65!"
      :x="plotLeft + plotWidth"
      :y="plotTop + plotHeight + 18"
      fill="currentColor"
      font-size="11"
      text-anchor="end"
    >
      {{ maximumXLabel }}
    </text>
    <text
      class="tw:text-base-content/75!"
      :x="plotLeft + plotWidth / 2"
      :y="graphHeight - 8"
      fill="currentColor"
      font-size="12"
      font-weight="600"
      text-anchor="middle"
    >
      {{ xAxisLabel }}
    </text>
    <text
      v-if="maximumYLabel"
      class="tw:text-base-content/65!"
      :x="plotLeft - 10"
      :y="plotTop + 4"
      fill="currentColor"
      font-size="11"
      text-anchor="end"
    >
      {{ maximumYLabel }}
    </text>
    <text
      class="tw:text-base-content/65!"
      :x="plotLeft - 10"
      :y="plotTop + plotHeight + 3"
      fill="currentColor"
      font-size="11"
      text-anchor="end"
    >
      {{ minimumYLabel }}
    </text>
    <text
      class="tw:text-base-content/75!"
      :transform="`rotate(-90 16 ${plotTop + plotHeight / 2})`"
      x="16"
      :y="plotTop + plotHeight / 2"
      fill="currentColor"
      font-size="12"
      font-weight="600"
      text-anchor="middle"
    >
      {{ yAxisLabel }}
    </text>

    <slot name="labels" />
  </svg>
</template>
