import type { DamageConsoleInitialization } from "../../types/damage/Damage";
import { getActorChoices } from "../actors/selection";

export function getDamageConsoleInitialization(): DamageConsoleInitialization {
  const locations =
    (game as unknown as { wfrp4e: { config: { locations?: Record<string, string> } } }).wfrp4e
      .config.locations ?? {};
  return {
    actors: getActorChoices({ includeVehicles: true, initial: "targeted" }),
    hitLocations: [
      { label: "Body / default", value: "body" },
      ...Object.entries(locations).map(([value, localization]) => ({
        label: game.i18n.localize(localization),
        value,
      })),
    ].filter(
      (item, index, all) => all.findIndex((candidate) => candidate.value === item.value) === index,
    ),
  };
}
