import { defineStore } from "pinia";
import { computed, ref } from "vue";
import type {
  GroupTestConsoleActions,
  GroupTestConsoleInitialization,
  GroupTestSettings,
} from "../../../types/group-test/GroupTest";

export const useGroupTestConsoleStore = defineStore("group-test-console", () => {
  const actors = ref<GroupTestConsoleInitialization["actors"]>([]);
  const settings = ref<GroupTestSettings>();
  const skills = ref<string[]>([]);
  const skill = ref("");
  const busy = ref(false);
  const errorMessage = ref("");
  let actions: GroupTestConsoleActions | undefined;
  const selectedUuids = computed(() =>
    actors.value.filter((actor) => actor.selected).map((actor) => actor.uuid),
  );

  function initialize(
    initialization: GroupTestConsoleInitialization,
    nextActions: GroupTestConsoleActions,
  ): void {
    actors.value = structuredClone(initialization.actors);
    settings.value = structuredClone(initialization.settings);
    skills.value = [...initialization.skills];
    skill.value = initialization.settings.defaultSkill;
    actions = nextActions;
  }
  async function run(quickSkill?: string): Promise<void> {
    await execute(async () => {
      const currentSettings = getSettings();
      await getActions().runGroupTest({
        bypassDialog: currentSettings.bypassDialog,
        difficulty: currentSettings.defaultDifficulty,
        fallbackAdvanced: currentSettings.fallbackAdvanced,
        fallbackDifficultySteps: currentSettings.fallbackDifficultySteps,
        modifier: currentSettings.defaultModifier,
        rollMode: currentSettings.defaultRollMode,
        skill: quickSkill ?? skill.value,
        uuids: selectedUuids.value,
      });
    });
  }
  async function save(): Promise<void> {
    await execute(async () => {
      const currentSettings = getSettings();
      currentSettings.defaultSkill = skill.value.trim();
      await getActions().saveSettings(currentSettings);
    });
  }
  async function execute(operation: () => Promise<void>): Promise<void> {
    busy.value = true;
    errorMessage.value = "";
    try {
      await operation();
    } catch (error) {
      errorMessage.value = error instanceof Error ? error.message : "The group test could not run.";
    } finally {
      busy.value = false;
    }
  }
  function getActions(): GroupTestConsoleActions {
    if (!actions) throw new Error("The Group Test Console has not been initialized.");
    return actions;
  }
  function getSettings(): GroupTestSettings {
    if (!settings.value) throw new Error("The Group Test Console has not been initialized.");
    return settings.value;
  }
  return { actors, busy, errorMessage, initialize, run, save, settings, skill, skills };
});
