import { ref } from "vue";
import { defineStore } from "pinia";
import { nextSessionNumber } from "../../../functions/session-management/submission";
import type {
  SessionConfiguration,
  SessionConfigurationActions,
  SessionConfigurationInitialization,
} from "../../../types/session-management/Configuration";

export const useSessionConfigurationStore = defineStore("session-configuration", () => {
  const settings = ref<SessionConfiguration>();
  const reference = ref("");
  const isWorking = ref(false);
  const errorMessage = ref<string>();
  let actions: SessionConfigurationActions;
  function initialize(
    data: SessionConfigurationInitialization,
    callbacks: SessionConfigurationActions,
  ): void {
    settings.value = structuredClone(data.settings);
    reference.value = data.currentSessionReference || "1";
    actions = callbacks;
  }
  async function save(): Promise<void> {
    if (isWorking.value || !settings.value) return;
    isWorking.value = true;
    errorMessage.value = undefined;
    try {
      nextSessionNumber(reference.value);
      if (
        !Number.isSafeInteger(settings.value.xp.defaultAmount) ||
        settings.value.xp.defaultAmount < 0
      )
        throw new Error("Enter a whole XP amount of zero or more.");
      if (settings.value.holdingScene && !settings.value.holdingSceneUuid)
        throw new Error("Choose a holding scene, or turn off scene movement.");
      await actions.save(
        JSON.parse(JSON.stringify(settings.value)) as SessionConfiguration,
        reference.value.trim(),
      );
    } catch (error) {
      console.error("Drowsy’s WFRP4e Toolkit | Could not save session settings.", error);
      errorMessage.value =
        error instanceof Error ? error.message : "Could not save session settings.";
    } finally {
      isWorking.value = false;
    }
  }
  return { errorMessage, initialize, isWorking, reference, save, settings };
});
