<script setup lang="ts">
import { computed, useId } from "vue";
import {
  getImperialPeriod,
  IMPERIAL_MAX_YEAR,
  IMPERIAL_PERIODS,
} from "../../../functions/imperial-calendar/calendar";
import type { ImperialDateFields } from "../../../types/imperial-calendar/Calendar";

const fields = defineModel<ImperialDateFields>({ required: true });
defineProps<{ label: string }>();
const emit = defineEmits<{ changePeriod: [period: string] }>();
const id = useId();
const period = computed(() => getImperialPeriod(fields.value.period));
</script>

<template>
  <fieldset
    class="dui-fieldset tw:min-w-0 tw:rounded-box tw:border-2 tw:border-base-content/20! tw:bg-base-100! tw:p-4"
  >
    <legend class="dui-fieldset-legend tw:font-serif tw:text-lg">{{ label }}</legend>
    <label class="tw:grid tw:gap-1">
      <span class="dui-label">Month or festival</span>
      <select
        :value="fields.period"
        class="dui-select dui-select-sm tw:w-full"
        @change="emit('changePeriod', ($event.target as HTMLSelectElement).value)"
      >
        <option v-for="choice in IMPERIAL_PERIODS" :key="choice.name" :value="choice.name">
          {{ choice.name }}{{ choice.intercalary ? " · festival" : "" }}
        </option>
      </select>
    </label>
    <div class="tw:grid tw:grid-cols-2 tw:gap-3">
      <label class="tw:grid tw:min-w-0 tw:gap-1">
        <span class="dui-label">Day</span>
        <input
          v-model="fields.day"
          class="dui-input dui-input-sm tw:w-full"
          type="number"
          min="1"
          :max="period.days"
          step="1"
          :disabled="period.intercalary"
          required
        />
      </label>
      <label class="tw:grid tw:min-w-0 tw:gap-1">
        <span class="dui-label">Year (I.C.)</span>
        <input
          v-model="fields.year"
          class="dui-input dui-input-sm tw:w-full"
          type="number"
          min="1"
          :max="IMPERIAL_MAX_YEAR"
          step="1"
          required
        />
      </label>
    </div>
    <p class="tw:m-0 tw:text-xs tw:text-base-content/70!">
      {{
        period.intercalary
          ? "A single festival day between months."
          : `${period.days} days in this month.`
      }}
    </p>
    <label class="tw:grid tw:gap-1">
      <span class="dui-label">Time (24-hour, optional)</span>
      <input
        v-model="fields.time"
        class="dui-input dui-input-sm tw:w-full tw:font-mono"
        type="text"
        placeholder="00:00:00"
        :aria-describedby="`${id}-time-hint`"
      />
    </label>
    <p :id="`${id}-time-hint`" class="tw:m-0 tw:text-xs tw:text-base-content/70!">
      HH:MM or HH:MM:SS. Blank means midnight.
    </p>
  </fieldset>
</template>
