import type { Component } from "vue";

import type { FearConsoleConfiguratorActions } from "../../../types/fear-terror/Configuration";
import FearConsoleConfiguratorApp from "../../../view/apps/fear-console-configurator/FearConsoleConfiguratorApp.vue";
import {
  getFearConsoleConfiguration,
  saveFearConsoleConfiguration,
} from "../../fear-terror/configuration";
import { MODULE_ID, MODULE_TITLE } from "../../constants";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../access";

export class FearConsoleConfiguratorApplication extends FoundryVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.fearConsole;

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    classes: [MODULE_ID, `${MODULE_ID}-fear-console-configurator`],
    id: `${MODULE_ID}-fear-console-configurator`,
    position: {
      height: 500,
      width: 560,
    },
    window: {
      icon: "fa-solid fa-skull",
      resizable: true,
      title: `${MODULE_TITLE} — Fear Console Configurator`,
    },
  };

  protected override getVueComponent(): Component {
    return FearConsoleConfiguratorApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    const actions: FearConsoleConfiguratorActions = {
      saveConfiguration: saveFearConsoleConfiguration,
    };

    return {
      actions,
      configuration: getFearConsoleConfiguration(),
    };
  }
}
