import type { ToolkitApplicationHandle } from "../../../types/module/api/ModuleApi";
import { MODULE_ID } from "../../constants";
import { GmToolkitMigrationApplication } from "./GmToolkitMigrationApplication";

export async function openGmToolkitMigration(): Promise<ToolkitApplicationHandle> {
  const application = new GmToolkitMigrationApplication();
  await application.render(true);
  return application;
}

export function openGmToolkitMigrationFromUi(): void {
  void openGmToolkitMigration().catch((error: unknown) => {
    console.error(`${MODULE_ID} | Failed to open the GM Toolkit importer.`, error);
    ui.notifications.error(
      "Drowsy’s WFRP4e Toolkit could not open the GM Toolkit importer. See the browser console for details.",
    );
  });
}
