import { computed, ref } from "vue";
import { defineStore } from "pinia";

import { getPsychologyTypeLabel } from "../../../functions/fear-terror/payload";
import type {
  ActorChoice,
  PsychologyPayload,
  PsychologyType,
} from "../../../types/fear-terror/Psychology";
import type {
  FearConsoleAction,
  FearConsoleActions,
  FearConsoleOptions,
} from "../../../types/fear-terror/Console";

interface FearConsoleInitialization extends FearConsoleOptions {
  actions: FearConsoleActions;
}

export const useFearConsoleStore = defineStore("fear-console", () => {
  const selectedType = ref<PsychologyType>("fear");
  const rating = ref(1);
  const source = ref("");
  const actors = ref<ActorChoice[]>([]);
  const activeAction = ref<undefined | FearConsoleAction>();
  const errorMessage = ref<undefined | string>();
  let consoleActions: FearConsoleActions | undefined;

  const isWorking = computed(() => activeAction.value !== undefined);
  const selectedTypeLabel = computed(() => getPsychologyTypeLabel(selectedType.value));
  const payload = computed<PsychologyPayload>(() => {
    const nextPayload: PsychologyPayload = {
      rating: rating.value,
      type: selectedType.value,
    };
    const trimmedSource = source.value.trim();

    if (trimmedSource) {
      nextPayload.source = trimmedSource;
    }

    return nextPayload;
  });

  function initialize(initialization: FearConsoleInitialization): void {
    consoleActions = initialization.actions;
    selectedType.value = initialization.initialPayload?.type ?? "fear";
    rating.value = initialization.initialPayload?.rating ?? 1;
    source.value = initialization.initialPayload?.source ?? "";
    refreshActors();
  }

  function refreshActors(): void {
    actors.value = getConsoleActions().getActorChoices();
  }

  async function runAction(action: FearConsoleAction): Promise<void> {
    if (isWorking.value) {
      return;
    }

    activeAction.value = action;
    errorMessage.value = undefined;

    try {
      const actions = getConsoleActions();

      if (action === "post-card") {
        await actions.postPrompt(payload.value);
      } else if (action === "copy-link") {
        await actions.copyLink(payload.value);
      } else {
        await actions.applyToSelectedActors(payload.value);
      }

      refreshActors();
      actions.onActionComplete();
    } catch (error) {
      console.error("Drowsy’s WFRP4e Toolkit | Fear Console action failed.", error);
      errorMessage.value =
        error instanceof Error
          ? error.message
          : "The Fear or Terror action could not be completed.";
    } finally {
      activeAction.value = undefined;
    }
  }

  function getConsoleActions(): FearConsoleActions {
    if (!consoleActions) {
      throw new Error("The Fear Console has not been initialized.");
    }

    return consoleActions;
  }

  return {
    activeAction,
    actors,
    errorMessage,
    initialize,
    isWorking,
    rating,
    refreshActors,
    runAction,
    selectedType,
    selectedTypeLabel,
    source,
  };
});
