import { isRecord, readString } from "../records/parse";
import { normalizeDarkWhispersPromptText } from "../dark-whispers/library";
import type { DarkWhispersPromptLibrary } from "../../types/dark-whispers/PromptLibrary";
import type {
  GmToolkitContentComparison,
  GmToolkitContentConfidence,
  GmToolkitDarkWhispersCandidatePreview,
  GmToolkitDarkWhispersImportRequest,
  GmToolkitDarkWhispersMigrationPreview,
  GmToolkitDarkWhispersSourceCandidate,
} from "../../types/gm-toolkit/Migration";

const DARK_WHISPERS_TABLE_ID = "9rXQv4uJcQoLBitt";
const DARK_WHISPERS_TABLE_NAME = "Dark Whispers";
const GM_TOOLKIT_MODULE_ID = "wfrp4e-gm-toolkit";
const GM_TOOLKIT_TABLE_PACK_ID = "gm-toolkit-tables";

export function discoverGmToolkitDarkWhispersCandidates(
  tables: readonly unknown[],
  moduleVersion?: string,
): GmToolkitDarkWhispersSourceCandidate[] {
  return tables.flatMap((table) => parseCandidate(table, moduleVersion)).sort(compareCandidates);
}

export function buildGmToolkitDarkWhispersMigrationPreview(
  candidates: readonly GmToolkitDarkWhispersSourceCandidate[],
  library: DarkWhispersPromptLibrary,
  libraryWarnings: readonly string[] = [],
): GmToolkitDarkWhispersMigrationPreview {
  const previews = candidates.map((candidate) => ({
    ...candidate,
    prompts: candidate.prompts.map((prompt) => ({
      ...prompt,
      comparison: comparePrompt(candidate.tableId, prompt.resultId, prompt.text, library),
    })),
    warnings: [...candidate.warnings],
  }));
  const topConfidence = previews[0]?.confidence;
  const equallyRanked = previews.filter((candidate) => candidate.confidence === topConfidence);
  const recommendedTableId = equallyRanked[0]?.tableId;
  const warnings = [...libraryWarnings];

  if (previews.length > 1) {
    warnings.push(
      `${previews.length} possible Dark Whispers tables were found. Review the selected source before importing.`,
    );
  }

  if (previews.length === 0) {
    warnings.push(
      "No imported GM Toolkit Dark Whispers table was found in this world. The source table is not created or modified.",
    );
  }

  return {
    candidates: previews,
    currentPromptCount: library.prompts.length,
    ...(recommendedTableId ? { recommendedTableId } : {}),
    warnings,
  };
}

export function applyGmToolkitDarkWhispersImport(
  preview: GmToolkitDarkWhispersMigrationPreview,
  library: DarkWhispersPromptLibrary,
  request: GmToolkitDarkWhispersImportRequest,
  importedAt: string,
): { added: number; library: DarkWhispersPromptLibrary; replaced: number; skipped: number } {
  const candidate = preview.candidates.find((item) => item.tableId === request.tableId);

  if (!candidate) {
    throw new Error("Select an available GM Toolkit Dark Whispers table.");
  }

  const selectedIds = new Set(request.resultIds);
  const selectedPrompts = candidate.prompts.filter((prompt) => selectedIds.has(prompt.resultId));

  if (selectedPrompts.length === 0) {
    throw new Error("Select at least one Dark Whispers prompt to import.");
  }

  const prompts = library.prompts.map((prompt) => ({
    ...prompt,
    ...(prompt.source ? { source: { ...prompt.source } } : {}),
  }));
  let added = 0;
  let replaced = 0;
  let skipped = 0;

  for (const sourcePrompt of selectedPrompts) {
    const sourceIndex = prompts.findIndex(
      (prompt) =>
        prompt.source?.type === "gm-toolkit" &&
        prompt.source.tableId === candidate.tableId &&
        prompt.source.resultId === sourcePrompt.resultId,
    );
    const duplicate = prompts.some((prompt) => prompt.text === sourcePrompt.text);

    if (sourceIndex >= 0) {
      const existingPrompt = prompts[sourceIndex]!;

      if (existingPrompt.text === sourcePrompt.text) {
        skipped += 1;
        continue;
      }

      if (request.conflictPolicy === "preserve") {
        skipped += 1;
        continue;
      }

      prompts[sourceIndex] = {
        ...existingPrompt,
        source: sourceFor(candidate, sourcePrompt.resultId),
        text: sourcePrompt.text,
      };
      replaced += 1;
      continue;
    }

    if (duplicate) {
      skipped += 1;
      continue;
    }

    prompts.push({
      id: importedPromptId(candidate.tableId, sourcePrompt.resultId),
      source: sourceFor(candidate, sourcePrompt.resultId),
      text: sourcePrompt.text,
    });
    added += 1;
  }

  return {
    added,
    library: {
      lastImport: {
        conflictPolicy: request.conflictPolicy,
        importedAt,
        resultIds: selectedPrompts.map((prompt) => prompt.resultId),
        ...(candidate.moduleVersion ? { sourceModuleVersion: candidate.moduleVersion } : {}),
        sourceTableId: candidate.tableId,
        sourceTableName: candidate.tableName,
      },
      prompts,
      version: 1,
    },
    replaced,
    skipped,
  };
}

function parseCandidate(
  value: unknown,
  moduleVersion?: string,
): GmToolkitDarkWhispersSourceCandidate[] {
  if (!isRecord(value)) {
    return [];
  }

  const tableId = readString(value["_id"]);
  const tableName = readString(value["name"]);
  const confidence = getConfidence(value, tableId, tableName);

  if (!tableId || !tableName || !confidence) {
    return [];
  }

  const warnings: string[] = [];
  const results = Array.isArray(value["results"]) ? value["results"] : [];
  const prompts = results.flatMap((result, index) => {
    if (!isRecord(result)) {
      warnings.push(`Table row ${index + 1} was invalid and was skipped.`);
      return [];
    }

    const resultId = readString(result["_id"]);
    const text = normalizeDarkWhispersPromptText(result["description"]);

    if (!resultId || !text) {
      warnings.push(`Table row ${index + 1} had no stable ID or prompt text and was skipped.`);
      return [];
    }

    return [
      {
        range: readRange(result["range"], index),
        resultId,
        text,
      },
    ];
  });

  if (prompts.length === 0) {
    warnings.push("The table contains no importable prompt rows.");
  }

  return [
    {
      confidence,
      ...(moduleVersion ? { moduleVersion } : {}),
      prompts,
      tableId,
      tableName,
      warnings,
    },
  ];
}

function getConfidence(
  value: Record<string, unknown>,
  tableId: string,
  tableName: string,
): GmToolkitContentConfidence | undefined {
  const stats = isRecord(value["_stats"]) ? value["_stats"] : {};
  const flags = isRecord(value["flags"]) ? value["flags"] : {};
  const wfrpFlags = isRecord(flags["wfrp4e"]) ? flags["wfrp4e"] : {};
  const toolkitFlags = flags[GM_TOOLKIT_MODULE_ID];
  const compendiumSource = readString(stats["compendiumSource"]);
  const exactName = tableName === DARK_WHISPERS_TABLE_NAME;

  if (
    (exactName &&
      compendiumSource.includes(`${GM_TOOLKIT_MODULE_ID}.${GM_TOOLKIT_TABLE_PACK_ID}`)) ||
    readString(wfrpFlags["key"]).toLowerCase() === "darkwhispers" ||
    (exactName && isRecord(toolkitFlags))
  ) {
    return "metadata";
  }

  if (tableId === DARK_WHISPERS_TABLE_ID) {
    return "id";
  }

  return exactName ? "name" : undefined;
}

function readRange(value: unknown, fallbackIndex: number): string {
  if (
    Array.isArray(value) &&
    value.length >= 2 &&
    Number.isFinite(Number(value[0])) &&
    Number.isFinite(Number(value[1]))
  ) {
    const minimum = Number(value[0]);
    const maximum = Number(value[1]);
    return minimum === maximum ? String(minimum) : `${minimum}–${maximum}`;
  }

  return String(fallbackIndex + 1);
}

function compareCandidates(
  left: GmToolkitDarkWhispersSourceCandidate,
  right: GmToolkitDarkWhispersSourceCandidate,
): number {
  const rank: Record<GmToolkitContentConfidence, number> = { id: 2, metadata: 3, name: 1 };
  return (
    rank[right.confidence] - rank[left.confidence] || right.prompts.length - left.prompts.length
  );
}

function comparePrompt(
  tableId: string,
  resultId: string,
  text: string,
  library: DarkWhispersPromptLibrary,
): GmToolkitContentComparison {
  const sourcePrompt = library.prompts.find(
    (prompt) =>
      prompt.source?.type === "gm-toolkit" &&
      prompt.source.tableId === tableId &&
      prompt.source.resultId === resultId,
  );

  if (sourcePrompt) {
    return sourcePrompt.text === text ? "same" : "conflict";
  }

  return library.prompts.some((prompt) => prompt.text === text) ? "duplicate" : "new";
}

function sourceFor(candidate: GmToolkitDarkWhispersCandidatePreview, resultId: string) {
  return {
    ...(candidate.moduleVersion ? { moduleVersion: candidate.moduleVersion } : {}),
    resultId,
    tableId: candidate.tableId,
    type: "gm-toolkit" as const,
  };
}

function importedPromptId(tableId: string, resultId: string): string {
  return `gm-toolkit:${tableId}:${resultId}`;
}
