import type {
  ImperialDateFields,
  ImperialDateTime,
  ImperialElapsedTime,
} from "../../types/imperial-calendar/Calendar";
import { validateImperialDateTime } from "./calculate";

export function readImperialDateFields(fields: ImperialDateFields): ImperialDateTime {
  const time = fields.time.trim() || "00:00:00";
  if (!/^\d{2}:\d{2}(?::\d{2})?$/.test(time)) {
    throw new RangeError("Use a 24-hour time: HH:MM or HH:MM:SS.");
  }
  const [hour = 0, minute = 0, second = 0] = time.split(":").map(Number);
  const date: ImperialDateTime = {
    year: fields.year === "" ? Number.NaN : Number(fields.year),
    period: fields.period,
    day: fields.day === "" ? Number.NaN : Number(fields.day),
    hour,
    minute,
    second,
  };
  validateImperialDateTime(date);
  return date;
}

export function formatImperialDuration(result: ImperialElapsedTime, useYears = false): string {
  const parts: [number, string][] = useYears
    ? [
        [result.years, "year"],
        [result.days, "day"],
      ]
    : [[result.wholeDays, "day"]];
  parts.push([result.hours, "hour"], [result.minutes, "minute"], [result.seconds, "second"]);
  return (
    parts
      .filter(([value]) => value > 0)
      .map(([value, unit]) => `${value.toLocaleString()} ${unit}${value === 1 ? "" : "s"}`)
      .join(", ") || "0 seconds"
  );
}
