import type { DamageProtection, DamageRequest } from "../../types/damage/Damage";
import {
  buildDamageBatchPlan,
  formatDamageBatchFailure,
  formatDamageResult,
  getDamageTypeKey,
  normalizeDamageRollTotal,
  resolveDamageLocation,
} from "../../functions/damage/plan";
import { resolveActors } from "../actors/selection";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";

interface DamageActorRuntime extends FoundryActorDocument {
  applyBasicDamage: (damage: number, options: Record<string, unknown>) => Promise<unknown>;
  system: {
    details?: { hitLocationTable?: { value?: string } };
    status?: { wounds?: { value?: number } };
  };
}

interface RollResult {
  total?: number;
}

export async function applyDamage(request: DamageRequest): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.damageConsole);
  const plan = buildDamageBatchPlan(request);
  const actors = (await resolveActors(plan.uuids)) as DamageActorRuntime[];
  if (actors.length === 0) throw new Error("None of the selected actors are available.");
  const sharedDamage = plan.rollDamagePerActor ? undefined : await evaluateFormula(plan.formula);
  const sharedLocation = plan.rollLocationPerActor
    ? undefined
    : resolveDamageLocation(plan.location, await rollSharedLocation(plan.location));
  const results: string[] = [];
  const failures: string[] = [];

  for (const actor of actors) {
    try {
      const damage = sharedDamage ?? (await evaluateFormula(plan.formula));
      const location = sharedLocation ?? (await rollActorLocation(actor));
      const message = await actor.applyBasicDamage(damage, {
        damageType: getDamageType(request.protection),
        loc: location,
        minimumOne: request.minimumOne,
        suppressMsg: true,
      });
      results.push(
        typeof message === "string"
          ? message
          : formatDamageResult({ actorName: actor.name, damage }),
      );
    } catch (error) {
      const reason = error instanceof Error ? error.message : "unknown error";
      failures.push(formatDamageResult({ actorName: actor.name, error: reason }));
    }
  }

  const whisper = Array.from(game.users)
    .filter((user) => user.isGM)
    .map((user) => user.id);
  await ChatMessage.create({ content: [...results, ...failures].join("<hr>"), whisper });
  if (failures.length > 0)
    throw new Error(formatDamageBatchFailure(results.length, failures.length));
}

async function evaluateFormula(formula: string): Promise<number> {
  const result = (await new Roll(formula).evaluate()) as RollResult;
  return normalizeDamageRollTotal(result.total, formula);
}

async function rollSharedLocation(location: string): Promise<string | undefined> {
  return location === "roll" ? rollHitLocation("hitloc") : undefined;
}

async function rollActorLocation(actor: DamageActorRuntime): Promise<string> {
  return rollHitLocation(actor.system.details?.hitLocationTable?.value ?? "hitloc");
}

async function rollHitLocation(table: string): Promise<string> {
  const runtime = game as unknown as {
    wfrp4e: {
      tables: {
        rollTable: (
          table: string,
          options?: Record<string, unknown>,
        ) => Promise<{ result?: string }>;
      };
    };
  };
  const result = await runtime.wfrp4e.tables.rollTable(table, { hideDSN: true });
  return String(result.result ?? "body");
}

function getDamageType(protection: DamageProtection): unknown {
  const types = (
    game as unknown as { wfrp4e: { config: { DAMAGE_TYPE: Record<string, unknown> } } }
  ).wfrp4e.config.DAMAGE_TYPE;
  return types[getDamageTypeKey(protection)];
}
