<script setup lang="ts">
const props = defineProps<{
  actorId: string;
  actorName: string;
  checked: boolean;
  disabled: boolean;
  purpose: string;
}>();

const emit = defineEmits<{
  change: [actorId: string, selected: boolean];
}>();

function updateSelection(event: Event): void {
  if (event.currentTarget instanceof HTMLInputElement) {
    emit("change", props.actorId, event.currentTarget.checked);
  }
}
</script>

<template>
  <label class="tw:cursor-pointer">
    <input
      class="dui-checkbox dui-checkbox-primary dui-checkbox-sm tw:appearance-none! tw:rounded-sm! tw:border-2! tw:border-primary! tw:bg-base-100! tw:bg-none! tw:shadow-none! tw:checked:border-primary! tw:checked:bg-primary! tw:checked:bg-none! tw:checked:text-primary-content!"
      type="checkbox"
      :checked="checked"
      :disabled="disabled"
      @change="updateSelection"
    />
    <span class="tw:sr-only">Include {{ actorName }} in {{ purpose }}</span>
  </label>
</template>
