import type { Component } from "vue";

import type { AdministrationActions } from "../../../types/administration/Administration";
import AdministrationConsoleApp from "../../../view/apps/administration-console/AdministrationConsoleApp.vue";
import { getAdministrationInitialization } from "../../administration/initialization";
import {
  rollD100,
  setCompendiumVisibility,
  setSceneLighting,
  setUnassignedPlayerWarning,
} from "../../administration/service";
import { MODULE_ID, MODULE_TITLE } from "../../constants";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../access";

export class AdministrationConsoleApplication extends FoundryVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.administrationConsole;
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    classes: [MODULE_ID, `${MODULE_ID}-administration-console`],
    id: `${MODULE_ID}-administration-console`,
    position: { height: 760, width: 760 },
    window: {
      icon: "fa-solid fa-screwdriver-wrench",
      resizable: true,
      title: `${MODULE_TITLE} — Administration Console`,
    },
  };

  protected override getVueComponent(): Component {
    return AdministrationConsoleApp;
  }
  protected override getVueProps(): Record<string, unknown> {
    const actions: AdministrationActions = {
      rollD100,
      setCompendiumVisibility,
      setSceneLighting,
      setUnassignedPlayerWarning,
    };
    return { actions, initialization: getAdministrationInitialization() };
  }
}
