import {
  calculatePreservedLightRadiusScale,
  hasValidGridMeasurements,
} from "../../functions/grid-scale/calculate";

interface GridScale {
  distance: number;
  size: number;
  units: string;
}

interface EmbeddedDocumentUpdate {
  _id: string;
  [path: string]: number | string;
}

export async function changeGridScalePreservingLighting(): Promise<void> {
  const scene = canvas?.scene;
  const currentUser = game.user;

  if (!scene) {
    ui.notifications.warn("No Scene is currently viewed.");
    return;
  }

  if (!currentUser) {
    ui.notifications.error("No current Foundry user is available.");
    return;
  }

  if (!scene.canUserModify(currentUser, "update")) {
    ui.notifications.error("You do not have permission to update this Scene.");
    return;
  }

  const oldGrid: GridScale = {
    distance: Number(scene.grid.distance),
    size: Number(scene.grid.size),
    units: String(scene.grid.units ?? ""),
  };

  if (!hasValidGridMeasurements(oldGrid)) {
    ui.notifications.error("The current Scene has an invalid grid size or distance.");
    return;
  }

  const newGrid = await promptForGridScale(oldGrid);
  if (!newGrid) return;

  if (!hasValidGridMeasurements(newGrid)) {
    ui.notifications.error("Grid size and distance must both be positive numbers.");
    return;
  }

  await updateSceneGridAndLighting(scene, oldGrid, newGrid);
}

async function promptForGridScale(oldGrid: GridScale): Promise<GridScale | null> {
  const units = foundry.utils.escapeHTML(oldGrid.units);
  const values = await foundry.applications.api.DialogV2.input({
    window: { title: "Change Grid Scale" },
    position: { width: 480 },
    content: `
      <form class="standard-form">
        <p class="notes">
          Ambient Lights and Token-emitted light radii will keep the same rendered size.
        </p>
        <div class="form-group">
          <label for="drowsy-grid-scale-size">Grid size (pixels)</label>
          <div class="form-fields">
            <input
              id="drowsy-grid-scale-size"
              name="size"
              type="number"
              min="1"
              step="1"
              value="${oldGrid.size}"
              required
            />
          </div>
        </div>
        <div class="form-group">
          <label for="drowsy-grid-scale-distance">Distance per space</label>
          <div class="form-fields">
            <input
              id="drowsy-grid-scale-distance"
              name="distance"
              type="number"
              min="0.000001"
              step="any"
              value="${oldGrid.distance}"
              required
            />
          </div>
        </div>
        <div class="form-group">
          <label for="drowsy-grid-scale-units">Units</label>
          <div class="form-fields">
            <input
              id="drowsy-grid-scale-units"
              name="units"
              type="text"
              value="${units}"
            />
          </div>
        </div>
      </form>
    `,
    ok: {
      label: "Update Grid",
      icon: "fa-solid fa-grid-2",
    },
    modal: true,
    rejectClose: false,
  });

  if (!values) return null;

  return {
    distance: Number(values.distance),
    size: Number(values.size),
    units: String(values.units ?? "").trim(),
  };
}

async function updateSceneGridAndLighting(
  scene: FoundrySceneDocument,
  oldGrid: GridScale,
  newGrid: GridScale,
): Promise<void> {
  const lightScale = calculatePreservedLightRadiusScale(oldGrid, newGrid);
  const oldAmbientLights = scene.lights.map((light) => ({
    "_id": light.id,
    "config.bright": light.config.bright,
    "config.dim": light.config.dim,
  }));
  const newAmbientLights = scene.lights.map((light) => ({
    "_id": light.id,
    "config.bright": light.config.bright * lightScale,
    "config.dim": light.config.dim * lightScale,
  }));
  const oldTokenLights = scene.tokens.map((token) => ({
    "_id": token.id,
    "light.bright": token.light.bright,
    "light.dim": token.light.dim,
  }));
  const newTokenLights = scene.tokens.map((token) => ({
    "_id": token.id,
    "light.bright": token.light.bright * lightScale,
    "light.dim": token.light.dim * lightScale,
  }));

  let ambientLightsChanged = false;
  let tokenLightsChanged = false;

  try {
    if (newAmbientLights.length > 0) {
      await scene.updateEmbeddedDocuments("AmbientLight", newAmbientLights);
      ambientLightsChanged = true;
    }

    if (newTokenLights.length > 0) {
      await scene.updateEmbeddedDocuments("Token", newTokenLights);
      tokenLightsChanged = true;
    }

    await scene.update(gridUpdate(newGrid));

    ui.notifications.info(
      `Grid updated from ${describeGrid(oldGrid)} to ${describeGrid(newGrid)}.`,
    );
  } catch (error: unknown) {
    const rollbackResults = await rollbackGridAndLighting({
      ambientLightsChanged,
      oldAmbientLights,
      oldGrid,
      oldTokenLights,
      scene,
      tokenLightsChanged,
    });
    const rollbackFailed = rollbackResults.some((result) => result.status === "rejected");
    const message = rollbackFailed
      ? "Grid update failed, and at least one rollback also failed. Check the console."
      : "Grid update failed. Any completed changes were rolled back.";

    console.error("Change Grid Scale macro failed.", error, rollbackResults);
    throw new Error(message, { cause: error });
  }
}

async function rollbackGridAndLighting(options: {
  ambientLightsChanged: boolean;
  oldAmbientLights: EmbeddedDocumentUpdate[];
  oldGrid: GridScale;
  oldTokenLights: EmbeddedDocumentUpdate[];
  scene: FoundrySceneDocument;
  tokenLightsChanged: boolean;
}): Promise<PromiseSettledResult<unknown>[]> {
  const rollback: Array<Promise<unknown>> = [];

  if (
    options.scene.grid.size !== options.oldGrid.size ||
    options.scene.grid.distance !== options.oldGrid.distance ||
    options.scene.grid.units !== options.oldGrid.units
  ) {
    rollback.push(options.scene.update(gridUpdate(options.oldGrid)));
  }

  if (options.ambientLightsChanged) {
    rollback.push(options.scene.updateEmbeddedDocuments("AmbientLight", options.oldAmbientLights));
  }

  if (options.tokenLightsChanged) {
    rollback.push(options.scene.updateEmbeddedDocuments("Token", options.oldTokenLights));
  }

  return Promise.allSettled(rollback);
}

function gridUpdate(grid: GridScale): Record<string, number | string> {
  return {
    "grid.distance": grid.distance,
    "grid.size": grid.size,
    "grid.units": grid.units,
  };
}

function describeGrid(grid: GridScale): string {
  return `${grid.size}px/${grid.distance}${grid.units}`;
}
