import { computed, ref } from "vue";
import { defineStore } from "pinia";

import { calculateImperialElapsedTime } from "../../../functions/imperial-calendar/calculate";
import { getImperialPeriod } from "../../../functions/imperial-calendar/calendar";
import { readImperialDateFields } from "../../../functions/imperial-calendar/fields";
import type { ImperialDateFields } from "../../../types/imperial-calendar/Calendar";

export const useImperialCalendarStore = defineStore("imperial-calendar", () => {
  const start = ref<ImperialDateFields>(initialDate());
  const end = ref<ImperialDateFields>(initialDate());
  const calculation = computed(() => {
    let label = "Start";
    try {
      const startDate = readImperialDateFields(start.value);
      label = "End";
      const endDate = readImperialDateFields(end.value);
      return { error: undefined, result: calculateImperialElapsedTime(startDate, endDate) };
    } catch (error: unknown) {
      if (!(error instanceof RangeError)) throw error;
      return { error: `${label}: ${error.message}`, result: undefined };
    }
  });

  function changePeriod(endpoint: "start" | "end", period: string): void {
    const fields = endpoint === "start" ? start.value : end.value;
    fields.period = period;
    // A festival has no numbered date choice. Other invalid dates stay visible for correction.
    if (getImperialPeriod(period).intercalary) fields.day = 1;
  }

  function swapDates(): void {
    [start.value, end.value] = [end.value, start.value];
  }

  return { start, end, calculation, changePeriod, swapDates };
});

function initialDate(): ImperialDateFields {
  return { year: 2522, period: "Hexenstag", day: 1, time: "00:00:00" };
}
