import { normalizeXpCurveParameters } from "../../functions/xp-curve/calculate";
import type {
  XpCurveConfiguratorInitialization,
  XpCurveConfiguratorSettings,
} from "../../types/xp-curve/Configuration";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";
import { MODULE_ID } from "../constants";
import { getXpActorChoices } from "./actors";
import { XP_CURVE_SETTINGS } from "./settings/keys";
import { getXpCurveSettings, isXpCurveLauncherEnabled, saveXpCurveSettings } from "./settings/load";

export function getXpCurveConfiguratorInitialization(): XpCurveConfiguratorInitialization {
  const settings = getXpCurveSettings();

  return {
    ...settings,
    actors: getXpActorChoices(settings.defaultSelection).actors,
    launchers: {
      tokenControls: isXpCurveLauncherEnabled(XP_CURVE_SETTINGS.showTokenControlsLauncher),
    },
  };
}

export async function saveXpCurveConfiguratorSettings(
  configuration: XpCurveConfiguratorSettings,
): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.xpCurveConsole);

  await saveXpCurveSettings({
    defaultReason: configuration.defaultReason,
    defaultSelection: configuration.defaultSelection,
    parameters: normalizeXpCurveParameters(configuration.parameters),
  });
  await game.settings.set(
    MODULE_ID,
    XP_CURVE_SETTINGS.showTokenControlsLauncher,
    configuration.launchers.tokenControls,
  );

  ui.notifications.info("XP Curve Console configuration saved.");
}
