import type { Component } from "vue";

import type { ToolkitHomeSection } from "../../../types/toolkit-home/Console";
import ToolkitHomeApp from "../../../view/apps/toolkit-home/ToolkitHomeApp.vue";
import { MODULE_ID, MODULE_TITLE } from "../../constants";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../access";

export class ToolkitHomeApplication extends FoundryVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.toolkitHome;

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    classes: [MODULE_ID, `${MODULE_ID}-toolkit-home`],
    id: `${MODULE_ID}-toolkit-home`,
    position: { height: 720, width: 760 },
    window: { icon: "fa-solid fa-toolbox", resizable: true, title: MODULE_TITLE },
  };

  constructor(private readonly sections: ToolkitHomeSection[]) {
    super();
  }

  protected override getVueComponent(): Component {
    return ToolkitHomeApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    return { sections: this.sections };
  }
}
