import type { SessionConfiguration } from "../../../types/session-management/Configuration";
import { getXpAwardSettings } from "../../xp-award/settings/load";
import { parseSessionManagementState } from "../../../functions/session-management/session";
import type { SessionManagementState } from "../../../types/session-management/SessionManagement";
import { MODULE_ID } from "../../constants";
import { SESSION_MANAGEMENT_SETTINGS } from "./keys";

export function getSessionManagementState(): SessionManagementState {
  return parseSessionManagementState(
    game.settings.get(MODULE_ID, SESSION_MANAGEMENT_SETTINGS.state),
  );
}

export function getCurrentSessionReference(): string {
  return getSessionManagementState().currentSessionReference;
}

export function getSessionTurnoverSettings(): SessionConfiguration {
  const pullPolicy = game.settings.get(MODULE_ID, SESSION_MANAGEMENT_SETTINGS.pullPolicy);

  const options = readOptions();
  const xp = getXpAwardSettings();
  const holdingSceneUuid = String(
    game.settings.get(MODULE_ID, SESSION_MANAGEMENT_SETTINGS.holdingSceneUuid) ?? "",
  ).trim();
  return {
    pause: options["pause"] !== false,
    fortuneReset: options["fortuneReset"] !== false,
    holdingScene:
      typeof options["holdingScene"] === "boolean"
        ? options["holdingScene"]
        : Boolean(holdingSceneUuid),
    xp: {
      defaultAmount:
        typeof options["defaultAmount"] === "number"
          ? options["defaultAmount"]
          : Math.max(0, xp.defaultAmount),
      defaultReason:
        typeof options["defaultReason"] === "string" ? options["defaultReason"] : xp.defaultReason,
      defaultSelection:
        options["defaultSelection"] === "party" ||
        options["defaultSelection"] === "company" ||
        options["defaultSelection"] === "world"
          ? options["defaultSelection"]
          : xp.defaultSelection,
      includeTimestampInReason:
        typeof options["includeTimestampInReason"] === "boolean"
          ? options["includeTimestampInReason"]
          : xp.includeTimestampInReason,
    },
    exportChat: game.settings.get(MODULE_ID, SESSION_MANAGEMENT_SETTINGS.exportChat) === true,
    holdingSceneUuid,
    pullPolicy: pullPolicy === "activate" || pullPolicy === "prompt" ? pullPolicy : "pull",
  };
}

export async function saveSessionTurnoverSettings(
  settings: {
    exportChat: boolean;
    holdingSceneUuid: string;
    pullPolicy: "activate" | "prompt" | "pull";
  } & Partial<SessionConfiguration>,
): Promise<void> {
  if (settings.xp) {
    await game.settings.set(
      MODULE_ID,
      SESSION_MANAGEMENT_SETTINGS.options,
      JSON.stringify({
        pause: settings.pause,
        fortuneReset: settings.fortuneReset,
        holdingScene: settings.holdingScene,
        ...settings.xp,
      }),
    );
  }
  await game.settings.set(
    MODULE_ID,
    SESSION_MANAGEMENT_SETTINGS.holdingSceneUuid,
    settings.holdingSceneUuid.trim(),
  );
  await game.settings.set(MODULE_ID, SESSION_MANAGEMENT_SETTINGS.exportChat, settings.exportChat);
  await game.settings.set(MODULE_ID, SESSION_MANAGEMENT_SETTINGS.pullPolicy, settings.pullPolicy);
}

export async function saveSessionManagementState(state: SessionManagementState): Promise<void> {
  await game.settings.set(MODULE_ID, SESSION_MANAGEMENT_SETTINGS.state, JSON.stringify(state));
}

function readOptions(): Record<string, unknown> {
  const raw = game.settings.get(MODULE_ID, SESSION_MANAGEMENT_SETTINGS.options);
  if (typeof raw !== "string") return {};
  try {
    const parsed: unknown = JSON.parse(raw);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed)
      ? (parsed as Record<string, unknown>)
      : {};
  } catch {
    return {};
  }
}
