export type AdvantageParticipant = "attacker" | "defender";

export interface AdvantageChange {
  amount: number;
  mode: "add" | "set";
  participant: AdvantageParticipant;
}

export function buildOpposedAdvantagePlan(
  winner: AdvantageParticipant,
  usesGroupAdvantage: boolean,
): AdvantageChange[] {
  const loser: AdvantageParticipant = winner === "attacker" ? "defender" : "attacker";

  if (usesGroupAdvantage) {
    return winner === "attacker" ? [{ amount: 1, mode: "add", participant: "attacker" }] : [];
  }

  return [
    { amount: 0, mode: "set", participant: loser },
    { amount: 1, mode: "add", participant: winner },
  ];
}

export function selectMomentumLossActorIds(
  combatants: readonly {
    actorId: string;
    currentAdvantage: number;
    roundStartAdvantage: number;
  }[],
): string[] {
  return combatants
    .filter(
      ({ currentAdvantage, roundStartAdvantage }) =>
        currentAdvantage > 0 && currentAdvantage <= roundStartAdvantage,
    )
    .map(({ actorId }) => actorId);
}
