import { computed, ref } from "vue";
import { defineStore } from "pinia";

import { calculateFixedXpAwardPlan } from "../../../functions/xp-award/calculate";
import { resolveFixedXpAwardReason } from "../../../functions/xp-award/reason";
import type { XpDefaultSelection } from "../../../types/xp-curve/XpCurve";
import type { XpAwardConsoleActions } from "../../../types/xp-award/Console";
import type { XpAwardConsoleInitialization, XpAwardRequest } from "../../../types/xp-award/XpAward";
import { createXpActorSelection } from "../shared/xp-actor-selection";

export const useXpAwardConsoleStore = defineStore("xp-award-console", () => {
  const {
    actors,
    initializeActors,
    resetSelection,
    selectedActors,
    setActorSelected,
    setAllActorsSelected,
  } = createXpActorSelection("The XP Award Console");
  const amount = ref(20);
  const defaultReason = ref("");
  const defaultSelection = ref<XpDefaultSelection>("party");
  const includeTimestampInReason = ref(true);
  const selectionSource = ref<"default" | "targets">("default");
  const errorMessage = ref<undefined | string>();
  const isWorking = ref(false);
  const isSettingsOpen = ref(false);
  let actions: XpAwardConsoleActions | undefined;
  let initialization: XpAwardConsoleInitialization | undefined;
  const plan = computed(() => calculateFixedXpAwardPlan(actors.value, amount.value));
  const canApply = computed(
    () =>
      selectedActors.value.length > 0 &&
      Number.isSafeInteger(amount.value) &&
      amount.value !== 0 &&
      !isWorking.value &&
      !isSettingsOpen.value,
  );
  const resolvedReason = computed(() => {
    const context = getInitialization().reasonContext;

    return resolveFixedXpAwardReason(defaultReason.value, context, includeTimestampInReason.value);
  });

  function initialize(
    nextInitialization: XpAwardConsoleInitialization,
    nextActions: XpAwardConsoleActions,
  ): void {
    actions = nextActions;
    initialization = nextInitialization;
    initializeActors(nextInitialization.actors);
    amount.value = nextInitialization.defaultAmount;
    defaultReason.value = nextInitialization.defaultReason;
    defaultSelection.value = nextInitialization.defaultSelection;
    includeTimestampInReason.value = nextInitialization.includeTimestampInReason;
    selectionSource.value = nextInitialization.selectionSource;
    errorMessage.value = undefined;
  }

  async function openSettings(): Promise<void> {
    if (isWorking.value || isSettingsOpen.value) return;
    isSettingsOpen.value = true;
    errorMessage.value = undefined;
    try {
      await getActions().openSettings((next) => {
        const previous = getInitialization();
        // Adopt new defaults only where the GM has not edited this award.
        if (amount.value === previous.defaultAmount) amount.value = next.defaultAmount;
        if (defaultReason.value === previous.defaultReason)
          defaultReason.value = next.defaultReason;
        const selectionUnchanged = actors.value.every(
          (actor) =>
            actor.selected === previous.actors.find((entry) => entry.id === actor.id)?.selected,
        );
        if (selectionUnchanged) {
          initializeActors(next.actors);
          selectionSource.value = next.selectionSource;
        }
        defaultSelection.value = next.defaultSelection;
        includeTimestampInReason.value = next.includeTimestampInReason;
        initialization = next;
      });
    } catch (error) {
      console.error("Drowsy’s WFRP4e Toolkit | Could not open XP settings.", error);
      errorMessage.value = error instanceof Error ? error.message : "Could not open XP settings.";
    } finally {
      isSettingsOpen.value = false;
    }
  }

  async function applyAwards(): Promise<void> {
    if (!canApply.value || isWorking.value) {
      return;
    }

    isWorking.value = true;
    errorMessage.value = undefined;

    try {
      const request: XpAwardRequest = {
        actorIds: selectedActors.value.map((actor) => actor.id),
        defaultAmount: Math.round(amount.value),
        defaultReason: defaultReason.value,
        defaultSelection: defaultSelection.value,
        includeTimestampInReason: includeTimestampInReason.value,
      };
      const result = await getActions().applyAwards(request);
      getActions().onActionComplete(result);
    } catch (error) {
      console.error("Drowsy’s WFRP4e Toolkit | Fixed XP award failed.", error);
      errorMessage.value =
        error instanceof Error ? error.message : "The XP changes could not be completed.";
    } finally {
      isWorking.value = false;
    }
  }

  function getActions(): XpAwardConsoleActions {
    if (!actions) {
      throw new Error("The XP Award Console has not been initialized.");
    }

    return actions;
  }

  function getInitialization(): XpAwardConsoleInitialization {
    if (!initialization) {
      throw new Error("The XP Award Console has not been initialized.");
    }

    return initialization;
  }

  return {
    actors,
    amount,
    applyAwards,
    canApply,
    defaultReason,
    defaultSelection,
    errorMessage,
    includeTimestampInReason,
    initialize,
    isWorking,
    isSettingsOpen,
    openSettings,
    plan,
    resetSelection,
    resolvedReason,
    selectedActors,
    selectionSource,
    setActorSelected,
    setAllActorsSelected,
  };
});
