import { ref } from "vue";
import { defineStore } from "pinia";
import type { XpAwardSettingsActions } from "../../../types/xp-award/Console";
import type { XpAwardSettings } from "../../../types/xp-award/XpAward";

export const useXpAwardSettingsStore = defineStore("xp-award-settings", () => {
  const settings = ref<XpAwardSettings>();
  const isWorking = ref(false);
  const errorMessage = ref<string>();
  let actions: XpAwardSettingsActions;

  function initialize(data: XpAwardSettings, callbacks: XpAwardSettingsActions): void {
    settings.value = { ...data };
    actions = callbacks;
  }

  async function save(): Promise<void> {
    if (isWorking.value || !settings.value) return;
    isWorking.value = true;
    errorMessage.value = undefined;
    try {
      if (!Number.isSafeInteger(settings.value.defaultAmount) || settings.value.defaultAmount === 0)
        throw new Error("Enter a non-zero whole-number XP amount.");
      await actions.save({ ...settings.value });
    } catch (error) {
      console.error("Drowsy’s WFRP4e Toolkit | Could not save XP settings.", error);
      errorMessage.value = error instanceof Error ? error.message : "Could not save XP settings.";
    } finally {
      isWorking.value = false;
    }
  }
  return { errorMessage, initialize, isWorking, save, settings };
});
