import type { XpAwardConsoleInitialization } from "../../types/xp-award/XpAward";
import { formatXpAwardDateTime } from "../../functions/xp-award/reason";
import { getCurrentSessionReference } from "../session-management/settings/load";
import { getXpActorChoices } from "../xp-curve/actors";
import { getXpAwardSettings } from "./settings/load";

export function getXpAwardConsoleInitialization(): XpAwardConsoleInitialization {
  const settings = getXpAwardSettings();
  const selection = getXpActorChoices(settings.defaultSelection);
  const awardedAt = new Date().toISOString();

  return {
    ...settings,
    ...selection,
    awardedAt,
    reasonContext: {
      date: awardedAt.slice(0, 10),
      datetime: formatXpAwardDateTime(awardedAt),
      session: getCurrentSessionReference(),
    },
  };
}
