import type { GroupTestRequest } from "../../types/group-test/GroupTest";

const DIFFICULTIES = [
  "impossible",
  "futile",
  "vhard",
  "hard",
  "difficult",
  "challenging",
  "average",
  "easy",
  "veasy",
] as const;

export interface GroupTestFallback {
  characteristic: string;
  difficulty: string;
}

export function adjustGroupTestDifficulty(difficulty: string, steps: number): string {
  const index = DIFFICULTIES.indexOf(difficulty as (typeof DIFFICULTIES)[number]);

  if (index < 0) return difficulty;

  return DIFFICULTIES[Math.max(0, Math.min(DIFFICULTIES.length - 1, index + Math.round(steps)))]!;
}

export function resolveGroupTestFallback(
  definition: unknown,
  request: Pick<GroupTestRequest, "difficulty" | "fallbackAdvanced" | "fallbackDifficultySteps">,
): GroupTestFallback | undefined {
  const advanced = readNested(definition, "system", "advanced", "value") === "adv";

  if (advanced && !request.fallbackAdvanced) return undefined;

  return {
    characteristic: String(readNested(definition, "system", "characteristic", "value") ?? "int"),
    difficulty: advanced
      ? adjustGroupTestDifficulty(request.difficulty, request.fallbackDifficultySteps)
      : request.difficulty,
  };
}

export function canAcceptGroupTestResult(
  expectedActorUuids: ReadonlySet<string>,
  receivedActorUuids: ReadonlySet<string>,
  actorUuid: string,
): boolean {
  return expectedActorUuids.has(actorUuid) && !receivedActorUuids.has(actorUuid);
}

function readNested(value: unknown, ...path: string[]): unknown {
  let current = value;

  for (const key of path) {
    if (!current || typeof current !== "object") return undefined;
    current = (current as Record<string, unknown>)[key];
  }

  return current;
}
