import type { AdvantageAdjustmentRequest } from "../../types/combat/Combat";
import { resolveActors } from "../actors/selection";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";

interface AdvantageActorRuntime extends FoundryActorDocument {
  addAdvantage: (amount: number) => Promise<unknown>;
  setAdvantage: (amount: number) => Promise<unknown>;
  system: { status?: { advantage?: { value?: number } } };
  inCombat?: boolean;
}

export async function adjustAdvantage(request: AdvantageAdjustmentRequest): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.combatConsole);
  if (request.uuids.length === 0) throw new Error("Select at least one actor.");
  if (!Number.isFinite(request.amount)) throw new Error("Enter a valid Advantage amount.");
  const amount = Math.max(1, Math.round(Math.abs(request.amount)));
  const actors = (await resolveActors(request.uuids)) as AdvantageActorRuntime[];
  const outsideCombat = actors.filter((actor) => actor.inCombat !== true);
  if (request.mode !== "clear" && outsideCombat.length > 0) {
    throw new Error(
      `Advantage can only be added or reduced in combat: ${outsideCombat.map(({ name }) => name).join(", ")}.`,
    );
  }

  for (const actor of actors) {
    if (request.mode === "clear") await setAdvantage(actor, 0);
    else if (request.mode === "add") await addAdvantage(actor, amount);
    else await addAdvantage(actor, -amount);
  }

  ui.notifications.info(
    `Updated Advantage for ${actors.length} actor${actors.length === 1 ? "" : "s"}.`,
  );
}

export async function addAdvantage(actor: AdvantageActorRuntime, amount: number): Promise<void> {
  if (typeof actor.addAdvantage !== "function")
    throw new Error(`${actor.name} does not expose WFRP4e Advantage controls.`);
  await actor.addAdvantage(amount);
}

export async function setAdvantage(actor: AdvantageActorRuntime, amount: number): Promise<void> {
  const value = Math.max(0, Math.round(amount));
  if (typeof actor.setAdvantage !== "function")
    throw new Error(`${actor.name} does not expose WFRP4e Advantage controls.`);
  await actor.setAdvantage(value);
}

export function asAdvantageActor(value: unknown): AdvantageActorRuntime | undefined {
  if (!value || typeof value !== "object") return undefined;
  const actor = value as Partial<AdvantageActorRuntime>;
  return actor.documentName === "Actor" ? (actor as AdvantageActorRuntime) : undefined;
}
