export interface GridMeasurements {
  distance: number;
  size: number;
}

export function hasValidGridMeasurements(grid: GridMeasurements): boolean {
  return (
    Number.isFinite(grid.size) &&
    grid.size > 0 &&
    Number.isFinite(grid.distance) &&
    grid.distance > 0
  );
}

export function calculatePreservedLightRadiusScale(
  oldGrid: GridMeasurements,
  newGrid: GridMeasurements,
): number {
  return (oldGrid.size / newGrid.size) * (newGrid.distance / oldGrid.distance);
}
