import type {
  DarkWhispersConsoleActions,
  DarkWhispersSettings,
  SendDarkWhispersRequest,
} from "../../types/dark-whispers/Console";
import type { DarkWhispersPrompt } from "../../types/dark-whispers/PromptLibrary";
import type { FoundryActorDocument } from "../../types/foundry";
import { MODULE_ID } from "../constants";
import { resolveActors } from "../actors/selection";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";
import {
  getDarkWhispersPromptLibrary,
  getDarkWhispersSettings,
  saveDarkWhispersPromptLibrary,
  saveDarkWhispersSettings,
} from "./settings/load";

interface WhisperActorRuntime extends FoundryActorDocument {
  ownership?: Record<string, number>;
}

export const darkWhispersActions: DarkWhispersConsoleActions = {
  save: saveDarkWhispers,
  send: sendDarkWhispers,
};

export async function saveDarkWhispers(
  prompts: DarkWhispersPrompt[],
  settings: DarkWhispersSettings,
): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.darkWhispersConsole);
  const current = getDarkWhispersPromptLibrary();
  const normalized = prompts.flatMap((prompt) => {
    const text = prompt.text.trim();
    return text ? [{ ...prompt, id: prompt.id || crypto.randomUUID(), text }] : [];
  });
  await saveDarkWhispersPromptLibrary({ ...current, prompts: normalized });
  await saveDarkWhispersSettings(settings);
  ui.notifications.info("Dark Whispers settings saved.");
}

export async function sendDarkWhispers(request: SendDarkWhispersRequest): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.darkWhispersConsole);
  const message = request.message.trim();
  if (!message) throw new Error("Enter a Dark Whisper message.");
  const actors = (await resolveActors(request.recipientUuids)) as WhisperActorRuntime[];
  const users = new Set<string>();
  for (const actor of actors) {
    const players = Array.from(game.users).filter((user) => !user.isGM);
    if (request.sendToOwners) {
      players
        .filter((user) => Number(actor.ownership?.[user.id] ?? 0) >= 3)
        .forEach((user) => users.add(user.id));
    } else {
      const assigned = players.find((user) => user.character?.id === actor.id);
      if (assigned) users.add(assigned.id);
    }
  }
  if (users.size === 0)
    throw new Error("The selected characters have no eligible player recipients.");
  const safe = foundry.utils.escapeHTML(message);
  const content =
    formatMessage(safe, getDarkWhispersSettings().messageStyle) +
    `<div class="drowsy-dark-whisper-actions" data-prompt="${encodeURIComponent(message)}"><button type="button" data-action="accept">Accept</button><button type="button" data-action="reject">Reject</button></div>`;
  await ChatMessage.create({
    content,
    flags: { [MODULE_ID]: { darkWhisper: true } },
    flavor: actors.map((actor) => actor.name).join(", "),
    whisper: [...users],
  });
}

export function registerDarkWhispersChatHooks(): void {
  Hooks.on("renderChatMessageHTML", (_message, html) => attachResponseListeners(html));
}

function attachResponseListeners(htmlValue: unknown): void {
  const candidate =
    htmlValue instanceof HTMLElement ? htmlValue : (htmlValue as { 0?: unknown } | undefined)?.[0];
  if (!(candidate instanceof HTMLElement)) return;
  for (const button of candidate.querySelectorAll<HTMLButtonElement>(
    ".drowsy-dark-whisper-actions button",
  )) {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      void respondToDarkWhisper(button);
    });
  }
}

async function respondToDarkWhisper(button: HTMLButtonElement): Promise<void> {
  if (game.user?.isGM) return ui.notifications.warn("A player must respond to a Dark Whisper.");
  const actor = game.user?.character;
  if (!actor) return ui.notifications.warn("Assign a character before responding.");
  const wrapper = button.closest<HTMLElement>(".drowsy-dark-whisper-actions");
  if (wrapper?.dataset["responded"] === "true") return;
  const prompt = decodeURIComponent(wrapper?.dataset["prompt"] ?? "");
  const action = button.dataset["action"] === "accept" ? "accepted" : "rejected";
  const whisper = Array.from(game.users)
    .filter((user) => user.isGM)
    .map((user) => user.id);
  await ChatMessage.create({
    content: `<p><strong>${foundry.utils.escapeHTML(actor.name)}</strong> ${action} the Dark Whisper.</p><blockquote>${foundry.utils.escapeHTML(prompt)}</blockquote>`,
    whisper,
  });
  if (wrapper) wrapper.dataset["responded"] = "true";
  wrapper?.querySelectorAll("button").forEach((candidate) => {
    (candidate as HTMLButtonElement).disabled = true;
  });
}

function formatMessage(message: string, style: DarkWhispersSettings["messageStyle"]): string {
  if (style === "plain") return `<blockquote>${message}</blockquote>`;
  if (style === "offer")
    return `<p>A dark power offers you this bargain:</p><blockquote>${message}</blockquote>`;
  return `<p>A dark whisper claws at the edge of your thoughts:</p><blockquote>${message}</blockquote>`;
}
