<script setup lang="ts">
import { storeToRefs } from "pinia";
import { useSessionManagementStore } from "../../../state/apps/session-management/store";
import type {
  SessionManagementConsoleActions,
  SessionManagementConsoleInitialization,
} from "../../../types/session-management/Console";
import SessionEndPanel from "./end/SessionEndPanel.vue";
import SessionLogPanel from "./log/SessionLogPanel.vue";
const props = defineProps<{
  actions: SessionManagementConsoleActions;
  initialization: SessionManagementConsoleInitialization;
}>();
const store = useSessionManagementStore();
store.initialize(props.initialization, props.actions);
const { activeTab, errorMessage, isWorking, isSettingsOpen, pending, statusMessage } =
  storeToRefs(store);
function moveTab(event: KeyboardEvent): void {
  if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
  event.preventDefault();
  activeTab.value =
    event.key === "Home"
      ? "end"
      : event.key === "End"
        ? "log"
        : activeTab.value === "end"
          ? "log"
          : "end";
  const list = event.currentTarget as HTMLElement;
  list.querySelector<HTMLButtonElement>(`#session-tab-${activeTab.value}`)?.focus();
}
</script>

<template>
  <main
    class="tw:@container tw:flex tw:h-full tw:min-h-0 tw:flex-col tw:overflow-hidden tw:bg-base-200! tw:text-base-content!"
  >
    <header
      class="tw:flex tw:shrink-0 tw:items-center tw:gap-2 tw:border-b tw:border-base-content/20 tw:px-4 tw:pt-2"
    >
      <div
        class="dui-tabs dui-tabs-border tw:flex-1"
        role="tablist"
        aria-label="Session management"
        @keydown="moveTab"
      >
        <button
          id="session-tab-end"
          class="dui-tab tw:flex-1 tw:font-serif tw:text-lg"
          :class="{ 'dui-tab-active': activeTab === 'end' }"
          type="button"
          role="tab"
          :aria-selected="activeTab === 'end'"
          aria-controls="session-end"
          :tabindex="activeTab === 'end' ? 0 : -1"
          @click="activeTab = 'end'"
        >
          End of Session
        </button>
        <button
          id="session-tab-log"
          class="dui-tab tw:flex-1 tw:font-serif tw:text-lg"
          :class="{ 'dui-tab-active': activeTab === 'log' }"
          type="button"
          role="tab"
          :aria-selected="activeTab === 'log'"
          aria-controls="session-log"
          :tabindex="activeTab === 'log' ? 0 : -1"
          @click="activeTab = 'log'"
        >
          Log
        </button>
      </div>
      <button
        class="dui-btn dui-btn-ghost dui-btn-square dui-btn-sm tw:mb-2"
        type="button"
        aria-label="Session Management Settings"
        title="Session Management Settings"
        :disabled="isWorking || pending || isSettingsOpen"
        @click="store.openSettings"
      >
        <i class="fa-solid fa-gear" aria-hidden="true" />
      </button>
    </header>
    <div
      v-if="errorMessage"
      class="dui-alert dui-alert-error tw:mx-4 tw:mt-3 tw:shrink-0 tw:text-sm"
      role="alert"
    >
      {{ errorMessage }}
    </div>
    <div
      v-if="statusMessage"
      class="dui-alert dui-alert-success tw:mx-4 tw:mt-3 tw:shrink-0 tw:text-sm"
      role="status"
    >
      {{ statusMessage }}
    </div>
    <SessionEndPanel v-show="activeTab === 'end'" />
    <SessionLogPanel v-show="activeTab === 'log'" />
  </main>
</template>
