import type { Component } from "vue";
import type { CombatConsoleActions } from "../../../types/combat/Combat";
import CombatConsoleApp from "../../../view/apps/combat-console/CombatConsoleApp.vue";
import { adjustAdvantage } from "../../combat/advantage";
import { checkConditions } from "../../combat/conditions";
import { getCombatConsoleInitialization } from "../../combat/initialization";
import { saveAdvantageSettings } from "../../combat/settings/load";
import { MODULE_TITLE } from "../../constants";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../access";

export class CombatConsoleApplication extends FoundryVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.combatConsole;
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: "wfrp4e-drowsys-toolkit-combat-console",
    position: { height: 720, width: 620 },
    window: {
      icon: "fa-solid fa-swords",
      resizable: true,
      title: `${MODULE_TITLE} — Combat Console`,
    },
  };

  protected override getVueComponent(): Component {
    return CombatConsoleApp;
  }
  protected override getVueProps(): Record<string, unknown> {
    const actions: CombatConsoleActions = {
      adjustAdvantage,
      checkConditions,
      saveSettings: saveAdvantageSettings,
    };
    return { actions, initialization: getCombatConsoleInitialization() };
  }
}
