import { FearConsoleConfiguratorApplication } from "../../apps/fear-console-configurator/FearConsoleConfiguratorApplication";
import { LOCALIZATION_NAMESPACE, MODULE_ID } from "../../constants";
import { registerBooleanLauncherSetting } from "../../settings/register";
import { FEAR_TERROR_LAUNCHER_SETTINGS } from "./launchers";

export function registerFearTerrorSettings(): void {
  registerBooleanLauncherSetting(
    FEAR_TERROR_LAUNCHER_SETTINGS.tokenControls,
    "TokenControlsLauncher",
  );
  registerBooleanLauncherSetting(FEAR_TERROR_LAUNCHER_SETTINGS.actorSheet, "ActorSheetLauncher");

  game.settings.registerMenu(MODULE_ID, "fearConsole", {
    hint: `${LOCALIZATION_NAMESPACE}.Menu.FearConsoleConfigurator.Hint`,
    icon: "fa-solid fa-gears",
    label: `${LOCALIZATION_NAMESPACE}.Menu.FearConsoleConfigurator.Label`,
    name: `${LOCALIZATION_NAMESPACE}.Menu.FearConsoleConfigurator.Name`,
    restricted: FearConsoleConfiguratorApplication.ACCESS_POLICY.gmOnly,
    type: FearConsoleConfiguratorApplication,
  });
}
