import { GM_TOOLKIT_9_2_LAUNCHERS, type GmToolkitLauncherDefinition } from "./launcher-catalog";
import type {
  GmToolkitLauncherCandidate,
  GmToolkitLauncherMigrationPreview,
  GmToolkitLauncherMatch,
  GmToolkitMacroSourceDocument,
} from "../../types/gm-toolkit/LauncherMigration";

const GM_TOOLKIT_MACRO_PACK = "wfrp4e-gm-toolkit.gm-toolkit-macros";
const DROWSY_MACRO_PACK = "wfrp4e-enhanced-fear-terror.macros";
const DROWSY_LAUNCHER_SIGNATURES: Readonly<
  Record<string, { fingerprint: string; length: number }>
> = {
  DrowsyGridScale1: { fingerprint: "9476a7a4", length: 756 },
  aW4rD8xP2cN7sL5q: { fingerprint: "795a9a75", length: 680 },
};

export function buildGmToolkitLauncherMigrationPreview(
  macros: readonly GmToolkitMacroSourceDocument[],
  hotbarSlots: ReadonlyMap<string, readonly number[]>,
  user: { id?: string; name?: string } = {},
): GmToolkitLauncherMigrationPreview {
  const candidates = macros.flatMap((macro) => discoverLauncher(macro, hotbarSlots));
  const remappableSlots = candidates
    .filter(isGmToolkitLauncherRemappable)
    .flatMap(({ hotbarSlots: slots }) => slots)
    .filter((slot, index, slots) => slots.indexOf(slot) === index)
    .sort((left, right) => left - right);

  return {
    candidates,
    counts: countMatches(candidates),
    remappableSlots,
    ...(user.id ? { userId: user.id } : {}),
    ...(user.name ? { userName: user.name } : {}),
    version: 1,
    warnings: user.id
      ? []
      : ["The current user was unavailable, so hotbar assignments could not be reviewed."],
  };
}

export function isGmToolkitLauncherRemappable(candidate: GmToolkitLauncherCandidate): boolean {
  return (
    candidate.match === "standard" &&
    candidate.replacement.disposition === "ready" &&
    candidate.hotbarSlots.length > 0
  );
}

export function fingerprintGmToolkitMacroCommand(command: string): string {
  let hash = 0x811c9dc5;

  for (let index = 0; index < command.length; index += 1) {
    hash = Math.imul(hash ^ command.charCodeAt(index), 0x01000193) >>> 0;
  }

  return hash.toString(16).padStart(8, "0");
}

export function isDrowsyLauncherSource(
  compendiumSource: string | undefined,
  macroId: string,
): boolean {
  return Boolean(
    compendiumSource &&
    compendiumSource.includes(DROWSY_MACRO_PACK) &&
    compendiumSource.endsWith(macroId),
  );
}

export function isStandardDrowsyLauncher(
  macro: GmToolkitMacroSourceDocument | undefined,
  macroId: string,
): boolean {
  const signature = DROWSY_LAUNCHER_SIGNATURES[macroId];

  return Boolean(
    macro &&
    signature &&
    isDrowsyLauncherSource(macro.compendiumSource, macroId) &&
    macro.command.length === signature.length &&
    fingerprintGmToolkitMacroCommand(macro.command) === signature.fingerprint,
  );
}

function discoverLauncher(
  macro: GmToolkitMacroSourceDocument,
  hotbarSlots: ReadonlyMap<string, readonly number[]>,
): GmToolkitLauncherCandidate[] {
  const sourceDefinition = GM_TOOLKIT_9_2_LAUNCHERS.find(
    ({ id }) =>
      macro.compendiumSource?.includes(GM_TOOLKIT_MACRO_PACK) === true &&
      macro.compendiumSource.endsWith(id),
  );
  const idDefinition = GM_TOOLKIT_9_2_LAUNCHERS.find(({ id }) => id === macro.id);
  const nameDefinition = GM_TOOLKIT_9_2_LAUNCHERS.find(({ name }) => name === macro.name);
  const definition = sourceDefinition ?? idDefinition ?? nameDefinition;

  if (!definition) {
    return [];
  }

  const confidence = sourceDefinition ? "source" : idDefinition ? "document-id" : "name";
  const exactCommand = commandMatches(definition, macro.command);
  const match: GmToolkitLauncherMatch = exactCommand
    ? "standard"
    : confidence === "name"
      ? "ambiguous"
      : "customized";

  return [
    {
      confidence,
      hotbarSlots: [...(hotbarSlots.get(macro.id) ?? [])].sort((left, right) => left - right),
      macroId: macro.id,
      macroName: macro.name,
      match,
      replacement: {
        compendiumId: DROWSY_MACRO_PACK,
        ...definition.replacement,
      },
      sourceMacroId: definition.id,
      sourceMacroName: definition.name,
    },
  ];
}

function commandMatches(definition: GmToolkitLauncherDefinition, command: string): boolean {
  return (
    command.length === definition.commandLength &&
    fingerprintGmToolkitMacroCommand(command) === definition.commandFingerprint
  );
}

function countMatches(
  candidates: readonly GmToolkitLauncherCandidate[],
): Record<GmToolkitLauncherMatch, number> {
  return {
    ambiguous: candidates.filter(({ match }) => match === "ambiguous").length,
    customized: candidates.filter(({ match }) => match === "customized").length,
    standard: candidates.filter(({ match }) => match === "standard").length,
  };
}
