import { isRecord, readString } from "../../functions/records/parse";
import {
  buildGmToolkitLauncherMigrationPreview,
  isStandardDrowsyLauncher,
} from "../../functions/gm-toolkit/launchers";
import type {
  GmToolkitLauncherMigrationPreview,
  GmToolkitMacroSourceDocument,
} from "../../types/gm-toolkit/LauncherMigration";
import type { FoundryMacroDocument } from "../../types/foundry";
import { MODULE_ID } from "../constants";

const DROWSY_MACRO_PACK = `${MODULE_ID}.macros`;

export function getGmToolkitLauncherMigrationPreview(): GmToolkitLauncherMigrationPreview {
  const macros = Array.from(game.macros).flatMap(extractMacroSource);
  const currentUser = game.user;
  const hotbarSlots = new Map<string, number[]>();

  if (currentUser) {
    for (let page = 1; page <= 5; page += 1) {
      for (const { macro, slot } of currentUser.getHotbarMacros(page)) {
        if (!macro?.id) continue;
        hotbarSlots.set(macro.id, [...(hotbarSlots.get(macro.id) ?? []), slot]);
      }
    }
  }

  return buildGmToolkitLauncherMigrationPreview(macros, hotbarSlots, {
    id: currentUser?.id,
    name: currentUser?.name,
  });
}

export async function resolveDrowsyLauncher(macroId: string): Promise<{
  imported: boolean;
  macro: FoundryMacroDocument;
}> {
  const existing = Array.from(game.macros).find((macro) => {
    const source = extractMacroSource(macro)[0];
    return isStandardDrowsyLauncher(source, macroId);
  });

  if (existing) {
    return { imported: false, macro: existing };
  }

  const pack = game.packs.get(DROWSY_MACRO_PACK);

  if (!pack) {
    throw new Error("The Drowsy launcher compendium is unavailable.");
  }

  const macro = await game.macros.importFromCompendium(pack, macroId);
  return { imported: true, macro };
}

function extractMacroSource(macro: FoundryMacroDocument): GmToolkitMacroSourceDocument[] {
  const value = macro.toObject();

  if (!isRecord(value)) {
    return [];
  }

  const id = readString(value["_id"] ?? macro.id);
  const name = readString(value["name"] ?? macro.name);
  const command = readString(value["command"]);
  const type = readString(value["type"]);

  if (!id || !name || !type) {
    return [];
  }

  const stats = value["_stats"];
  const compendiumSource = isRecord(stats) ? readString(stats["compendiumSource"]) : "";

  return [
    {
      command,
      ...(compendiumSource ? { compendiumSource } : {}),
      id,
      name,
      type,
    },
  ];
}
