import type { VisionSettings } from "../../../types/token-tools/TokenTools";
import { MODULE_ID } from "../../constants";
import { VISION_SETTINGS } from "./keys";
export function getVisionSettings(): VisionSettings {
  return {
    darkRange: number("darkRange"),
    normalRange: number("normalRange"),
    overrideDarkVision: bool("overrideDarkVision"),
    overrideNightVision: bool("overrideNightVision"),
  };
}
export async function saveVisionSettings(settings: VisionSettings): Promise<void> {
  const values: VisionSettings = {
    ...settings,
    darkRange: Math.max(0, Math.round(settings.darkRange)),
    normalRange: Math.max(0, Math.round(settings.normalRange)),
  };
  for (const [name, key] of Object.entries(VISION_SETTINGS))
    await game.settings.set(MODULE_ID, key, values[name as keyof VisionSettings]);
}
function number(key: "darkRange" | "normalRange"): number {
  const value = Number(game.settings.get(MODULE_ID, VISION_SETTINGS[key]));
  if (!Number.isFinite(value))
    throw new Error(`The saved Token Tools setting “${VISION_SETTINGS[key]}” is not a number.`);
  return value;
}
function bool(key: "overrideDarkVision" | "overrideNightVision"): boolean {
  return game.settings.get(MODULE_ID, VISION_SETTINGS[key]) === true;
}
