export function canCurrentUserAccessApplication(policy: ToolkitApplicationAccessPolicy): boolean {
  const currentUser = game.user;

  return currentUser !== null && (!policy.gmOnly || currentUser.isGM);
}

export function assertCurrentUserCanAccessApplication(
  policy: ToolkitApplicationAccessPolicy,
): void {
  if (!canCurrentUserAccessApplication(policy)) {
    throw new Error(`Only a GM can use the ${policy.name}.`);
  }
}
