import type { XpActorChoice } from "../../types/xp-curve/XpCurve";
import type { FixedXpAwardPlan } from "../../types/xp-award/XpAward";

export function calculateFixedXpAwardPlan(
  actors: XpActorChoice[],
  amount: number,
): FixedXpAwardPlan {
  const normalizedAmount = Number.isFinite(amount) ? Math.round(amount) : 0;
  const awards = actors
    .filter((actor) => actor.selected)
    .map((actor) => {
      const requestedAmount =
        actor.category === "companion" ? Math.floor(normalizedAmount / 2) : normalizedAmount;
      const appliedAmount = Math.max(requestedAmount, -actor.totalXp);

      return {
        actorId: actor.id,
        actorName: actor.name,
        afterXp: actor.totalXp + appliedAmount,
        amount: appliedAmount,
        beforeXp: actor.totalXp,
        category: actor.category,
      };
    });

  return {
    awards,
    totalChange: awards.reduce((sum, award) => sum + award.amount, 0),
  };
}
