import { escapeHtml } from "../../functions/xp-curve/reason";
import { addXpAwardBatch } from "../../functions/xp-award/audit";
import { calculateFixedXpAwardPlan } from "../../functions/xp-award/calculate";
import { formatXpAwardDateTime, resolveFixedXpAwardReason } from "../../functions/xp-award/reason";
import type {
  FixedXpAward,
  XpAwardBatchRecord,
  XpAwardRequest,
  XpAwardResult,
} from "../../types/xp-award/XpAward";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";
import { getCurrentSessionReference } from "../session-management/settings/load";
import { getXpActorRuntimes } from "../xp-curve/actors";
import { getXpAwardAuditLog, saveXpAwardAuditLog } from "./settings/load";

export async function applyFixedXpAwards(
  request: XpAwardRequest,
  session?: { reference: string; reason: string },
): Promise<XpAwardResult> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.xpAwardConsole);

  const actorIds = Array.from(new Set(request.actorIds));

  if (actorIds.length === 0) {
    throw new Error("Select at least one character actor.");
  }

  if (!Number.isSafeInteger(request.defaultAmount) || request.defaultAmount === 0) {
    throw new Error("Enter a non-zero whole-number XP change.");
  }

  const actorRuntimes = getXpActorRuntimes(actorIds);
  const plan = calculateFixedXpAwardPlan(
    actorRuntimes.map((runtime) => runtime.choice),
    request.defaultAmount,
  );
  const awardedAt = new Date().toISOString();
  const sessionReference = session?.reference ?? getCurrentSessionReference();
  const reason =
    session?.reason ??
    resolveFixedXpAwardReason(
      request.defaultReason,
      {
        date: awardedAt.slice(0, 10),
        datetime: formatXpAwardDateTime(awardedAt),
        session: sessionReference,
      },
      request.includeTimestampInReason,
    );

  const appliedAwards: FixedXpAward[] = [];

  for (const [index, runtime] of actorRuntimes.entries()) {
    const award = plan.awards[index]!;

    try {
      await runtime.awardExperience(award.amount, reason);
      appliedAwards.push(award);
    } catch (error) {
      const appliedSummary =
        appliedAwards.length > 0
          ? ` XP was already changed for ${appliedAwards.map((entry) => entry.actorName).join(", ")}.`
          : "";
      const detail = error instanceof Error ? ` ${error.message}` : "";

      throw new Error(`Could not change XP for ${award.actorName}.${appliedSummary}${detail}`, {
        cause: error,
      });
    }
  }

  const result: XpAwardResult = {
    ...plan,
    awardedAt,
    reason,
    sessionReference,
  };
  const batch: XpAwardBatchRecord = {
    ...result,
    id: crypto.randomUUID(),
  };

  await saveXpAwardAuditLog(addXpAwardBatch(getXpAwardAuditLog(), batch));
  await postXpAwardSummary(result);
  ui.notifications.info(
    `Applied ${formatSigned(result.totalChange)} XP across ${result.awards.length} actors.`,
  );

  return result;
}

async function postXpAwardSummary(result: XpAwardResult): Promise<void> {
  const rows = result.awards
    .map(
      (award) =>
        `<li><strong>${escapeHtml(award.actorName)}</strong>: ${formatSigned(award.amount)} XP ` +
        `(${award.beforeXp} → ${award.afterXp})</li>`,
    )
    .join("");
  const content =
    `<h2>XP Award</h2><p>${escapeHtml(result.reason || "No reason")}</p>` +
    `<p><small>${escapeHtml(formatXpAwardDateTime(result.awardedAt))}</small></p>` +
    `<ul>${rows}</ul><p><strong>${formatSigned(result.totalChange)} XP in total.</strong></p>`;
  const messageData = game.wfrp4e.utility.chatDataSetup(content, "gmroll", false, {
    alias: "Drowsy’s WFRP4e Toolkit",
  });

  await ChatMessage.create(messageData);
}

function formatSigned(value: number): string {
  return value > 0 ? `+${value}` : String(value);
}
