import { LOCALIZATION_NAMESPACE } from "../../constants";
import { registerHiddenWorldSetting } from "../../settings/register";
import { DARK_WHISPERS_SETTINGS } from "./keys";

export function registerDarkWhispersSettings(): void {
  registerHiddenWorldSetting(
    DARK_WHISPERS_SETTINGS.promptLibrary,
    JSON.stringify({ prompts: [], version: 1 }),
    String,
    `${LOCALIZATION_NAMESPACE}.Settings.DarkWhispers.PromptLibrary`,
  );
  registerHiddenWorldSetting(
    DARK_WHISPERS_SETTINGS.defaultGroup,
    "party",
    String,
    `${LOCALIZATION_NAMESPACE}.Settings.DarkWhispers.DefaultGroup`,
  );
  registerHiddenWorldSetting(
    DARK_WHISPERS_SETTINGS.messageStyle,
    "taunt",
    String,
    `${LOCALIZATION_NAMESPACE}.Settings.DarkWhispers.MessageStyle`,
  );
}
