<script setup lang="ts">
import { computed } from "vue";
import { storeToRefs } from "pinia";

import { useXpCurveConsoleStore } from "../../../state/apps/xp-curve-console/store";
import type {
  XpCurveConsoleActions,
  XpCurveConsoleInitialization,
} from "../../../types/xp-curve/Console";
import ConsoleActionFooter from "../shared/ConsoleActionFooter.vue";
import XpAwardWorkspace from "./award/XpAwardWorkspace.vue";
import XpConsoleHeader from "./navigation/XpConsoleHeader.vue";

const props = defineProps<{
  actions: XpCurveConsoleActions;
  initialization: XpCurveConsoleInitialization;
}>();

const store = useXpCurveConsoleStore();
store.initialize(props.initialization, props.actions);

const {
  actors,
  canApply,
  defaultReason,
  errorMessage,
  isWorking,
  plan,
  positiveAwardCount,
  resolvedReason,
  selectedActors,
  selectionSource,
} = storeToRefs(store);
const selectionLabel = computed(() => {
  if (selectionSource.value === "targets") {
    return "Recipients: targeted tokens";
  }

  const labels = {
    company: "company default",
    party: "party default",
    world: "world default",
  };

  return `Recipients: ${labels[props.initialization.defaultSelection]}`;
});
</script>

<template>
  <main
    class="tw:flex tw:h-full tw:max-h-full tw:min-h-0 tw:min-w-0 tw:flex-col tw:overflow-hidden tw:bg-base-200! tw:text-base-content!"
  >
    <XpConsoleHeader
      :highest-xp="plan.highestXp"
      :positive-award-count="positiveAwardCount"
      :selected-count="selectedActors.length"
      :selection-label="selectionLabel"
      :selection-source="selectionSource"
      :total-award="plan.totalAward"
      @configure="props.actions.openConfigurator"
    />

    <div v-if="errorMessage" class="dui-alert dui-alert-error tw:m-4 tw:mb-0" role="alert">
      <i class="fa-solid fa-triangle-exclamation" aria-hidden="true" />
      <span class="tw:min-w-0 tw:break-words">{{ errorMessage }}</span>
    </div>

    <div class="tw:min-h-0 tw:min-w-0 tw:flex-1 tw:overflow-auto tw:p-4">
      <XpAwardWorkspace
        v-model:default-reason="defaultReason"
        :actors="actors"
        :disabled="isWorking"
        :plan="plan"
        :resolved-reason="resolvedReason"
        :selection-source="selectionSource"
        @reset="store.resetSelection"
        @select-all="store.setAllActorsSelected"
        @update:selected="store.setActorSelected"
      />
    </div>

    <ConsoleActionFooter
      :disabled="!canApply"
      icon="fa-solid fa-award"
      :label="`Award ${plan.totalAward} XP`"
      :working="isWorking"
      @action="store.applyAwards"
    />
  </main>
</template>
