import type { Component } from "vue";

import type { XpCurveConsoleActions } from "../../../types/xp-curve/Console";
import XpCurveConsoleApp from "../../../view/apps/xp-curve-console/XpCurveConsoleApp.vue";
import { openXpCurveConfiguratorFromUi } from "../xp-curve-configurator/open";
import { MODULE_ID, MODULE_TITLE } from "../../constants";
import { getXpCurveConsoleInitialization } from "../../xp-curve/initialization";
import { applyXpCurveAwards } from "../../xp-curve/service";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../access";

export class XpCurveConsoleApplication extends FoundryVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.xpCurveConsole;

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    classes: [MODULE_ID, `${MODULE_ID}-xp-curve-console`],
    id: `${MODULE_ID}-xp-curve-console`,
    position: {
      height: 720,
      width: 820,
    },
    window: {
      icon: "fa-solid fa-chart-line",
      resizable: true,
      title: `${MODULE_TITLE} — XP Curve Console`,
    },
  };

  protected override getVueComponent(): Component {
    return XpCurveConsoleApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    const actions: XpCurveConsoleActions = {
      applyAwards: applyXpCurveAwards,
      onActionComplete: () => {
        void this.close().catch((error: unknown) => {
          console.error(`${MODULE_ID} | Failed to close the XP Curve Console.`, error);
          ui.notifications.error(
            "XP awards completed, but Drowsy’s WFRP4e Toolkit could not close the console.",
          );
        });
      },
      openConfigurator: () => {
        openXpCurveConfiguratorFromUi({
          onSaved: () => this.render(true),
        });
      },
    };

    return {
      actions,
      initialization: getXpCurveConsoleInitialization(),
    };
  }
}
