import type { VisionMode, VisionSettings } from "../../types/token-tools/TokenTools";

export interface VisionContext {
  hasDarkVision: boolean;
  lightRange: number;
  nightVisionAdvances: number;
  sceneDarkness: number;
  sceneHasGlobalLight: boolean;
}

export function buildTokenSight(
  mode: VisionMode,
  settings: VisionSettings,
  context: VisionContext,
): Record<string, unknown> {
  const normalRange = Math.max(0, settings.normalRange);
  const darkRange = Math.max(0, settings.darkRange);
  const base = {
    angle: 360,
    attenuation: 0.1,
    brightness: 0,
    color: null,
    contrast: 0,
    enabled: true,
    range: normalRange,
    saturation: 0,
    visionMode: "basic",
  };

  if (mode === "none") return { ...base, brightness: -1, enabled: false, range: 0 };
  if (mode === "blinded") return { ...base, brightness: 1, range: 1, saturation: 1 };
  if (mode === "normal") return base;
  if (mode === "dark") {
    const range = context.hasDarkVision || settings.overrideDarkVision ? darkRange : normalRange;
    return { ...base, brightness: range / 2, range };
  }

  const advances = Math.max(context.nightVisionAdvances, settings.overrideNightVision ? 1 : 0);
  const canUseNightVision =
    context.sceneDarkness < 1 || context.lightRange > 0 || context.sceneHasGlobalLight;
  return {
    ...base,
    range: canUseNightVision
      ? Math.max(normalRange, advances * 20 + Math.max(0, context.lightRange))
      : 0,
    saturation: advances > 0 && canUseNightVision ? -1 : 0,
  };
}
