<script setup lang="ts">
import DiamondHandle from "./graph/DiamondHandle.vue";
import GraphCanvas from "./graph/GraphCanvas.vue";
import RecipientLegend from "./graph/RecipientLegend.vue";
import RoundHandle from "./graph/RoundHandle.vue";
import { type DecayGraphEmit, type DecayGraphProps, useDecayGraph } from "./useDecayGraph";

const props = defineProps<DecayGraphProps>();
const emit = defineEmits<DecayGraphEmit>();
const {
  beginDrag,
  endDrag,
  maximumRecipientXp,
  pivotPoint,
  points,
  recipientLegend,
  recipientPoints,
  strengthPoint,
  toGraphX,
  updateDrag,
  updatePivotWithKeyboard,
  updateStrengthWithKeyboard,
} = useDecayGraph(props, emit);
</script>

<template>
  <figure class="tw:m-0 tw:block tw:min-w-0" aria-labelledby="xp-decay-graph-heading">
    <div class="tw:mb-2">
      <h4 id="xp-decay-graph-heading" class="tw:m-0 tw:text-sm tw:font-semibold">
        Catch-up strength by recipient total XP
      </h4>
      <p class="tw:m-0 tw:text-xs tw:text-base-content/65!">
        Drag the diamond to choose where decay begins. Drag the round point to make decay gentler or
        stronger.
      </p>
    </div>

    <GraphCanvas
      description="The horizontal axis is each recipient's own total XP. The vertical axis is the multiplier applied to that recipient's initial catch-up value. Numbered markers identify selected recipients."
      description-id="xp-decay-graph-description"
      :markers="recipientPoints"
      :maximum-x-label="`${Math.round(maximumRecipientXp)} XP`"
      maximum-y-label="100%"
      minimum-y-label="0%"
      :points="points"
      title="Editable recipient XP decay curve"
      title-id="xp-decay-graph-title"
      :vertical-guide-x="toGraphX(scalePivot)"
      x-axis-label="Recipient total XP"
      y-axis-label="Decay multiplier"
      @pointercancel="endDrag"
      @pointermove="updateDrag"
      @pointerup="endDrag"
    >
      <template #handles>
        <RoundHandle
          aria-label="Recipient decay strength"
          :aria-value-max="2"
          :aria-value-min="0"
          :aria-value-now="scaleExponent"
          :aria-value-text="`Decay exponent ${scaleExponent}`"
          :x="strengthPoint.x"
          :y="strengthPoint.y"
          @keydown="updateStrengthWithKeyboard"
          @pointerdown="beginDrag('strength', $event)"
        />
        <DiamondHandle
          aria-label="Recipient total XP where decay begins"
          :aria-value-max="Math.round(maximumRecipientXp)"
          :aria-value-min="1"
          :aria-value-now="scalePivot"
          :aria-value-text="`${scalePivot} total XP`"
          :x="pivotPoint.x"
          :y="pivotPoint.y"
          @keydown="updatePivotWithKeyboard"
          @pointerdown="beginDrag('pivot', $event)"
        />
      </template>
    </GraphCanvas>

    <RecipientLegend :items="recipientLegend" />
  </figure>
</template>
