import type { GroupTestRequest } from "../../types/group-test/GroupTest";
import {
  canAcceptGroupTestResult,
  resolveGroupTestFallback,
} from "../../functions/group-test/fallback";
import { MODULE_ID } from "../constants";
import { resolveActors } from "../actors/selection";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";
import { getGroupTestSettings } from "./settings/load";
import { compileGroupTestSkillNames } from "./skill-catalog";

interface TestResultRuntime {
  result?: { description?: string; roll?: number; SL?: number };
  roll: () => Promise<TestResultRuntime>;
  succeeded?: boolean;
  target?: number;
}
interface TestActorRuntime extends FoundryActorDocument {
  setupCharacteristic: (
    key: string,
    options?: Record<string, unknown>,
  ) => Promise<TestResultRuntime>;
  setupSkill: (skill: unknown, options?: Record<string, unknown>) => Promise<TestResultRuntime>;
  uuid: string;
}
interface TestSummary {
  actor: string;
  actorUuid: string;
  roll?: number;
  sl?: number;
  succeeded: boolean;
  target?: number;
}
interface PendingBatch {
  expected: number;
  expectedUuids: Set<string>;
  received: Set<string>;
  skill: string;
  summaries: TestSummary[];
}
interface GroupTestSocket {
  emit: (channel: string, data: unknown) => void;
  on: (channel: string, callback: (data: unknown) => void) => void;
}
const pendingBatches = new Map<string, PendingBatch>();

export async function runGroupTest(request: GroupTestRequest): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.groupTestConsole);
  if (!request.skill.trim()) throw new Error("Choose or enter a skill.");
  if (request.uuids.length === 0) throw new Error("Select at least one actor.");
  const actors = (await resolveActors(request.uuids)) as TestActorRuntime[];
  const batchId = crypto.randomUUID();
  const delegated = actors.filter(
    (actor) => !request.bypassDialog && isAssignedToActivePlayer(actor),
  );
  if (delegated.length > 0) getGroupTestSocket();
  const local = actors.filter((actor) => !delegated.includes(actor));
  const batch: PendingBatch = {
    expected: actors.length,
    expectedUuids: new Set(actors.map(({ uuid }) => uuid)),
    received: new Set(),
    skill: request.skill,
    summaries: [],
  };
  pendingBatches.set(batchId, batch);
  trimPendingBatches();
  delegated.forEach((actor) => emitRollRequest(batchId, actor.uuid, request));
  for (const actor of local) {
    const summary = await runActorTest(actor, request);
    addBatchResult(batchId, summary);
  }
  await finishBatchIfReady(batchId);
  if (delegated.length > 0)
    ui.notifications.info(
      `Requested ${delegated.length} private player roll${delegated.length === 1 ? "" : "s"}.`,
    );
}

function isAssignedToActivePlayer(actor: TestActorRuntime): boolean {
  return Array.from(game.users).some(
    (user) =>
      user.isGM === false &&
      (user as FoundryUser & { active?: boolean }).active !== false &&
      user.character?.id === actor.id,
  );
}

function emitRollRequest(batchId: string, actorUuid: string, request: GroupTestRequest): void {
  getGroupTestSocket().emit(`module.${MODULE_ID}`, {
    actorUuid,
    batchId,
    request,
    requesterUserId: game.user?.id,
    type: "group-test-request",
  });
}

export function registerGroupTestHooks(): void {
  Hooks.once("ready", async () => {
    await compileGroupTestSkillNames();
    getGroupTestSocket().on(`module.${MODULE_ID}`, (data) => void handleSocket(data));
  });
}

async function runActorTest(
  actor: TestActorRuntime,
  request: GroupTestRequest,
): Promise<TestSummary> {
  const options = {
    fields: {
      difficulty: request.difficulty,
      modifier: request.modifier,
      rollMode: request.rollMode,
    },
    groupTest: true,
    skipDialog: request.bypassDialog,
    skipTargets: true,
    title: `Secret ${request.skill} Test — ${actor.name}`,
  };
  const ownedSkill = actor.has(request.skill, "skill");
  let test: TestResultRuntime;
  if (ownedSkill) test = await actor.setupSkill(ownedSkill, options);
  else {
    const definition = await findSkill(request.skill);
    if (!definition) throw new Error(`Skill “${request.skill}” was not found in WFRP4e content.`);
    const fallback = resolveGroupTestFallback(definition, request);
    if (!fallback) return { actor: actor.name, actorUuid: actor.uuid, succeeded: false };
    test = await actor.setupCharacteristic(fallback.characteristic, {
      ...options,
      fields: { ...options.fields, difficulty: fallback.difficulty },
    });
  }
  const result = await test.roll();
  return {
    actor: actor.name,
    actorUuid: actor.uuid,
    roll: result.result?.roll,
    sl: result.result?.SL,
    succeeded: result.succeeded === true,
    target: result.target,
  };
}

async function findSkill(name: string): Promise<unknown> {
  const utility = (
    game as unknown as { wfrp4e: { utility: { findSkill?: (name: string) => Promise<unknown> } } }
  ).wfrp4e.utility;
  return utility.findSkill ? utility.findSkill(name) : undefined;
}

async function postSummary(skill: string, summaries: TestSummary[]): Promise<void> {
  const rows = summaries
    .map(
      (result) =>
        `<li><strong>${foundry.utils.escapeHTML(result.actor)}</strong>: ${result.succeeded ? "Success" : "Failure"}${result.sl === undefined ? "" : ` (${result.sl} SL)`}${result.roll === undefined ? "" : ` — ${result.roll} vs ${result.target ?? "?"}`}</li>`,
    )
    .join("");
  const whisper = Array.from(game.users)
    .filter((user) => user.isGM)
    .map((user) => user.id);
  await ChatMessage.create({
    content: `<h3>Secret Group Test: ${foundry.utils.escapeHTML(skill)}</h3><ul>${rows}</ul>`,
    whisper,
  });
}

async function handleSocket(data: unknown): Promise<void> {
  if (!data || typeof data !== "object") return;
  const message = data as {
    actorUuid?: string;
    batchId?: string;
    request?: GroupTestRequest;
    requesterUserId?: string;
    responderUserId?: string;
    summary?: TestSummary;
    type?: string;
  };
  if (message.type === "group-test-result") {
    if (!isResponsibleGm() || !message.batchId || !message.summary) return;
    if (!isValidDelegatedResult(message.summary, message.responderUserId)) return;
    addBatchResult(message.batchId, message.summary);
    await finishBatchIfReady(message.batchId);
    return;
  }
  if (
    message.type !== "group-test-request" ||
    !message.actorUuid ||
    !message.batchId ||
    !message.request ||
    !isActiveGm(message.requesterUserId)
  )
    return;
  const character = game.user?.character as (FoundryActorDocument & { uuid?: string }) | undefined;
  if (character?.uuid === message.actorUuid) {
    const [actor] = (await resolveActors([message.actorUuid])) as TestActorRuntime[];
    if (actor) {
      const summary = await runActorTest(actor, message.request);
      emitSocket({
        batchId: message.batchId,
        responderUserId: game.user?.id,
        summary,
        type: "group-test-result",
      });
    }
  }
}

function addBatchResult(batchId: string, summary: TestSummary): void {
  const batch = pendingBatches.get(batchId);
  if (!batch || !canAcceptGroupTestResult(batch.expectedUuids, batch.received, summary.actorUuid))
    return;
  batch.received.add(summary.actorUuid);
  batch.summaries.push(summary);
}

async function finishBatchIfReady(batchId: string): Promise<void> {
  const batch = pendingBatches.get(batchId);
  if (!batch || batch.received.size < batch.expected) return;
  pendingBatches.delete(batchId);
  const threshold = getGroupTestSettings().summaryThreshold;
  if (threshold > 0 && batch.summaries.length >= threshold)
    await postSummary(batch.skill, batch.summaries);
}

function trimPendingBatches(): void {
  while (pendingBatches.size > 20) {
    const oldest = pendingBatches.keys().next().value;
    if (typeof oldest === "string") pendingBatches.delete(oldest);
    else return;
  }
}

function isValidDelegatedResult(summary: TestSummary, senderId?: string): boolean {
  if (!senderId || typeof summary.actorUuid !== "string") return false;
  const sender = Array.from(game.users).find((user) => user.id === senderId);
  const assignedUuid = (sender?.character as (FoundryActorDocument & { uuid?: string }) | undefined)
    ?.uuid;
  return sender?.isGM === false && assignedUuid === summary.actorUuid;
}

function isActiveGm(userId?: string): boolean {
  if (!userId) return false;
  const user = Array.from(game.users).find((candidate) => candidate.id === userId);
  return user?.isGM === true && (user as FoundryUser & { active?: boolean }).active !== false;
}

function emitSocket(data: unknown): void {
  getGroupTestSocket().emit(`module.${MODULE_ID}`, data);
}

function getGroupTestSocket(): GroupTestSocket {
  const socket = (game as unknown as { socket?: GroupTestSocket }).socket;
  if (!socket)
    throw new Error("Foundry socket services are unavailable for delegated group tests.");
  return socket;
}

function isResponsibleGm(): boolean {
  return (
    game.user?.isGM === true &&
    (game.user as FoundryUser & { isUniqueGM?: boolean }).isUniqueGM !== false
  );
}
