import type { Component } from "vue";

import type { ToolkitHomeSection } from "../../../types/toolkit-home/Console";
import SceneManagementConsoleApp from "../../../view/apps/scene-management-console/SceneManagementConsoleApp.vue";
import { MODULE_ID, MODULE_TITLE } from "../../constants";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../access";

export class SceneManagementConsoleApplication extends FoundryVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.sceneManagementConsole;

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    classes: [MODULE_ID, `${MODULE_ID}-scene-management`],
    id: `${MODULE_ID}-scene-management`,
    position: { height: 580, width: 680 },
    window: {
      icon: "fa-solid fa-map",
      resizable: true,
      title: `${MODULE_TITLE} — Scene Management`,
    },
  };

  constructor(private readonly sections: ToolkitHomeSection[]) {
    super();
  }

  protected override getVueComponent(): Component {
    return SceneManagementConsoleApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    return { sections: this.sections };
  }
}
