import { shallowRef } from "vue";

export interface ActiveGraphDrag<DragKind, Snapshot> {
  kind: DragKind;
  pointerId: number;
  snapshot: Snapshot;
  svg: SVGSVGElement;
}

export function useGraphDrag<DragKind, Snapshot>(
  createSnapshot: () => Snapshot,
  updateFromPointer: (drag: ActiveGraphDrag<DragKind, Snapshot>, event: PointerEvent) => void,
) {
  const activeDrag = shallowRef<ActiveGraphDrag<DragKind, Snapshot>>();

  function beginDrag(kind: DragKind, event: PointerEvent): void {
    const target = event.currentTarget as SVGElement;
    const svg = target.ownerSVGElement;

    if (!svg) {
      throw new Error("XP graph drag handles must be rendered inside an SVG element.");
    }

    const drag = {
      kind,
      pointerId: event.pointerId,
      snapshot: createSnapshot(),
      svg,
    };
    activeDrag.value = drag;
    svg.setPointerCapture(event.pointerId);
    updateFromPointer(drag, event);
  }

  function updateDrag(event: PointerEvent): void {
    const drag = activeDrag.value;

    if (drag?.pointerId === event.pointerId) {
      updateFromPointer(drag, event);
    }
  }

  function endDrag(event: PointerEvent): void {
    const drag = activeDrag.value;

    if (drag?.pointerId !== event.pointerId) {
      return;
    }

    if (drag.svg.hasPointerCapture(event.pointerId)) {
      drag.svg.releasePointerCapture(event.pointerId);
    }
    activeDrag.value = undefined;
  }

  return {
    activeDrag,
    beginDrag,
    endDrag,
    updateDrag,
  };
}
