<script setup lang="ts">
import { storeToRefs } from "pinia";

import { useGmToolkitMigrationStore } from "../../../state/apps/gm-toolkit-migration/store";
import type {
  GmToolkitMigrationConsoleActions,
  GmToolkitMigrationConsoleInitialization,
} from "../../../types/gm-toolkit/Console";
import ConsoleFrame from "../shared/ConsoleFrame.vue";
import GmToolkitContentMigrationPanel from "./GmToolkitContentMigrationPanel.vue";
import GmToolkitCutoverReportPanel from "./GmToolkitCutoverReportPanel.vue";
import GmToolkitLauncherMigrationPanel from "./GmToolkitLauncherMigrationPanel.vue";
import GmToolkitMigrationPanel from "./GmToolkitMigrationPanel.vue";

const props = defineProps<{
  actions: GmToolkitMigrationConsoleActions;
  initialization: GmToolkitMigrationConsoleInitialization;
}>();

const store = useGmToolkitMigrationStore();
store.initialize(props.initialization, props.actions);

const {
  cutoverReport,
  darkWhispersConflictPolicy,
  darkWhispersSelections,
  darkWhispersTableId,
  errorMessage,
  isWorking,
  launcherSelections,
  preview,
  settingSelections,
  state,
  statusMessage,
} = storeToRefs(store);
</script>

<template>
  <ConsoleFrame
    description="Copy the settings and content you want to keep, update safe hotbar links, and review the result before disabling GM Toolkit."
    :error-message="errorMessage"
    icon="fa-solid fa-box-archive"
    :status-message="statusMessage"
    title="Import from GM Toolkit"
  >
    <div class="tw:grid tw:min-w-0 tw:gap-3">
      <GmToolkitMigrationPanel
        v-if="preview?.source"
        :is-working="isWorking"
        :last-imported-at="state.migration?.importedAt"
        :preview="preview"
        :selections="settingSelections"
        @import="store.importSettings"
        @selection-change="store.setSettingSelection"
      />

      <GmToolkitContentMigrationPanel
        v-if="preview"
        v-model:conflict-policy="darkWhispersConflictPolicy"
        :is-working="isWorking"
        :preview="preview.darkWhispers"
        :selected-table-id="darkWhispersTableId"
        :selections="darkWhispersSelections"
        @import="store.importDarkWhispers"
        @selection-change="store.setDarkWhispersSelection"
        @table-change="store.setDarkWhispersTable"
      />

      <GmToolkitLauncherMigrationPanel
        v-if="preview?.launchers.candidates.length"
        :is-working="isWorking"
        :preview="preview.launchers"
        :selections="launcherSelections"
        @remap="store.remapLaunchers"
        @selection-change="store.setLauncherSelection"
      />

      <GmToolkitCutoverReportPanel
        v-if="cutoverReport || state.cutoverReview"
        :is-working="isWorking"
        :report="cutoverReport"
        :review="state.cutoverReview"
        @review="store.reviewCutover"
      />

      <div v-if="!preview && !cutoverReport" class="dui-alert" role="status">
        <i class="fa-solid fa-circle-check" aria-hidden="true" />
        <span>No GM Toolkit settings, content, or launchers were found in this world.</span>
      </div>
    </div>
  </ConsoleFrame>
</template>
