import { computed } from "vue";

import {
  buildDecayGraphProjection,
  calculateCurveExponentKeyboardUpdate,
  calculateDecayGraphBounds,
  calculateDecayPivotKeyboardUpdate,
  calculateDecayPointerUpdate,
  projectGraphX,
} from "../../../../functions/xp-curve/graph";
import type { DecayGraphBounds } from "../../../../types/xp-curve/Graph";
import type { XpAward, XpDecaySample } from "../../../../types/xp-curve/XpCurve";
import { type ActiveGraphDrag, useGraphDrag } from "./graph/drag";
import { getGraphPointerPosition } from "./graphMath";

type DragKind = "pivot" | "strength";

export interface DecayGraphProps {
  awards: XpAward[];
  samples: XpDecaySample[];
  scaleExponent: number;
  scalePivot: number;
}

export type DecayGraphEmit = {
  (event: "update:scaleExponent", value: number): void;
  (event: "update:scalePivot", value: number): void;
};

export function useDecayGraph(props: DecayGraphProps, emit: DecayGraphEmit) {
  const calculatedBounds = computed(() =>
    calculateDecayGraphBounds(props.scalePivot, props.samples, props.awards),
  );
  const { activeDrag, beginDrag, endDrag, updateDrag } = useGraphDrag<DragKind, DecayGraphBounds>(
    () => ({ ...calculatedBounds.value }),
    updateFromPointer,
  );
  const bounds = computed(() => activeDrag.value?.snapshot ?? calculatedBounds.value);
  const projection = computed(() =>
    buildDecayGraphProjection({
      awards: props.awards,
      bounds: bounds.value,
      samples: props.samples,
      scaleExponent: props.scaleExponent,
      scalePivot: props.scalePivot,
    }),
  );
  const maximumRecipientXp = computed(() => bounds.value.maximumRecipientXp);
  const points = computed(() => projection.value.points);
  const pivotPoint = computed(() => projection.value.pivotPoint);
  const recipientLegend = computed(() => projection.value.recipientLegend);
  const recipientPoints = computed(() => projection.value.recipientPoints);
  const strengthPoint = computed(() => projection.value.strengthPoint);

  function toGraphX(recipientXp: number): number {
    return projectGraphX(recipientXp, bounds.value.maximumRecipientXp);
  }

  function updateFromPointer(
    drag: ActiveGraphDrag<DragKind, DecayGraphBounds>,
    event: PointerEvent,
  ): void {
    const update = calculateDecayPointerUpdate(
      drag.kind,
      getGraphPointerPosition(drag.svg, event),
      drag.snapshot,
    );

    if (update.kind === "pivot") {
      emit("update:scalePivot", update.scalePivot);
      return;
    }

    emit("update:scaleExponent", update.scaleExponent);
  }

  function updatePivotWithKeyboard(event: KeyboardEvent): void {
    const scalePivot = calculateDecayPivotKeyboardUpdate(event.key, props.scalePivot);

    if (scalePivot === undefined) {
      return;
    }

    event.preventDefault();
    emit("update:scalePivot", scalePivot);
  }

  function updateStrengthWithKeyboard(event: KeyboardEvent): void {
    const scaleExponent = calculateCurveExponentKeyboardUpdate(
      event.key,
      props.scaleExponent,
      0,
      2,
    );

    if (scaleExponent === undefined) {
      return;
    }

    event.preventDefault();
    emit("update:scaleExponent", scaleExponent);
  }

  return {
    beginDrag,
    endDrag,
    maximumRecipientXp,
    pivotPoint,
    points,
    recipientLegend,
    recipientPoints,
    strengthPoint,
    toGraphX,
    updateDrag,
    updatePivotWithKeyboard,
    updateStrengthWithKeyboard,
  };
}
