import type {
  GmToolkitDarkWhispersCandidatePreview,
  GmToolkitDarkWhispersMigrationPreview,
} from "../../types/gm-toolkit/Migration";

export function getSelectedGmToolkitDarkWhispersCandidate(
  preview: GmToolkitDarkWhispersMigrationPreview,
  tableId: string,
): GmToolkitDarkWhispersCandidatePreview | undefined {
  return preview.candidates.find((candidate) => candidate.tableId === tableId);
}

export function createGmToolkitDarkWhispersSelections(
  preview: GmToolkitDarkWhispersMigrationPreview,
  tableId: string,
): Record<string, boolean> {
  const candidate = getSelectedGmToolkitDarkWhispersCandidate(preview, tableId);

  return Object.fromEntries(
    (candidate?.prompts ?? []).map((prompt) => [prompt.resultId, prompt.comparison === "new"]),
  );
}

export function getSelectedGmToolkitDarkWhispersResultIds(
  selections: Readonly<Record<string, boolean>>,
): string[] {
  return Object.entries(selections).flatMap(([resultId, selected]) => (selected ? [resultId] : []));
}
