import { parseXpAwardAuditLog } from "../../../functions/xp-award/audit";
import type { XpDefaultSelection } from "../../../types/xp-curve/XpCurve";
import type { XpAwardAuditLog, XpAwardSettings } from "../../../types/xp-award/XpAward";
import { MODULE_ID } from "../../constants";
import { XP_AWARD_SETTINGS } from "./keys";

export function getXpAwardSettings(): XpAwardSettings {
  return {
    defaultAmount: Math.round(
      Number(game.settings.get(MODULE_ID, XP_AWARD_SETTINGS.defaultAmount)),
    ),
    defaultReason: readString(XP_AWARD_SETTINGS.defaultReason),
    defaultSelection: readDefaultSelection(),
    includeTimestampInReason:
      game.settings.get(MODULE_ID, XP_AWARD_SETTINGS.includeTimestampInReason) === true,
  };
}

export async function saveXpAwardSettings(settings: XpAwardSettings): Promise<void> {
  const values = [
    [XP_AWARD_SETTINGS.defaultAmount, Math.round(settings.defaultAmount)],
    [XP_AWARD_SETTINGS.defaultReason, settings.defaultReason],
    [XP_AWARD_SETTINGS.defaultSelection, settings.defaultSelection],
    [XP_AWARD_SETTINGS.includeTimestampInReason, settings.includeTimestampInReason],
  ] as const;

  for (const [key, value] of values) {
    await game.settings.set(MODULE_ID, key, value);
  }
}

export function getXpAwardAuditLog(): XpAwardAuditLog {
  return parseXpAwardAuditLog(game.settings.get(MODULE_ID, XP_AWARD_SETTINGS.auditLog));
}

export async function saveXpAwardAuditLog(auditLog: XpAwardAuditLog): Promise<void> {
  await game.settings.set(MODULE_ID, XP_AWARD_SETTINGS.auditLog, JSON.stringify(auditLog));
}

function readString(key: string): string {
  const value = game.settings.get(MODULE_ID, key);
  return typeof value === "string" ? value : "";
}

function readDefaultSelection(): XpDefaultSelection {
  const value = readString(XP_AWARD_SETTINGS.defaultSelection);

  if (value === "company" || value === "world") {
    return value;
  }

  return "party";
}
