import { getSessionTurnoverSettings } from "./settings/load";

export function registerSessionManagementHooks(): void {
  Hooks.on("preUpdateToken", preventHoldingSceneMovement);
}

function preventHoldingSceneMovement(tokenValue: unknown, changeValue: unknown): void {
  if (game.user?.isGM || !isRecord(tokenValue) || !isRecord(changeValue)) return;
  const holdingSceneUuid = getSessionTurnoverSettings().holdingSceneUuid;
  const sceneUuid = (canvas as unknown as { scene?: { uuid?: string } } | undefined)?.scene?.uuid;
  if (!holdingSceneUuid || sceneUuid !== holdingSceneUuid) return;
  if (changeValue["x"] !== undefined) changeValue["x"] = tokenValue["x"];
  if (changeValue["y"] !== undefined) changeValue["y"] = tokenValue["y"];
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}
