export function buildLightPreset(id: LightPresetId, willpowerBonus = 0): TokenLightData {
  if (id === "none") return structuredClone(BASE);
  if (id === "pha")
    return merge({
      alpha: 0.6,
      bright: willpowerBonus,
      color: "#ffddbb",
      dim: willpowerBonus,
      animation: { intensity: 2, speed: 2, type: "sunburst" },
    });
  return merge(presets[id]);
}
function merge(
  changes: Partial<TokenLightData> & { animation?: Partial<TokenLightData["animation"]> },
): TokenLightData {
  return {
    ...structuredClone(BASE),
    ...changes,
    animation: { ...BASE.animation, ...changes.animation },
    darkness: { ...BASE.darkness, ...changes.darkness },
  };
}
