import type { GmToolkitCutoverReview } from "../gm-toolkit/Cutover";
import type { GmToolkitMigrationSnapshot } from "../gm-toolkit/State";
import type { XpAwardRequest } from "../xp-award/XpAward";

export interface SessionRecord {
  id: string;
  occurredAt: string;
  recordedAt: string;
  reference: string;
}

export type SessionTurnoverStepId =
  | "pause"
  | "holding-scene"
  | "xp"
  | "fortune"
  | "chat-export"
  | "record";

export type SessionTurnoverStepStatus = "completed" | "failed" | "pending" | "skipped";

export interface SessionTurnoverStepRecord {
  detail?: string;
  finishedAt?: string;
  id: SessionTurnoverStepId;
  status: SessionTurnoverStepStatus;
}

export interface SessionTurnoverOperation {
  request?: SessionTurnoverRequest;
  id: string;
  sessionReference: string;
  startedAt: string;
  steps: SessionTurnoverStepRecord[];
}

export interface SessionManagementState {
  currentSessionReference: string;
  /** @deprecated Read only as migration evidence from releases before the dedicated importer. */
  gmToolkitCutoverReview?: GmToolkitCutoverReview;
  /** @deprecated Read only as migration evidence from releases before the dedicated importer. */
  gmToolkitMigration?: GmToolkitMigrationSnapshot;
  sessions: SessionRecord[];
  turnover?: SessionTurnoverOperation;
  version: 1;
}

export interface CompleteSessionRequest {
  nextSessionReference: string;
  occurredAt: string;
  sessionReference: string;
}

export interface SessionTurnoverRequest extends CompleteSessionRequest {
  /** Explicit session recipients and XP inputs; omitted by legacy API callers. */
  xp?: XpAwardRequest;
  chatExport: boolean;
  fortuneReset: boolean;
  holdingScene: boolean;
  pause: boolean;
  xpAward: boolean;
}

export interface SessionTurnoverResult {
  operation: SessionTurnoverOperation;
  record?: SessionRecord;
}

export const EMPTY_SESSION_MANAGEMENT_STATE: SessionManagementState = {
  currentSessionReference: "",
  sessions: [],
  version: 1,
};
