import type { XpActorCategory, XpActorChoice, XpDefaultSelection } from "../xp-curve/XpCurve";

export interface XpAwardSettings {
  defaultAmount: number;
  defaultReason: string;
  defaultSelection: XpDefaultSelection;
  includeTimestampInReason: boolean;
}

export interface FixedXpAward {
  actorId: string;
  actorName: string;
  afterXp: number;
  amount: number;
  beforeXp: number;
  category: XpActorCategory;
}

export interface FixedXpAwardPlan {
  awards: FixedXpAward[];
  totalChange: number;
}

export interface XpAwardRequest extends XpAwardSettings {
  actorIds: string[];
}

export interface XpAwardResult extends FixedXpAwardPlan {
  awardedAt: string;
  reason: string;
  sessionReference: string;
}

export interface XpAwardBatchRecord extends XpAwardResult {
  id: string;
}

export interface XpAwardAuditLog {
  batches: XpAwardBatchRecord[];
  version: 1;
}

export interface XpAwardConsoleInitialization extends XpAwardSettings {
  actors: XpActorChoice[];
  awardedAt: string;
  reasonContext: {
    date: string;
    datetime: string;
    session: string;
  };
  selectionSource: "default" | "targets";
}

export const EMPTY_XP_AWARD_AUDIT_LOG: XpAwardAuditLog = {
  batches: [],
  version: 1,
};
