export async function saveCurrentSessionReference(reference: string): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.sessionManagementConsole);
  const normalizedReference = reference.trim();

  if (!normalizedReference) {
    throw new Error("Enter a current session reference.");
  }

  await saveSessionManagementState({
    ...getSessionManagementState(),
    currentSessionReference: normalizedReference,
  });
  ui.notifications.info(`Current session reference saved as ${normalizedReference}.`);
}

export async function completeSession(request: CompleteSessionRequest): Promise<SessionRecord> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.sessionManagementConsole);
  const completed = completeSessionState(getSessionManagementState(), request, {
    id: crypto.randomUUID(),
    recordedAt: new Date().toISOString(),
  });

  await saveSessionManagementState(completed.state);
  ui.notifications.info(
    `Session ${completed.record.reference} recorded. Current session is now ${completed.state.currentSessionReference}.`,
  );

  return completed.record;
}

export async function saveSessionConfiguration(
  settings: {
    exportChat: boolean;
    holdingSceneUuid: string;
    pullPolicy: "activate" | "prompt" | "pull";
  } & Partial<SessionConfiguration>,
): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.sessionManagementConsole);
  await saveSessionTurnoverSettings(settings);
  ui.notifications.info("Session turnover options saved.");
}

export async function pullEveryoneToViewedScene(): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.sessionManagementConsole);
  const runtime = getSessionRuntime();
  const scene = runtime.scenes.viewed;
  if (!scene) throw new Error("View a Scene before pulling players.");

  let policy = getSessionTurnoverSettings().pullPolicy;
  if (policy === "prompt") {
    policy = (await foundry.applications.api.DialogV2.confirm({
      content: `<p>Activate <strong>${foundry.utils.escapeHTML(scene.name)}</strong> for everyone? Choose Cancel to pull connected players without activating it.</p>`,
      modal: true,
      rejectClose: false,
      window: { title: "Pull Everyone to Scene" },
    }))
      ? "activate"
      : "pull";
  }
  if (policy === "activate") {
    await scene.activate();
    ui.notifications.info(`${scene.name} is now the active Scene.`);
    return;
  }

  for (const user of runtime.users) {
    if (!user.isGM && user.active) runtime.socket.emit("pullToScene", scene.id, user.id);
  }
  ui.notifications.info(`Connected players were pulled to ${scene.name}.`);
}

export async function runSessionTurnover(
  request: SessionTurnoverRequest,
): Promise<SessionTurnoverResult> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.sessionManagementConsole);
  validateSessionSubmission(request);
  let state = getSessionManagementState();
  if (
    state.turnover?.request &&
    state.turnover.steps.some((step) => step.status === "failed" || step.status === "pending")
  ) {
    request = state.turnover.request;
  }
  let operation = getOrCreateTurnover(state.turnover, request);
  state = { ...state, turnover: operation };
  await saveSessionManagementState(state);

  for (const step of operation.steps) {
    if (step.status === "completed" || step.status === "skipped") continue;

    try {
      if (step.id === "record") {
        operation = updateSessionTurnoverStep(operation, step.id, "completed", now());
        const completed = completeSessionState({ ...state, turnover: operation }, request, {
          id: crypto.randomUUID(),
          recordedAt: now(),
        });
        await saveSessionManagementState(completed.state);
        ui.notifications.info(`Session ${completed.record.reference} turnover completed.`);
        return { operation, record: completed.record };
      }

      const detail = await runTurnoverStep(step.id, request);
      operation = updateSessionTurnoverStep(operation, step.id, "completed", now(), detail);
      state = { ...state, turnover: operation };
      await saveSessionManagementState(state);
    } catch (error) {
      const detail = error instanceof Error ? error.message : "The step failed.";
      operation = updateSessionTurnoverStep(operation, step.id, "failed", now(), detail);
      await saveSessionManagementState({ ...state, turnover: operation });
      throw new Error(`${stepLabel(step.id)} failed: ${detail}`, { cause: error });
    }
  }

  return { operation };
}

async function runTurnoverStep(
  stepId: Exclude<SessionTurnoverStepId, "record">,
  request: SessionTurnoverRequest,
): Promise<string> {
  const runtime = getSessionRuntime();

  if (stepId === "pause") {
    await runtime.togglePause(true, { broadcast: true });
    return "Game paused for all users.";
  }

  if (stepId === "holding-scene") {
    const uuid = getSessionTurnoverSettings().holdingSceneUuid;
    if (!uuid) throw new Error("Choose a holding Scene first.");
    const scene = await runtime.fromUuid(uuid);
    if (!scene || scene.documentName !== "Scene")
      throw new Error("The configured holding Scene no longer exists.");
    await scene.activate();
    return `${scene.name} activated.`;
  }

  if (stepId === "xp") {
    const settings = request.xp ?? getXpAwardSettings();
    const actorIds =
      request.xp?.actorIds ??
      getXpActorChoices(settings.defaultSelection)
        .actors.filter(({ selected }) => selected)
        .map(({ id }) => id);
    await applyFixedXpAwards(
      { ...settings, actorIds },
      {
        reference: request.sessionReference.trim(),
        reason: sessionXpReason(settings, request.sessionReference, request.occurredAt),
      },
    );
    return `XP applied to ${actorIds.length} character${actorIds.length === 1 ? "" : "s"}.`;
  }

  if (stepId === "fortune") return resetFortune(request.xp?.actorIds);

  if (!runtime.messages.export)
    throw new Error("Chat export is unavailable in this Foundry version.");
  await runtime.messages.export();
  return "Chat log exported.";
}

function getOrCreateTurnover(
  current: SessionTurnoverOperation | undefined,
  request: SessionTurnoverRequest,
): SessionTurnoverOperation {
  if (
    current?.sessionReference === request.sessionReference.trim() &&
    current.steps.some(({ status }) => status === "failed" || status === "pending")
  ) {
    return current;
  }

  const enabled = new Set<SessionTurnoverStepId>(["record"]);
  if (request.pause) enabled.add("pause");
  if (request.holdingScene) enabled.add("holding-scene");
  if (request.xpAward) enabled.add("xp");
  if (request.fortuneReset) enabled.add("fortune");
  if (request.chatExport) enabled.add("chat-export");
  return {
    ...createSessionTurnoverOperation(
      crypto.randomUUID(),
      request.sessionReference,
      now(),
      enabled,
    ),
    request: structuredClone(request),
  };
}

function stepLabel(stepId: SessionTurnoverStepId): string {
  return {
    "chat-export": "Chat export",
    "fortune": "Fortune reset",
    "holding-scene": "Holding Scene",
    "pause": "Pause",
    "record": "Session recording",
    "xp": "XP award",
  }[stepId];
}

function now(): string {
  return new Date().toISOString();
}

interface SessionSceneRuntime {
  activate: () => Promise<unknown>;
  documentName: "Scene";
  id: string;
  name: string;
}

interface SessionGameRuntime {
  fromUuid: (uuid: string) => Promise<SessionSceneRuntime | undefined>;
  messages: { export?: () => Promise<unknown> };
  scenes: { viewed?: SessionSceneRuntime | null };
  socket: { emit: (event: string, ...args: unknown[]) => void };
  togglePause: (paused: boolean, options: { broadcast: boolean }) => Promise<unknown>;
  users: Iterable<FoundryUser & { active?: boolean }>;
}

function getSessionRuntime(): SessionGameRuntime {
  const globalRuntime = globalThis as unknown as { fromUuid: SessionGameRuntime["fromUuid"] };
  return { ...(game as unknown as SessionGameRuntime), fromUuid: globalRuntime.fromUuid };
}
