import { LOCALIZATION_NAMESPACE, MODULE_ID } from "../../constants";
import { ADVANTAGE_SETTINGS } from "./keys";

export function registerCombatSettings(): void {
  for (const [name, key] of Object.entries(ADVANTAGE_SETTINGS)) {
    game.settings.register(MODULE_ID, key, {
      config: false,
      default: name !== "persistentNotifications",
      hint: `${LOCALIZATION_NAMESPACE}.Settings.Advantage.${name}.Hint`,
      name: `${LOCALIZATION_NAMESPACE}.Settings.Advantage.${name}.Name`,
      scope: "world",
      type: Boolean,
    });
  }
}
