import { FearConsoleApplication } from "../../apps/fear-console/FearConsoleApplication";
import { openFearConsoleFromUi } from "../../apps/fear-console/open";
import { inferActorPsychologyPayload } from "../infer";
import { FEAR_TERROR_LAUNCHER_SETTINGS, isFearTerrorLauncherEnabled } from "../settings/launchers";

const ACTION_NAME = "openFearConsole";
const BUTTON_CLASS = "wfrp4e-enhanced-fear-terror-actor-header";

const ACTOR_SHEET_HEADER_HOOKS = [
  "getHeaderControlsActorSheetWFRP4eCharacter",
  "getHeaderControlsActorSheetWFRP4eNPC",
  "getHeaderControlsActorSheetWFRP4eCreature",
  "getHeaderControlsStandardWFRP4eActorSheet",
  "getHeaderControlsBaseWFRP4eActorSheet",
  "getHeaderControlsWarhammerActorSheetV2",
];

const ACTOR_SHEET_RENDER_HOOKS = [
  "renderActorSheetWFRP4eCharacter",
  "renderActorSheetWFRP4eNPC",
  "renderActorSheetWFRP4eCreature",
  "renderStandardWFRP4eActorSheet",
  "renderBaseWFRP4eActorSheet",
  "renderWarhammerActorSheetV2",
];

export function registerActorSheetEntry(): void {
  for (const hookName of ACTOR_SHEET_HEADER_HOOKS) {
    Hooks.on(hookName, (sheet, controls) => {
      if (!canShowActorSheetEntry()) {
        return;
      }

      addActorSheetHeaderButton(sheet as FoundryDocumentSheet, controls as FoundryHeaderControl[]);
    });
  }

  for (const hookName of ACTOR_SHEET_RENDER_HOOKS) {
    Hooks.on(hookName, (sheet) => {
      if (!canShowActorSheetEntry()) {
        return;
      }

      injectActorSheetHeaderButton(sheet as FoundryDocumentSheet);
    });
  }
}

function canShowActorSheetEntry(): boolean {
  return (
    FearConsoleApplication.canCurrentUserAccess() &&
    isFearTerrorLauncherEnabled(FEAR_TERROR_LAUNCHER_SETTINGS.actorSheet)
  );
}

function addActorSheetHeaderButton(
  sheet: FoundryDocumentSheet,
  controls: FoundryHeaderControl[],
): void {
  const actor = sheet.document;

  if (actor.documentName !== "Actor") {
    return;
  }

  if (controls.some((control) => control.action === ACTION_NAME)) {
    return;
  }

  controls.push({
    action: ACTION_NAME,
    icon: "fa-solid fa-skull",
    label: "Fear Console",
  });

  sheet.options.actions ??= {};
  sheet.options.actions[ACTION_NAME] = function () {
    openFearConsoleForActor(this.document);
  };
}

function injectActorSheetHeaderButton(sheet: FoundryDocumentSheet): void {
  const actor = sheet.document;
  const element = sheet.element;

  if (actor.documentName !== "Actor" || !(element instanceof HTMLElement)) {
    return;
  }

  const header = element.querySelector(".window-header");

  if (!header || header.querySelector(`.${BUTTON_CLASS}`)) {
    return;
  }

  const button = document.createElement("button");
  button.type = "button";
  button.classList.add(BUTTON_CLASS, "header-control", "icon", "fa-solid", "fa-skull");
  button.dataset["action"] = ACTION_NAME;
  button.dataset["tooltip"] = "Fear Console";
  button.ariaLabel = "Open Drowsy’s WFRP4e Toolkit Fear Console";

  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openFearConsoleForActor(actor);
  });

  const insertionPoint =
    header.querySelector('[data-action="toggleControls"]') ??
    header.querySelector('[data-action="close"]');

  header.insertBefore(button, insertionPoint);
}

function openFearConsoleForActor(actor: FoundryActorDocument): void {
  try {
    const initialPayload = inferActorPsychologyPayload(actor);
    openFearConsoleFromUi({ initialPayload });
  } catch (error) {
    console.error(
      "wfrp4e-enhanced-fear-terror | Could not infer Fear or Terror from the actor.",
      error,
    );
    ui.notifications.error(
      "Drowsy’s WFRP4e Toolkit could not read this actor. See the browser console for details.",
    );
  }
}
