import { computed, ref } from "vue";
import { defineStore } from "pinia";

import {
  calculateXpAwardPlan,
  normalizeXpCurveParameters,
  sampleXpCurve,
  sampleXpDecayCurve,
} from "../../../functions/xp-curve/calculate";
import {
  DEFAULT_XP_CURVE_CONFIGURATOR_SETTINGS,
  type XpCurveConfiguratorActions,
  type XpCurveConfiguratorInitialization,
  type XpCurveConfiguratorSettings,
} from "../../../types/xp-curve/Configuration";
import type {
  XpActorChoice,
  XpCurveParameters,
  XpDefaultSelection,
} from "../../../types/xp-curve/XpCurve";

export const useXpCurveConfiguratorStore = defineStore("xp-curve-configurator", () => {
  const actors = ref<XpActorChoice[]>([]);
  const parameters = ref<XpCurveParameters>({
    ...DEFAULT_XP_CURVE_CONFIGURATOR_SETTINGS.parameters,
  });
  const defaultReason = ref(DEFAULT_XP_CURVE_CONFIGURATOR_SETTINGS.defaultReason);
  const defaultSelection = ref<XpDefaultSelection>(
    DEFAULT_XP_CURVE_CONFIGURATOR_SETTINGS.defaultSelection,
  );
  const launchers = ref({
    ...DEFAULT_XP_CURVE_CONFIGURATOR_SETTINGS.launchers,
  });
  const errorMessage = ref<undefined | string>();
  const statusMessage = ref<undefined | string>();
  const isSaving = ref(false);
  let configuratorActions: XpCurveConfiguratorActions | undefined;

  const plan = computed(() => calculateXpAwardPlan(actors.value, parameters.value));
  const largestGap = computed(() => Math.max(0, ...plan.value.awards.map((award) => award.gap)));
  const curveSamples = computed(() =>
    sampleXpCurve(parameters.value, Math.max(largestGap.value * 1.1, 1)),
  );
  const decaySamples = computed(() =>
    sampleXpDecayCurve(parameters.value, Math.max(plan.value.highestXp * 1.1, 1)),
  );

  function initialize(
    initialization: XpCurveConfiguratorInitialization,
    actions: XpCurveConfiguratorActions,
  ): void {
    configuratorActions = actions;
    actors.value = initialization.actors.map((actor) => ({ ...actor }));
    parameters.value = { ...initialization.parameters };
    defaultReason.value = initialization.defaultReason;
    defaultSelection.value = initialization.defaultSelection;
    launchers.value = { ...initialization.launchers };
    errorMessage.value = undefined;
    statusMessage.value = undefined;
  }

  function setDefaultSelection(selection: XpDefaultSelection): void {
    defaultSelection.value = selection;
    statusMessage.value = undefined;
  }

  function resetToDefaults(): void {
    parameters.value = { ...DEFAULT_XP_CURVE_CONFIGURATOR_SETTINGS.parameters };
    defaultReason.value = DEFAULT_XP_CURVE_CONFIGURATOR_SETTINGS.defaultReason;
    defaultSelection.value = DEFAULT_XP_CURVE_CONFIGURATOR_SETTINGS.defaultSelection;
    launchers.value = { ...DEFAULT_XP_CURVE_CONFIGURATOR_SETTINGS.launchers };
    errorMessage.value = undefined;
    statusMessage.value = "Defaults restored. Save configuration to apply them.";
  }

  async function saveConfiguration(): Promise<void> {
    if (isSaving.value) {
      return;
    }

    isSaving.value = true;
    errorMessage.value = undefined;
    statusMessage.value = undefined;

    try {
      parameters.value = normalizeXpCurveParameters(parameters.value);
      const configuration: XpCurveConfiguratorSettings = {
        defaultReason: defaultReason.value,
        defaultSelection: defaultSelection.value,
        launchers: { ...launchers.value },
        parameters: { ...parameters.value },
      };

      await getConfiguratorActions().saveConfiguration(configuration);
      statusMessage.value = "Configuration saved. Launcher changes apply after a reload.";
    } catch (error) {
      console.error("Drowsy’s WFRP4e Toolkit | XP configuration save failed.", error);
      errorMessage.value =
        error instanceof Error
          ? error.message
          : "The XP Curve Console configuration could not be saved.";
    } finally {
      isSaving.value = false;
    }
  }

  function getConfiguratorActions(): XpCurveConfiguratorActions {
    if (!configuratorActions) {
      throw new Error("The XP Curve Configurator has not been initialized.");
    }

    return configuratorActions;
  }

  return {
    actors,
    curveSamples,
    decaySamples,
    defaultReason,
    defaultSelection,
    errorMessage,
    initialize,
    isSaving,
    launchers,
    parameters,
    plan,
    resetToDefaults,
    saveConfiguration,
    setDefaultSelection,
    statusMessage,
  };
});
