import { GM_TOOLKIT_9_2_SETTING_DEFINITIONS } from "../../functions/gm-toolkit/catalog";
import { normalizeGmToolkitSetting } from "../../functions/gm-toolkit/migration";
import type {
  GmToolkitSettingDefinition,
  GmToolkitSourceSnapshot,
} from "../../types/gm-toolkit/Migration";
import { GM_TOOLKIT_MODULE_ID } from "../constants";

export function getGmToolkitSourceSnapshot(): GmToolkitSourceSnapshot | undefined {
  const moduleEntry = game.modules.get(GM_TOOLKIT_MODULE_ID);
  const worldStorage = game.settings.storage?.get("world");
  const persistedValues = new Map<string, string>();

  for (const definition of GM_TOOLKIT_9_2_SETTING_DEFINITIONS) {
    const serialized = worldStorage?.getItem(settingId(definition.key));

    if (serialized !== null && serialized !== undefined) {
      persistedValues.set(definition.key, serialized);
    }
  }

  if (!moduleEntry && persistedValues.size === 0) {
    return undefined;
  }

  const warnings: string[] = [];
  const settings = GM_TOOLKIT_9_2_SETTING_DEFINITIONS.map((definition) => {
    const resolved = resolveSetting(definition, persistedValues);

    if (!resolved.valid) {
      warnings.push(
        `${settingId(definition.key)} could not be normalized; the 9.2.0 baseline is shown instead.`,
      );
    }

    return resolved;
  });

  return {
    active: moduleEntry?.active === true,
    installed: moduleEntry !== undefined,
    ...(moduleEntry?.version ? { moduleVersion: moduleEntry.version } : {}),
    schemaVersion: "9.2.0",
    settings,
    warnings,
  };
}

function resolveSetting(
  definition: GmToolkitSettingDefinition,
  persistedValues: ReadonlyMap<string, string>,
) {
  const persisted = persistedValues.get(definition.key);

  if (persisted !== undefined) {
    return normalizeGmToolkitSetting(
      definition,
      parsePersistedValue(persisted, definition),
      "persisted",
    );
  }

  if (game.settings.settings.has(settingId(definition.key))) {
    return normalizeGmToolkitSetting(
      definition,
      game.settings.get(GM_TOOLKIT_MODULE_ID, definition.key),
      "registered",
    );
  }

  return normalizeGmToolkitSetting(definition, definition.defaultValue, "baseline");
}

function parsePersistedValue(serialized: string, definition: GmToolkitSettingDefinition): unknown {
  try {
    return JSON.parse(serialized) as unknown;
  } catch {
    return definition.kind === "string" ? serialized : undefined;
  }
}

function settingId(key: string): string {
  return `${GM_TOOLKIT_MODULE_ID}.${key}`;
}
