import { ToolkitHomeApplication } from "../../apps/toolkit-home/ToolkitHomeApplication";
import { openToolkitHome } from "../../apps/toolkit-home/open";
import { LOCALIZATION_NAMESPACE, MODULE_ID } from "../../constants";

export function registerToolkitHomeSettings(): void {
  class ToolkitHomeMenuApplication extends ToolkitHomeApplication {
    constructor() {
      super([]);
    }

    override async render(_force?: boolean): Promise<this> {
      await openToolkitHome();
      return this;
    }
  }

  game.settings.registerMenu(MODULE_ID, "toolkitHome", {
    hint: `${LOCALIZATION_NAMESPACE}.Menu.ToolkitHome.Hint`,
    icon: "fa-solid fa-toolbox",
    label: `${LOCALIZATION_NAMESPACE}.Menu.ToolkitHome.Label`,
    name: `${LOCALIZATION_NAMESPACE}.Menu.ToolkitHome.Name`,
    restricted: ToolkitHomeApplication.ACCESS_POLICY.gmOnly,
    type: ToolkitHomeMenuApplication,
  });
}
