import type { ToolkitApplicationHandle } from "../../../types/module/api/ModuleApi";
import { MODULE_ID } from "../../constants";
import { XpAwardConsoleApplication } from "./XpAwardConsoleApplication";

export async function openXpAwardConsole(): Promise<ToolkitApplicationHandle> {
  const application = new XpAwardConsoleApplication();
  await application.render(true);
  return application;
}

export function openXpAwardConsoleFromUi(): void {
  void openXpAwardConsole().catch((error: unknown) => {
    console.error(`${MODULE_ID} | Failed to open the XP Award Console.`, error);
    ui.notifications.error(
      "Drowsy’s WFRP4e Toolkit could not open the XP Award Console. See the browser console for details.",
    );
  });
}
