import { discoverGmToolkitDarkWhispersCandidates } from "../../functions/gm-toolkit/content";
import type { GmToolkitDarkWhispersSourceCandidate } from "../../types/gm-toolkit/Migration";
import { GM_TOOLKIT_MODULE_ID } from "../constants";

export function getGmToolkitDarkWhispersCandidates(): GmToolkitDarkWhispersSourceCandidate[] {
  const moduleVersion = game.modules.get(GM_TOOLKIT_MODULE_ID)?.version;
  const tables = Array.from(game.tables).map((table) => plainTextTableData(table.toObject()));

  return discoverGmToolkitDarkWhispersCandidates(tables, moduleVersion);
}

function plainTextTableData(value: unknown): unknown {
  if (typeof value !== "object" || value === null) {
    return value;
  }

  const results: unknown = Reflect.get(value, "results");

  if (!Array.isArray(results)) {
    return value;
  }

  return {
    ...value,
    results: results.map((result: unknown) => {
      if (typeof result !== "object" || result === null) {
        return result;
      }

      return {
        ...result,
        description: htmlToPlainText(Reflect.get(result, "description")),
      };
    }),
  };
}

function htmlToPlainText(value: unknown): string {
  if (typeof value !== "string") {
    return "";
  }

  if (!/[<&]/.test(value)) {
    return value;
  }

  const container = document.createElement("div");
  container.innerHTML = value;
  container.querySelectorAll("script, style, template").forEach((element) => element.remove());

  return container.textContent ?? "";
}
