import { AdministrationConsoleApplication } from "../../apps/administration-console/AdministrationConsoleApplication";
import { LOCALIZATION_NAMESPACE, MODULE_ID } from "../../constants";
import { registerHiddenWorldSetting } from "../../settings/register";
import { ADMINISTRATION_SETTINGS } from "./keys";

export function registerAdministrationSettings(): void {
  registerHiddenWorldSetting(
    ADMINISTRATION_SETTINGS.showUnassignedPlayerWarning,
    true,
    Boolean,
    `${LOCALIZATION_NAMESPACE}.Settings.Administration.ShowUnassignedPlayerWarning`,
  );
  game.settings.registerMenu(MODULE_ID, "administrationConsole", {
    hint: `${LOCALIZATION_NAMESPACE}.Menu.AdministrationConsole.Hint`,
    icon: "fa-solid fa-screwdriver-wrench",
    label: `${LOCALIZATION_NAMESPACE}.Menu.AdministrationConsole.Label`,
    name: `${LOCALIZATION_NAMESPACE}.Menu.AdministrationConsole.Name`,
    restricted: AdministrationConsoleApplication.ACCESS_POLICY.gmOnly,
    type: AdministrationConsoleApplication,
  });
}
