import type { XpAwardAuditLog, XpAwardBatchRecord } from "../../types/xp-award/XpAward";
import { EMPTY_XP_AWARD_AUDIT_LOG } from "../../types/xp-award/XpAward";
import { isRecord, normalizeIsoDateTime, readString } from "../records/parse";

const MAX_XP_AWARD_BATCHES = 500;

export function addXpAwardBatch(
  auditLog: XpAwardAuditLog,
  batch: XpAwardBatchRecord,
): XpAwardAuditLog {
  return {
    batches: [batch, ...auditLog.batches].slice(0, MAX_XP_AWARD_BATCHES),
    version: 1,
  };
}

export function parseXpAwardAuditLog(value: unknown): XpAwardAuditLog {
  if (typeof value !== "string") {
    return { ...EMPTY_XP_AWARD_AUDIT_LOG, batches: [] };
  }

  try {
    const parsed: unknown = JSON.parse(value);

    if (!isRecord(parsed) || parsed["version"] !== 1 || !Array.isArray(parsed["batches"])) {
      return { ...EMPTY_XP_AWARD_AUDIT_LOG, batches: [] };
    }

    return {
      batches: parsed["batches"].flatMap(parseBatch).slice(0, MAX_XP_AWARD_BATCHES),
      version: 1,
    };
  } catch {
    return { ...EMPTY_XP_AWARD_AUDIT_LOG, batches: [] };
  }
}

function parseBatch(value: unknown): XpAwardBatchRecord[] {
  if (!isRecord(value) || !Array.isArray(value["awards"])) {
    return [];
  }

  const awardedAt = normalizeIsoDateTime(value["awardedAt"]);
  const id = readString(value["id"]);
  const reason = readString(value["reason"]);
  const sessionReference = readString(value["sessionReference"]);
  const awards = value["awards"].flatMap(parseAward);

  if (!awardedAt || !id || awards.length === 0) {
    return [];
  }

  return [
    {
      awardedAt,
      awards,
      id,
      reason,
      sessionReference,
      totalChange: awards.reduce((sum, award) => sum + award.amount, 0),
    },
  ];
}

function parseAward(value: unknown): XpAwardBatchRecord["awards"] {
  if (!isRecord(value)) {
    return [];
  }

  const category = value["category"];
  const amount = Number(value["amount"]);
  const beforeXp = Number(value["beforeXp"]);
  const afterXp = Number(value["afterXp"]);

  if (
    (category !== "standard" && category !== "companion") ||
    !Number.isFinite(amount) ||
    !Number.isFinite(beforeXp) ||
    !Number.isFinite(afterXp)
  ) {
    return [];
  }

  return [
    {
      actorId: readString(value["actorId"]),
      actorName: readString(value["actorName"]),
      afterXp: Math.round(afterXp),
      amount: Math.round(amount),
      beforeXp: Math.round(beforeXp),
      category,
    },
  ];
}
