import type { GmToolkitLauncherMigrationPreview } from "../../types/gm-toolkit/LauncherMigration";
import { isGmToolkitLauncherRemappable } from "./launchers";

export type GmToolkitLauncherSelections = Record<number, boolean>;

export interface GmToolkitLauncherAssignment {
  macroId: string;
  slot: number;
}

export function createGmToolkitLauncherSelections(
  preview: GmToolkitLauncherMigrationPreview | undefined,
): GmToolkitLauncherSelections {
  return Object.fromEntries((preview?.remappableSlots ?? []).map((slot) => [slot, true]));
}

export function getSelectedGmToolkitLauncherSlots(
  selections: GmToolkitLauncherSelections,
): number[] {
  return Object.entries(selections)
    .filter(([, selected]) => selected)
    .map(([slot]) => Number(slot))
    .filter((slot) => Number.isInteger(slot))
    .sort((left, right) => left - right);
}

export function buildGmToolkitLauncherAssignments(
  preview: GmToolkitLauncherMigrationPreview,
  slots: readonly number[],
): GmToolkitLauncherAssignment[] {
  const requestedSlots = Array.from(new Set(slots)).filter(
    (slot) => Number.isInteger(slot) && slot >= 1 && slot <= 50,
  );

  return requestedSlots.flatMap((slot) => {
    const candidate = preview.candidates.find(
      (candidate) =>
        candidate.hotbarSlots.includes(slot) && isGmToolkitLauncherRemappable(candidate),
    );

    return candidate?.replacement.macroId ? [{ macroId: candidate.replacement.macroId, slot }] : [];
  });
}
