<script setup lang="ts">
import type { XpActorChoice, XpAward, XpAwardPlan } from "../../../../types/xp-curve/XpCurve";
import ActorSelectionCheckbox from "../../shared/ActorSelectionCheckbox.vue";

const props = defineProps<{
  actors: XpActorChoice[];
  disabled: boolean;
  plan: XpAwardPlan;
}>();

const emit = defineEmits<{
  "reset": [];
  "select-all": [selected: boolean];
  "update:selected": [actorId: string, selected: boolean];
}>();

function getAward(actorId: string): XpAward | undefined {
  return props.plan.awards.find((award) => award.actorId === actorId);
}

function updateActorSelection(actorId: string, selected: boolean): void {
  emit("update:selected", actorId, selected);
}
</script>

<template>
  <section
    class="dui-card dui-card-border tw:min-w-0 tw:border-2 tw:border-base-content/20! tw:bg-base-100! tw:text-base-content! tw:shadow-md"
    aria-labelledby="recipients-title"
  >
    <div class="dui-card-body tw:min-w-0 tw:gap-3 tw:p-4">
      <div class="tw:flex tw:flex-wrap tw:items-start tw:justify-between tw:gap-2">
        <div>
          <div class="tw:flex tw:items-center tw:gap-2">
            <h2
              id="recipients-title"
              class="dui-card-title tw:font-serif tw:text-lg tw:text-base-content!"
            >
              Recipients
            </h2>
            <span class="dui-badge dui-badge-sm">{{ plan.awards.length }} selected</span>
          </div>
          <p class="tw:m-0 tw:text-xs tw:text-base-content/65!">
            The XP leader sets the gap only. Decay is calculated from each recipient’s own total.
          </p>
        </div>
        <div class="tw:flex tw:flex-wrap tw:gap-1">
          <button
            class="dui-btn dui-btn-ghost dui-btn-sm"
            :disabled="disabled"
            type="button"
            @click="emit('select-all', true)"
          >
            All
          </button>
          <button
            class="dui-btn dui-btn-ghost dui-btn-sm"
            :disabled="disabled"
            type="button"
            @click="emit('select-all', false)"
          >
            None
          </button>
          <button
            class="dui-btn dui-btn-ghost dui-btn-sm"
            :disabled="disabled"
            type="button"
            @click="emit('reset')"
          >
            Reset
          </button>
        </div>
      </div>

      <div
        v-if="actors.length"
        class="tw:max-w-full tw:min-w-0 tw:overflow-x-auto tw:rounded-box tw:border tw:border-base-content/20! tw:bg-base-100!"
      >
        <table class="dui-table dui-table-sm tw:min-w-[52rem]">
          <thead class="tw:bg-base-300/60!">
            <tr>
              <th scope="col">Use</th>
              <th scope="col">Actor</th>
              <th class="tw:text-right" scope="col">Total XP</th>
              <th class="tw:text-right" scope="col">Leader gap</th>
              <th class="tw:text-right" scope="col">Initial XP</th>
              <th class="tw:text-right" scope="col">Decay</th>
              <th class="tw:text-right" scope="col">Final award</th>
              <th class="tw:text-right" scope="col">New total</th>
            </tr>
          </thead>
          <tbody>
            <tr
              v-for="actor in actors"
              :key="actor.id"
              :class="{ 'tw:bg-base-200!': actor.selected }"
            >
              <td>
                <ActorSelectionCheckbox
                  :actor-id="actor.id"
                  :actor-name="actor.name"
                  :checked="actor.selected"
                  :disabled="disabled"
                  purpose="the XP curve"
                  @change="updateActorSelection"
                />
              </td>
              <th class="tw:min-w-44" scope="row">
                <span class="tw:block tw:font-semibold">{{ actor.name }}</span>
                <span
                  v-if="actor.category === 'companion'"
                  class="dui-badge dui-badge-ghost dui-badge-xs"
                >
                  Companion rate
                </span>
              </th>
              <td class="tw:text-right tw:tabular-nums">{{ actor.totalXp }}</td>
              <td class="tw:text-right tw:tabular-nums">
                {{ getAward(actor.id)?.gap ?? "—" }}
              </td>
              <td class="tw:text-right tw:tabular-nums">
                {{ getAward(actor.id) ? Math.round(getAward(actor.id)?.catchUpValue ?? 0) : "—" }}
              </td>
              <td class="tw:text-right tw:tabular-nums">
                {{
                  getAward(actor.id)
                    ? `${Math.round((getAward(actor.id)?.decayMultiplier ?? 0) * 100)}%`
                    : "—"
                }}
              </td>
              <td class="tw:text-right tw:font-bold tw:tabular-nums">
                {{ getAward(actor.id) ? `+${getAward(actor.id)?.award}` : "—" }}
              </td>
              <td class="tw:text-right tw:tabular-nums">
                {{ getAward(actor.id)?.afterXp ?? "—" }}
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      <div v-else class="dui-alert dui-alert-warning" role="status">
        <i class="fa-solid fa-user-slash" aria-hidden="true" />
        <span>No WFRP4e character actors are available in this world.</span>
      </div>
    </div>
  </section>
</template>
