import { getXpActorChoices } from "../xp-curve/actors";
import type { SessionManagementConsoleInitialization } from "../../types/session-management/Console";
import { getSessionManagementState, getSessionTurnoverSettings } from "./settings/load";

export function getSessionManagementConsoleInitialization(): SessionManagementConsoleInitialization {
  const state = getSessionManagementState();
  const settings = getSessionTurnoverSettings();

  return {
    actors: getXpActorChoices(settings.xp.defaultSelection).actors,
    occurredAtLocal: formatDateTimeLocal(new Date()),
    scenes: Array.from(
      (game as unknown as { scenes: Iterable<{ name: string; uuid: string }> }).scenes,
    )
      .map(({ name, uuid }) => ({ label: name, uuid }))
      .sort((left, right) => left.label.localeCompare(right.label)),
    settings,
    state,
  };
}

function formatDateTimeLocal(date: Date): string {
  const offsetDate = new Date(date.getTime() - date.getTimezoneOffset() * 60_000);
  return offsetDate.toISOString().slice(0, 16);
}
