import {
  calculateXpAwardPlan,
  normalizeXpCurveParameters,
} from "../../functions/xp-curve/calculate";
import { escapeHtml, resolveXpAwardReason } from "../../functions/xp-curve/reason";
import type { XpAwardRequest, XpAwardResult, XpCurveSettings } from "../../types/xp-curve/XpCurve";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";
import { getXpReasonContext } from "./initialization";
import { getXpActorRuntimes } from "./actors";
import { saveXpCurveSettings } from "./settings/load";

export async function applyXpCurveAwards(request: XpAwardRequest): Promise<XpAwardResult> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.xpCurveConsole);

  const actorIds = Array.from(new Set(request.actorIds));
  const actorRuntimes = getXpActorRuntimes(actorIds);
  const parameters = normalizeXpCurveParameters(request.parameters);
  const plan = calculateXpAwardPlan(
    actorRuntimes.map((runtime) => runtime.choice),
    parameters,
  );

  if (plan.awards.length < 2) {
    throw new Error("Select at least two character actors to calculate catch-up XP.");
  }

  if (plan.totalAward < 1) {
    throw new Error("This curve produces no XP awards for the selected actors.");
  }

  const settings: XpCurveSettings = {
    defaultReason: request.defaultReason,
    defaultSelection: request.defaultSelection,
    parameters,
  };
  await saveXpCurveSettings(settings);

  const reason = resolveXpAwardReason(request.defaultReason, getXpReasonContext());
  const appliedActorNames: string[] = [];

  for (const [index, runtime] of actorRuntimes.entries()) {
    const award = plan.awards[index]!;

    if (award.award === 0) {
      continue;
    }

    try {
      await runtime.awardExperience(award.award, reason);
      appliedActorNames.push(award.actorName);
    } catch (error) {
      const appliedSummary =
        appliedActorNames.length > 0
          ? ` XP was already applied to ${appliedActorNames.join(", ")}.`
          : "";
      const detail = error instanceof Error ? ` ${error.message}` : "";

      throw new Error(`Could not award XP to ${award.actorName}.${appliedSummary}${detail}`, {
        cause: error,
      });
    }
  }

  const result: XpAwardResult = {
    ...plan,
    reason,
  };
  await postXpAwardSummary(result);
  ui.notifications.info(
    `Awarded ${result.totalAward} total XP across ${appliedActorNames.length} actors.`,
  );

  return result;
}

export async function saveXpCurveDefaults(settings: XpCurveSettings): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.xpCurveConsole);

  await saveXpCurveSettings({
    ...settings,
    parameters: normalizeXpCurveParameters(settings.parameters),
  });
  ui.notifications.info("XP Curve Console defaults saved.");
}

async function postXpAwardSummary(result: XpAwardResult): Promise<void> {
  const rows = result.awards
    .filter((award) => award.award > 0)
    .map(
      (award) =>
        `<li><strong>${escapeHtml(award.actorName)}</strong>: +${award.award} XP ` +
        `(${award.beforeXp} → ${award.afterXp})</li>`,
    )
    .join("");
  const content =
    `<h2>XP Curve Award</h2><p>${escapeHtml(result.reason)}</p>` +
    `<ul>${rows}</ul><p><strong>${result.totalAward} XP awarded in total.</strong></p>`;
  const messageData = game.wfrp4e.utility.chatDataSetup(content, "gmroll", false, {
    alias: "Drowsy’s WFRP4e Toolkit",
  });

  await ChatMessage.create(messageData);
}
