<script setup lang="ts">
import { computed } from "vue";

import type {
  GmToolkitLauncherCandidate,
  GmToolkitLauncherMigrationPreview,
} from "../../../types/gm-toolkit/LauncherMigration";
import { isGmToolkitLauncherRemappable } from "../../../functions/gm-toolkit/launchers";

const props = defineProps<{
  isWorking: boolean;
  preview: GmToolkitLauncherMigrationPreview;
  selections: Record<number, boolean>;
}>();

const emit = defineEmits<{
  remap: [];
  selectionChange: [slot: number, selected: boolean];
}>();

const selectedCount = computed(
  () => Object.values(props.selections).filter((selected) => selected).length,
);

function isRemappable(candidate: GmToolkitLauncherCandidate): boolean {
  return isGmToolkitLauncherRemappable(candidate);
}

function candidateSelected(candidate: GmToolkitLauncherCandidate): boolean {
  return (
    isRemappable(candidate) &&
    candidate.hotbarSlots.every((slot) => props.selections[slot] === true)
  );
}

function updateCandidate(candidate: GmToolkitLauncherCandidate, event: Event): void {
  const input = event.currentTarget;
  const selected = input instanceof HTMLInputElement && input.checked;

  for (const slot of candidate.hotbarSlots) {
    emit("selectionChange", slot, selected);
  }
}

function matchLabel(candidate: GmToolkitLauncherCandidate): string {
  if (candidate.match === "standard") return "Stock macro";
  if (candidate.match === "customized") return "Customized";
  return "Review match";
}

function dispositionLabel(candidate: GmToolkitLauncherCandidate): string {
  if (candidate.replacement.disposition === "ready") return "Can remap";
  if (candidate.replacement.disposition === "independent") return "Works without GM Toolkit";
  return "Keep original";
}

function hotbarLabel(slots: readonly number[]): string {
  return slots.length
    ? `Slot${slots.length === 1 ? "" : "s"} ${slots.join(", ")}`
    : "Not on hotbar";
}
</script>

<template>
  <section
    class="dui-card dui-card-border tw:min-w-0 tw:border-2 tw:border-accent/40! tw:bg-base-100! tw:shadow-md"
    aria-labelledby="gm-toolkit-launcher-title"
  >
    <div class="dui-card-body tw:min-w-0 tw:gap-3 tw:p-4">
      <div class="tw:flex tw:flex-wrap tw:items-start tw:justify-between tw:gap-3">
        <div class="tw:min-w-0 tw:flex-1">
          <div class="tw:flex tw:flex-wrap tw:items-center tw:gap-2">
            <h2 id="gm-toolkit-launcher-title" class="dui-card-title tw:font-serif tw:text-lg">
              Hotbar launchers
            </h2>
            <span class="dui-badge dui-badge-sm">{{ preview.candidates.length }} found</span>
          </div>
          <p class="tw:m-0 tw:text-xs tw:text-base-content/65!">
            Reviews this user’s hotbar without running or copying GM Toolkit commands. Customized
            macros stay untouched.
          </p>
        </div>

        <button
          class="dui-btn dui-btn-accent dui-btn-sm tw:shrink-0"
          :disabled="isWorking || selectedCount === 0"
          type="button"
          @click="emit('remap')"
        >
          <span
            v-if="isWorking"
            class="dui-loading dui-loading-spinner dui-loading-sm"
            aria-hidden="true"
          />
          <i v-else class="fa-solid fa-arrow-right-arrow-left" aria-hidden="true" />
          Remap {{ selectedCount }} slot{{ selectedCount === 1 ? "" : "s" }}
        </button>
      </div>

      <div class="tw:flex tw:flex-wrap tw:gap-2 tw:text-xs">
        <span class="dui-badge dui-badge-sm">{{ preview.counts.standard }} stock</span>
        <span class="dui-badge dui-badge-sm">{{ preview.counts.customized }} customized</span>
        <span class="dui-badge dui-badge-sm">{{ preview.counts.ambiguous }} review</span>
        <span class="dui-badge dui-badge-sm">{{ preview.userName ?? "Current user" }}</span>
      </div>

      <div
        class="tw:max-w-full tw:overflow-x-auto tw:rounded-box tw:border tw:border-base-content/20!"
      >
        <table class="dui-table dui-table-sm tw:min-w-[46rem]">
          <thead class="tw:bg-base-300/60!">
            <tr>
              <th scope="col">Remap</th>
              <th scope="col">GM Toolkit macro</th>
              <th scope="col">Match</th>
              <th scope="col">Hotbar</th>
              <th scope="col">Drowsy outcome</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="candidate in preview.candidates" :key="candidate.macroId">
              <td>
                <label
                  v-if="isRemappable(candidate)"
                  class="tw:flex tw:cursor-pointer tw:items-center tw:gap-2"
                >
                  <input
                    class="dui-checkbox dui-checkbox-sm"
                    :checked="candidateSelected(candidate)"
                    type="checkbox"
                    @change="updateCandidate(candidate, $event)"
                  />
                  <span class="tw:sr-only">
                    Remap {{ candidate.sourceMacroName }} from
                    {{ hotbarLabel(candidate.hotbarSlots) }}
                  </span>
                </label>
                <span v-else aria-hidden="true">—</span>
              </td>
              <th class="tw:max-w-56 tw:whitespace-normal" scope="row">
                {{ candidate.macroName }}
              </th>
              <td>
                <span class="dui-badge dui-badge-sm">{{ matchLabel(candidate) }}</span>
              </td>
              <td class="tw:whitespace-nowrap">{{ hotbarLabel(candidate.hotbarSlots) }}</td>
              <td class="tw:max-w-72 tw:whitespace-normal">
                <div class="tw:flex tw:flex-wrap tw:items-center tw:gap-2">
                  <span class="dui-badge dui-badge-sm">{{ dispositionLabel(candidate) }}</span>
                  <span v-if="candidate.replacement.macroName" class="tw:font-semibold">
                    {{ candidate.replacement.macroName }}
                  </span>
                </div>
                <p class="tw:mt-1 tw:mb-0 tw:text-xs tw:text-base-content/65!">
                  {{ candidate.replacement.label }}
                </p>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      <div class="dui-alert tw:py-2 tw:text-xs" role="note">
        <i class="fa-solid fa-shield-halved" aria-hidden="true" />
        <span>
          Remapping imports the Drowsy launcher if needed and updates only the selected hotbar
          slots. Source macros are never edited or deleted.
        </span>
      </div>

      <div
        v-for="warning in preview.warnings"
        :key="warning"
        class="dui-alert dui-alert-warning tw:py-2 tw:text-xs"
        role="alert"
      >
        <i class="fa-solid fa-triangle-exclamation" aria-hidden="true" />
        <span>{{ warning }}</span>
      </div>
    </div>
  </section>
</template>
