import { buildLightPreset } from "../../functions/token-tools/presets";
import { buildTokenSight } from "../../functions/token-tools/vision";
import type { TokenToolsRequest } from "../../types/token-tools/TokenTools";
import { getVisionSettings } from "./settings/load";
import { assertCurrentUserCanAccessApplication, TOOLKIT_APPLICATION_ACCESS } from "../apps/access";

interface TokenRuntime {
  actor?:
    | (FoundryActorDocument & { system: { characteristics?: { wp?: { bonus?: number } } } })
    | null;
  document: { update: (data: Record<string, unknown>) => Promise<unknown> };
}

interface TraitRuntime {
  system?: { advances?: { value?: number } };
}

export async function applyTokenTools(request: TokenToolsRequest): Promise<void> {
  assertCurrentUserCanAccessApplication(TOOLKIT_APPLICATION_ACCESS.tokenToolsConsole);
  const tokens =
    (canvas as unknown as { tokens?: { controlled?: TokenRuntime[] } })?.tokens?.controlled ?? [];
  if (tokens.length === 0) throw new Error("Select at least one token.");
  let updated = 0;
  const failures: Array<{ error: unknown; name: string }> = [];
  for (const token of tokens) {
    try {
      const wp = Number(token.actor?.system.characteristics?.wp?.bonus ?? 0);
      const light = buildLightPreset(request.light, wp);
      await token.document.update({
        light,
        sight: buildTokenSight(request.vision, getVisionSettings(), {
          hasDarkVision: hasActorItem(token.actor, "NAME.DarkVision", "trait"),
          lightRange: light.dim,
          nightVisionAdvances: getNightVisionAdvances(token.actor),
          sceneDarkness: Number(canvas.scene?.darkness ?? 0),
          sceneHasGlobalLight: canvas.scene?.globalLight === true,
        }),
      });
      updated += 1;
    } catch (error) {
      failures.push({ error, name: token.actor?.name ?? "Unknown token" });
    }
  }
  if (failures.length > 0) {
    console.error("Drowsy’s WFRP4e Toolkit | Token updates failed.", failures);
    const failureSummary = failures
      .map(
        ({ error, name }) => `${name}: ${error instanceof Error ? error.message : String(error)}`,
      )
      .join("; ");
    throw new Error(
      `Updated ${updated} token${updated === 1 ? "" : "s"}; failed: ${failureSummary}.`,
      { cause: failures.map(({ error }) => error) },
    );
  }
  ui.notifications.info(`Updated ${updated} token${updated === 1 ? "" : "s"}.`);
}

function hasActorItem(
  actor: TokenRuntime["actor"],
  localizationKey: string,
  type: string,
): boolean {
  return Boolean(actor?.has(game.i18n.localize(localizationKey), type));
}

function getNightVisionAdvances(actor: TokenRuntime["actor"]): number {
  const name = game.i18n.localize("NAME.NightVision");
  const item = (actor?.has(name, "trait") || actor?.has(name, "talent")) as
    | TraitRuntime
    | false
    | undefined;
  return item ? Math.max(1, Number(item.system?.advances?.value ?? 1)) : 0;
}
