<script setup lang="ts">
import { storeToRefs } from "pinia";

import { useAdministrationConsoleStore } from "../../../state/apps/administration-console/store";
import type {
  AdministrationActions,
  AdministrationInitialization,
} from "../../../types/administration/Administration";
import ConsoleFrame from "../shared/ConsoleFrame.vue";

const props = defineProps<{
  actions: AdministrationActions;
  initialization: AdministrationInitialization;
}>();
const store = useAdministrationConsoleStore();
store.initialize(props.initialization, props.actions);
const {
  errorMessage,
  isWorking,
  packs,
  scene,
  selectedPackIds,
  showUnassignedPlayerWarning,
  spectators,
  statusMessage,
  visibility,
} = storeToRefs(store);
</script>

<template>
  <ConsoleFrame
    description="Manage Scene lighting, compendium visibility, player assignments, and utility rolls."
    :error-message="errorMessage"
    icon="fa-solid fa-screwdriver-wrench"
    :status-message="statusMessage"
    title="Administration Console"
  >
    <div class="tw:grid tw:min-w-0 tw:gap-3">
      <section
        class="dui-card dui-card-border tw:border-2 tw:border-base-content/20! tw:bg-base-100!"
      >
        <div class="dui-card-body tw:gap-3 tw:p-4">
          <h2 class="dui-card-title tw:font-serif tw:text-lg">Viewed Scene</h2>
          <template v-if="scene">
            <p class="tw:m-0 tw:text-sm">{{ scene.name }}</p>
            <div class="tw:flex tw:flex-wrap tw:gap-2">
              <span class="dui-badge">Token Vision: {{ scene.tokenVision ? "on" : "off" }}</span>
              <span class="dui-badge">Global light: {{ scene.globalLight ? "on" : "off" }}</span>
            </div>
            <div class="tw:flex tw:flex-wrap tw:justify-end tw:gap-2">
              <button
                class="dui-btn dui-btn-sm"
                :disabled="isWorking"
                type="button"
                @click="store.applySceneMode('token-vision')"
              >
                Use Token Vision
              </button>
              <button
                class="dui-btn dui-btn-sm"
                :disabled="isWorking"
                type="button"
                @click="store.applySceneMode('global-light')"
              >
                Use global light
              </button>
            </div>
          </template>
          <div v-else class="dui-alert" role="status">View a Scene to manage its lighting.</div>
        </div>
      </section>

      <section
        class="dui-card dui-card-border tw:min-w-0 tw:border-2 tw:border-base-content/20! tw:bg-base-100!"
      >
        <div class="dui-card-body tw:min-w-0 tw:gap-3 tw:p-4">
          <div class="tw:flex tw:flex-wrap tw:items-center tw:justify-between tw:gap-2">
            <h2 class="dui-card-title tw:font-serif tw:text-lg">Compendium visibility</h2>
            <div class="tw:flex tw:gap-2">
              <button class="dui-btn dui-btn-xs" type="button" @click="store.setAllPacks(true)">
                Select all
              </button>
              <button class="dui-btn dui-btn-xs" type="button" @click="store.setAllPacks(false)">
                Clear
              </button>
            </div>
          </div>
          <div
            class="tw:max-h-56 tw:overflow-auto tw:rounded-box tw:border tw:border-base-content/15!"
          >
            <label
              v-for="pack in packs"
              :key="pack.id"
              class="tw:flex tw:items-start tw:gap-2 tw:border-b tw:border-base-content/10! tw:p-2 last:tw:border-0"
            >
              <input v-model="pack.selected" class="dui-checkbox dui-checkbox-sm" type="checkbox" />
              <span class="tw:min-w-0 tw:flex-1">
                <span class="tw:block tw:text-sm tw:font-semibold">{{ pack.label }}</span>
                <span class="tw:block tw:text-xs tw:text-base-content/60!"
                  >{{ pack.packageName }} · {{ pack.type }} · {{ pack.visibility }}</span
                >
              </span>
            </label>
          </div>
          <div class="tw:flex tw:flex-wrap tw:items-center tw:justify-end tw:gap-2">
            <select
              v-model="visibility"
              class="dui-select dui-select-sm tw:border-base-content/25! tw:bg-base-100!"
            >
              <option value="observer">Visible to players</option>
              <option value="limited">Hidden from players</option>
            </select>
            <button
              class="dui-btn dui-btn-primary dui-btn-sm"
              :disabled="isWorking || !selectedPackIds.length"
              type="button"
              @click="store.applyVisibility"
            >
              Apply to {{ selectedPackIds.length }} pack{{
                selectedPackIds.length === 1 ? "" : "s"
              }}
            </button>
          </div>
        </div>
      </section>

      <section class="tw:grid tw:gap-3 tw:min-[38rem]:grid-cols-2">
        <div
          class="dui-card dui-card-border tw:border-2 tw:border-base-content/20! tw:bg-base-100!"
        >
          <div class="dui-card-body tw:gap-2 tw:p-4">
            <h2 class="dui-card-title tw:font-serif tw:text-lg">Player assignments</h2>
            <div v-if="spectators.length" class="dui-alert dui-alert-warning" role="status">
              <span
                >{{ spectators.join(", ") }} {{ spectators.length === 1 ? "has" : "have" }} no
                assigned character.</span
              >
            </div>
            <p v-else class="tw:m-0 tw:text-sm">Every player has an assigned character.</p>
            <label class="tw:flex tw:items-center tw:gap-2">
              <input
                v-model="showUnassignedPlayerWarning"
                class="dui-toggle dui-toggle-sm"
                type="checkbox"
              />
              Warn the GM at startup
            </label>
            <button
              class="dui-btn dui-btn-secondary dui-btn-sm tw:w-fit"
              type="button"
              @click="store.savePlayerWarning"
            >
              Save preference
            </button>
          </div>
        </div>
        <div
          class="dui-card dui-card-border tw:border-2 tw:border-base-content/20! tw:bg-base-100!"
        >
          <div class="dui-card-body tw:gap-2 tw:p-4">
            <h2 class="dui-card-title tw:font-serif tw:text-lg">Utility roll</h2>
            <button
              class="dui-btn dui-btn-primary"
              :disabled="isWorking"
              type="button"
              @click="store.rollD100"
            >
              <i class="fa-solid fa-dice-d20" aria-hidden="true" /> Roll d100
            </button>
          </div>
        </div>
      </section>
    </div>
  </ConsoleFrame>
</template>
