import type { ToolkitApplicationHandle } from "../../../types/module/api/ModuleApi";
import type { ToolkitHomeSection } from "../../../types/toolkit-home/Console";
import { setSceneLighting } from "../../administration/service";
import { changeGridScalePreservingLighting } from "../../grid-scale/service";
import { pullEveryoneToViewedScene } from "../../session-management/service";
import { openTokenToolsConsole } from "../token-tools-console/open";
import { SceneManagementConsoleApplication } from "./SceneManagementConsoleApplication";

export async function openSceneManagementConsole(): Promise<ToolkitApplicationHandle> {
  const sections: ToolkitHomeSection[] = [
    {
      id: "scene",
      label: "Viewed Scene",
      actions: [
        action(
          "grid-scale",
          "Change Grid Scale (Preserve Lighting)",
          "Change grid measurements while preserving rendered light sizes.",
          "fa-solid fa-grid-2",
          changeGridScalePreservingLighting,
        ),
        action(
          "pull-everyone",
          "Pull Everyone to Scene",
          "Activate this Scene or pull connected players using your saved policy.",
          "fa-solid fa-people-pulling",
          pullEveryoneToViewedScene,
        ),
        action(
          "token-vision",
          "Use Token Vision",
          "Enable Token Vision and disable global illumination for this Scene.",
          "fa-solid fa-eye",
          () => setSceneLighting("token-vision"),
        ),
        action(
          "global-light",
          "Use Global Light",
          "Enable global illumination and disable Token Vision for this Scene.",
          "fa-solid fa-sun",
          () => setSceneLighting("global-light"),
        ),
      ],
    },
    {
      id: "tokens",
      label: "Controlled Tokens",
      actions: [
        action(
          "token-tools",
          "Open Token Vision & Light",
          "Apply vision modes and light presets to controlled tokens.",
          "fa-solid fa-lightbulb",
          async () => {
            await openTokenToolsConsole();
          },
        ),
      ],
    },
  ];
  const application = new SceneManagementConsoleApplication(sections);
  await application.render(true);
  return application;
}

function action(
  id: string,
  label: string,
  description: string,
  icon: string,
  open: () => Promise<void>,
) {
  return { description, icon, id, label, open };
}
