<script setup lang="ts">
import { computed } from "vue";

import type {
  GmToolkitImportField,
  GmToolkitMigrationPreview,
} from "../../../types/gm-toolkit/Migration";

const props = defineProps<{
  isWorking: boolean;
  lastImportedAt?: string;
  preview: GmToolkitMigrationPreview;
  selections: Record<GmToolkitImportField, boolean>;
}>();

const emit = defineEmits<{
  import: [];
  selectionChange: [field: GmToolkitImportField, selected: boolean];
}>();

const selectedCount = computed(
  () => Object.values(props.selections).filter((selected) => selected).length,
);
const sourceState = computed(() => {
  if (props.preview.source?.active) return "Active module";
  if (props.preview.source?.installed) return "Installed, disabled";
  return "Persisted world data";
});

function displayValue(value: boolean | number | string): string {
  if (value === "") return "None";
  return String(value);
}

function comparisonLabel(comparison: string): string {
  if (comparison === "same") return "Already matches";
  if (comparison === "target-empty") return "New value";
  return "Different";
}

function updateSelection(field: GmToolkitImportField, event: Event): void {
  const input = event.currentTarget;
  emit("selectionChange", field, input instanceof HTMLInputElement && input.checked);
}
</script>

<template>
  <section
    class="dui-card dui-card-border tw:min-w-0 tw:border-2 tw:border-secondary/40! tw:bg-base-100! tw:shadow-md"
    aria-labelledby="gm-toolkit-import-title"
  >
    <div class="dui-card-body tw:min-w-0 tw:gap-3 tw:p-4">
      <div class="tw:flex tw:flex-wrap tw:items-start tw:justify-between tw:gap-3">
        <div class="tw:min-w-0 tw:flex-1">
          <div class="tw:flex tw:flex-wrap tw:items-center tw:gap-2">
            <h2 id="gm-toolkit-import-title" class="dui-card-title tw:font-serif tw:text-lg">
              Settings
            </h2>
            <span class="dui-badge dui-badge-outline dui-badge-sm">{{ sourceState }}</span>
            <span v-if="preview.source?.moduleVersion" class="dui-badge dui-badge-sm">
              {{ preview.source.moduleVersion }}
            </span>
          </div>
          <p class="tw:m-0 tw:text-sm tw:text-base-content/70!">
            Choose which saved values to copy. Your GM Toolkit settings will not be changed.
          </p>
          <p v-if="lastImportedAt" class="tw:mt-1 tw:mb-0 tw:text-xs tw:text-base-content/60!">
            Last imported {{ new Date(lastImportedAt).toLocaleString() }}
          </p>
        </div>
        <button
          class="dui-btn dui-btn-sm tw:border-secondary! tw:text-base-content!"
          :disabled="isWorking || selectedCount === 0"
          type="button"
          @click="emit('import')"
        >
          <span
            v-if="isWorking"
            class="dui-loading dui-loading-spinner dui-loading-sm"
            aria-hidden="true"
          />
          <i v-else class="fa-solid fa-file-import" aria-hidden="true" />
          Import {{ selectedCount || "selected" }}
        </button>
      </div>

      <div class="tw:flex tw:flex-wrap tw:gap-2 tw:text-xs" aria-label="Migration inventory">
        <span class="dui-badge dui-badge-sm">
          {{ preview.dispositionCounts.import }} can be imported
        </span>
        <span
          v-if="preview.dispositionCounts.pending"
          class="dui-badge dui-badge-ghost dui-badge-sm"
        >
          {{ preview.dispositionCounts.pending }} not transferred
        </span>
        <span class="dui-badge dui-badge-sm">
          {{ preview.dispositionCounts.supersede }} handled another way
        </span>
        <span class="dui-badge dui-badge-sm">
          {{ preview.dispositionCounts.retire }} not needed
        </span>
        <span class="dui-badge dui-badge-sm"> {{ preview.dispositionCounts.skip }} ignored </span>
      </div>

      <div v-if="!preview.source?.active" class="dui-alert tw:py-2 tw:text-xs" role="note">
        <i class="fa-solid fa-database" aria-hidden="true" />
        <span> Saved world data is available even while GM Toolkit is disabled. </span>
      </div>

      <div
        class="tw:max-w-full tw:overflow-x-auto tw:rounded-box tw:border tw:border-base-content/20!"
      >
        <table class="dui-table dui-table-sm tw:min-w-[38rem]">
          <thead class="tw:bg-base-300/60!">
            <tr>
              <th scope="col">Import</th>
              <th scope="col">Value</th>
              <th scope="col">GM Toolkit</th>
              <th scope="col">Drowsy</th>
              <th scope="col">Comparison</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="item in preview.imports" :key="item.field">
              <td>
                <label class="tw:flex tw:cursor-pointer tw:items-center tw:gap-2">
                  <input
                    class="dui-checkbox dui-checkbox-sm"
                    :checked="selections[item.field]"
                    type="checkbox"
                    @change="updateSelection(item.field, $event)"
                  />
                  <span class="tw:sr-only">Import {{ item.label }}</span>
                </label>
              </td>
              <th scope="row">{{ item.label }}</th>
              <td class="tw:max-w-48 tw:truncate" :title="displayValue(item.sourceValue)">
                {{ displayValue(item.sourceValue) }}
              </td>
              <td class="tw:max-w-48 tw:truncate" :title="displayValue(item.currentValue)">
                {{ displayValue(item.currentValue) }}
              </td>
              <td>
                <span class="dui-badge dui-badge-sm">
                  {{ comparisonLabel(item.comparison) }}
                </span>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      <div
        v-for="warning in preview.source?.warnings ?? []"
        :key="warning"
        class="dui-alert dui-alert-warning tw:py-2 tw:text-xs"
        role="alert"
      >
        <i class="fa-solid fa-triangle-exclamation" aria-hidden="true" />
        <span>{{ warning }}</span>
      </div>
    </div>
  </section>
</template>
