import type {
  SessionForm,
  SessionManagementConsoleInitialization,
} from "../../types/session-management/Console";
import type {
  SessionConfiguration,
  SessionConfigurationInitialization,
} from "../../types/session-management/Configuration";
import type {
  SessionManagementState,
  SessionTurnoverRequest,
  SessionTurnoverResult,
} from "../../types/session-management/SessionManagement";
import { nextSessionNumber } from "./submission";

export function initializeSessionForm(data: SessionManagementConsoleInitialization): {
  form: SessionForm;
  initialization: SessionManagementConsoleInitialization;
} {
  const initialization = structuredClone(data);
  const request = data.state.turnover?.steps.some(
    (step) => step.status === "failed" || step.status === "pending",
  )
    ? data.state.turnover.request
    : undefined;
  if (request?.xp) initialization.settings.xp = { ...request.xp };
  return {
    initialization,
    form: {
      currentSessionReference:
        request?.sessionReference ?? (data.state.currentSessionReference || "1"),
      occurredAtLocal: request?.occurredAt ?? data.occurredAtLocal,
      amount: request?.xp?.defaultAmount ?? data.settings.xp.defaultAmount,
      actors: data.actors.map((actor) => ({
        ...actor,
        selected: request?.xp ? request.xp.actorIds.includes(actor.id) : actor.selected,
      })),
    },
  };
}

export function buildSessionTurnoverRequest(
  form: SessionForm,
  settings: SessionConfiguration,
): SessionTurnoverRequest {
  return {
    chatExport: settings.exportChat,
    fortuneReset: settings.fortuneReset,
    holdingScene: settings.holdingScene,
    pause: settings.pause,
    xpAward: form.amount > 0,
    sessionReference: form.currentSessionReference,
    nextSessionReference: nextSessionNumber(form.currentSessionReference),
    occurredAt: form.occurredAtLocal,
    xp: {
      ...settings.xp,
      defaultAmount: form.amount,
      actorIds: form.actors.filter((actor) => actor.selected).map((actor) => actor.id),
    },
  };
}

export function applySessionTurnoverResult(
  state: SessionManagementState,
  result: SessionTurnoverResult,
  requestedNext: string,
): SessionManagementState {
  return {
    ...state,
    turnover: result.operation,
    ...(result.record
      ? {
          sessions: [result.record, ...state.sessions].slice(0, 500),
          currentSessionReference: result.operation.request?.nextSessionReference ?? requestedNext,
        }
      : {}),
  };
}

export function applySessionSettingsUpdate(
  form: SessionForm,
  currentReference: string,
  settings: SessionConfiguration,
  saved: SessionConfigurationInitialization,
): { form: SessionForm; reloadActors: boolean } {
  return {
    form: {
      ...form,
      amount:
        form.amount === settings.xp.defaultAmount ? saved.settings.xp.defaultAmount : form.amount,
      currentSessionReference:
        saved.currentSessionReference !== currentReference
          ? saved.currentSessionReference
          : form.currentSessionReference,
    },
    reloadActors: saved.settings.xp.defaultSelection !== settings.xp.defaultSelection,
  };
}
