import { parseSessionSubmission } from "./submission";
import type {
  CompleteSessionRequest,
  SessionManagementState,
  SessionRecord,
  SessionTurnoverOperation,
  SessionTurnoverStepId,
  SessionTurnoverStepStatus,
} from "../../types/session-management/SessionManagement";
import { EMPTY_SESSION_MANAGEMENT_STATE } from "../../types/session-management/SessionManagement";
import { isRecord, normalizeIsoDateTime, readString } from "../records/parse";
import { parseGmToolkitCutoverReview } from "../gm-toolkit/cutover";
import { parseGmToolkitMigrationSnapshot } from "../gm-toolkit/state";

const MAX_SESSION_RECORDS = 500;

export function suggestNextSessionReference(reference: string): string {
  const normalizedReference = reference.trim();

  if (!normalizedReference) {
    return "";
  }

  const numericReference = Number(normalizedReference);

  if (Number.isFinite(numericReference) && Math.trunc(numericReference) === numericReference) {
    return String(numericReference + 1);
  }

  return normalizedReference;
}

export function completeSessionState(
  state: SessionManagementState,
  request: CompleteSessionRequest,
  metadata: { id: string; recordedAt: string },
): { record: SessionRecord; state: SessionManagementState } {
  const sessionReference = request.sessionReference.trim();
  const nextSessionReference = request.nextSessionReference.trim();
  const occurredAt = requireIsoDateTime(request.occurredAt, "session occurrence");
  const recordedAt = requireIsoDateTime(metadata.recordedAt, "session record");

  if (!sessionReference) {
    throw new Error("Enter the session reference that is being completed.");
  }

  if (!nextSessionReference) {
    throw new Error("Enter the next session reference.");
  }

  const record: SessionRecord = {
    id: metadata.id,
    occurredAt,
    recordedAt,
    reference: sessionReference,
  };

  return {
    record,
    state: {
      ...state,
      currentSessionReference: nextSessionReference,
      sessions: [record, ...state.sessions].slice(0, MAX_SESSION_RECORDS),
    },
  };
}

export function parseSessionManagementState(value: unknown): SessionManagementState {
  const parsed = parseJsonRecord(value);

  if (!parsed || parsed["version"] !== 1) {
    return { ...EMPTY_SESSION_MANAGEMENT_STATE, sessions: [] };
  }

  const sessions = Array.isArray(parsed["sessions"])
    ? parsed["sessions"].flatMap(parseSessionRecord).slice(0, MAX_SESSION_RECORDS)
    : [];
  const migration = parseGmToolkitMigrationSnapshot(parsed["gmToolkitMigration"]);
  const cutoverReview = parseGmToolkitCutoverReview(parsed["gmToolkitCutoverReview"]);
  const turnover = parseSessionTurnoverOperation(parsed["turnover"]);

  return {
    currentSessionReference: readString(parsed["currentSessionReference"]),
    ...(cutoverReview ? { gmToolkitCutoverReview: cutoverReview } : {}),
    ...(migration ? { gmToolkitMigration: migration } : {}),
    sessions,
    ...(turnover ? { turnover } : {}),
    version: 1,
  };
}

export function createSessionTurnoverOperation(
  id: string,
  sessionReference: string,
  startedAt: string,
  enabledSteps: ReadonlySet<SessionTurnoverStepId>,
): SessionTurnoverOperation {
  const normalizedReference = sessionReference.trim();
  const normalizedStartedAt = requireIsoDateTime(startedAt, "turnover start");

  if (!id || !normalizedReference)
    throw new Error("A turnover ID and session reference are required.");

  return {
    id,
    sessionReference: normalizedReference,
    startedAt: normalizedStartedAt,
    steps: SESSION_TURNOVER_STEPS.map((stepId) => ({
      id: stepId,
      status: enabledSteps.has(stepId) ? "pending" : "skipped",
    })),
  };
}

export function updateSessionTurnoverStep(
  operation: SessionTurnoverOperation,
  stepId: SessionTurnoverStepId,
  status: Exclude<SessionTurnoverStepStatus, "pending">,
  finishedAt: string,
  detail?: string,
): SessionTurnoverOperation {
  const normalizedFinishedAt = requireIsoDateTime(finishedAt, "turnover step");

  return {
    ...operation,
    steps: operation.steps.map((step) =>
      step.id === stepId
        ? { id: step.id, status, finishedAt: normalizedFinishedAt, ...(detail ? { detail } : {}) }
        : { ...step },
    ),
  };
}

export const SESSION_TURNOVER_STEPS: readonly SessionTurnoverStepId[] = [
  "pause",
  "holding-scene",
  "xp",
  "fortune",
  "chat-export",
  "record",
];

function parseSessionRecord(value: unknown): SessionRecord[] {
  if (!isRecord(value)) {
    return [];
  }

  const id = readString(value["id"]);
  const occurredAt = normalizeIsoDateTime(value["occurredAt"]);
  const recordedAt = normalizeIsoDateTime(value["recordedAt"]);
  const reference = readString(value["reference"]);

  return id && occurredAt && recordedAt && reference
    ? [{ id, occurredAt, recordedAt, reference }]
    : [];
}

function parseSessionTurnoverOperation(value: unknown): SessionTurnoverOperation | undefined {
  if (!isRecord(value) || !Array.isArray(value["steps"])) return undefined;
  const id = readString(value["id"]);
  const sessionReference = readString(value["sessionReference"]);
  const startedAt = normalizeIsoDateTime(value["startedAt"]);
  const steps = value["steps"].flatMap((step) => {
    if (!isRecord(step)) return [];
    const stepId = readString(step["id"]);
    const status = readString(step["status"]);
    if (!isSessionTurnoverStepId(stepId) || !isSessionTurnoverStepStatus(status)) return [];
    const finishedAt = normalizeIsoDateTime(step["finishedAt"]);
    const detail = readString(step["detail"]);
    return [
      { id: stepId, status, ...(finishedAt ? { finishedAt } : {}), ...(detail ? { detail } : {}) },
    ];
  });

  const request = parseSessionSubmission(value["request"]);
  return id && sessionReference && startedAt && steps.length === SESSION_TURNOVER_STEPS.length
    ? { id, sessionReference, startedAt, steps, ...(request ? { request } : {}) }
    : undefined;
}

function isSessionTurnoverStepId(value: string): value is SessionTurnoverStepId {
  return SESSION_TURNOVER_STEPS.includes(value as SessionTurnoverStepId);
}

function isSessionTurnoverStepStatus(value: string): value is SessionTurnoverStepStatus {
  return ["completed", "failed", "pending", "skipped"].includes(value);
}

function parseJsonRecord(value: unknown): Record<string, unknown> | undefined {
  if (typeof value !== "string") {
    return undefined;
  }

  try {
    const parsed: unknown = JSON.parse(value);
    return isRecord(parsed) ? parsed : undefined;
  } catch {
    return undefined;
  }
}

function requireIsoDateTime(value: string, label: string): string {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    throw new Error(`Enter a valid ${label} date and time.`);
  }

  return date.toISOString();
}
