<script setup lang="ts">
import GraphCanvas from "./graph/GraphCanvas.vue";
import DiamondHandle from "./graph/DiamondHandle.vue";
import RecipientLegend from "./graph/RecipientLegend.vue";
import RoundHandle from "./graph/RoundHandle.vue";
import { plotLeft, plotTop, plotWidth } from "./graphMath";
import { type CatchUpGraphEmit, type CatchUpGraphProps, useCatchUpGraph } from "./useCatchUpGraph";

const props = defineProps<CatchUpGraphProps>();
const emit = defineEmits<CatchUpGraphEmit>();
const {
  beginDrag,
  endDrag,
  maximumGap,
  points,
  recipientLegend,
  recipientPoints,
  referencePoint,
  shapePoint,
  toGraphX,
  toGraphY,
  updateDrag,
  updateReferenceWithKeyboard,
  updateShapeWithKeyboard,
} = useCatchUpGraph(props, emit);
</script>

<template>
  <figure class="tw:m-0 tw:block tw:min-w-0" aria-labelledby="xp-catch-up-graph-heading">
    <div class="tw:mb-2">
      <h4 id="xp-catch-up-graph-heading" class="tw:m-0 tw:text-sm tw:font-semibold">
        Initial catch-up value by XP gap
      </h4>
      <p class="tw:m-0 tw:text-xs tw:text-base-content/65!">
        Drag the diamond to set the reference gap and hard limit. Drag the round point to shape the
        curve.
      </p>
    </div>

    <GraphCanvas
      description="The horizontal axis is the recipient's gap below the selected XP leader. The vertical axis is the initial catch-up value before recipient decay, companion rate, and the final hard limit. Numbered markers identify selected recipients."
      description-id="xp-catch-up-graph-description"
      :markers="recipientPoints"
      :maximum-x-label="`${Math.round(maximumGap)} XP`"
      minimum-y-label="0"
      :points="points"
      title="Editable catch-up XP curve"
      title-id="xp-catch-up-graph-title"
      :vertical-guide-x="toGraphX(gapForMaximumAward)"
      x-axis-label="Gap below selected XP leader"
      y-axis-label="Initial catch-up XP"
      @pointercancel="endDrag"
      @pointermove="updateDrag"
      @pointerup="endDrag"
    >
      <template #guides>
        <line
          class="tw:text-warning"
          :x1="plotLeft"
          :x2="plotLeft + plotWidth"
          :y1="toGraphY(maximumAward)"
          :y2="toGraphY(maximumAward)"
          stroke="currentColor"
          stroke-dasharray="6 5"
        />
      </template>

      <template #handles>
        <RoundHandle
          aria-label="Catch-up curve shape"
          :aria-value-max="5"
          :aria-value-min="0.1"
          :aria-value-now="curveExponent"
          :aria-value-text="`Exponent ${curveExponent}`"
          :x="shapePoint.x"
          :y="shapePoint.y"
          @keydown="updateShapeWithKeyboard"
          @pointerdown="beginDrag('shape', $event)"
        />
        <DiamondHandle
          :aria-label="`Reference point: ${gapForMaximumAward} XP gap and ${maximumAward} XP hard limit. Use left and right arrows for the gap, up and down arrows for the hard limit.`"
          role="button"
          :x="referencePoint.x"
          :y="referencePoint.y"
          @keydown="updateReferenceWithKeyboard"
          @pointerdown="beginDrag('reference', $event)"
        />
      </template>

      <template #labels>
        <text
          class="tw:text-warning"
          :x="plotLeft + 7"
          :y="Math.max(plotTop + 12, toGraphY(maximumAward) - 7)"
          fill="currentColor"
          font-size="11"
          font-weight="600"
        >
          Hard limit {{ maximumAward }} XP
        </text>
      </template>
    </GraphCanvas>

    <RecipientLegend :items="recipientLegend" />
  </figure>
</template>
