import type { ToolkitHomeSection } from "../../../types/toolkit-home/Console";
import type { ToolkitApplicationHandle } from "../../../types/module/api/ModuleApi";
import { openFearConsole } from "../fear-console/open";
import { openGmToolkitMigration } from "../gm-toolkit-migration/open";
import { openSessionManagementConsole } from "../session-management/open";
import { openXpAwardConsole } from "../xp-award-console/open";
import { openXpCurveConsole } from "../xp-curve-console/open";
import { ToolkitHomeApplication } from "./ToolkitHomeApplication";
import { openAdministrationConsole } from "../administration-console/open";
import { openCombatConsole } from "../combat-console/open";
import { openDamageConsole } from "../damage-console/open";
import { openDarkWhispersConsole } from "../dark-whispers-console/open";
import { openGroupTestConsole } from "../group-test-console/open";
import { openTokenToolsConsole } from "../token-tools-console/open";
import { openSceneManagementConsole } from "../scene-management-console/open";
import { openImperialCalendarCalculator } from "../imperial-calendar/open";

export async function openToolkitHome(): Promise<ToolkitApplicationHandle> {
  const sections: ToolkitHomeSection[] = [
    {
      id: "gameplay",
      label: "Gameplay",
      actions: [
        action(
          "combat",
          "Combat Console",
          "Manage Advantage and condition checks.",
          "fa-solid fa-swords",
          openCombatConsole,
        ),
        action(
          "damage",
          "Damage Console",
          "Apply damage to several actors.",
          "fa-solid fa-bolt",
          openDamageConsole,
        ),
        action(
          "group-test",
          "Secret Group Tests",
          "Run private WFRP4e tests for a group.",
          "fa-solid fa-dice-d100",
          openGroupTestConsole,
        ),
        action(
          "dark-whispers",
          "Dark Whispers",
          "Send temptations to characters with Corruption.",
          "fa-solid fa-comment-dots",
          openDarkWhispersConsole,
        ),
        action(
          "fear",
          "Fear Console",
          "Apply Fear and Terror through WFRP4e.",
          "fa-solid fa-ghost",
          openFearConsole,
        ),
        action(
          "xp-curve",
          "XP Curve Console",
          "Review and award campaign catch-up XP.",
          "fa-solid fa-chart-line",
          openXpCurveConsole,
        ),
        action(
          "xp-award",
          "XP Award Console",
          "Apply a fixed XP change to selected characters.",
          "fa-solid fa-award",
          openXpAwardConsole,
        ),
        action(
          "token-tools",
          "Token Vision & Light",
          "Apply vision modes and light presets.",
          "fa-solid fa-eye",
          openTokenToolsConsole,
        ),
      ],
    },
    {
      id: "campaign",
      label: "Campaign",
      actions: [
        action(
          "imperial-calendar",
          "Imperial Calendar Calculator",
          "Measure elapsed time between Imperial dates and times.",
          "fa-solid fa-calendar-days",
          openImperialCalendarCalculator,
        ),
        action(
          "scene-management",
          "Scene Management",
          "Open common Scene and token-viewing actions.",
          "fa-solid fa-map",
          openSceneManagementConsole,
        ),
        action(
          "session",
          "Session Management",
          "Record session turnover and history.",
          "fa-solid fa-calendar-check",
          openSessionManagementConsole,
        ),
        action(
          "administration",
          "Administration Console",
          "Manage Scenes, compendium visibility, players, and utility rolls.",
          "fa-solid fa-screwdriver-wrench",
          openAdministrationConsole,
        ),
        action(
          "import",
          "Import from GM Toolkit",
          "Copy supported settings, prompts, and launchers.",
          "fa-solid fa-file-import",
          openGmToolkitMigration,
        ),
      ],
    },
  ];
  const application = new ToolkitHomeApplication(sections);
  await application.render(true);
  return application;
}

function action(
  id: string,
  label: string,
  description: string,
  icon: string,
  openApplication: () => Promise<ToolkitApplicationHandle>,
) {
  return {
    description,
    icon,
    id,
    label,
    open: async () => {
      await openApplication();
    },
  };
}
