import type { ActorChoice } from "../../types/fear-terror/Psychology";

interface SelectedActor {
  actor: FoundryActorDocument;
  choice: ActorChoice;
}

export function getTargetedActorChoices(): ActorChoice[] {
  return getTargetedActors().map(({ choice }) => choice);
}

export function getTargetedActorDocuments(): FoundryActorDocument[] {
  return getTargetedActors().map(({ actor }) => actor);
}

function getTargetedActors(): SelectedActor[] {
  const actors = new Map<string, SelectedActor>();

  for (const token of game.user?.targets ?? []) {
    addActor(actors, token.actor);
  }

  return Array.from(actors.values());
}

function addActor(
  actors: Map<string, SelectedActor>,
  actor: FoundryActorDocument | null | undefined,
): void {
  if (!actor || actors.has(actor.id)) {
    return;
  }

  actors.set(actor.id, {
    actor,
    choice: {
      id: actor.id,
      name: actor.name,
      source: "targeted",
    },
  });
}
