import { defineStore } from "pinia";
import { computed, ref } from "vue";
import type {
  AdvantageSettings,
  CombatConsoleActions,
  CombatConsoleInitialization,
} from "../../../types/combat/Combat";

export const useCombatConsoleStore = defineStore("combat-console", () => {
  const actors = ref<CombatConsoleInitialization["actors"]>([]);
  const settings = ref<AdvantageSettings>();
  const amount = ref(1);
  const endOfRoundOnly = ref(true);
  const skipPlayerCharacters = ref(true);
  const busy = ref(false);
  const errorMessage = ref("");
  let actions: CombatConsoleActions | undefined;

  const selectedUuids = computed(() =>
    actors.value.filter((actor) => actor.selected).map((actor) => actor.uuid),
  );

  function initialize(
    initialization: CombatConsoleInitialization,
    nextActions: CombatConsoleActions,
  ): void {
    actors.value = structuredClone(initialization.actors);
    settings.value = structuredClone(initialization.settings);
    actions = nextActions;
  }

  async function adjust(mode: "add" | "clear" | "reduce"): Promise<void> {
    await run(() =>
      getActions().adjustAdvantage({ amount: amount.value, mode, uuids: selectedUuids.value }),
    );
  }

  async function check(): Promise<void> {
    await run(() =>
      getActions().checkConditions({
        endOfRoundOnly: endOfRoundOnly.value,
        skipPlayerCharacters: skipPlayerCharacters.value,
        uuids: selectedUuids.value,
      }),
    );
  }

  async function save(): Promise<void> {
    await run(() => getActions().saveSettings(getSettings()));
  }

  async function run(operation: () => Promise<void>): Promise<void> {
    busy.value = true;
    errorMessage.value = "";
    try {
      await operation();
    } catch (error) {
      errorMessage.value =
        error instanceof Error ? error.message : "The action could not be completed.";
    } finally {
      busy.value = false;
    }
  }

  function getActions(): CombatConsoleActions {
    if (!actions) throw new Error("The Combat Console has not been initialized.");
    return actions;
  }

  function getSettings(): AdvantageSettings {
    if (!settings.value) throw new Error("The Combat Console has not been initialized.");
    return settings.value;
  }

  return {
    actors,
    amount,
    busy,
    check,
    adjust,
    endOfRoundOnly,
    errorMessage,
    initialize,
    save,
    settings,
    skipPlayerCharacters,
  };
});
