import { MODULE_ID } from "../../constants";

export const FEAR_TERROR_LAUNCHER_SETTINGS = {
  actorSheet: "showActorSheetLauncher",
  tokenControls: "showTokenControlsLauncher",
} as const;

type FearTerrorLauncherSetting =
  (typeof FEAR_TERROR_LAUNCHER_SETTINGS)[keyof typeof FEAR_TERROR_LAUNCHER_SETTINGS];

export function isFearTerrorLauncherEnabled(setting: FearTerrorLauncherSetting): boolean {
  return game.settings.get(MODULE_ID, setting) === true;
}
