import type { AdvantageSettings } from "../../../types/combat/Combat";
import { MODULE_ID } from "../../constants";
import { ADVANTAGE_SETTINGS } from "./keys";

export function getAdvantageSettings(): AdvantageSettings {
  return {
    automateCondition: read(ADVANTAGE_SETTINGS.automateCondition),
    automateDamage: read(ADVANTAGE_SETTINGS.automateDamage),
    automateOpposed: read(ADVANTAGE_SETTINGS.automateOpposed),
    clearOnJoin: read(ADVANTAGE_SETTINGS.clearOnJoin),
    clearOnLeave: read(ADVANTAGE_SETTINGS.clearOnLeave),
    promptMomentumLoss: read(ADVANTAGE_SETTINGS.promptMomentumLoss),
    persistentNotifications: read(ADVANTAGE_SETTINGS.persistentNotifications),
  };
}

export async function saveAdvantageSettings(settings: AdvantageSettings): Promise<void> {
  for (const [key, value] of Object.entries(settings)) {
    await game.settings.set(MODULE_ID, ADVANTAGE_SETTINGS[key as keyof AdvantageSettings], value);
  }
}

function read(key: string): boolean {
  return game.settings.get(MODULE_ID, key) === true;
}
