import type {
  GmToolkitCutoverReport,
  GmToolkitCutoverSettingStatus,
} from "../../types/gm-toolkit/Cutover";

export function settingStatusLabel(status: GmToolkitCutoverSettingStatus): string {
  return {
    "already-matched": "Already matched",
    "changed-after-import": "Changed after import",
    "imported": "Imported",
    "not-imported": "Not imported",
  }[status];
}
export function launcherMatchLabel(
  match: GmToolkitCutoverReport["launchers"]["unresolved"][number]["match"],
): string {
  if (match === "standard") return "Stock macro";
  if (match === "customized") return "Customized";
  return "Check manually";
}
export function sourceEvidenceLabel(report: GmToolkitCutoverReport): string {
  if (report.source.evidence === "current")
    return report.source.active ? "Active module" : "Current world data";
  return report.source.evidence === "saved-snapshot" ? "Saved import snapshot" : "World documents";
}
