import type { Component } from "vue";

import type { SessionManagementConsoleActions } from "../../../types/session-management/Console";
import SessionManagementConsoleApp from "../../../view/apps/session-management/SessionManagementConsoleApp.vue";
import { MODULE_ID, MODULE_TITLE } from "../../constants";
import { getSessionManagementConsoleInitialization } from "../../session-management/initialization";
import { runSessionTurnover } from "../../session-management/service";
import { openSessionSettings } from "./SessionSettingsApplication";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { TOOLKIT_APPLICATION_ACCESS } from "../access";

export class SessionManagementApplication extends FoundryVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.sessionManagementConsole;

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    classes: [MODULE_ID, `${MODULE_ID}-session-management`],
    id: `${MODULE_ID}-session-management`,
    position: {
      height: 590,
      width: 700,
    },
    window: {
      icon: "fa-solid fa-calendar-check",
      resizable: true,
      title: `${MODULE_TITLE} — Session Turnover Console`,
    },
  };

  protected override getVueComponent(): Component {
    return SessionManagementConsoleApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    const actions: SessionManagementConsoleActions = {
      openSettings: openSessionSettings,
      reload: getSessionManagementConsoleInitialization,
      runSessionTurnover,
    };

    return {
      actions,
      initialization: getSessionManagementConsoleInitialization(),
    };
  }
}
