import { XpCurveConfiguratorApplication } from "../../apps/xp-curve-configurator/XpCurveConfiguratorApplication";
import { LOCALIZATION_NAMESPACE, MODULE_ID } from "../../constants";
import {
  registerBooleanLauncherSetting,
  registerHiddenWorldSetting,
} from "../../settings/register";
import { DEFAULT_XP_CURVE_SETTINGS } from "../../../types/xp-curve/XpCurve";
import { XP_CURVE_SETTINGS } from "./keys";

export function registerXpCurveSettings(): void {
  registerBooleanLauncherSetting(
    XP_CURVE_SETTINGS.showTokenControlsLauncher,
    "XpCurveTokenControlsLauncher",
  );

  registerWorldSetting(
    XP_CURVE_SETTINGS.maximumAward,
    DEFAULT_XP_CURVE_SETTINGS.parameters.maximumAward,
    Number,
    "MaximumAward",
    {
      range: { max: 100_000, min: 0, step: 1 },
    },
  );
  registerWorldSetting(
    XP_CURVE_SETTINGS.gapForMaximumAward,
    DEFAULT_XP_CURVE_SETTINGS.parameters.gapForMaximumAward,
    Number,
    "GapForMaximumAward",
    { range: { max: 1_000_000, min: 1, step: 100 } },
  );
  registerWorldSetting(
    XP_CURVE_SETTINGS.curveExponent,
    DEFAULT_XP_CURVE_SETTINGS.parameters.curveExponent,
    Number,
    "CurveExponent",
    { range: { max: 5, min: 0.1, step: 0.05 } },
  );
  registerWorldSetting(
    XP_CURVE_SETTINGS.scalePivot,
    DEFAULT_XP_CURVE_SETTINGS.parameters.scalePivot,
    Number,
    "ScalePivot",
    { range: { max: 1_000_000, min: 1, step: 100 } },
  );
  registerWorldSetting(
    XP_CURVE_SETTINGS.scaleExponent,
    DEFAULT_XP_CURVE_SETTINGS.parameters.scaleExponent,
    Number,
    "ScaleExponent",
    { range: { max: 2, min: 0, step: 0.05 } },
  );
  registerWorldSetting(
    XP_CURVE_SETTINGS.companionMultiplier,
    DEFAULT_XP_CURVE_SETTINGS.parameters.companionMultiplier,
    Number,
    "CompanionMultiplier",
    { range: { max: 1, min: 0, step: 0.05 } },
  );
  registerWorldSetting(
    XP_CURVE_SETTINGS.defaultReason,
    DEFAULT_XP_CURVE_SETTINGS.defaultReason,
    String,
    "DefaultReason",
  );
  registerWorldSetting(
    XP_CURVE_SETTINGS.defaultSelection,
    DEFAULT_XP_CURVE_SETTINGS.defaultSelection,
    String,
    "DefaultSelection",
    {
      choices: {
        company: `${LOCALIZATION_NAMESPACE}.Settings.XpCurve.DefaultSelection.Company`,
        party: `${LOCALIZATION_NAMESPACE}.Settings.XpCurve.DefaultSelection.Party`,
        world: `${LOCALIZATION_NAMESPACE}.Settings.XpCurve.DefaultSelection.World`,
      },
    },
  );

  game.settings.registerMenu(MODULE_ID, "xpCurveConsole", {
    hint: `${LOCALIZATION_NAMESPACE}.Menu.XpCurveConfigurator.Hint`,
    icon: "fa-solid fa-sliders",
    label: `${LOCALIZATION_NAMESPACE}.Menu.XpCurveConfigurator.Label`,
    name: `${LOCALIZATION_NAMESPACE}.Menu.XpCurveConfigurator.Name`,
    restricted: XpCurveConfiguratorApplication.ACCESS_POLICY.gmOnly,
    type: XpCurveConfiguratorApplication,
  });
}

function registerWorldSetting(
  key: string,
  defaultValue: boolean | number | string,
  type: BooleanConstructor | NumberConstructor | StringConstructor,
  localizationKey: string,
  options: Pick<FoundrySettingConfig, "choices" | "range"> = {},
): void {
  registerHiddenWorldSetting(
    key,
    defaultValue,
    type,
    `${LOCALIZATION_NAMESPACE}.Settings.XpCurve.${localizationKey}`,
    options,
  );
}
