import type { CombatConsoleInitialization } from "../../types/combat/Combat";
import { getActorChoices } from "../actors/selection";
import { getAdvantageSettings } from "./settings/load";

export function getCombatConsoleInitialization(): CombatConsoleInitialization {
  return {
    actors: getActorChoices({ includeVehicles: true, initial: "controlled" }),
    settings: getAdvantageSettings(),
  };
}
