import type { Component } from "vue";

import type { GmToolkitMigrationConsoleActions } from "../../../types/gm-toolkit/Console";
import GmToolkitMigrationApp from "../../../view/apps/gm-toolkit-migration/GmToolkitMigrationApp.vue";
import { MODULE_ID, MODULE_TITLE } from "../../constants";
import { getGmToolkitMigrationConsoleInitialization } from "../../gm-toolkit/initialization";
import { getGmToolkitCutoverReport } from "../../gm-toolkit/migration";
import {
  importGmToolkitDarkWhispers,
  importGmToolkitSettings,
  remapGmToolkitLaunchers,
  reviewGmToolkitCutover,
} from "../../gm-toolkit/service";
import { TOOLKIT_APPLICATION_ACCESS } from "../access";
import { FoundryVueApplication } from "../FoundryVueApplication";

export class GmToolkitMigrationApplication extends FoundryVueApplication {
  static override ACCESS_POLICY = TOOLKIT_APPLICATION_ACCESS.gmToolkitMigration;

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    classes: [MODULE_ID, `${MODULE_ID}-gm-toolkit-migration`],
    id: `${MODULE_ID}-gm-toolkit-migration`,
    position: {
      height: 760,
      width: 780,
    },
    window: {
      icon: "fa-solid fa-box-archive",
      resizable: true,
      title: `${MODULE_TITLE} — Import from GM Toolkit`,
    },
  };

  protected override getVueComponent(): Component {
    return GmToolkitMigrationApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    const actions: GmToolkitMigrationConsoleActions = {
      getCutoverReport: getGmToolkitCutoverReport,
      importDarkWhispers: importGmToolkitDarkWhispers,
      importSettings: importGmToolkitSettings,
      remapLaunchers: remapGmToolkitLaunchers,
      reviewCutover: reviewGmToolkitCutover,
    };

    return {
      actions,
      initialization: getGmToolkitMigrationConsoleInitialization(),
    };
  }
}
