<script setup lang="ts">
import { computed, ref, watch } from "vue";

import type {
  GmToolkitCutoverReport,
  GmToolkitCutoverReview,
} from "../../../types/gm-toolkit/Cutover";
import {
  launcherMatchLabel,
  settingStatusLabel,
  sourceEvidenceLabel,
} from "../../../functions/gm-toolkit/cutover-display";

const props = defineProps<{
  isWorking: boolean;
  report?: GmToolkitCutoverReport;
  review?: GmToolkitCutoverReview;
}>();

const emit = defineEmits<{ review: [] }>();

const acknowledged = ref(false);
const reviewIsCurrent = computed(() =>
  Boolean(props.report && props.review?.evidenceId === props.report.evidenceId),
);
const canDisable = computed(
  () =>
    reviewIsCurrent.value &&
    props.report?.replacement.ready === true &&
    props.report.combat.active === false,
);
const reviewStatusLabel = computed(() =>
  reviewIsCurrent.value
    ? canDisable.value
      ? "Reviewed — ready to disable"
      : props.report?.replacement.ready === false
        ? "Keep GM Toolkit enabled"
        : "Reviewed — combat active"
    : "Review required",
);

watch(
  () => props.report?.evidenceId,
  () => (acknowledged.value = false),
);
</script>

<template>
  <section
    class="dui-card dui-card-border tw:min-w-0 tw:border-2 tw:border-accent/50! tw:bg-base-100! tw:shadow-md"
    aria-labelledby="gm-toolkit-cutover-title"
  >
    <div class="dui-card-body tw:min-w-0 tw:gap-3 tw:p-4">
      <div class="tw:flex tw:flex-wrap tw:items-start tw:justify-between tw:gap-3">
        <div class="tw:min-w-0 tw:flex-1">
          <div class="tw:flex tw:flex-wrap tw:items-center tw:gap-2">
            <h2 id="gm-toolkit-cutover-title" class="dui-card-title tw:font-serif tw:text-lg">
              Before you disable GM Toolkit
            </h2>
            <span
              class="dui-badge dui-badge-sm"
              :class="canDisable ? 'dui-badge-success' : 'dui-badge-warning'"
            >
              {{ reviewStatusLabel }}
            </span>
          </div>
        </div>
      </div>

      <template v-if="report">
        <div class="tw:grid tw:min-w-0 tw:gap-2 tw:min-[38rem]:grid-cols-3">
          <div class="dui-stat tw:min-w-0 tw:rounded-box tw:bg-base-200! tw:p-3">
            <div class="dui-stat-title tw:text-xs">Settings found</div>
            <div class="dui-stat-value tw:text-2xl">{{ report.settings.total }}</div>
            <div class="dui-stat-desc tw:truncate">{{ sourceEvidenceLabel(report) }}</div>
          </div>
          <div class="dui-stat tw:min-w-0 tw:rounded-box tw:bg-base-200! tw:p-3">
            <div class="dui-stat-title tw:text-xs">Source prompts</div>
            <div class="dui-stat-value tw:text-2xl">{{ report.content.sourcePromptCount }}</div>
            <div class="dui-stat-desc">{{ report.content.currentPromptCount }} in Drowsy</div>
          </div>
          <div class="dui-stat tw:min-w-0 tw:rounded-box tw:bg-base-200! tw:p-3">
            <div class="dui-stat-title tw:text-xs">Detected launchers</div>
            <div class="dui-stat-value tw:text-2xl">{{ report.launchers.detectedMacros }}</div>
            <div class="dui-stat-desc">{{ report.launchers.unresolved.length }} need review</div>
          </div>
        </div>

        <div
          v-for="notice in report.notices"
          :key="`${notice.code}:${notice.message}`"
          class="dui-alert dui-alert-warning tw:py-2 tw:text-xs"
          role="alert"
        >
          <i class="fa-solid fa-triangle-exclamation" aria-hidden="true" />
          <span>{{ notice.message }}</span>
        </div>

        <details class="dui-collapse dui-collapse-arrow tw:border tw:border-base-content/20!">
          <summary class="dui-collapse-title tw:min-h-0 tw:py-3 tw:font-semibold">Settings</summary>
          <div class="dui-collapse-content tw:min-w-0 tw:px-3 tw:pb-3">
            <div class="tw:mb-2 tw:flex tw:flex-wrap tw:gap-1">
              <span class="dui-badge dui-badge-sm">
                {{ report.settings.dispositionCounts.import }} can be imported
              </span>
              <span v-if="report.settings.dispositionCounts.pending" class="dui-badge dui-badge-sm">
                {{ report.settings.dispositionCounts.pending }} not transferred
              </span>
              <span class="dui-badge dui-badge-sm">
                {{ report.settings.dispositionCounts.supersede }} handled another way
              </span>
              <span class="dui-badge dui-badge-sm">
                {{ report.settings.dispositionCounts.retire }} not needed
              </span>
              <span class="dui-badge dui-badge-sm">
                {{ report.settings.dispositionCounts.skip }} ignored
              </span>
            </div>
            <div
              class="tw:max-w-full tw:overflow-x-auto tw:rounded-box tw:border tw:border-base-content/15!"
            >
              <table class="dui-table dui-table-sm tw:min-w-[38rem]">
                <thead class="tw:bg-base-300/60!">
                  <tr>
                    <th scope="col">Value</th>
                    <th scope="col">Source</th>
                    <th scope="col">Drowsy</th>
                    <th scope="col">Outcome</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="item in report.settings.items" :key="item.field">
                    <th scope="row">{{ item.label }}</th>
                    <td class="tw:max-w-52 tw:break-words">{{ item.sourceValue }}</td>
                    <td class="tw:max-w-52 tw:break-words">{{ item.currentValue }}</td>
                    <td>
                      <span class="dui-badge dui-badge-sm">{{
                        settingStatusLabel(item.status)
                      }}</span>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </details>

        <details class="dui-collapse dui-collapse-arrow tw:border tw:border-base-content/20!">
          <summary class="dui-collapse-title tw:min-h-0 tw:py-3 tw:font-semibold">
            Dark Whispers content
          </summary>
          <div class="dui-collapse-content tw:grid tw:gap-2 tw:px-3 tw:pb-3">
            <p class="tw:m-0 tw:text-xs tw:text-base-content/70!">
              {{ report.content.sourceTableName || "No source table detected" }}
            </p>
            <div class="tw:flex tw:flex-wrap tw:gap-1">
              <span class="dui-badge dui-badge-success dui-badge-sm">
                {{ report.content.comparisonCounts.same }} imported
              </span>
              <span class="dui-badge dui-badge-sm">
                {{ report.content.comparisonCounts.duplicate }} duplicates
              </span>
              <span class="dui-badge dui-badge-warning dui-badge-sm">
                {{ report.content.comparisonCounts.new }} new
              </span>
              <span class="dui-badge dui-badge-warning dui-badge-sm">
                {{ report.content.comparisonCounts.conflict }} changed
              </span>
            </div>
          </div>
        </details>

        <details
          v-if="report.launchers.unresolved.length"
          class="dui-collapse dui-collapse-arrow tw:border tw:border-base-content/20!"
          open
        >
          <summary class="dui-collapse-title tw:min-h-0 tw:py-3 tw:font-semibold">
            Launchers to check ({{ report.launchers.unresolved.length }})
          </summary>
          <div class="dui-collapse-content tw:min-w-0 tw:px-3 tw:pb-3">
            <div
              class="tw:max-w-full tw:overflow-x-auto tw:rounded-box tw:border tw:border-base-content/15!"
            >
              <table class="dui-table dui-table-sm tw:min-w-[44rem]">
                <thead class="tw:bg-base-300/60!">
                  <tr>
                    <th scope="col">Macro</th>
                    <th scope="col">Match</th>
                    <th scope="col">Hotbar</th>
                    <th scope="col">Drowsy outcome</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="launcher in report.launchers.unresolved" :key="launcher.macroId">
                    <th scope="row">{{ launcher.macroName }}</th>
                    <td>{{ launcherMatchLabel(launcher.match) }}</td>
                    <td>
                      {{ launcher.hotbarSlots.length ? launcher.hotbarSlots.join(", ") : "None" }}
                    </td>
                    <td class="tw:max-w-md tw:whitespace-normal">{{ launcher.outcome }}</td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </details>

        <div
          v-if="reviewIsCurrent"
          class="dui-alert"
          :class="canDisable ? 'dui-alert-success' : 'dui-alert-warning'"
          role="status"
        >
          <i
            :class="canDisable ? 'fa-solid fa-circle-check' : 'fa-solid fa-shield-halved'"
            aria-hidden="true"
          />
          <span>
            Reviewed by {{ review?.reviewedByUserName }} on
            {{ new Date(review!.reviewedAt).toLocaleString() }}.
            <template v-if="canDisable">
              GM Toolkit can now be disabled. Items marked “not transferred” will not be available
              after it is disabled.
            </template>
            <template v-else>Finish the active combat before disabling GM Toolkit.</template>
          </span>
        </div>

        <div
          v-else
          class="tw:grid tw:gap-3 tw:rounded-box tw:border tw:border-warning/50! tw:bg-warning/10! tw:p-3"
        >
          <div v-if="review" class="dui-alert dui-alert-warning tw:py-2 tw:text-xs" role="alert">
            <i class="fa-solid fa-rotate" aria-hidden="true" />
            <span>
              Source data or import choices changed after the previous review. Check the current
              summary again.
            </span>
          </div>
          <label class="tw:flex tw:cursor-pointer tw:items-start tw:gap-3">
            <input
              v-model="acknowledged"
              class="dui-checkbox dui-checkbox-sm tw:mt-0.5 tw:shrink-0"
              type="checkbox"
            />
            <span class="tw:text-sm">
              I reviewed every value, prompt, and launcher above. Anything not imported or replaced
              is intentionally retained or accepted for manual follow-up.
            </span>
          </label>
          <button
            class="dui-btn dui-btn-accent dui-btn-sm tw:justify-self-end"
            :disabled="isWorking || !acknowledged"
            type="button"
            @click="emit('review')"
          >
            <span
              v-if="isWorking"
              class="dui-loading dui-loading-spinner dui-loading-sm"
              aria-hidden="true"
            />
            <i v-else class="fa-solid fa-clipboard-check" aria-hidden="true" />
            Save review
          </button>
          <p class="tw:m-0 tw:text-xs tw:text-base-content/70!">
            Review this summary before disabling GM Toolkit. Keep it enabled while any action lacks
            an equivalent; if combat is active, finish it first.
          </p>
        </div>
      </template>

      <div v-else-if="review" class="dui-alert dui-alert-success" role="status">
        <i class="fa-solid fa-circle-check" aria-hidden="true" />
        <span>
          {{ review.reviewedByUserName }} reviewed the import on
          {{ new Date(review.reviewedAt).toLocaleString() }}. No GM Toolkit source data is currently
          available.
        </span>
      </div>
    </div>
  </section>
</template>
